const int N=2005;

vector<int>adj[N];
int sz[N],low[N],high[N];

void dfs_sz(int u,int p,string &s){
  sz[u]=(s[u]=='1');
  for(auto i:adj[u]){
    if(i!=p){
      dfs_sz(i,u,s);
      sz[u]+=sz[i];
    }
  }
}

int gett(int u,int p,string &s,int dep){
  int val=0;
  if(s[u]=='1'){
    val+=dep;
  }
  for(auto i:adj[u]){
    if(i!=p){
      val+=gett(i,u,s,dep+1);
    }
  }
  return val;
}

void check(int u,int p,string &s,int dep){
  if(s[u]=='1'){
    high[u]+=dep;
  }
  vector<int>lown;
  int sum=0,tot=0;
  for(auto i:adj[u]){
    if(i!=p){
      check(i,u,s,dep+1);
      high[u]+=high[i]+sz[i];
      lown.pb(low[i]+sz[i]);
      sum+=low[i]+sz[i];
    }
  }
  sort(all(lown));
  if(lown.size()==0){
    return;
  }
  if(lown.size()==1){
    low[u]=lown[0];
  }
  else{
    if(lown.back()>sum-lown.back()){
      low[u]=(2*lown.back()-sum);
    }
    else{
      low[u]=((sum)%2);
    }
  }
}

