    for(auto j:adj[i]){
      int gt=gett(j,i,s,1);
      if(sz[j]){
	zz.pb(gt);
      }
    }
    sort(all(zz));
    int sum=accumulate(all(zz),0);
    if(zz.size()==0){
      op=0;
