void solve() {
  int N; cin >> N;
  string s; cin >> s;
  vector<vi32> edges(N);
  rep(i, N - 1) {
    int a, b; cin >> a >> b;
    a--, b--;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }

  struct Data {
    vi32 list = vi32();
  };

  vector<vector<Data>> dp(N);
  vi32 par(N, -1);

  auto lift = [&](Data a, int u) {
    each(l, a.list) l++;
    if (s[u] == '1') a.list.push_back(0);
    return a;
  };

  auto merge = [](Data a, Data b) {
    each(l, b.list) a.list.push_back(l);
    return a;
  };

  function<Data(int, int)> dfs = [&](int v, int p) {
    int n = edges[v].size();
    dp[v] = vector<Data>(n);

    Data ret;
    rep(i, n) {
      int u = edges[v][i];
      if (u == p) {
        par[v] = i;
        continue;
      }
      dp[v][i] = lift(dfs(u, v), u);
      ret = merge(ret, dp[v][i]);
    }
    return ret;
  };

  vector<vi32> lists(N);
  vi32 answers;

  function<void(int, Data)> bfs = [&](int v, Data d) {
    if (par[v] != -1) {
      dp[v][par[v]] = lift(d, edges[v][par[v]]);
    }
    int n = edges[v].size();
    vector<Data> dpl(n + 1);
    vector<Data> dpr(n + 1);
    repp(i, n) dpl[i + 1] = merge(dpl[i], dp[v][i]);
    rrep(i, n) dpr[i] = merge(dpr[i + 1], dp[v][i]);

    auto r = lift(dpr[0], v);

    int sum = 0;
    int mx = 0;
    each(l, r.list) sum += l, amax(mx, l);
    if (sum % 2 == 0 && mx * 2 <= sum) {
      answers.push_back(sum / 2);
    }

    rep(i, n) if (i != par[v]) {
      int u = edges[v][i];
      bfs(u, merge(dpl[i], dpr[i + 1]));
    }
  };

  dfs(0, -1);
  bfs(0, Data());

  if (answers.size() == 0) {
    cout << -1 << '\n';
  } else {
    sort(all(answers));
    cout << answers[0] << '\n';
  }
}

