const int INF = 0x3f3f3f3f3f3f;
const int maxn = 2005;
using namespace std;
struct E{
	int to, nxt;
}e[maxn << 1];
int head[maxn], tot = 0;
void addedge(int u, int v){
	e[++tot].to = v, e[tot].nxt = head[u];
	head[u] = tot;
}
int dep[maxn], sz[maxn], sdep[maxn], sum = 0; char s[maxn];
void dfs1(int cur, int fa){
	dep[cur] = dep[fa] + 1;
	sum += (dep[cur] - 1) * (s[cur] == '1');
	for (int i = head[cur]; i; i = e[i].nxt){
		int v = e[i].to;
		if (v != fa){
			dfs1(v, cur);
			sz[cur] += sz[v] + (s[v] == '1');
			sdep[cur] += sdep[v] + sz[v] + (s[v] == '1');
		}
	}
}
void dfs2(int cur, int fa){
	int link = 0;
	for (int i = head[cur]; i; i = e[i].nxt){
		int v = e[i].to;
		if (v == fa) continue;
		if (sdep[v] + sz[v] > sdep[link] + sz[link]) link = v;
	}
	if (link == 0) return;
	dfs2(link, cur); sdep[cur] = 0;
	for (int i = head[cur]; i; i = e[i].nxt)
		if (e[i].to != fa) sdep[cur] += sdep[e[i].to] + sz[e[i].to] + (s[e[i].to] == '1');
	if (2ll * (sdep[link] + sz[link]) > sdep[cur]) sdep[cur] = 2ll * (sdep[link] + sz[link]) - sdep[cur];
	else sdep[cur] = sdep[cur] & 1;
}
int n, ans = INF;
signed main(){
	scanf("%lld%s", &n, s + 1);
	for (int u, v, i = 1; i < n; i++){
		scanf("%lld%lld", &u, &v);
		addedge(u, v); addedge(v, u);
	}
	for (int rt = 1; rt <= n; rt++){
		memset(dep, 0, sizeof dep); memset(sz, 0, sizeof sz); sum = 0;
		memset(sdep, 0, sizeof sdep);
		dfs1(rt, 0); if (sum & 1) continue;
		dfs2(rt, 0);
		if (sdep[rt] == 0) ans = min(ans, sum >> 1);
	}
	if (ans == INF) ans = -1;
	printf("%lld\n", ans);
	return 0;
}

