int DFS(int u, int p, int d)
{
	int sum=w[u]*d;
	for(int v:E[u]) if(v!=p) sum+=DFS(v,u,d+1);
	return sum;
}
pair<int,int> MIN(int u, int p, int d)
{
	int sum=w[u]*d;
	int cnt=w[u];
	int all=0;
	int mx=0;
	for(int v:E[u]) if(v!=p)
	{
		pair<int,int> now=MIN(v,u,d+1);
		all+=now.first-now.second*d;
		cnt+=now.second;
		sum+=now.second*d;
		mx=max(mx,now.first-now.second*d);
	}
	int ost=all-mx;
	if(ost<mx) all=mx-ost;
	else
	{
		if(all&1) all=1;
		else all=0;
	}
	sum+=all;
	return mp(sum,cnt);
}
