void DFS(int u,int fa){
	siz[u]=mx[u]=mn[u]=0;
	for(auto v : lnk[u]){
		if(v==fa) continue;
		DFS(v,u);
		mx[v]+=siz[v];mn[v]+=siz[v];
		siz[u]+=siz[v];
		if(max(mn[u],mn[v])<=min(mx[u],mx[v])) mn[u]=((mn[u]&1)^(mn[v]&1));
		else mn[u]=max(mn[u],mn[v])-min(mx[u],mx[v]);
		mx[u]+=mx[v];
	}
	if(gnu[u]=='1') siz[u]++;
}
