void calc(int u,int par=-1){
    int mxy=-1;
    for(int y:v[u]){
	if(y!=par){
	    calc(y,u);
	    if(mxy==-1 || (mxy!=-1 && sig[y]+cnt[y]>sig[mxy]+cnt[mxy])) mxy=y;
	}
