inline S add(S& l, T r) {
  return mod(l += r);
}

ll po(ll v, ll u) {
  return u ? po(v * v % MOD, u >> 1) * (u & 1 ? v : 1) % MOD : 1;
}

int n;
string s;
vi adj[N];

ll sum[N], num[N], del[N];

void dfs(int v, int par = -1) {
  num[v] = sum[v] = del[v] = 0;
  if (s[v] == '1') num[v]++;
  int id = -1, mx = -1;
  for (auto e : adj[v])
    if (e ^ par) {
      dfs(e, v);
      sum[v] += sum[e] + num[e];
      num[v] += num[e];
      if (smax(mx, sum[e] + num[e])) id = e;
    }
  if (id == -1) return;
  if (2 * mx <= sum[v])
    del[v] = sum[v] >> 1;
  else {
    int sum2 = (sum[v] >> 1) << 1;
    int needed = (2 * mx - sum2) >> 1;
    if (del[id] >= needed)
      del[v] = sum[v] >> 1;
    else
      del[v] = sum[v] - mx - 2 * del[id];
  }
}

