		REPC(x, st) {
			q.emplace(x);
		}

		ll cnt = 0;
		while (q.size() > 1) {
			ll a = q.top();
			q.pop();
			ll b = q.top();
			q.pop();
			if (a - 1 > 0) {
				q.push(a - 1);
			}
			if (b - 1 > 0) {
				q.push(b - 1);
			}
			++cnt;
		}
		if (q.empty()) {
			MIN(ans, cnt);
		}

	}
	cout << ((ans < 1e9) ? ans : -1) << endl;

}

