void create(int u, int v)
{
	edge++; a[edge] = v; nxt[edge] = head[u]; head[u] = edge;
}
void get_f(int u, int fa)
{
	f[u] = 0; g[u] = 0; diff[u] = 0;
	if (s[u] == '1') diff[u] = 1;
	int mx = 0, son = 0;
	for (int i = head[u]; i; i = nxt[i])
	{
		int v = a[i];
		if (v != fa)
		{
			get_f(v, u);
			diff[u] += diff[v];
			g[u] += g[v] + diff[v];
			if (g[v] + diff[v] > mx) {mx = g[v] + diff[v]; son = v;}
		}
	}
	if (mx * 2 <= g[u])
	{
		if (g[u] % 2) f[u] = 1;
		else f[u] = 0;
	}
	else f[u] = max(0, f[son] + diff[son] - (g[u] - mx));
	if (g[u] % 2 && f[u] == 0) f[u] = 1;
}
