    if(ch==par) {
      continue;
    }
    dfs(ch,node);
    depthSum[node] += depthSum[ch] + cnt[ch];
    cnt[node] += cnt[ch];
  }
}

int getMin(int node,int par) {
  int maxChild = 0;
  for(int ch : adj[node]) {
    if(ch!=par) {
      if(depthSum[ch]>depthSum[maxChild]) {
        maxChild = ch;
      }
    }
  }
  if(maxChild==0) {
    return 0;
  }
  int minDepthSum = getMin(maxChild,node) + cnt[maxChild];
  if(minDepthSum <= depthSum[node] - (depthSum[maxChild]+cnt[maxChild])) {
    return depthSum[node]&1;
  }
  return minDepthSum - depthSum[node] + (depthSum[maxChild]+cnt[maxChild]);
}

int solveRoot(int root) {
  dfs(root,0);
  if(getMin(root,0)==0) {
    return depthSum[root]/2;
  } else {
    return 1e9;
  }
}

