pair<int,int> canDo(int node,int par,int &need) {
  pair<int,int> tmp = {0,0};
  if(need==0) {
    return tmp;
  }
  priority_queue<int> pq;
  for(int ch: adj[node]) {
    if(ch==par) {
      continue;
    }
    pair<int,int> t = canDo(ch,node,need);
    if(t.second==0) {
      continue;
    }
    pq.push(t.first + t.second);
    tmp.second += t.second;
  }

  while(pq.size()>1 && need>0) {
    int a = pq.top();
    pq.pop();
    int b = pq.top();
    pq.pop();
    if(a>0 && b>0) {
      --need;
      --a,--b;
      if(a>0) {
        pq.push(a);
      }
      if(b>0) {
        pq.push(b);
      }
    } else {
      break;
    }
  }
  while(!pq.empty()) {
    tmp.first += pq.top();
    pq.pop();
  }
  return tmp;
}

int solveRoot(int root) {
  int ret = 0;
  vector<pair<int,int> >v;
  int sum = 0;
  for(int ch : adj[root]) {
    pair<int,int> tmp = get(ch,root);
