int solve(const vector<vector<int>>& graph, const string& S, int node)
{
    map<int, int> M;
    int acc = 0;
    function<void(int, int, int, int)> recur = [&](int node, int prev, int parent, int d) {
        if (S[node] == '1') acc += d;
        if (prev == -1) {
            for (auto next : graph[node]) {
                recur(next, node, next, 1);
            }
        } else {
            if (S[node] == '1') M[parent] += d;
            for (auto next : graph[node]) if (next != prev) {
                recur(next, node, parent, d+1);
            }
        }
    };
    recur(node, -1, -1, 0);
    if (acc == 0) return 0;
    vector<int> X;
    for (auto &p : M) X.push_back(p.second);
    if (acc % 2 == 0 && *max_element(begin(X), end(X)) <= acc / 2) {
        return acc / 2;
    } else {
        return -1;
    }
}
