int count[N];

ll recDP(int i, int p = -1) {
	dp_min[i] = 0;
	dp_max[i] = 0;
	count[i] = 0;
	for (auto t : conns[i]) {
		if (t == p) continue;
		recDP(t, i);
		dp_max[i] += dp_max[t];
		count[i] += count[t];
	}

	dp_min[i] = dp_max[i] % 2;
	for (auto t : conns[i]) {
		if (t == p) continue;
		ll offer = dp_min[t] + dp_max[t] - dp_max[i];
		dp_min[i] = max(dp_min[i], offer);
	}

	if (p == -1) {
		// Solve at root
		if (dp_min[i] == 0) return dp_max[i] / 2;
		else return INF;
	}

	if (str[i] == '1') ++count[i];
	dp_min[i] += count[i];
	dp_max[i] += count[i];

	return -1; // Not root
}

