	cin >> str;
	for (int i = 0; i < n-1; ++i) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		conns[a].push_back(b);
		conns[b].push_back(a);
	}

	// Possible iff sum of distances to the target node is even
	// Given that, we then need that the minimum total distance at every branch is at most the sum of the maximum distances of other branches.
	// No operation in a branch can bring two pieces further away from the root, but a operation can bring both of two pieces closer.

	// So for every branch DP 3 values:
	//	1. Total minimum distance of pieces to parent
	//	2. Total maximum distance of pieces to parent
	//	3. Count of pieces
	// Say we count these for every subtree. To do that, first solve all subtrees of a node, then find sum of maximum distances,
	// then loop over every node, subtract its maximum from the total maximum, and check if its minimum is <= the sum of other maximums.
	// If it isn't, the total minimum distance of pieces to parent of this node will be that node's minimum - sum of other maximums.
	// If no node has such a situation, the minimum distance for this node will be the sum of maximums mod 2.

	ll ans = INF;
	for (int i = 0; i < n; ++i) {
		ans = min(ans, recDP(i));
	}
	if (ans == INF) cout << "-1\n";
	else cout << ans << '\n';
}

