void chemthan() {
    int n; cin >> n;
    string s; cin >> s;
    vector<vi> adj(n);
    FOR(i, 0, n - 1) {
        int u, v; cin >> u >> v; u--, v--;
        adj[u].pb(v), adj[v].pb(u);
    }
    int tres = INF;
    vi d(n), g(n);
    function<pi(int, int)> dfs = [&] (int u, int p) {
        g[u] = 0;
        int res = 0;
        if (s[u] == '1') g[u] = 1, res = d[u];
        vi vals, vals2;
        for (int v : adj[u]) {
            if (v ^ p) {
                d[v] = d[u] + 1;
                pi e = dfs(v, u);
                res += e.se;
                int t = e.fi + g[v];
                vals.pb(t);
                vals2.pb(e.se);
                g[u] += g[v];
            }
        }
        if (p == -1) {
            int sum = 0;
            FOR(i, 0, sz(vals)) {
                sum += vals[i];
            }
            int found = 0;
            int w = *max_element(all(vals));
            FOR(i, 0, sz(vals)) {
                if (vals[i] == w && vals2[i] <= sum - vals[i]) {
                    found = 1;
                }
            }
            if (found) {
                sum = 0;
                FOR(v, 0, n) if (s[v] == '1') {
                    sum += d[v];
                }
                if (sum % 2 == 0) {
                    chkmin(tres, sum / 2);
                }
            }
            return mp(0, 0);
        }
        else {
            if (sz(vals)) {
                int sum = 0;
                FOR(i, 0, sz(vals)) {
                    sum += vals[i];
                }
                int found = 0;
                int w = *max_element(all(vals));
                int z = INF;
                FOR(i, 0, sz(vals)) {
                    if (vals[i] == w) {
                        chkmin(z, max(0, vals2[i] - (sum - vals[i])));
                    }
                    if (vals[i] == w && vals2[i] <= sum - vals[i]) {
                        found = 1;
                    }
                }
                if (found) {
                    return mp(sum % 2, res);
                }
                else {
                    return mp(z, res);
                }
            }
            return mp(0, res);
        }
        return mp(0, 0);
    };
    FOR(u, 0, n) {
        d[u] = 0;
        dfs(u, -1);
    }
    if (tres == INF) tres = -1;
    cout << tres << "\n";
}

