void merge(int a,int b){
	l[a]=(l[a]<=l[b]&&l[b]<=r[a])||(l[b]<=l[a]&&l[a]<=r[b])?
			(l[b]^l[a])&1:max(l[a]-r[b],r[a]-l[b]);
	r[a]=r[a]+r[b];
}
void dfs(int x){
	size[x]=(s[x]=='1');
	sum+=dep[x]*(s[x]=='1');
	l[x]=r[x]=0;
	for(int i=last[x];i!=-1;i=e[i].nxt)if(e[i].t!=fa[x]){
		fa[e[i].t]=x;
		dep[e[i].t]=dep[x]+1;
		dfs(e[i].t);
		size[x]+=size[e[i].t];
		l[e[i].t]+=size[e[i].t];
		r[e[i].t]+=size[e[i].t];
		merge(x,e[i].t);
	}
}
