using namespace std;
typedef long long ll;

ll const MAX = 2005;
vector<ll> g[MAX];
bool ex[MAX];

bool dfs(vector<long long>& num, vector<ll>& dist, vector<ll>& point, vector<bool>& visited, ll cur, ll i){
    visited[cur] = 1;
    for(ll nx: g[cur]){
        if(visited[nx]){
            continue;
        }
        dfs(num, dist, point, visited, nx, i);

        dist[nx] += num[nx];
        ll dn = dist[nx], dc = dist[cur], pn = point[nx], pc = point[cur];
        if(dist[nx] < dist[cur]){
            swap(dn, dc);
            swap(pn, pc);
        }
        point[cur] = dc * 2 + min(dn - dc, pn) / 2 * 2;
        num[cur] += num[nx];
        dist[cur] += dist[nx];
    }
    num[cur] += ex[cur];
    return (dist[cur] == point[cur]);
}

ll f(ll n,ll i){
    vector<long long> num(MAX, 0), dist(MAX, 0), point(MAX,0);
    vector<bool> visited(MAX, 0);
    if(dfs(num, dist, point, visited, i, i)){
        return point[i] / 2;
    }else{
        return 1e18;
    }
}

