	VL dp2(n);
	V<list<ll>> lst(n);
	treeDP(n, graph, 0, [&](ll from, ll to) {
		// update
		dp1[to] += dp1[from];
		ll ad = dp1[from] + dp2[from];
		dp2[to] += ad;
		if (ad > 0) { lst[to].emplace_back(ad); }
	});
	VL cost(n); cost[0] = dp2[0];
	graphBFS(n, graph, 0, [&](ll from, ll to) {
		ll dif = cost[from];
		if (dp2[from] != dp2[to]) { dif -= (dp1[to] + dp2[to]); }
		dif += (dp1[0] - dp1[to]);
		if (dif > 0) { lst[to].emplace_back(dif); }
		cost[to] = dif;
	});

	ll ans = 1e10;
	REPC(v, lst) {
		if (v.empty()) {
			ans = 0;
			break;
		}
		if (v.size() == 2) {
			if (*v.begin() == *v.rbegin()) {
				chmin(ans, *v.begin());
			}
			continue;
		}
		ll mx = -1;
		ll sum = 0;
		REPC(x, v) { chmax(mx, x); sum += x; }
		if (sum & 1) { continue; }
		if (sum - mx >= mx) {
			chmin(ans, sum / 2);
		}
	}
	cout << ((ans > 1e9) ? -1 : ans) << endl;
