#define range(i, m, n) for(int i = m; i < n; i++)
#define husk(i, m, n) for(int i = m; i > n; i--)

int n;
string s;

int main() {
  cin >> n >> s;
  vector<vector<int>> g(n);
  range(i, 0, n - 1) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  vector<int> dep(n);
  vector<int> w(n);
  vector<int> total(n);
  function<void(int, int)> dfs = [&](int v, int p) {
    dep[v] = total[v] = w[v] = 0;
    if(~p) dep[v] = dep[p] + 1;
    if(s[v] == '1') {
      w[v] = 1;
    }
    for(int u : g[v]) {
      if(u == p) continue;
      dfs(u, v);
      w[v] += w[u];
      total[v] += total[u] + w[u];
    }
  };
  int res = INT_MAX;
  for(int v = 0; v < n; v++) {
    dfs(v, -1);
    if(total[v] & 1) continue;
    int cur = v;
    int par = -1;
    int ans = 0;
    int ps = 0;
    while(true) {
      ans += (total[cur] - ps) / 2;
      int p = -1;
      for(int u : g[cur]) {
        if(u == par) continue;
        if(p == -1 || total[p] + w[p] < total[u] + w[u]) p = u;
      }
      if(p == -1) {
        ans = INT_MAX;
        break;
      }
      int c = total[cur] + ps - total[p] - w[p];
      if(total[p] + w[p] <= c) break;
      // total[p] + w[p] > c
      // x + w[p] == c
      // w[p] > c ?
      if(w[p] > c) {
        ans = INT_MAX;
        break;
      }
      par = cur; cur = p; ps = c - w[p];
    }
    res = min(res, ans);
  }
  if(res == INT_MAX) res = -1;
  cout << res;
  return 0;
}

