tuple<int, int, int> DFS(int u, int p = 0) {
    int tot = 0, mi = 0, cnt = s[u] - '0';
    pair<int, int> mx = {0, 0};
    for (int &v : adj[u]) {
        if (v != p) {
            auto [ct, cm, cc] = DFS(v, u);
            cnt += cc; ct += cc; cm += cc;
            tot += ct;
            mx = max(mx, {ct, cm});
        }
    }
    mi = max(tot & 1, mx.second - (tot - mx.first));
    return {tot, mi, cnt};
}

