int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n; cin >> n;
    string s; cin >> s;
    int ss = 0;
    for (auto &x: s) ss += x & 1;
    long long cnt[n], sum[n], ans[n];
    vector<int> e[n];
    for (int i = 0; i < n-1; i++) {
        int a, b; cin >> a >> b; a--, b--;
        e[a].emplace_back(b);
        e[b].emplace_back(a);
    }
    auto dfs = [&e, &cnt, &sum, &ans, &s](auto f, int curr, int prev) -> void {
        cnt[curr] = 0, sum[curr] = 0, ans[curr] = 0;
        long long sumi = 0, maxi = 0;
        for (auto &to: e[curr]) {
            if (to == prev) continue;
            f(f, to, curr);
            cnt[curr] += cnt[to];
            ans[curr] += ans[to];
            sumi += cnt[to]+sum[to];
            maxi = max(maxi, cnt[to]+sum[to]);
        }
        if (prev != -1) {
            if (maxi * 2 <= sumi) {
                ans[curr] += sumi / 2;
                sum[curr] = sumi - (sumi / 2) * 2;
            } else {
                ans[curr] += sumi - maxi;
                sum[curr] = sumi - (sumi - maxi) * 2;
            }
        } else {
            int j;
            for (auto &to: e[curr]) {
                if (maxi == cnt[to]+sum[to]) {
                    j == to; break;
                }
            }
            long long sums = 0;
            for (auto &to: e[curr]) {
                long long d = min(ans[to], (maxi-(cnt[to]+sum[to]))/2);
                sums += cnt[to]+sum[to] + d * 2;
                ans[curr] -= d;
            }
            if (maxi * 2 <= sums) {
                ans[curr] += sums / 2;
                sum[curr] = sums % 2;
            } else {
                sum[curr] = -1;
            }
        }
        if (s[curr] & 1) cnt[curr]++;
    };
    long long mini = 1e18;
    for (int i = 0; i < n; i++) {
        dfs(dfs, i, -1);
        assert(cnt[i] == ss);
        if (!sum[i]) mini = min(mini, ans[i]); 
    }
    mini = mini == 1e18 ? -1 : mini;
    cout << mini << "\n";
    return 0;
}

