        G[b].push_back(a);
    }
    int64_t ans=1000000000;
    function<P(int64_t,int64_t)> dfs = [&](int v,int prev){
        int64_t children=0,dist=0;
        if(S[v]=='1') children++;
        for(auto to:G[v]){
            if(to==prev) continue;
            int64_t c,d;
            tie(c,d)=dfs(to, v);
            children+=c;
            dist+=c+d;
        }
        return P(children,dist);
    };
    for(int root=0;root<N;root++){
        vector<int64_t> V;
        int64_t sum=0;
        for(auto to:G[root]){
            int64_t c,d;
            tie(c,d)=dfs(to,root);
            V.push_back(c+d);
            sum+=c+d;
        }
        if(sum%2) continue;
        bool flag=true;
        for(auto v:V){
            if(v>sum-v){
                flag=false;
                break;
            }
        }
        if(flag) ans=min(ans,sum/2);
    }
    if(ans==1000000000)ans=-1;
    cout<<ans<<endl;
