            sum += S, chmax(max, S);
        }
        if (sum % 2 == 0 and sum >= 2 * max) { chmin(ans, sum / 2); }
    }
    std::cout << (ans == INF<int> ? -1 : ans) << std::endl;
    return 0;
}

