  auto f1 = [](const data& a, const data& b) {
    data ret;
    ret.cnt = a.cnt+b.cnt;
    ret.mx = a.mx + b.mx;
    ret.mn = max({a.mn - b.mx, b.mn - a.mx, (a.mx + b.mx) % 2});
    return ret;
  };

  auto f2 = [](const data& a, int64 b) {
    b += a.cnt;
    return data(a.mn + b, a.mx + b, b);
  };

  ReRooting<int64, data> rer(N, f1, f2, data(0, 0, 0));
  int64 ans = INF_LL;
  REP(i, N-1) {
