const int N = 2e3;

int n;
int had[N + 1];
struct Edge {
	int to, next;
} edge[(N << 1) + 1];
int start[N + 1], tot;
int f[N + 1], sum[N + 1], val[N + 1];
int ans = 1e9;

inline void addedge(int u, int v)
{
	edge[++tot] = Edge{ v, start[u] };
	start[u] = tot;
	edge[++tot] = Edge{ u, start[v] };
	start[v] = tot;
	return;
}
inline void dfs(int u, int fa)
{
	val[u] = had[u];
	sum[u] = 0;
	int maxx = 0;
	for (int i = start[u]; i; i = edge[i].next) {
		int v = edge[i].to;
		if (v != fa) {
			dfs(v, u);
			val[u] += val[v];
			sum[v] += val[v];
			sum[u] += sum[v];
			if (sum[v] > sum[maxx])
				maxx = v;
		}
	}
	if (!maxx) {
		f[u] = 0;
		return;
	}
	if (sum[u] - sum[maxx] >= sum[maxx])
		f[u] = sum[u] / 2;
	else
		f[u] = sum[u] - sum[maxx] + min(f[maxx], ((sum[maxx] << 1) - sum[u]) / 2);
	return;
}
