    {
        dfs( root, -1 );
        if ( dp[root].minOpnum == 0 ) ans = min( ans, dp[root].maxOpnum );
    }

    if ( ans == ( 1 << 30 ) )
        cout << -1 << endl;
    else
        cout << ans / 2 << endl;

    return 0;
}

