            m1 = p.second.first - p.second.second * 2;
            m2 = p.second.first;
        }

        sum += p.second.first;
    }

    if (m1 > sum - m2) {
        c3 = m1 - (sum - m2);
    } else {
        c3 = sum / 2;
    }

    if (s[x] == '1') c1++;

    return make_pair(c1, make_pair(c2, c3));
}

