        edges[v].emplace_back(u);
    }

    lint ret = inf;

    for (int i = 0; i < n; ++i) {

        vector<lint> nstot(n, 0);
        vector<lint> ns(n, 0);
        vector<int> depth(n, 0);
        {
            function<void(int, int)> dfs = [&](int c, int p) {
                for (auto &v : edges[c]) {
                    if (v == p)
                        continue;
                    depth[v] = depth[c] + 1;
                    dfs(v, c);
                    ns[c] += ns[v];
                    nstot[c] += nstot[v];
                }
                nstot[c] += ns[c];
                if (s[c] == '1')
                    ns[c] = 1;
            };
            dfs(i, -1);
