        for (int j = 0; j < (int)sub[u].size(); ++j) {
            while (!sub[x].empty() && sub[u][j] > d) {
                int y = sub[x].back();
                sub[x].pop_back();
                int k = min(sub[u][j] - d, y - d);
                sub[u][j] -= k;
                y -= k;
                res += k;
                root |= y == d;
                root |= sub[u][j] == d;
                if (y > d) sub[x].push_back(y);
            }
        }
        for (int j = 0; j < (int)sub[u].size(); ++j) {
            if (sub[u][j] > d)
                sub[x].push_back(sub[u][j]);
        }
    }
    if (root) sub[x].push_back(d);
    return res;
}

int solve(int r) {
    for (int i = 0; i < n; ++i) sub[i].clear();
    int res = dfs(r, -1, 0);
    if ((int)sub[r].size() == 1 && sub[r][0] == 0) return res;
    return inf;
}

