pair<int,int> get(int node,int par) {
  int cc = 0, sumD = 0;
  if(s[node]=='1') {
    cc = 1;
  }
  for(int ch : adj[node]) {
    if(ch==par) {
      continue;
    }
    pair<int,int> tmp = get(ch,node);
    cc += tmp.first , sumD += tmp.second +tmp.first;
  }
  return make_pair(cc,sumD);
}

pair<int,int> canDo(int node,int par,int &need) {
  pair<int,int> tmp = {0,0};
  if(need==0) {
    return tmp;
  }
  priority_queue<int> pq;
  for(int ch: adj[node]) {
    if(ch==par) {
      continue;
    }
    pair<int,int> t = canDo(ch,node,need);
    if(t.second==0) {
      continue;
    }
    pq.push(t.first + t.second);
    tmp.second += t.second;
  }

  while(pq.size()>1 && need>0) {
    int a = pq.top();
    pq.pop();
    int b = pq.top();
    pq.pop();
    if(a>0 && b>0) {
      --need;
      --a,--b;
      if(a>0) {
        pq.push(a);
      }
      if(b>0) {
        pq.push(b);
      }
    } else {
      break;
    }
  }
  while(!pq.empty()) {
    tmp.first += pq.top();
    pq.pop();
  }
  return tmp;
}

int solveRoot(int root) {
  int ret = 0;
  vector<pair<int,int> >v;
  int sum = 0;
  for(int ch : adj[root]) {
    pair<int,int> tmp = get(ch,root);
    if(tmp.first==0) {
      continue;
    }
    v.push_back(make_pair(tmp.second + tmp.first,ch));
    sum += v.back().first;
  }
  if(v.size()==1) {
    return 1e9;
  }
  if(sum%2!=0) {
    return 1e9;
  }
  if(v.size()==0) {
    return 0;
  }
  sort(v.begin(),v.end());
  int need = max(v.back().first*2 - sum,0);
  need/=2;
  v.back().first -= need*2;
  ret += need;
  canDo(v.back().second,root,need);
  if(need==0) {
    int ad = 0;
      for(pair<int,int> g : v) {
        ad += g.first;
      }
      assert(ad%2==0);
      ad/=2;
      return ret + ad;
  } else {
    return 1e9;
  }
}

