ll getsum(ll n, ll f, const string & s, const unordered_multimap<ll, ll> & graph, ll non) {
	ll sum = 0;

	vector<bool> use(n, false);
	use[non] = true;
	queue<PAIR> q;
	use[f] = true;
	q.emplace(f, 1);
	while (!q.empty()) {
		ll from = q.front().first;
		ll l = q.front().second;
		if (s[from] == '1') { sum += l; }
		q.pop();
		auto range = graph.equal_range(from);
		REPI2(itr, range.first, range.second) {
			ll to = itr->second;
			if (!use[to]) {
				use[to] = true;
				q.emplace(to, l + 1);
			}
		}
	}
	return sum;
}

list<ll> getst(ll n, ll f, const string & s, const unordered_multimap<ll, ll> & graph) {
	list<ll> ans;
	auto range = graph.equal_range(f);
	REPI2(itr, range.first, range.second) {
		auto p = getsum(n, itr->second, s, graph, f);
		if (p > 0) {
			ans.emplace_back(p);
		}
	}

	return ans;
}

