        vi vals, vals2;
        for (int v : adj[u]) {
            if (v ^ p) {
                d[v] = d[u] + 1;
                pi e = dfs(v, u);
                res += e.se;
                int t = e.fi + g[v];
                vals.pb(t);
                vals2.pb(e.se);
                g[u] += g[v];
            }
        }
        if (p == -1) {
            int sum = 0;
            FOR(i, 0, sz(vals)) {
                sum += vals[i];
            }
            int found = 0;
            FOR(i, 0, sz(vals)) {
                if (vals2[i] <= sum - vals[i]) {
                    found = 1;
                }
            }
            if (found) {
                sum = 0;
                FOR(v, 0, n) if (s[v] == '1') {
                    sum += d[v];
                }
                if (sum % 2 == 0) {
                    chkmin(tres, sum / 2);
                }
            }
            return mp(0, 0);
        }
        else {
            sort(all(vals));
            if (sz(vals)) {
                int sum = 0;
                FOR(i, 0, sz(vals) -1 ) {
                    sum += vals[i];
                }
                int b = vals.back();
                if (sum <= b) {
                    return mp(b - sum, res);
                }
                else {
                    return mp((sum + b) % 2, res);
                }
            }
        }
        return mp(0, 0);
    };
    FOR(u, 0, n) {
        d[u] = 0;
        dfs(u, -1);
    }
