int n,head[N],cnt,v[N],dp[N];
int siz[N],siz2[N],ans=-1;
struct edge
{
	int to,nxt;
}w[2*N];
void add(int x,int y)
{
	w[++cnt]=(edge){y,head[x]};
	head[x]=cnt;
}
void dfs(int x,int last)
{
	siz[x]=v[x],siz2[x]=0;
	int maxn=0,id;
	for(int i=head[x];i;i=w[i].nxt)
	{
		int y=w[i].to;
		if(y==last)continue;
		dfs(y,x);
		siz[x]+=siz[y];
		siz2[x]+=siz2[y]+siz[y];
		if(siz2[y]+siz[y]>maxn)
			maxn=siz2[y]+siz[y],id=y;
	}
	if(maxn<=siz2[x]-maxn)dp[x]=siz2[x]/2;
	else
	{
		dp[x]=(siz2[x]-maxn)+min(dp[id],(maxn-(siz2[x]-maxn))/2);
	}
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
		scanf("%1d",&v[i]);
	for(int i=1,x,y;i<n;i++)
	{
		scanf("%d %d",&x,&y);
