const ll maxn=1e5+500;
const ll inf=1e17+800;

string s;
vector<ll> ger[maxn];
ll dp[maxn];
ll sz[maxn];
ll dpu[maxn];
ll par[maxn];
ll kol;

void dfs(ll a,ll p=-1){
	sz[a]=s[a];
	par[a]=p;
	for(auto v:ger[a]){
		if(v!=p){
			dfs(v,a);
			sz[a]+=sz[v];
			dp[a]+=dp[v];
			dp[a]+=sz[v];
		}	
	}
}
void dfss(ll a,ll p=-1){
	for(auto v:ger[a]){
		if(v!=p){
			dpu[v]=dpu[a]+dp[a]-(dp[v]+sz[v])+(kol-sz[v]);
			dfss(v,a);
		}
	}
}
int main(){
	ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);	
	ll n;
	cin>>n;
	cin>>s;
	for(ll i=0;i<n;i++){
		s[i]-='0';
		kol+=s[i];
	}
	for(ll i=1;i<n;i++){
		ll a,b;
		cin>>a>>b;
		a--;b--;
		ger[a].pb(b);
		ger[b].pb(a);
	}
	dfs(0);
	dfss(0);
	ll ans=inf;
	for(ll i=0;i<n;i++){
		vector<ll> vec;
		for(auto v:ger[i]){
			if(v!=par[i]){
				vec.pb(dp[v]+sz[v]);
			}
		}
		vec.pb(dpu[i]);
		sort(vec.begin(),vec.end());
		ll s=0;
		for(auto e:vec){
			s+=e;
		}
		if(s%2==1 || vec.back()*2>s){
			continue;
		}
		ans=min(ans,s/2);
	}
	if(ans==inf){
		cout<<-1;
	}else{
		cout<<ans;
	}
}

