const int N = 1e5 + 5;
int n;
string s;
vector<int> graph[N]; 
int cnt[N];
int dis[N];
int dp[N];
int ans = -1;

void dfs(int v, int par)
{
    cnt[v] = 0;
    dis[v] = 0;
    if (s[v] - '0')
    {
        cnt[v]++;
    }
    for (auto u: graph[v])
    {
        if (u == par)
        {
            continue;
        }
        dfs(u, v);
        cnt[v] += cnt[u];
        dis[v] += dis[u] + cnt[u];
    }
    dp[v] = dis[v] % 2;
    for (int u: graph[v])
    {
        if (u == par)
        {
            continue;
        }
        dp[v] = max(dp[v], (dp[u] + cnt[u]) - (dis[v] - (dis[u] + cnt[u])));
    }
}

int main() 
{
    cin >> n >> s;
    for (int i = 0; i < n - 1; i++)
    {
        int u, v;
        cin >> u >> v;
        graph[u - 1].push_back(v - 1);
        graph[v - 1].push_back(u - 1);
    }
    for (int i = 0; i < n; i++)
    {
        dfs(i, -1);
        if (dp[i] != 0)
        {
            continue;
        }
        if (ans == -1)
        {
            ans = dis[i] / 2;
        }
        else
        {
            ans = min(ans, dis[i] / 2);
        }
    }
    cout << ans << endl;

}

