		}
	}
}

int dp(int u,int pre){
	int mx_id=0,mx_n=0;
	for(int i=h[u];i;i=e[i].nex){
		int v=e[i].to;
		if(v!=pre){
			if(!mx_id||f[v]+sz[v]>mx_n){
				mx_id=v;
				mx_n=f[v]+sz[v];
			}
		}
	}
	if(f[u]-mx_n>=mx_n){
		return f[u]&1;
	}
	int d=dp(mx_id,u)+sz[mx_id];
	if(f[u]-mx_n>=d){
		return f[u]&1;
	}else{
		return d-(f[u]-mx_n);
	}
}

