        pairs p;
        int val = G.dp2[i];
        if(val % 2 == 0){
            for(auto e: G.G[i]) p.pb(Pii(G.dp2[e.to], i));
            Sort(p);
            Reverse(p);
            int tmp = 0;
            G.dfs3(p[0].s, tmp);
            p[0].f -= tmp;
            if(p[0].f * 2 <= val) Min(ans, val / 2);
        }
    }
    if(ans < INF) Out(ans);
    else Out(-1);

    return 0;
}

