			int h=g[i][j];
			cnt=0;
			dfs(h,i);
			tmp=min(tmp,cnt);
			if(tmp==cnt)
			{
				pos=h;
			}
			sum+=cnt;
		}
		if(sum%2==0 and tmp<=sum/2)
		{
			res=min(res,sum/2);
		}
		else
		{
			if(sum%2==0)
			{
				if(res>sum/2)
				{
					int f=dfs1(pos,i);
					int ft=sum-tmp;
					if(f<=ft)
					{
						res=min(res,sum/2);
					}
				}
			}
		}
	}
	if(res>=INF)
	{
		res=-1;
	}
	cout<<res<<'\n';
	return 0;
}

