using namespace std;
typedef long long ll;
const int MAXN = 2100;

int N;
string S;
vector <int> edge[MAXN];
int nnode[MAXN], ddep[MAXN], dmin[MAXN];
int ans;

void flood (int cloc, int last)
{
    int ntot = 0, nbest = 0, nmin = 0;
    nnode[cloc] = S[cloc] - '0';
    ddep[cloc] = 0;
    for (int neigh : edge[cloc])
    {
        if (neigh == last) continue;
        flood (neigh, cloc);

        nnode[cloc] += nnode[neigh];
        int nb = ddep[neigh] + nnode[neigh];
        ddep[cloc] += nb;
        ntot += nb;
        nbest = max (nbest, nb);
        nmin = max (nmin, dmin[neigh] + nnode[neigh]);
    }

    dmin[cloc] = max (0, nbest + nmin - ntot);
}

void solve_root (int x)
{
    flood (x, -1);
    if (dmin[x] == 0 && ddep[x] % 2 == 0)
        ans = min (ans, ddep[x]);
}

int main()
{
