        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    ans = 1e9;
    for (int i = 0; i < N; i++)
    {
        solve_root (i);
    }
    if (ans > 1e8)
        cout << "-1\n";
    else
        cout << ans / 2 << "\n";
}

