constexpr ll INF = (1LL << 30) - 1LL;
constexpr ll LINF = (1LL << 60) - 1LL;
constexpr ll MOD = 1e9 + 7;
template <typename T> void chmin(T &a, T b) { a = min(a, b); }
template <typename T> void chmax(T &a, T b) { a = max(a, b); }
vector<vector<int>> G;
vector<int> ds, sz, d;
string s;
void build(int i, int p, int dep) {
    d[i] = dep;
    ds[i] = 0;
    sz[i] = 0;
    if (s[i] == '1') {
        sz[i]++;
        ds[i] += dep;
    }
    for (auto &e : G[i]) {
        if (e == p) {
            continue;
        }
        build(e, i, dep + 1);
        sz[i] += sz[e];
        ds[i] += ds[e];
    }
}
int calc(int i, int p) {
    int dp = ds[i] - sz[i] * d[i];
    int res = 0;
    for (auto &e : G[i]) {
        if (e == p) {
            continue;
        }
        int dd = ds[e] - sz[e] * d[i];
        if (dd > dp / 2) {
            int t = dp - dd + calc(e, i) + sz[e];
            res = max(0, (calc(e, i) + sz[e]) - t / 2);
        }
    }
    if (dp % 2) {
        chmax(res, 1);
    }
    return res;
}
int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    cin >> s;
    G.resize(n);
