    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    int res = INF;
    for (int i = 0; i < n; i++) {
        build(i, -1, 0);
        if (calc(i, -1) == 0) {
            chmin(res, ds[i] / 2);
        }
    }
    if (res == INF) {
        cout << -1 << endl;
    } else {
        cout << res << endl;
    }
}

