    function<int (int, int)> dfs = [&] (int u, int fa) {
      siz[u] = str[u] == '1';
      remain[u] = 0;
      int res = 0, sum = 0;
      vector<int> son;
      for (int v : adj[u]) {
        if (v != fa) {
          res += dfs(v, u);
          siz[u] += siz[v];
          son.push_back(remain[v]);
          sum += remain[v];
        }
      }
      if (son.empty()) {
        remain[u] = siz[u];
        return 0;
