int nxt[N<<1],to[N<<1],head[N],cnt;
void add(int u,int v)
{
	nxt[++cnt]=head[u];
	to[cnt]=v;
	head[u]=cnt;
}
bool choose[N];
ll f[N];
int siz[N];
void dfs(int u,int pre)
{
	siz[u]=choose[u];
	for(int i=head[u];i;i=nxt[i])
	{
		int v=to[i];
		if(v==pre) continue;
		dfs(v,u);
		siz[u]+=siz[v];
		f[u]+=f[v]+siz[v];
	}
}
int work(int u,int pre)
{
	int p=0;
	for(int i=head[u];i;i=nxt[i])
	{
		int v=to[i];
		if(v==pre) continue;
		if(f[v]>f[p]) p=v;
	}
	if(!p) return 0;
	int res=work(p,u)+siz[p],ans=f[u]-f[p]-siz[p];

	if(ans>=res) return f[u]&1;
	else return res-ans;
}
