        for(auto e: G[v]) if(e.to != p){
            dfs1(e.to, S, v);
            dp1[v] += dp1[e.to];
            dp2[v] += dp1[e.to] + dp2[e.to];
        }
        if(S[v] == '1') dp1[v]++;    
    }

    void dfs2(int v, int p = -1){
        int M = 0, S = 0, i0;
        for(auto e: G[v]) if(e.to != p){
            S += dp1[e.to] + dp2[e.to];
            if(dp1[e.to] + dp2[e.to] > M){
                M = dp1[e.to] + dp2[e.to];
                i0 = e.to;
            }
        }
        S -= M;
        if(M > 0){
            dfs2(i0, v);
            dp2[v] = max(0LL, dp1[i0] + dp2[i0] - S);
        }
    }
};

