using namespace std;

const int N = 2005;
const int inf = 1000000000;
struct edge {
    int to, nxt;
} tree[N << 1];
int n, head[N], l[N], r[N], sz[N], cnt = 0;
char str[N];
void addedge (int u, int v) {
    edge e = {v, head[u]};
    tree[head[u] = cnt++] = e;
}

void dfs (int u, int fa) {
    int l_mx = 0;
    sz[u] = (str[u - 1] == '1'), r[u] = 0;
    for (int i = head[u]; ~i; i = tree[i].nxt) {
        int v = tree[i].to;
        if (v != fa) {
            dfs(v, u);
            sz[u] += sz[v];
            l_mx = max(l_mx, l[v] + sz[v]), r[u] += r[v] + sz[v];
        }
    }
    l[u] = 0;
    for (int i = head[u]; ~i; i = tree[i].nxt) {
        int v = tree[i].to;
        if (v != fa) {
            if (r[v] + sz[v] <= l_mx) l[u] += r[v] + sz[v];
            else l[u] += l_mx - (l_mx ^ r[v] ^ sz[v] & 1);
        }
    }
    l[u] = (l_mx << 1) - l[u];
    if (l[u] < 0) l[u] = r[u] & 1;
}
int main () {
    scanf("%d%s", &n, str);
    for (int i = 1; i <= n; i++) head[i] = -1;
    for (int i = 1; i < n; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        addedge(u, v), addedge(v, u);
    }

    int ans = inf;
    for (int i = 1; i <= n; i++) {
        dfs(i, 0);
        if (l[i] <= 0) ans = min(ans, r[i] >> 1);
    }
    if (ans >= inf) printf("-1\n");
    else printf("%d\n", ans);
    return 0;
}

