int good(int x, int p, int need, int f = 1)
{
        vector < int > g;
        s[x] = 0;
        if(a[x] == '1'){
                s[x] += f;
        }
        for(int y: v[x]){
                if(y == p){
                        continue;
                }
                need = good(y, x, need, f + 1);
                g.push_back(s[y]);
                s[x] += s[y];
        }
        if(g.empty()){
                return need;
        }
        sort(g.begin(), g.end());
        for(int i = 0; i < g.size(); i++){
                g[i] -= f;
        }
        int sum = 0;
        for(int i = 1; i < g.size(); i++) sum += g[i - 1];
        int can = 0;
        if(sum >= g.back()){
                can = sum + g.back();
        } else{
                can = sum * 2;
        }
        int gg = min(can, need);
        need -= gg;
        s[x] -= gg;
        return need;
}

