void dfs(int x, int fa)
{
	siz[x] = (s[x] == '1'); N += (s[x] == '1');
	int S = v[x].size();
	int tot = 0;
	for(int i = 0; i < S; i++)
	{
		int y = v[x][i];
		if(y == fa) continue;
		dfs(y, x);
	}

	for(int i = 0; i < S; i++)
	{
		int y = v[x][i];
		if(y == fa) continue;
		siz[x] += siz[y];
		f[x] += f[y] + siz[y];
		h[++tot] = y;
	}

	int sum = 0;
	for(int i = 1; i <= tot; i++)
	{
		g[h[i]] += sum;
		sum += f[h[i]] + siz[h[i]];
	}

	sum = 0;
	for(int i = tot; i >= 1; i--)
	{
		g[h[i]] += sum;
		sum += f[h[i]] + siz[h[i]];
	}
}

void dfs2(int x, int fa)
{ 
	if(fa) g[x] = g[x] + g[fa] + N - siz[fa];
	int S = v[x].size();
	int Max = 0, sum = 0;
	for(int i = 0; i < S; i++)
	{
		int y = v[x][i];
		if(y == fa) continue;
		dfs2(y, x);
		Max = std::max(Max, f[y] + siz[y]);
		sum += f[y] + siz[y];
	}
	Max = std::max(Max, g[x] + N - siz[x]); 
	sum += g[x] + N - siz[x];
	if(sum % 2 == 0 && Max <= sum / 2) ans = std::min(ans, sum / 2);
}

