void depth_dfs(int node, int parent) {
    depth[node] = parent < 0 ? 0 : depth[parent] + 1;
    piece_count[node] = S[node] - '0';
    depth_sum[node] = 0;

    for (int neighbor : adj[node])
        if (neighbor != parent) {
            depth_dfs(neighbor, node);
            depth_sum[node] += depth_sum[neighbor] + piece_count[neighbor];
            piece_count[node] += piece_count[neighbor];
        }
}

void answer_dfs(int node, int parent) {
    min_depth_sum[node] = depth_sum[node];
    vector<pair<int, int>> children;

    for (int neighbor : adj[node])
        if (neighbor != parent) {
            answer_dfs(neighbor, node);
            children.emplace_back(depth_sum[neighbor] + piece_count[neighbor], min_depth_sum[neighbor] + piece_count[neighbor]);
        }

    if (!children.empty()) {
        nth_element(children.begin(), --children.end(), children.end());
        int sum_except = 0;

        for (int i = 0; i < (int) children.size() - 1; i++)
            sum_except += children[i].first;

        if (children.back().second <= sum_except) {
            if (parent < 0 && depth_sum[node] % 2 == 0)
                best = min(best, depth_sum[node] / 2);

            min_depth_sum[node] = depth_sum[node] % 2;
        } else {
            min_depth_sum[node] = children.back().second - sum_except;
        }
    }
}

