	dep[u] = dep[fa] + 1,
	all[u] = 1ll * (A[u] - '0') * dep[u];
	for (int v : adj[u]) 
		if (v != fa)
			getAns(v, u), all[u] += all[v];
}

inline bool Judge(int u) {
	long long mx = 0;
	long long sum = 0;
	for (int v : adj[u]) {
		mx = max(mx, all[v]);
		sum += all[v];
	}

	if (mx * 2 > sum)
		return false;
	if (sum & 1)
		return false;
	if (ans == -1)
		ans = sum >> 1;
	else
		ans = min(ans, sum >> 1); 
	return true;
}

int main(void)
{
	ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);

	cin >> n;
	cin >> (A + 1);
	for (int i = 1, u = 0, v = 0;i < n; ++i) 
		cin >> u >> v, adj[u].push_back(v), adj[v].push_back(u);

	bool ok = 0;
	for (int i = 1;i <= n && (ok ^ 1); ++i) {
		dep[i] = 0;
		for (int v : adj[i])
			getAns(v, i);
		ok |= Judge(i);
	}

	cout << ans << '\n';

	return 0;
}

