			low[x]=sl%2; d[x]+=sl/2;
		}
	}else{
		if(sr-p[1].r >= p[1].l) low[x]=0,d[x]+=p[1].l;
		else low[x]=p[1].l-(sr-p[1].r),d[x]+=sr-p[1].r;
	}
}

