			if(son==-1||yl[e->v]+siz[e->v]>yl[son]+siz[son])
				son=e->v;
			add+=Max[e->v]-yl[e->v];
		}
		add-=Max[son]-yl[son];
		if(add>=yl[i]&&!(Max[i]&1))
			ans=min(ans,Max[i]>>1);
	}
	if(ans>=INF) printf("-1\n");
	else printf("%d\n",ans);
	return 0;
}

