const int MAX = 2 * 1e5;
vector<int> g[MAX];
int N;

vector<int> calc(int node) {
    vector<int> d(N, -1);
    d[node] = 0;

    queue<int> q;
    q.push(node);
    while ( !q.empty() ) {
        int x = q.front();
        q.pop();
        for ( int y: g[x] ) {
            if ( d[y] == -1 ) {
                d[y] = d[x] + 1;
                q.push(y);
            }
        }
    }
    return d;
}


