    for (int i = 0; i < N; i++) {
        if ( S[i] == '0' ) {
            continue;
        } else {
            count++;
        }
        vector<int> d(N);
        d = calc(i);
        for (int j = 0; j < N; j++) {
            if ( i != j && S[j] == '1' ) {
                sum += d[j];
            }
        }
