using namespace std;

const int N=2004;
int n,h,x,y;
int a[N],firs[N],f[N],s[N],siz[N];
struct edge { int too,nex; }g[N<<1];

void add (int x,int y)
{
    g[++h].nex=firs[x];
    firs[x]=h;
    g[h].too=y;
}

void update (int &a,int b)
{
    if(b==-1) return;
    if(a==-1) a=b;
    else a=min(a,b);
}

void dfs (int x,int fa)
{
    int j,ms=-1,pos;
    siz[x]=a[x];
    for (R i=firs[x];i;i=g[i].nex)
    {
        j=g[i].too;
        if(j==fa) continue;
        dfs(j,x);
        s[x]+=s[j]+siz[j];
        siz[x]+=siz[j];
		s[j]+=siz[j];
        if(s[j]>ms) ms=s[j],pos=j;
    }
    if(ms==-1) return;
    if(ms*2<=s[x]) f[x]=s[x]/2;
    else f[x]=s[x]-ms+min(f[pos],(2*ms-s[x])/2);
}

int solve (int x)
{
    for (R i=1;i<=n;++i) f[i]=0,s[i]=0,siz[i]=0;
    dfs(x,-1);
    if(s[x]%2) return -1;
    if(f[x]!=s[x]/2) return -1;
    return s[x]/2;
}

int main()
{
    scanf("%d",&n);
    for (R i=1;i<=n;++i)
        scanf("%1d",&a[i]);
    for (R i=1;i<n;++i)
    {
        scanf("%d%d",&x,&y);
        add(x,y); add(y,x);
    }
    int ans=-1;
    for (R i=1;i<=n;++i) update(ans,solve(i));
    printf("%d",ans);
    return 0;
}

