void dfs1(int u,int fa){
	size[u]=s[u]-'0',dis[u]=0;
	for(int i=head[u];i;i=nxt[i]){
		int v=to[i]; if(v==fa) continue; dfs1(v,u);
		size[u]+=size[v],dis[u]+=dis[v]+size[v];
	}
