struct T{
    ll cnt=0,dist_sum=0;
    pair<pll,pll> dist_max={{-LINF,-LINF},{-LINF,-LINF}};
    T& operator+=(T a){
        pll mn={a.dist_min()+a.cnt,a.dist_sum+a.cnt};
        if(mn>dist_max.first)swap(mn,dist_max.first);
        if(mn>dist_max.second)swap(mn,dist_max.second);
        cnt+=a.cnt;
        a.dist_sum+=a.cnt;
        dist_sum+=a.dist_sum;
        return *this;
    }
    ll dist_min() const {
        ll ans=dist_max.first.first-(dist_sum-dist_max.first.second);
        if(ans<0)ans&=1;
        return ans;
    }
};
T operator-(T a,T b){
    pll mn={b.dist_min()+b.cnt,b.dist_sum+b.cnt};
    if(mn==a.dist_max.first)a.dist_max.first=a.dist_max.second;
    a.cnt-=b.cnt;
    b.dist_sum+=b.cnt;
    a.dist_sum-=b.dist_sum;
    return a;
}
