		for(auto &i : c) {
			sz += i.sz;
			sm += i.sm;
			l += i.l;
			msm = max(msm, i.sm);
			ml = max(ml, i.l);
		}
		if(2*msm <= sm) l = sm&1;
		else l = min(l, 2*msm - sm);
		ll cs = 0;
