ll n, m, k, t;

vector <ll> V[maxn];

ll H[maxn];

ll S[maxn];

ll C[maxn];

ll D[maxn];

string s;

void dfs(ll v, ll p) {
    if (v != p) {
        H[v] = H[p] + 1;
    }
    D[v] = 0;
    S[v] = 0;
    C[v] = s[v] - '0';
    ll mx = 0;
    ll sum = 0;
    for (auto v1 : V[v]) {
        if (v1 == p) {
            continue;
        }
        dfs(v1, v);
        C[v] += C[v1];
        S[v] += S[v1];
        S[v] += C[v1];
        ll val = D[v1] + C[v1];
        mx = max(mx, val);
        sum += S[v1] + C[v1];
    }
    D[v] = max(0LL, 2 * mx - sum);
    // cout << v + 1 << " " << S[v] << endl;
}

