		memset(dep, 0, sizeof dep); memset(sz, 0, sizeof sz); sum = 0;
		memset(sdep, 0, sizeof sdep);
		dfs1(rt, 0); if (sum & 1) continue;
		dfs2(rt, 0);
		if (sdep[rt] == 0) ans = min(ans, sum >> 1);
	}
