struct Vertex
{
  ll h, c, l, r;
  Vertex() {}
  Vertex(ll h, ll c = 0, ll l = 0, ll r = 0) : h{h}, c{c}, l{l}, r{r} {}

  void upper()
  {
    l += c;
    r += c;
  }
};

ostream &operator<<(ostream &os, Vertex const &v)
{
  return os << "{h:" << v.h << ", c:" << v.c << ", l:" << v.l << ", r:" << v.r << "}";
}

class Solve
{
  // tree construction
  int N;
  string S;
  vector<vector<int>> V;

  // data structure
  int root;
  vector<Vertex> A;

public:
  Solve(int N, string S, vector<vector<int>> const &V) : N{N}, S{S}, V(V), A(N)
  {
    assert(static_cast<int>(S.size()) == N && static_cast<int>(V.size()) == N);
  }

  ll calc()
  {
    ll ans{infty};
    for (auto i = 0; i < N; i++)
    {
      ch_min(ans, solve(i));
    }
    return ans;
  }

private:
  ll solve(int root)
  {
#if DEBUG == 1
    cerr << "root = " << root << endl;
#endif
    init(root);
    dfs(root);
    if (A[root].l == 0)
    {
      return A[root].r / 2;
    }
    else
    {
      return infty;
    }
  }

  void init(int root)
  {
    Solve::root = root;
    for (auto i = 0; i < N; i++)
    {
      A[i] = Vertex(S[i] - '0');
    }
  }

  void dfs(int v, int parent = -1)
  {
    for (auto e : V[v])
    {
      if (e != parent)
      {
        dfs(e, v);
      }
    }
    ll sum_L{0};
    ll sum_R{0};
    ll maxi_L{0};
    A[v].c += A[v].h;
    for (auto e : V[v])
    {
      if (e != parent)
      {
        A[e].upper();
        A[v].c += A[e].c;
        sum_L += A[e].l;
        sum_R += A[e].r;
        ch_max(maxi_L, A[e].l);
      }
    }
    A[v].r = sum_R;
    if (maxi_L > sum_L - maxi_L)
    {
      A[v].l = sum_R;
      for (auto e : V[v])
      {
        if (e != parent && A[e].l == maxi_L)
        {
          if (A[e].l > sum_R - A[e].r)
          {
            ch_min(A[v].l, A[e].l - (sum_R - A[e].r));
          }
          else
          {
            ch_min(A[v].l, sum_L % 2);
          }
        }
      }
    }
    else
    {
      A[v].l = sum_L % 2;
    }
#if DEBUG == 1
    cerr << "A[" << v << "] = " << A[v] << endl;
#endif
  }
};

