int min_pnt;

// (i) par: parent（NULLのときはcurrがroot)
// (i) curr: current node
// (o) val[0]: curr以下のsubtreeから来るコマの合計手数。ムダなく集めたとき。
//     val[1]: curr以下のsubtreeから来るコマの合計手数。ただし途中でSubtree内部で手数を減らした最小値。
//     val[2]: curr以下のsubtreeから来るコマの個数。
void dfs( int par, int curr, int val[3] )   
{
    int siz=(int)g[curr].size();
    int i;

    val[0]=val[1]=val[2]=0;
    int sum_val1=0;
    int max_val=0;
    for(i=0; i<siz; i++) {
        int next = g[curr][i];
        if(next==par) continue;

        int val_next[3];
        dfs( curr, next, val_next );
        val[0] += val_next[0];
        val[2] += val_next[2];
        sum_val1 += val_next[1];
        max_val = MAX(max_val, val_next[0]+val_next[1]);
    }
    int tmp_val1 = val[0] - max_val;
    if(tmp_val1 >= 0) {
        val[1] = val[0]%2;
    }
    else {
        val[1] = -tmp_val1;
    }

    if(par<0) {
        if(val[1]==0 && val[0]%2==0) {
            min_pnt = MIN(min_pnt, val[0]/2);
        }
#ifdef _DEBUG
        printf("val[0],val[1],min_pnt=%d,%d,%d\n", val[0],val[1],min_pnt);
#endif
    }
    else {
        if(str[curr]=='1') {
            val[2]++;
        }
        val[0]+=val[2];
        val[1]+=val[2];
    }

    return;
}

