int gi() {
	int x=0,o=1;char ch=getchar();
	while((ch<'0'||ch>'9')&&ch!='-') ch=getchar();
	if(ch=='-') o=-1,ch=getchar();
	while(ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
	return x*o;
}

int n,sz[N],sd=0;
pii f[N];
char s[N];
vector<int> E[N];

void dfs(int u,int fa,int dep) {
	f[u]=mp(0,0),sz[u]=s[u]-'0';
	if(sz[u]) sd+=dep;
	for(auto v:E[u]) if(v^fa) dfs(v,u,dep+1),f[u].se+=f[v].se+sz[v],sz[u]+=sz[v];
	int mx=-1,w=0;
	for(auto v:E[u]) if(v!=fa&&f[v].fi+sz[v]>mx) mx=f[v].fi+sz[v],w=v;
	bool fl=1;
	for(auto v:E[u]) if(v!=fa&&v!=w&&f[v].se+sz[v]>=f[w].fi+sz[w]) fl=0;
	if(fl) {
		f[u].fi=f[w].fi+sz[w];
		for(auto v:E[u]) if(v!=fa&&v!=w) f[u].fi-=f[v].se+sz[v];
		f[u].fi=max(f[u].fi,0);
	}
	if(((f[u].fi)&1)!=((f[u].se)&1)) ++f[u].fi;
}

