	return res;
}



pair<int, int> dfs2(int a, int p, int d) {
	int res = 0;
	pair<int, int> pa;
	vector<int> tot;
	int num = 0;
	int sum = 0;
	int mx = 0;
	for (int i : g[a]) {
		if (i != p) {
			pa = dfs2(i, a, d + 1);
			num += pa.second;
			tot.push_back(pa.first + pa.second);
			sum += pa.first + pa.second;
			mx = max(mx, pa.first + pa.second);
		}
	}

	res = max(sum % 2, 2 * mx - sum);

	if (S[a] == '1') {
		num++;
	}
	return make_pair(res, num);
}

