		for (int j : g[i]) {
			int t = dfs(j, i, 1);
			pair<int, int> p = dfs2(j, i, 1);
			sum += t;
			vp.emplace_back(p.first + p.second, t);
		}

		if (sum % 2 == 0) {
			int mx1 = 0;
			int mx2 = 0;

			int mxmn = 0;
			for (int t = 0; t < vp.size(); t++) {
				if (mx1 < vp[t].second) {
					mx2 = mx1;
					mx1 = vp[t].second;
					mxmn = vp[t].first;
				}
				else if (mx2 < vp[t].second) {
					mx2 = vp[t].second;
				}
			}
			bool ok = false;
			if (2 * mx1 <= sum)ok = true;
			else {
				//cerr << mx1 << " " << mx2 << " " << mxmn << endl;
				int n = max(mxmn, mx2 + ((mx1 + mx2) % 2));
				int diff = mx1 - n;

				if (2 * (mx1 - diff) <= (sum - diff) )ok = true;

			}

			if (ok) {
				//cerr << i << endl;
				res = min(res, sum / 2);
			}
		}

	}
	if (res == INF)res = -1;
	cout << res << endl;
