		v[a].push_back(b);
		v[b].push_back(a);
	}
	long long int ans=LLONG_MAX;
	for(int i=0;i<n;i++){
		dfs(i);
		if(dp_min[i]==0LL){
			ans=min(ans,dp_max[i]/2LL);
		}
	}
	if(ans==LLONG_MAX){
		puts("-1");
		return 0;
	}
	printf("%lld\n",ans);
	return 0;
}

