    int cnt = s[v] - '0';
    int sum = 0;
    pii MAX = {0, 0};
    for (int &nv : g[v]) {
      if (nv != p) {
        auto ret = dfs(nv, v);
        cnt += ret.second;
        sum += ret.first.first;
        chmax(MAX, ret.first);
      }
    }
    int omit = min(sum / 2, MAX.second + (sum - MAX.first));
    return ppi({sum + cnt, omit}, cnt);
  };

