typedef long long ll;
const int maxn = 2000 + 10;
const ll INF = 1LL << 60;

int n, h[maxn], ecnt;
ll Ans;
struct enode{
	int v, n;
	enode() {}
	enode(int _v, int _n):v(_v), n(_n) {}
}e[maxn << 1];
char s[maxn];

inline void addedge(int u, int v) { ecnt ++; e[ecnt] = enode(v,h[u]); h[u] = ecnt; }

int sz[maxn], f[maxn], g[maxn], dep[maxn];

inline void Merge(int p, int u, int v) {
	sz[p] = sz[u] + sz[v];
	f[p] = f[u] + f[v];
	if(g[u] > g[v]) swap(u,v);
	if(f[u] > g[v]) g[p] = f[p] % 2;
	else g[p] = g[v] - f[u];
}

void dfs(int u, int fa) {
	sz[u] = f[u] = g[u] = 0;
	for(int i = h[u];~ i;i = e[i].n) {
		int v = e[i].v;
		if(v == fa) continue;
		dep[v] = dep[u] + 1;
		dfs(v,u);
		f[v] += sz[v]; g[v] += sz[v];
		int p = 0; Merge(p,u,v);
		sz[u] = sz[p]; f[u] = f[p]; g[u] = g[p];
	}
	if(s[u] == '1') sz[u] ++;
}

inline void solve(int r) {
	dep[r] = 0;
	dfs(r,0);
	if(g[r] == 0) {
		ll tmp = 0;
		for(int i = 1;i <= n;i ++) if(s[i] == '1') tmp += (ll)dep[i];
		Ans = min(Ans,tmp / 2);
	}
}

int main() {
	scanf("%d", &n); ecnt = 0;
	memset(h,-1,sizeof(h));
	scanf("%s", s + 1);
	for(int i = 1;i < n;i ++) {
		int u, v;
		scanf("%d%d", &u, &v);
		addedge(u,v);
		addedge(v,u);
	}
	Ans = INF;
	for(int i = 1;i <= n;i ++) {
		solve(i);
	}
	if(Ans == INF) Ans = -1;
	printf("%lld\n", Ans);
	return 0;
}

