void DFS(int u, int p)
{
    High[u] = Low[u] = 0;
    Child[u] = Mark[u];
    for (auto v : adj[u])
    {
        if (v != p)
        {
            DFS(v, u);
            Child[u] += Child[v];
            High[v] += Child[v];
            Low[v] += Child[v];
            High[u] += High[v];
        }
    }
    int mx = 0;
    int mxh = 0;
    for (auto v : adj[u])
    {
        if (v != p && High[v] > mxh)
        {
            mxh = High[v];
            mx = Low[v];
        }
    }
    if (mx <= High[u] - mxh)
    {
        Low[u] = High[u] % 2;
    }
    else
    {
        Low[u] = mx - (High[u] - mxh);
    }
}

