int n, a[N], low[N], high[N], cnt[N];
vector <int> ke[N], child[N];
bool cmp(int v1, int v2) {
    return low[v1] > low[v2];
}
void Dfs(int u, int p) {
    cnt[u] = a[u];
    low[u] = high[u] = 0;
    child[u].clear();
    for (auto v: ke[u])
        if (v != p) {
            Dfs(v, u);
            if (cnt[v])
                child[u].push_back(v);
            cnt[u] += cnt[v];
            high[v] += cnt[v];
            low[v] += cnt[v];
            high[u] += high[v];
        }
    if (child[u].size() <= 1) {
        for (auto v: child[u])
            low[u] += low[v];
        return;
    }
    sort(child[u].begin(), child[u].end(), cmp);
    int amax = low[child[u][0]];
    low[u] = amax * 2;
    for (auto v: child[u])
        if (v != p)
            low[u] -= min(amax, high[v]);
    if (low[u] < 0)
        low[u] = (-low[u]) % 2;
}
