pair<long long, long long> cnt_dfs(int curr, int prev) {
    pair<long long, long long> ret = {0, 0};
    // sum, num
    long long maxi = 0;
    for (auto x: v[curr]) {
        if (x == prev) continue;
        auto tmp = cnt_dfs(x, curr);
        if (s[x] == '1') tmp.second++;
        tmp.first += tmp.second;
        maxi = max(maxi, tmp.first);
        ret = {ret.first + tmp.first, ret.second + tmp.second};
    }
    if (prev != -1) return ret;
    else {
        //cout << curr << " " << ret.first << " " << ret.second << " " << maxi << endl;
        if (ret.first >= maxi * 2 && ret.first % 2 == 0) return ret;
        else return {-1, 0};
    }
}

int main() {
    cin >> n; cin >> s;
    for (int i = 0; i < n-1; i++) {
        int a, b; cin >> a >> b;
        a--; b--;
        v[a].emplace_back(b); v[b].emplace_back(a);
    }
    long long ans = 1e18;
    for (int i = 0; i < n; i++) {
        auto it = cnt_dfs(i, -1);
        //cout << i << " " << it.first << " " << it.second << endl;
        long long u = it.first;
        if (u != -1) {
            ans = min(ans, u / 2);
        }
    }
    assert(ans != 1e18);
    if (ans == 1e18) cout << -1 << endl;
    else cout << ans << endl;
    return 0;
}

