ll cnt(int v, int d = 1) {
	used[v] = 1;

	ll c = (s[v] == '1') * d;
	for (auto to : gr[v]) {
		if (!used[to]) {
			c += cnt(to, d + 1);
		}
	}

	return c;
}

ll mincnt(int v, int d = 1) {
	used[v] = 1;

	ll c = (s[v] == '1') * d, c2 = 0;
	for (auto to : gr[v]) {
		if (!used[to]) {
			ll q = mincnt(to, d + 1);
			ll k = min(c2, q);
			q -= k;
			c2 -= k;
			c2 += q;
		}
	}

	return c + c2;
}

