                    l=0;
                }
                if(a>=l&&a<=r)l=0;
                if(a<=l){
                    l=min(l-a,b-r);
                }
                if(a>=r) l=a-r;
            }
            else{
                r=r+b;
                if(b<=l){
                    l=l-b;
                }
                if(b<=r){
                    l=1;
                }
                if(a>=l&&a<=r)l=1;
                if(a<=l){
                    l=min(l-a,b-r);
                }
                if(a>=r) l=a-r;
            }
        }
