const int INF=2e9,N=5005;
int n,a,b,k,ans=INF;
char s[N];
int head[N],d[N],f[N],size[N];
struct edge{int v,next;}e[N<<1];

inline void add(int u,int v)
{
    e[++k]=(edge){v,head[u]};
    head[u]=k;
}

inline void prepare(void)
{
    memset(d,0,sizeof(d));
    memset(size,0,sizeof(size));
    memset(f,0,sizeof(f));
}

inline int min(int a,int b)
{
	return a<b?a:b;
}

inline void DFS(int u,int fa)
{
    size[u]=s[u]-'0';
    register int son=0;
    for(register int i=head[u];i;i=e[i].next)
    {
        if(e[i].v==fa) continue;
        DFS(e[i].v,u);
        size[u]+=size[e[i].v];
        d[e[i].v]+=size[e[i].v],d[u]+=d[e[i].v];
        if(d[son]<=d[e[i].v]) son=e[i].v;
    }
    if(!son) f[u]=0;
    else if(d[u]>=d[son]<<1) f[u]=d[u]>>1;
    else f[u]=d[u]-d[son]+min(f[son],((d[son]<<1)-d[u])>>1);
}

