using namespace std;

const ll N = 1e5 + 5, INF = 1e18;

ll ans = INF;
vector < ll > g[N];

ll n;
ll a[N];
ll s[N];
ll dp[N], DP[N];


void dfs (ll k, ll p){
    s[k] = a[k];
    ll sum = 0, ma = 0;
    for (ll i = 0; i < (ll)g[k].size(); i++){
        ll u = g[k][i];
        if (u == p)
            continue;
        dfs (u, k);
        s[k] += s[u];
        DP[k] += DP[u];
        ll x = s[u] + dp[u];
        ma = max (ma, x);
        sum += x;
    }
    if (ma * 2 > sum){
        dp[k] = ma * 2 - sum;
        DP[k] += sum - ma;
    }
    else {
        dp[k] = sum % 2;
        DP[k] += sum / 2;
    }
}



main()
{
    //freopen ("in.in", "r", stdin);freopen ("out.out", "w", stdout);
    ios_base::sync_with_stdio(false);
    cin >> n;
    string s;
    cin >> s;
    for (ll i = 0; i < n; i++)
        a[i + 1] = s[i] - '0';
    for (ll i = 1; i < n; i++){
        ll u, v;
        cin >> u >> v;
        g[u].pb (v);
        g[v].pb (u);
    }
    for (ll i = 1; i <= n; i++){
        for (ll j = 1; j <= n; j++){
            s[j] = 0;
            dp[j] = 0;
            DP[j] = 0;
        }
        dfs (i, 0);
        if (dp[i] == 0)
            ans = min (ans, DP[i]);
    }
    if (ans == INF)
        ans = -1;
    cout << ans << endl;
    return 0;
}

