	if(dp[par][pos] != -1) return dp[par][pos];
	vector<ll> v;
	REP(i, tree[pos].size()) {
		if(tree[pos][i] == par) continue;
		v.pb(dfs1(pos, tree[pos][i]) + node[pos][tree[pos][i]]);
	}
	sort(ALL(v));
	int m = (int)v.size();
	if(m == 0) return dp[par][pos] = 0;
	if(m == 1) {
		return dp[par][pos] = v[0];
	}
	ll sum = 0;
	REP(i, m) sum += v[i];
	if(v[m - 1] > sum - v[m - 1]) {
		return dp[par][pos] = v[m - 1] - (sum - v[m - 1]);
	} else {
		if(sum % 2) return dp[par][pos] = 1;
		else return dp[par][pos] = 0;
	}
}

ll dfs2(ll par, ll pos) {
	if(node[par][pos] != -1) return node[par][pos];
	ll ret = 0;
	if(s[pos] == '1') ret++;
	REP(i, tree[pos].size()) {
		if(tree[pos][i] == par) continue;
		ret += dfs2(pos, tree[pos][i]);
	}
	return node[par][pos] = ret;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> n;
	cin >> s;
	tree.resize(n);
	dp.assign(n, vector<ll>(n, -1));
	node.assign(n, vector<ll>(n, -1));
	REP(i, n - 1) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		tree[a].pb(b);
		tree[b].pb(a);
	}
	REP(i, n) REP(j, tree[i].size()) {
		dfs2(i, tree[i][j]);
	}
	REP(i, n) REP(j, tree[i].size()) {
		dfs1(i, tree[i][j]);
	}
	ll ans = INF * INF;
	REP(i, n) {
		vector<int> d;
		REP(j, tree[i].size()) {
			d.pb(dp[i][tree[i][j]] + node[i][tree[i][j]]);
		}
		sort(ALL(d));
		int m = (int)d.size();
		ll sum = 0;
		REP(j, m) sum += d[j];
		if(sum % 2) continue;
		if(d[m - 1] <= sum - d[m - 1]) ans = min(ans, sum / 2);
	}
	if(ans == INF * INF) {
		cout << -1 << endl;
	} else cout << ans << endl;
	return 0;
}

