        for(int i = 1; i < g.size(); i++) sum += g[i - 1];
        int can = 0;
        if(sum >= g.back()){
                can = sum + g.back();
        } else{
                can = sum * 2;
        }
        int gg = min(can, need);
        need -= gg;
        s[x] -= gg;
        return need;
}

