		priority_queue<int> &q = Q[u];
		while (!q.empty())
			q.pop();
		for (int v : E[u])
			if (v != f)
			{
				q.push(dfs(v, u));
				size[u] += size[v];
			}
		while (q.size() > 1)
		{
			int a = q.top();
			q.pop();
			int b = q.top();
			q.pop();
			a--, b--, ans++;
			if (a)
				q.push(a);
			if (b)
				q.push(b);
		}	
		return size[u] + (q.empty() ? 0 : q.top());
	}

	void work()
	{
		scanf("%d%s", &n, str + 1);
		int tot = 0;
		for (int i = 1; i <= n; i++)
			if (str[i] == '1')
				A[i] = 1, ++tot;
