			E[v].push_back(u);
		}
		int mn = INT_MAX;
		for (int i = 1; i <= n; i++)
		{
			ans = 0;
			if (dfs(i, 0) == tot)
				mn = min(mn, ans);
		}
		printf("%d\n", mn == INT_MAX ? -1 : mn);
	}
}

