int dp[N], sub[N], dsum[N];
string s;
int n;

void dfs(int u, int p, int d) {
    sub[u] = (s[u] == '1');
    dsum[u] = (s[u] == '1' ? d : 0);
    int all_sum = 0;
    vector<pair<int,int>> bottom;
    for(int v : G[u]) {
        if(v == p) continue;
        dfs(v, u, d+1);
        sub[u] += sub[v];
        dsum[u] += dsum[v];
        if(sub[v]) {
            bottom.push_back({sub[v]+dp[v], v});
            all_sum += sub[v]+dp[v];
        }
    }
    sort(bottom.begin(), bottom.end());
    if(bottom.empty()) dp[u] = 0;
    else {
        if(bottom.size() == 1) dp[u] = bottom[0].first;
        else {
            int most = 0;
            for(int i = 0; i+1 < bottom.size(); i++) {
                int v = bottom[i].second;
                most += dsum[v] - d * sub[v];
            }
            dp[u] = max(bottom.back().first - most, all_sum&1);
        }
    }
}

