	Edge(const int &v,const int &next) :v(v),next(next) {}
	Edge() {}
}e[maxn<<1];
int head[maxn],k;
inline void AddEdge(const int &u,const int &v) {
	e[++k]=Edge(v,head[u]);
	head[u]=k;
