	int maxp=0;cnt[u]=s[u]-'0';
	for(int i(head[u]);i;i=e[i].next) {
		const int &v=e[i].v;
		if(v==fa) continue;
		dfs(v,u);
		cnt[u]+=cnt[v];
		sum[u]+=(sum[v]+=cnt[v]);//因为sum[maxp]要和sum[u]比大小，或者说当前转化为从u出发。所以要加上cnt[v]
		if(sum[v]>sum[maxp]) maxp=v;
	}
	if(!maxp) return;
	if(sum[u]>=2*sum[maxp]) f[u]=sum[u]/2;
	else f[u]=sum[u]-sum[maxp]+min(f[maxp],(2*sum[maxp]-sum[u])/2);
}

