#define MAX_N (2000L)
#define INF (1000000000000000000L)

using namespace std;

long calc_total_depth(const vector<vector<long>> &adj_lists, const char *cs,
                      long cur, long d, long par) {
  const long N = adj_lists.size();
  long ret = cs[cur] == '1' ? d : 0L;
  for (long nxt : adj_lists[cur]) {
    if (nxt != par) {
      ret += calc_total_depth(adj_lists, cs, nxt, d + 1, cur);
    }
  }
  return ret;
}

int main(int argc, char *argv[]) {
  // read inputs
  long N, as[MAX_N], bs[MAX_N];
  char cs[MAX_N + 1];
