  for (long i = 0; i < N - 1; i++) {
    scanf("%ld %ld", &as[i], &bs[i]);
    as[i]--;  // NOTE : modified input
    bs[i]--;  // NOTE : modified input
  }

  // create adj_lists
  vector<vector<long>> adj_lists(N, vector<long>());
  for (long i = 0; i < N - 1; i++) {
    const long a = as[i], b = bs[i];
    adj_lists[a].push_back(b);
    adj_lists[b].push_back(a);
  }

  // solve
  long ans = INF;
  for (long i = 0; i < N; i++) {
    long total_depth = 0, max_depth = 0;
    for (long nxt : adj_lists[i]) {
      const long depth = calc_total_depth(adj_lists, cs, nxt, 1, i);
      total_depth += depth;
      max_depth = max(max_depth, depth);
    }
    // check if possible
    if (total_depth % 2 == 0 && 2 * max_depth <= total_depth) {
      ans = min(ans, total_depth / 2);
    }
  }
  printf("%ld\n", ans < INF ? ans : -1);

  return 0;
}

