void dfs(int v, int par, int cd)
{
	siz[v] = S[v] == '1';
	sum[v] = 0;
	rep(i, G[v].size()) {
		int u = G[v][i];
		if(u == par) continue;
		dfs(u, v, cd + 1);
		siz[v] += siz[u];
		sum[v] += sum[u];
	}
	sum[v] += siz[v];
}

pair<int, int> solve(int v, int par)
{
	int tots = 0, maxs = 0, maxg = -1;
	rep(i, G[v].size()) {
		if(G[v][i] == par) continue;
		tots += sum[G[v][i]];
		maxs = max(maxs, sum[G[v][i]]);
		if(maxs == sum[G[v][i]]) maxg = G[v][i];
	}
	PII cur = MP(0, 0);
	if(tots % 2 == 1) return MP(INF, INF);
	else if(tots < maxs * 2) {
		cur = solve(maxg, v);
		if(cur != MP(INF, INF)) maxs -= cur.first;
		else cur.first = 0;
	}
	if(tots < maxs * 2) return MP(tots - maxs, tots / 2);
	else return MP(tots / 2, tots / 2);
}

