int n;
string s;
vector<vector<int>> tree;
vector<vector<P>> dp;
vector<vector<ll>> node;

P dfs1(ll par, ll pos) {
	if(dp[par][pos].first != -1) return dp[par][pos];
	vector<P> v;
	REP(i, tree[pos].size()) {
		if(tree[pos][i] == par) continue;
		P tmp = dfs1(pos, tree[pos][i]);
		tmp.first += node[pos][tree[pos][i]];
		tmp.second += node[pos][tree[pos][i]];
		v.pb(tmp);

	}
	int m = (int)v.size();
	if(m == 0) return dp[par][pos] = P(0, 0);
	if(m == 1) {
		return dp[par][pos] = v[0];
	}
	ll mx = 0, mn = 0;
	REP(i, m) mx += v[i].second;
	REP(i, m) swap(v[i].first, v[i].second);
	REP(i, m) v[i].second = -v[i].second;
	sort(ALL(v));
	REP(i, m) v[i].second = -v[i].second;
	ll tmp1 = v[m - 1].first, tmp2 = 0;
	REP(i, m - 1) {
		if(v[i].second >= tmp1) tmp2 += tmp1;
		else tmp2 += v[i].second;
	}
	if(tmp1 > tmp2) {
		mn = tmp1 - tmp2;
	} else {
		if(tmp1 == tmp2 && (tmp1 + tmp2) % 2) mn = 1;
		else mn = 0;
	}
	return dp[par][pos] = P(mn, mx);
}

ll dfs2(ll par, ll pos) {
	if(node[par][pos] != -1) return node[par][pos];
	ll ret = 0;
	if(s[pos] == '1') ret++;
	REP(i, tree[pos].size()) {
		if(tree[pos][i] == par) continue;
		ret += dfs2(pos, tree[pos][i]);
	}
	return node[par][pos] = ret;
}

