	node.assign(n, vector<ll>(n, -1));
	REP(i, n - 1) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		tree[a].pb(b);
		tree[b].pb(a);
	}
	REP(i, n) REP(j, tree[i].size()) {
		dfs2(i, tree[i][j]);
	}
	REP(i, n) REP(j, tree[i].size()) {
		dfs1(i, tree[i][j]);
	}
	ll ans = INF * INF;
	REP(i, n) {
		vector<P> d;
		REP(j, tree[i].size()) {
			P tmp = dp[i][tree[i][j]];
			tmp.first += node[i][tree[i][j]];
			tmp.second += node[i][tree[i][j]];
			d.pb(tmp);
		}
		int m = (int)d.size();
		ll mx = 0, mn = 0;
		REP(i, m) mx += d[i].second;
		REP(i, m) swap(d[i].first, d[i].second);
		REP(i, m) d[i].second = -d[i].second;
		sort(ALL(d));
		REP(i, m) d[i].second = -d[i].second;
		ll tmp1 = d[m - 1].first, tmp2 = 0;
		REP(i, m - 1) {
			if(d[i].second >= tmp1) tmp2 += tmp1;
			else tmp2 += d[i].second;
		}
		if(tmp1 > tmp2) {
			mn = tmp1 - tmp2;
		} else {
			if(tmp1 == tmp2 && (tmp1 + tmp2) % 2) mn = 1;
			else mn = 0;
		}

		if(mn == 0 && mx % 2 == 0) {
			ans = min(ans, mx / 2);
		}
	}
	if(ans == INF * INF) {
		cout << -1 << endl;
	} else {
		cout << ans << endl;
	}
	return 0;
}

