void Calculate_Depth(vector<vector<int>>&edge, vector<int>&depth, int stnode) {
	depth[stnode] = 0;
	queue<int>Q;
	Q.push(stnode);
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		for (auto i : edge[cn]) {
			if (depth[i] > depth[cn] + 1) {
				depth[i] = depth[cn] + 1;
				Q.push(i);
			}
		}
	}
	return;
}

void Search(const vector<vector<int>>&edge, const vector<int>&depth, vector<int>&sum, vector<int>&num, vector<int>&mini, const string&s, int node) {
	if (s[node] == '1')num[node] = 1;
	for (auto i : edge[node]) {
		if (depth[i] < depth[node])continue;
		Search(edge, depth, sum, num, mini, s, i);
		num[node] += num[i];
		sum[node] += num[i] + sum[i];
	}
	for (auto i : edge[node]) {
		if (depth[i] < depth[node])continue;
		if (sum[node] < (num[i] + sum[i]) * 2) {
			mini[node] = max(0, (mini[i] + num[i]) * 2 - (sum[node]-(sum[i]-mini[i])));
		}
	}
	return;
}

