char s[N];int dep[N],top[N],fa[N],sz[N],son[N],n,tmp;ll res;
void dfs1(int u){
    sz[u]=1,dep[u]=dep[fa[u]]+1;
    go(u)if(v!=fa[u]){
        fa[v]=u,dfs1(v),sz[u]+=sz[v];
        if(sz[v]>sz[son[u]])son[u]=v;
    }
}
void dfs2(int u,int t){
    top[u]=t;if(!son[u])return;
	dfs2(son[u],t);
    go(u)if(v!=fa[u]&&v!=son[u])dfs2(v,v);
}
inline int LCA(R int u,R int v){
	while(top[u]!=top[v]){
		if(dep[top[u]]<dep[top[v]])swap(u,v);
		u=fa[top[u]];
	}
	return dep[u]<dep[v]?u:v;
}
inline int dis(R int u,R int v){return dep[u]+dep[v]-(dep[LCA(u,v)]<<1);}
