using namespace std;
typedef pair<llint, llint> P;

llint n;
string s;
vector<llint> G[2005];
llint cnt[2005], sum[2005], rem[2005];

llint cntdfs(llint v, llint p)
{
	cnt[v] = s[v]-'0';
	for(llint i = 0; i < G[v].size(); i++){
		if(G[v][i] == p) continue;
		cnt[v] += cntdfs(G[v][i], v);
	}
	return cnt[v];
}

llint sumdfs(llint v, llint p)
{
	sum[v] = 0;
	for(llint i = 0; i < G[v].size(); i++){
		if(G[v][i] == p) continue;
		sum[v] += sumdfs(G[v][i], v) + cnt[G[v][i]];
	}
	return sum[v];
}

llint remdfs(llint v, llint p)
{
	llint Sum = 0, Max = 0, Max_u;
	for(llint i = 0; i < G[v].size(); i++){
		if(G[v][i] == p) continue;
		Sum += sum[G[v][i]] + cnt[G[v][i]];
		if(Max < sum[G[v][i]] + cnt[G[v][i]]){
			Max = sum[G[v][i]] + cnt[G[v][i]];
			Max_u = G[v][i];
		}
	}
	if(Max <= Sum/2) return rem[v] = 0;
	return rem[v] = max(0LL, rem[Max_u]+cnt[Max_u] - (Sum-Max));
}

int main(void)
{
	cin >> n >> s;
	s = "#" + s;
	llint u, v;
	for(llint i = 1; i <= n-1; i++){
		cin >> u >> v;
		G[u].push_back(v);
		G[v].push_back(u);
	}

	llint ans = inf;
	for(llint i = 1; i <= n; i++){
		cntdfs(i, -1), sumdfs(i, -1), remdfs(i, -1);
		//cout << i << " " << sum[i] << " " << rem[i] << endl;
		//for(int j = 1; j <= n; j++) cout << rem[j] << " "; cout << endl;
		if(sum[i] % 2 == 0 && rem[i] <= 0) ans = min(ans, sum[i]/2);
	}
	if(ans >= inf) ans = -1;
	cout << ans << endl;

	return 0;
}

