pair<ll, ll> dfs(ll now, ll from){
  pair<ll, ll> ret(0, 0);
  if(s[now]=='1') ret.first++;
  for(auto to:G[now]){
    if(from==to) continue;
    pair<ll, ll> p = dfs(to, now);
    p.second += p.first;
    ret.first += p.first;
    ret.second += p.second;
  }
  return state[now] = ret;
}

//操作の回数、深さの和
pair<ll, ll> dfs2(ll now, ll from){
  pair<ll, ll> ret(0, 0);
  ll m = -1, m_tm = -1;//深さ、操作回数
  pair<ll, ll> S(0, 0);
  for(auto to:G[now]){
    if(from==to) continue;
    pair<ll, ll> p = dfs2(to, now);
    p.second += state[to].first;
    ret.first += p.first;
    ret.second += p.second;
    S.first += p.first;
    S.second += p.second;

    if(m<p.second){
      m = p.second;
      m_tm = p.first;
    }
  }
  if(m==-1) return ret;
  S.first -= m_tm;
  S.second -= m;
  if(S.second+S.first*2>=m){
    ll tm = (S.second+m)/2;
    ret.first += tm;
    ret.second -= tm*2;
  }else{
    ll tm = S.second+S.first*2;
    ret.first -= S.first;
    ret.second += S.first*2;
    ret.first += tm;
    ret.second -= tm*2;
  }
  return ret;
}
