#define all(x) (x).begin(),(x).end()
const int mod=1000000007,MAX=2005,INF=1<<30;
bool exist[MAX];
vector<int> G[MAX];
int depth[MAX],cnt[MAX];
vector<pair<int,int>> dis;

void DFS(int u,int p){
    for(int to:G[u]){
        if(to==p) continue;

        depth[to]=depth[u]+1;
        DFS(to,u);
        cnt[u]+=cnt[to];
    }
    if(exist[u]) cnt[u]++;
}

pair<int,int> solve(int u,int p){
    pair<int,int> sum={0,0};
    vector<int> T;
    for(int to:G[u]){
        if(to==p) continue;
        pair<int,int> a=solve(to,u);
        sum.first+=a.first;
        sum.second+=a.second;

        if(a.first-2*a.second-cnt[to]*depth[u]) T.push_back(a.first-2*a.second-cnt[to]*depth[u]);
    }
    if(exist[u]){
        sum.first+=depth[u];
    }

    sort(all(T));
    int s=0;
    for(int i=0;i<T.size();i++) s+=T[i];

    if(T.size()) sum.second+=min(s/2,s-T.back());
    return sum;
}

int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;cin>>N;

    string S;cin>>S;
    for(int i=0;i<N;i++){
        if(S[i]=='1') exist[i]=1;
    }

    for(int i=0;i<N-1;i++){
        int a,b;cin>>a>>b;
        a--;b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    int ans=INF;

    for(int i=0;i<N;i++){
        memset(depth,0,sizeof(depth));
        memset(cnt,0,sizeof(cnt));
        dis.clear();
        DFS(i,-1);

        for(int to:G[i]){
            pair<int,int> a=solve(to,i);
            if(a.first) dis.push_back(a);
        }
        if(dis.size()==0){
            ans=0;
            continue;
        }
        sort(all(dis));

        int sum=0;
        for(pair<int,int> a:dis) sum+=a.first;
        if(sum%2==0){
            if(dis.back().first*2<=sum) ans=min(ans,sum/2);
            else{
                if(dis.back().first-dis.back().second<=(sum-dis.back().first)) ans=min(ans,sum/2);
            }
        }
    }

    if(ans==INF) ans=-1;
    cout<<ans<<endl;
}

