using namespace std;

const int INF = 1e9;

const int MAXN = 2333;
int N;
string S;
vector<int> adj[MAXN];
int subcnt[MAXN], dpmi[MAXN], dpma[MAXN];

void dfs(int cur, int prv = -1) {
	int maxmi = -1;
	int maxma = -1;
	subcnt[cur] = (S[cur] == '1');
	dpmi[cur] = dpma[cur] = 0;
	for (int nxt : adj[cur]) {
		if (nxt == prv) continue;
		dfs(nxt, cur);

		subcnt[cur] += subcnt[nxt];
		dpma[cur] += dpma[nxt] + subcnt[nxt];
		if (dpmi[nxt] + subcnt[nxt] > maxmi) {
			maxmi = dpmi[nxt] + subcnt[nxt];
			maxma = dpma[nxt] + subcnt[nxt];
		}
	}

	dpmi[cur] = max(maxmi - (dpma[cur] - maxma), dpma[cur] % 2);
}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> N;
	cin >> S;
	for (int i = 0; i < N-1; i++) {
		int a, b; cin >> a >> b; a--, b--;
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	int ans = INF;
	for (int root = 0; root < N; root++) {
		dfs(root);
		if (dpmi[root] == 0) {
			ans = min(ans, dpma[root] / 2);
		}
	}
	if (ans == INF) {
		ans = -1;
	}
	cout << ans << endl;

	return 0;
}

