const int N = 2222;
vector<int> a[N];
string s;

long long level[N];
long long cnt[N];
long long suml[N];

long long dfs(int v, int p) {
	long long res = 0;
	if (s[v] == '1') {
		res += level[v];
	}
	vector<long long> cnts;
	vector<long long> to;
	vector<long long> sumls;
	for (int x : a[v]) {
		if (x != p) {
			level[x] = level[v] + 1;
			long long tmp = dfs(x, v);
			res += tmp;
			sumls.push_back(tmp);
			cnts.push_back(cnt[x]);
			to.push_back(x);
		}
	}
	if (!sumls.empty()) {
		int idx = max_element(all(sumls)) - sumls.begin();
		if (res / 2 < sumls[idx]) {
			long long zbs = min(cnts[idx], sumls[idx] - res / 2);
			cnt[v] = zbs + min(res / 2 - zbs, res - cnts[idx] - zbs);
		} else {
			cnt[v] = res / 2;
		}
	} else {
		cnt[v] = 0;
	}
	return suml[v] = res;
}

long long solve(int r) {
	memset(level, 0, sizeof(level));
	memset(cnt, 0, sizeof(cnt));
	vector<long long> dsts;
	for (int x : a[r]) {
		level[x] = 1;
		dsts.push_back(dfs(x, r));
	}
	long long sum = accumulate(all(dsts), 0ll);
	if (sum % 2) {
		return -1;
	}
	if (*max_element(all(dsts)) * 2 > sum) {
		int idx = max_element(all(dsts)) - dsts.begin();
		int x = a[r][idx];
		long long zbs = min(cnt[x], dsts[idx] * 2 - sum);
		if (zbs == dsts[idx] * 2 - sum) {
			return sum / 2;
		} else {
			return -1;
		}
	} else {
		return sum / 2;
	}
}

int main() {
	int n = nxt();
	cin >> s;
	for (int i = 0; i < n - 1; ++i) {
		int u = nxt() - 1, v = nxt() - 1;
		a[u].push_back(v);
		a[v].push_back(u);
	}

	long long ans = -1;
	for (int r = 0; r < n; ++r) {
		long long tmp = solve(r);
		if (ans == -1 || (tmp > -1 && tmp < ans)) {
			ans = tmp;
		}
	}

	cout << ans << "\n";

	return 0;
}

