typedef long long ll;
struct number {
  int siz, low, high;
  number(): siz(0), low(0), high(0) {
  }
};
int main() {
  do {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
  } while (false);
  int n, ans = INT_MAX;
  cin >> n;
  string str;
  cin >> str;
  vector<vector<int> > adj(n);
  for (int i = 1; i < n; i++) {
    int u, v;
    cin >> u >> v;
    adj[--u].push_back(--v);
    adj[v].push_back(u);
  }
  auto add_edge = [&] (number a) {
    a.low += a.siz;
    a.high += a.siz;
    return a;
  };
  auto add = [&] (number a, number b) {
    number res;
    res.siz = a.siz + b.siz;
    res.high = a.high + b.high;
    if (a.low > b.low) {
      swap(a, b);
    }
    if (a.high > b.low) {
      res.low = res.high % 2;
    } else {
      res.low = b.low - a.high;
    }
    return res;
  };
  for (int root = 0; root < n; root++) {
    vector<number> value(n);
    function<int (int, int, int)> dfs = [&] (int u, int fa, int dep) {
      int res = 0;
      for (int v : adj[u]) {
        if (v != fa) {
          res += dfs(v, u, dep + 1);
          value[u] = add(value[u], add_edge(value[v]));
        }
      }
      if (str[u] == '1') {
        value[u].siz++;
        res += dep;
      }
      return res;
    };
    int res = dfs(root, -1, 0);
    if (!value[root].low) {
      ans = min(ans, res / 2);
    }
  }
  cout << (ans == INT_MAX ? -1 : ans) << endl;
  return 0;
}

