int sum[maxn], cnt[maxn], dp[maxn];

void dfs(int v, int p) {
  sum[v] = 0;
  cnt[v] = (s[v] == '1');
  int maxu = -1;
  for (int i = 0; i < sz(g[v]); i++) {
    int u = g[v][i];
    if (u == p) {
      continue;
    }
    dfs(u, v);
    sum[v] += sum[u] + cnt[u];
    cnt[v] += cnt[u];
    if (maxu == -1 || sum[u] + cnt[u] > sum[maxu] + cnt[maxu]) {
      maxu = u;
    }
  }
  if (maxu == -1) {
    dp[v] = sum[v];
    return;
  }
  int x = sum[maxu] + cnt[maxu];
  int y = dp[maxu] + cnt[maxu];
  if (2 * x <= sum[v]) {
    dp[v] = (sum[v] & 1);
    return;
  }
  if (2 * y <= sum[v] - (x - y)) {
    dp[v] = (sum[v] & 1);
    return;
  }
  int z = sum[v] - (x - y) - y;
  dp[v] = y - z;
}

