array<int, 3> go(auto& adj, const string& st, int loc, int par) {
    int stones = 0;
    int sum_lo = 0, sum_hi = 0;

    vector<array<int, 2>> cres;
    for (int nbr : adj[loc]) if (nbr != par) {
        auto cr = go(adj, st, nbr, loc);

        stones += cr[2];
        sum_lo += cr[0] + cr[2];
        sum_hi += cr[1] + cr[2];
        cres.push_back({ cr[0] + cr[2], cr[1] + cr[2] });
    }

    int lo = sum_lo, hi = sum_hi;
    if (cres.size()) {
        sort(all(cres));
        auto big = cres.back();
        if (big[0] <= sum_hi - big[1]) {
            lo = sum_lo & 1;
        } else {
            lo = big[0] - (sum_hi - big[1]);
        }
    }

    stones += st[loc] == '1';
    return { lo, hi, stones };
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int N;
    string str;
    cin >> N >> str;

    vvi adj(N);
    vi u(N - 1), v(N - 1);

    for (int i = 0; i < N - 1; i++) {
        cin >> u[i] >> v[i];
        --u[i], --v[i];
        adj[u[i]].push_back(v[i]);
        adj[v[i]].push_back(u[i]);
    }

    int ans = INT_MAX;
    for (int i = 0; i < N; i++) {
        auto r = go(adj, str, i, i);
        if (r[0] == 0) ans = min(ans, r[1] / 2);
    }
    cout << (ans < INT_MAX ? ans : -1) << endl;

    return 0;
}

