const int INF = 1e9 + 7;

int n;
char S[2005]; 
vector<int> G[2005];
int dep[2005], sum[2005];

void dfs(int v, int par, int cd)
{
	dep[v] = cd;
	sum[v] = S[v] == '1' ? dep[v] : 0;
	rep(i, G[v].size()) {
		int u = G[v][i];
		if(u == par) continue;
		dfs(u, v, cd + 1);
		sum[v] += sum[u];
	}
}

int solve(int v)
{
	dfs(v, -1, 0);
	int tots = 0, maxs = 0;
	rep(i, G[v].size()) {
		tots += sum[G[v][i]];
		maxs = max(maxs, sum[G[v][i]]);
	}
	if(tots % 2 == 1) return INF;
	else return tots / 2;
}

int main()
{
	scanf("%d%s", &n, S + 1);
	rep(i, n - 1) {
		int u, v;
		scanf("%d%d", &u, &v);
		G[u].push_back(v);
		G[v].push_back(u);
	}

	int ret = INF;
	rep1(i, n) ret = min(ret, solve(i));
	printf("%d\n", ret >= INF ? -1 : ret);
	return 0;
}

