bitset<SIZE> bs;
const ll inf = 5e15;

PLL dfs(ll cur, ll pre) {
    ll cnt = bs.test(cur), dsum = 0;
    for (ll nxt : edges[cur]) if (nxt != pre) {
        ll a, b;
        tie(a, b) = dfs(nxt, cur);
        cnt += a;
        dsum += b;
    }
    return PLL(cnt, dsum + cnt);
}

ll calc(ll root) {
    V<PLL> res;
    ll sum = 0;
    for (ll nxt : edges[root]) {
        auto tmp = dfs(nxt, root);
        sum += tmp.second;
        res.push_back(tmp);
    }

    DEBUG(make_tuple(root, res));
    if (sum & 1) return inf;
    for (auto &&e : res) {
        ll a = e.second;
        if (sum - a < a) return inf;
    }
    DEBUG(make_tuple(root, sum));
    return sum / 2;
}

ll solve() {
