#include <bits/stdc++.h>

using namespace std;
int n;
string s;
const int N = 3000;
vector<int> ed[N];
int sz[N];
int hg[N];
int dp[N];

void precalc(int v, int p, int h) {
    sz[v] = s[v - 1] - '0';
    hg[v] = h;
    for (auto to: ed[v]) {
        if (to == p) {
            continue;
        }
        precalc(to, v, h + 1);
        sz[v] += sz[to];
    }
}

bool good(priority_queue<int> hp) {
    while (hp.size() > 1) {
        int u = hp.top();
        hp.pop();
        int v = hp.top();
        hp.pop();
        if (u == 0 && v == 0) {
            continue;
        } else if (u == 0 || v == 0) {
            return false;
        } else {
            u--;
            v--;
            hp.push(u);
            hp.push(v);
        }
    }
    if (hp.size() == 1 && hp.top() != 0) {
        return false;
    }
    return true;
}

void dfs(int v, int p) {
    int cnt = 0;
    int sum = 0;
    priority_queue<pair<int, int> > hp;
    for (auto to: ed[v]) {
        if (to == p) {
            continue;
        }
        dfs(to, v);
        hp.push(make_pair(dp[to], to));
    }
    while (hp.size() > 1) {
        auto a = hp.top();
        hp.pop();
        auto b = hp.top();
        hp.pop();
        if (a.first == hg[v] * sz[a.second] || b.first == hg[v] * sz[b.second]) {
            hp.push(a);
            hp.push(b);
            break;
        } else {
            a.first--;
            b.first--;
            hp.push(a);
            hp.push(b);
        }
    }
    dp[v] = 0;
    while (hp.size() > 0) {
        dp[v] += hp.top().first;
        hp.pop();
    }
    if (s[v - 1] == '1') {
        dp[v] += hg[v];
    }
}

int main() {
    cin >> n;
    cin >> s;
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        ed[u].push_back(v);
        ed[v].push_back(u);
    }
    int ans = n * n + 20;
    for (int root = 1; root <= n; root++) {
        precalc(root, 0, 0);
        int sum = 0;
        for (int i = 1; i <= n; i++) {
            if (s[i - 1] == '1') {
                sum += hg[i];
            }
        }
        if (sum % 2 == 1) {
            continue;
        }
        dfs(root, 0);
        if (dp[root] == 0) {
            ans = min(ans, sum / 2);
        }
    }
    if (ans == n * n + 20) {
        cout << "-1\n";
    } else {
        cout << ans << "\n";
    }
    return 0;
}

