namespace zyt
{
	template<typename T>
	inline bool read(T &x)
	{
		char c;
		bool f = false;
		x = 0;
		do
			c = getchar();
		while (c != EOF && c != '-' && !isdigit(c));
		if (c == EOF)
			return false;
		if (c == '-')
			f = true, c = getchar();
		do
			x = x * 10 + c - '0', c = getchar();
		while (isdigit(c));
		if (f)
			x = -x;
		return true;
	}
	template<typename T>
	inline void write(T x)
	{
		static char buf[20];
		char *pos = buf;
		if (x < 0)
			putchar('-'), x = -x;
		do
			*pos++ = x % 10 + '0';
		while (x /= 10);
		while (pos > buf)
			putchar(*--pos);
	}
	const int N = 2010, INF = 0x3f3f3f3f;
	char w[N];
	vector<int> e[N];
	int n, ans = INF, f[N], g[N], num[N], dep[N];
	void dfs(const int u, const int fa)
	{
		int id = 0, mx = 0;
		g[u] = 0;
		if (w[u] == '1')
			num[u] = 1;
		else
			num[u] = 0;
		for (auto v : e[u])
		{
			if (v == fa)
				continue;
			dep[v] = dep[u] + 1;
			dfs(v, u);
			num[u] += num[v];
			g[u] += g[v] + num[v];
			if (g[v] + num[v] > mx)
				id = v, mx = g[v] + num[v];
		}
		if (mx <= g[u] - mx || mx * 2 - g[u] <= f[id])
			f[u] = g[u] / 2 * 2;
		else
			f[u] = 2 * (g[u] - mx) + f[id];
	}
	void solve(const int r)
	{
		dep[r] = 0;
		dfs(r, 0);
		if (f[r] == g[r])
			ans = min(ans, g[r] / 2);
	}
	int work()
	{
		read(n);
		scanf("%s", w + 1);
		for (int i = 1; i < n; i++)
		{
			int a, b;
			read(a), read(b);
			e[a].push_back(b), e[b].push_back(a);
		}
		for (int i = 1; i <= n; i++)
			solve(i);
		if (ans == INF)
			puts("-1");
		else
			write(ans);
		return 0;
	}
}
