vector<vector<ll>>g;
struct T{
    ll cnt=0,dist_sum=0;
    pll dist_max={-LINF,-LINF};
    T& operator+=(T a){
        a.dist_sum+=a.cnt;
        ll mn=a.dist_min()+a.cnt;
        if(mn>dist_max.first)swap(mn,dist_max.first);
        if(mn>dist_max.second)swap(mn,dist_max.second);
        cnt+=a.cnt;
        dist_sum+=a.dist_sum;
        return *this;
    }
    T operator-(T a){
        a.dist_sum+=a.cnt;
        ll mn=a.dist_min()+a.cnt;
        if(mn==dist_max.first)dist_max.first=dist_max.second;
        cnt-=a.cnt;
        dist_sum-=a.dist_sum;
        return *this;
    }
    ll dist_min() const {
        ll ans=dist_max.first;
        ans=ans*2-dist_sum;
        if(ans<0)ans&=1;
        return ans;
    }
};
vector<T>dp;
void dfs1(ll from,ll at){
    each(i,g[at])if(i!=from){
        dfs1(at,i);
        dp[at]+=dp[i];
    }
}
void dfs2(ll from,ll at){
    each(i,g[at])if(i!=from){
        dp[i]+=dp[at]-dp[i];
        dfs2(at,i);
    }
}
