    rep(n)if(s[i]=='1')dp[i].cnt=1;
    dfs1(-1,0);
    dfs2(-1,0);
    ll ans=LINF;
    each(i,dp)if(!i.dist_min())chmin(ans,i.dist_sum/2);
    if(ans==LINF)return out(-1);
    out(ans);
}

#include <cstdio>
#include <cstring>
#include <iostream>
#include <algorithm>
using namespace std;
#define N 2005
#define inf 0x3f3f3f3f
int n;
int fir[N], tar[N << 1], nex[N << 1], cnt;
int mn[N], mx[N], siz[N];
int now, tot, ans = inf;
char S[N];
void Add(int a, int b)
{
	++cnt;
	tar[cnt] = b;
	nex[cnt] = fir[a];
	fir[a] = cnt;
}
void Dfs(int r, int fa, int d)
{
	if (S[r] == '1')
		now += d;
	for (int i = fir[r]; i; i = nex[i])
	{
		int v = tar[i];
		if (v == fa)
			continue;
		Dfs(v, r, d + 1);
	}
}
void Dfs1(int r, int fa, int d)
{
	if (S[r] == '1')
		tot += d;
	for (int i = fir[r]; i; i = nex[i])
	{
		int v = tar[i];
		if (v == fa)
			continue;
		Dfs1(v, r, d + 1);
	}
}
void Dfs2(int r, int fa)
{
	int tot = 0, p = 0;
	siz[r] = S[r] - '0';
	for (int i = fir[r]; i; i = nex[i])
	{
		int v = tar[i];
		if (v == fa)
			continue;
		Dfs2(v, r);
		if (mn[v] > mn[p])
			p = v;
		tot += mx[v];
		siz[r] += siz[v];
	}
	mx[r] = tot;
	tot -= mx[p];
	mn[r] = max(0, mn[p] - tot);
	if (fa)
	{
		mn[r] += siz[r];
		mx[r] += siz[r];
	}
}
void Solve(int r)
{
	tot = 0;
	Dfs1(r, 0, 0);
	if (tot & 1)
		return;
	Dfs2(r, 0);
	if (mn[r] > 0)
		return;
	ans = min(ans, tot / 2);
}
int main()
{
	scanf("%d%s", &n, S + 1);
	for (int i = 1; i < n; i++)
	{
		int a, b;
		scanf("%d%d", &a, &b);
		Add(a, b), Add(b, a);
	}
	for (int i = 1; i <= n; i++)
		Solve(i);
	if (ans == inf)
		puts("-1");
	else
		printf("%d\n",ans);
}

