typedef long long ll;

ll gcd(ll x, ll y) {
	if (y == 0)return x;
	return gcd(y, x%y);
}
ll lcm(ll x, ll y) {
	return x / gcd(x, y)*y;
}
ll kai(ll x, ll y, ll m) {
	ll res = 1;
	for (ll i = x - y + 1; i <= x; i++) {
		res *= i; res %= m;
	}
	return res;
}
ll mod_pow(ll x, ll y, ll m) {
	ll res = 1;
	while (y > 0) {
		if (y & 1) {
			res = res * x % m;
		}
		x = x * x % m;
		y >>= 1;
	}
	return res;
}

ll comb(ll x, ll y, ll m) {
	if (y > x)return 0;
	return kai(x, y, m) * mod_pow(kai(y, y, m), m - 2, m) % m;
}

const int INF = 1000000000;

int n;
string s;
vector<int> vec[2010];
int ans = INF;
int cnt[2010], d[2010], cnt2[2010], d2[2010], pp[2010];
vector<int> ve;

void dfs(int v, int p) {
	pp[v] = p;
	for (int i = 0; i < (int)vec[v].size(); i++) {
		if (vec[v][i] == p)continue;
		dfs(vec[v][i], v);
		d[v] += d[vec[v][i]] + cnt[vec[v][i]];
		cnt[v] += cnt[vec[v][i]];
	}
	if (s[v - 1] == '1')cnt[v]++;
}

void dfs2(int v, int p) {
	for (int i = 0; i < (int)vec[v].size(); i++) {
		if (vec[v][i] == p)continue;
		cnt2[vec[v][i]] = cnt2[v] + cnt[v] - cnt[vec[v][i]];
		d2[vec[v][i]] = d2[v] + cnt2[v] + d[v] - d[vec[v][i]] - cnt[vec[v][i]] + cnt[v] - cnt[vec[v][i]];
		dfs2(vec[v][i], v);
	}
}

signed main() {
	cin >> n >> s;
	int k = 0;
	for (int i = 0; i < n; i++)if (s[i] == '1')k++;
	if (k == 1) {
		cout << 0 << endl;
		return 0;
	}
	for (int i = 1; i < n; i++) {
		int a, b; cin >> a >> b;
		vec[a].push_back(b);
		vec[b].push_back(a);
	}
	dfs(1, 0);
	dfs2(1, 0);
	for (int i = 1; i <= n; i++) {
		int k = 0, ma = 0;
		for (int j = 0; j < (int)vec[i].size(); j++) {
			if (vec[i][j] == pp[i])k += d2[i], ma = max(ma, d2[i]);
			else k += d[vec[i][j]] + cnt[vec[i][j]], ma = max(ma, d[vec[i][j]] + cnt[vec[i][j]]);
		}
		if (k % 2 == 0 && ma <= k / 2)ans = min(ans, k / 2);
	}
	if (ans == INF)cout << -1 << endl;
	else cout << ans << endl;
}

