typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;
#define Fi first
#define Se second
#define pb push_back
#define szz(x) (int)x.size()
#define rep(i,n) for(int i=0;i<n;i++)
#define all(x) x.begin(),x.end()
typedef tuple<int, int, int> t3;

int N;
char In[2020];
vector <int> E[2020];

int down[2020];
void pdfs(int x, int fa) {
	down[x] = (In[x] == '1');
	for(int e : E[x]) if(e != fa) {
		pdfs(e, x);
		down[x] += down[e];
	}
}

typedef pair<pii, int> ppi;

pii Do(int x, int fa) {
	pii res = pii(0, 0);
	vector <pii> w;
	for(int e : E[x]) if(e != fa) {
		pii r = Do(e, x);
		r.Fi += down[e];
		r.Se += down[e];
		w.pb(r);
	}
	sort(all(w));
	if(szz(w) == 0) return res;
	int MX = 0;
	for(pii e : w) MX += e.Se;
	int MN = 0;
	int sum = 0;
	int m = szz(w);
	rep(i, m-1) sum += w[i].Se;
	if(sum < w[m-1].Fi) {
		MN = w[m-1].Fi - sum;
		return pii(MN, MX);
	}
	else {
		MN = MX % 2;
		return pii(MN, MX);
	}
}

int solve(int x) {
	pdfs(x, -1);
	pii r = Do(x, -1);
	if(r.Fi != 0) return 1e9;
	else return r.Se / 2;
}

int main() {
	scanf("%d", &N);
	scanf("%s", In+1);
	for(int i=1;i<N;i++) {
		int x, y; scanf("%d%d", &x, &y);
		E[x].pb(y);
		E[y].pb(x);
	}
	int ans = 1e9;
	for(int i=1;i<=N;i++) {
		ans = min(ans, solve(i));
	}
	if(ans > 1e8) puts("-1");
	else printf("%d\n", ans);
	return 0;
}

