int main(){
  int N; cin >> N;
  string S;
  cin >> S;
  vector<vector<int>> dist(2001, vector<int>(2001,1e9));
  map<int, set<int>> node;
  for (int i=0; i<N-1; i++){
    int a, b; cin >> a >> b;
    node[a].insert(b);
    node[b].insert(a);
  }
  for (int i=1; i<=N; i++){
    queue<pair<int,int>> que;
    que.push(make_pair(i,0));
    while(!que.empty()){
      auto check = que.front();
      que.pop();
      dist[i][check.first] = check.second;
      for (auto k: node[check.first]){
        if (dist[i][k] ==1e9){
          que.push(make_pair(k,check.second+1));
        }
      }
    }
  }
  set<int> checkpos;
  for (int i=0; i<N; i++){
    if (S[i]=='1') checkpos.insert(i+1);
  }
  int ans = 1e9;
  for (int i=1; i<=N; i++){
    int tmpans = 0;
    for (auto k: checkpos){
      tmpans += dist[i][k];
    }
    ans = min(ans, tmpans);
  }
  if (ans % 2!=0){
    cout << -1 << endl;
  }
  else {
    set<int> center;
    for (int i=1; i<=N; i++){
      int tmpans = 0;
      for (auto k: checkpos){
        tmpans += dist[i][k];
      }
      if (tmpans == ans) center.insert(i);
    }
    for (auto i: center){
      bool flag =true;
      for (auto j: node[i]){
        int tmpcount = 0;
        for (auto k: checkpos){
          if (dist[i][k]==dist[i][j]+dist[j][k]){
            tmpcount += dist[i][k];
          }
          if (tmpcount > ans/2){
            flag = false;
            break;
          }
        }
        if (!flag) break;
      }
      if (flag) {
        cout << ans/2 << endl;
        return 0;
      }
    }
    cout << -1 << endl;
  }
}

