void DFS(int R, vector< vector<int> > & G, auto & par, auto & cnt, auto & sum_dep, auto & sum_min, string & S) {
	if(S[R] == '1') cnt[R] = 1;
	ALL_THE(G[R], it) if(par[*it] == -1) {
		par[*it] = R;
		DFS(*it, G, par, cnt, sum_dep, sum_min, S);
		cnt[R] += cnt[*it];
		sum_dep[R] += sum_dep[*it] + cnt[*it];
	}
	sum_min[R] = 0;
	ALL_THE(G[R], it) if(par[*it] == R) {
		int d = sum_dep[R]-sum_dep[*it]-cnt[*it];
		if(sum_min[*it]+cnt[*it] <= d) sum_min[R] = max(sum_min[R], sum_dep[R]&1);
		sum_min[R] = max(sum_min[R], sum_min[*it]+cnt[*it]-d);
	}
}

