void dfs(int now, int par) {
  if (par >= 0) dist[now] = dist[par] + 1;
  int id = 0, sum = 0, len = g[now].size();
  for (int i = 0; i < len; ++i) {
    int to = g[now][i];
    if (to == par) continue;
    dfs(to, now);
    cnt[now] += cnt[to];
    ng[to] += cnt[to];
    ok[now] += ok[to];
    if (ng[to] > ng[g[now][id]]) id = i;
    sum += ng[to];
  }
  if (ng[g[now][id]] * 2 <= sum) {
    ok[now] += sum - (sum & 1);
    ng[now] = sum & 1;
  } else {
    int loss = ng[g[now][id]], tmp = ok[now];
    ok[now] += (sum - loss) * 2;
    loss -= (sum - loss);
    tmp -= ok[g[now][id]];
    tmp = min(loss, tmp) / 2 * 2;
    ok[now] += tmp;
    loss -= tmp;
    ng[now] = loss;
  }
  cnt[now] += s[now] == '1';
}

