	function<void(int, int)> dfs = [&] (int u, int f) {
		Sum[u] = 0;
		if(s[u] == '1') {
			Sum[u] += dep[u];
		}
		for(int v : G[u]) {
			if(v != f) {
				dep[v] = dep[u] + 1;
				dfs(v, u);
				Sum[u] += Sum[v];
			}
		}
	};

	int ans = inf;
	for(int i = 0; i < n; ++i) {
		dep[i] = 0;	
		dfs(i, -1);

		int mx = 0;
		int sum = 0;
		bool ok = true;
		for(int j = 0; j < n; ++j) {
			if(s[j] == '1') {
				sum += dep[j];
				mx = max(mx, dep[j]);
			}
		}

		for(int j : G[i]) {
			if(Sum[j] * 2 > sum) {
				ok = false;
			}
		}

		if(ok && mx * 2 <= sum && sum % 2 == 0) {
			ans = min(ans, sum / 2);
		}
	}

	if(ans == inf) {
		cout << -1 << '\n';
	} else {
		cout << ans << '\n';
	}

	return 0;
}

