	if (sum[x] - mx[x] >= mx[x]) {

		f[x] = sum[x] / 2;
	}
	else {
		int u = mp[x];
		f[x] = sum[x] - mx[x] + min(f[u], (2 * mx[x] - sum[x]) / 2);
