	for (int i = 0; i < n - 1; i++) {
		int a, b;
		cin >> a >> b;
		a--, b--;
		g[a].pb(b);
		g[b].pb(a);
	}
	int res = 1e9;
	for (int i = 0; i < n; i++) {
		int sums = 0;
		int kek = 0;
		int pos = -1;
		for (auto h: g[i]) {
			cnt = 0;
			dist[h] = 1;
			dfs(h, i);
			chkmax(kek, cnt);
			if (kek == cnt) {
				pos = h;
			}
			sums += cnt;
		}
		//cout << sums << ' ' << i << endl;
		if (sums % 2 == 0 && kek <= sums / 2) {
			chkmin(res, sums / 2);
		} else {
			if (sums % 2 == 0) {

				if (res > sums / 2) {

					int f = dfs1(pos, i);
					int ft = sums - kek;
					ft += f;
					if (f <= ft / 2) {
						chkmin(res, sums / 2);
					}
				}
			}
		}
	}
	if (res > 1e8) {
		res = -1;
	}
	cout << res << '\n';
	return 0;
}

