void chemthan() {
    int n; cin >> n;
    string s; cin >> s;
    vector<vi> adj(n);
    FOR(i, 0, n - 1) {
        int u, v; cin >> u >> v; u--, v--;
        adj[u].pb(v), adj[v].pb(u);
    }
    vector<vi> d(n, vi(n, INF));
    FOR(u, 0, n) {
        queue<int> que;
        d[u][u] = 0, que.push(u);
        while (sz(que)) {
            int v = que.front(); que.pop();
            for (int w : adj[v]) {
                if (chkmin(d[u][w], d[u][v] + 1)) {
                    que.push(w);
                }
            }
        }
    }
    pi best = mp(INF, INF);
    FOR(u, 0, n) {
        int sum = 0;
        FOR(v, 0, n) if (s[v] == '1') {
            sum += d[u][v];
        }
        chkmin(best, mp(sum, u));
    }
    int sum = 0;
    FOR(u, 0, n) if (s[u] == '1') {
        sum += d[u][best.se];
    }
    if (sum & 1) {
        cout << -1 << "\n";
    }
    else {
        cout << sum / 2 << "\n";
    }
}

