#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
const int N = 2e3 + 10;
const long long linf = 1e16 + 10;
int n;
string s;
vector<int> adj[N];
int pa[N];
ll d[N], sub[N];

long long DFS(int lv, int st) {
    long long ans = 0;
    if (s[st] == '1') {
        ans += lv;
        sub[st]++;
    }
    for(auto en : adj[st]) if (en != pa[st]) {
        pa[en] = st;
        ans += DFS(lv + 1, en);
    }
    vector<ll> rem;
    for(auto en : adj[st]) if (en != pa[st]) {
        rem.push_back(d[en] + sub[en]);
        sub[st] += sub[en];
    }
    if (!rem.empty()) {
        sort(rem.begin(), rem.end());
        ll psum = 0;
        for(int i = 0; i < rem.size() - 1; i++) psum += rem[i];
        if (rem.back() > psum) {
            d[st] = rem.back() - psum;
        } else d[st] = (psum + rem.back()) % 2;
    }
    //cout << st << " " << d[st] << " " << sub[st] << '\n';
    return ans;
}
long long solve() {
    long long ans = linf;
    for(int i = 1; i <= n; i++) {
        pa[i] = 0;
        memset(d, 0, sizeof(d));
        memset(sub, 0, sizeof(sub));
        //cout << "Start " << i << '\n';
        long long res = DFS(0, i);
        if (d[i] == 0) 
            ans = min(ans, res);
    }
    if (ans == linf) return -1;
    return ans / 2;
}
int main() {

