ll dfs(const string &s, const vector<vector<int>> &a, int ic, int ia){
    vector<int> v(a.size(), -1); v[ic] = 0, v[ia] = 1;
    ll ans = 0;
    if(s[ia] == '1') ans ++;
    function<void(int)> f = [&](int i){
        for(const int &j : a[i]){
            if(v[j] != -1) continue;
            v[j] = v[i] + 1;
            if(s[j] == '1') ans += v[j];
            f(j);
        }
    };
    f(ia);
    return ans;
}

