    Cin(int, n);
    Cin(string, s);
    Vec2(int, n, 0, a);
    Rep(n-1){
        Cin(int, x, y); x--; y--;
        a[x].push_back(y);
        a[y].push_back(x);
    }

    For(ic, n){
        priority_queue<int> q; q.push(0);
        ll sum = 0;
        for(const int &ia : a[ic]){
            ll w = dfs(s, a, ic, ia);
            if(w != 0) q.push(w);
            sum += w;
        }
        if(sum % 2 != 0) continue;

        /*auto r = q;
        while(!r.empty()){
            cout << r.top() << " "; r.pop();
        }
        Cout("");*/
        ll res = 0;

        while(true){
            int x = q.top(); q.pop();
            if(x == 0){
                Cout(sum / 2);
                return 0;
            }
            int nx = q.top(); q.pop();
            if(nx == 0){
                if(x <= res){
                    Cout(sum / 2);
                    return 0;
                }
                break;
            }
            x -= nx;
            res += nx;
            if(x != 0) q.push(x);
        }
    }
    Cout(-1);
}

