tuple<ll,ll,ll> rec(int c, int p){
	ll child = s[c] == '1';
	ll mx = 0, mn = 0;
	for(int i : e[c]) if(i != p){
		ll n, x, m; tie(n, x, m) = rec(i, c);
		n += m; x += m;
		if(mn <= x && n <= mx) mn = (mx + x) % 2;
		else{
			assert(n > mx || mn > x);
			if(n > mx) mn = n - mx;
			else mn -= x;
		}
		mx += x;
		child += m;
	}
	return tie(mn, mx, child);
}

