void dfs(int u, int p){
    cnt[u] = hasPices[u];
    high[u] = 0;
    priority_queue <int, vector<int>, greater<int> > Q;
    for(int v : adj[u])
        if (v != p){
            dfs(v, u);
            Q.push(high[v] + cnt[v]);
            if (Q.size() > 2)
                Q.pop();
            cnt[u] += cnt[v];
            high[u] += high[v] + cnt[v];
        }
    if (Q.size() <= 1){
        low[u] = high[u] % 2;
    } else {
        int x = Q.top();
        int sum = 0;
        for(int v : adj[u])
            if (v != p)
                sum += min(high[v] + cnt[v], x - abs(high[v] + cnt[v] - x) % 2);
        low[u] = max(sum % 2, x * 2 - sum);
    }
}

