pair<int, int> go(int x, int l, int d)
{
	pair<int, int> r;
	if (S[x] == '1') r.first += d, Z[x] = 1;
	else Z[x] = 0;
	int mx = 0, sm = 0;
	for (auto &y : G[x]) if (y != l){
		auto n = go(y, x, d + 1);
		Z[x] += Z[y];
		r.first += n.first;
		mx = max(mx, n.second);
		sm += n.second;
	}
	if (mx <= sm / 2) sm %= 2;
	else sm = sm - 2 * (sm - mx);
	r.second = sm + Z[x];
	return r;
}

