		vector<pair<int, int> > res;
		int mn = 0, mx = 0;
		for (auto &p : G[c]){
			auto n = go(p, c, 1);
			res.push_back(n);
			mn += n.second;
			mx += n.first;
		}
		if (mx % 2 || ans < mx / 2) continue;

		int u = 0, v = 0;
		for (auto &p : res){
			u = max(u, p.second);
			v = max(v, p.first);
		}
