		dp[v][0]++;
	pii b = mp(0, 0);
	for (int u : g[v]) {
		if (u == par) continue;
		dfs(u, v);
		dp[v][0] += dp[u][0];
		pii t = mp(dp[u][2] + dp[u][0], dp[u][1] + dp[u][0]);
		dp[v][2] += t.first;
		b = max(b, t);
	}
  	for(auto u:g[v]) {
    	if(u==par) continue; 
    	assert(b.second >= dp[u][1] + dp[u][0]);
    }
  	assert(b.second <= b.first);
	if (b.second > dp[v][2] - b.first) {
		dp[v][1] = b.second - (dp[v][2] - b.first);
	} else {
		dp[v][1] = dp[v][2] & 1;
	}
}

