const int mod=1000000007,MAX=2005,INF=1<<30;
bool exist[MAX];
vector<int> G[MAX];
int depth[MAX],cnt[MAX];
vector<pair<int,int>> dis;

void DFS(int u,int p){
    for(int to:G[u]){
        if(to==p) continue;

        depth[to]=depth[u]+1;
        DFS(to,u);
        cnt[u]+=cnt[to];
    }
    if(exist[u]) cnt[u]++;
}

pair<int,int> solve(int u,int p){
    pair<int,int> sum={0,0};
    vector<int> T;
    for(int to:G[u]){
        if(to==p) continue;
        pair<int,int> a=solve(to,u);
        sum.first+=a.first;
        sum.second+=a.second;

        if(a.first-2*a.second-cnt[to]*depth[u]) T.push_back(a.first-2*a.second-cnt[to]*depth[u]);
    }
    if(exist[u]){
        sum.first+=depth[u];
    }

    sort(all(T));
    int s=0;
    for(int i=0;i<T.size();i++) s+=T[i];

    if(T.size()) sum.second+=min(s/2,s-T.back());
    return sum;
}

