        }
        if(dis.size()==0){
            ans=0;
            continue;
        }
        sort(all(dis));

        int sum=0;
        for(pair<int,int> a:dis) sum+=a.first;
        if(sum%2==0){
            if(dis.back().first*2<=sum) ans=min(ans,sum/2);
