template <class T>
inline void read(T &res)
{
	res = 0; bool bo = 0; char c;
	while (((c = getchar()) < '0' || c > '9') && c != '-');
	if (c == '-') bo = 1; else res = c - 48;
	while ((c = getchar()) >= '0' && c <= '9')
		res = (res << 3) + (res << 1) + (c - 48);
	if (bo) res = ~res + 1;
}

const int N = 2005, M = N << 1, INF = 0x3f3f3f3f;

int n, ecnt, nxt[M], adj[N], go[M], c[N], d[N], f[N], ans = INF;
char s[N];

void add_edge(int u, int v)
{
	nxt[++ecnt] = adj[u]; adj[u] = ecnt; go[ecnt] = v;
	nxt[++ecnt] = adj[v]; adj[v] = ecnt; go[ecnt] = u;
}

void dfs(int u, int fu)
{
	c[u] = s[u] == '1'; d[u] = 0; int vt = 0;
	for (int e = adj[u], v; e; e = nxt[e])
		if ((v = go[e]) != fu)
		{
			dfs(v, u); c[u] += c[v]; d[u] += d[v] + c[v];
			if (d[v] + c[v] > d[vt] + c[vt]) vt = v;
		}
	if ((d[vt] + c[vt] << 1) <= d[u]) return (void) (f[u] = d[u] >> 1);
	int orz = f[vt] << 1;
	if ((d[vt] + c[vt] << 1) - d[u] <= orz) return (void) (f[u] = d[u] >> 1);
	f[u] = f[vt] + (d[u] - d[vt] - c[vt]);
}

