int dp[N], sz[N], mx[N];
vi g[N];
int calc(vi &e){
    int s = 0, M = 0, m = -1;
    for(auto &x : e){
        int w = dp[x] + sz[x];
        s += w;
        if(M <= w){
            M = w;
            m = x;
        }
    }
    if(2 * M <= s)return 0;
    int t = 0;
    for(auto &x : e){
        if(x != m)t += mx[x] + sz[x];
    }
    return max(0, M - t);
}
