    for (auto u : graph[v]) if (u != p)
    {
        dfs(u, v);
        cnt[v] += cnt[u];
        si[v] += si[u];
    }
    si[v] += cnt[v];
}

void check(int v)
{
    dfs(v, -1);
    //for (int i = 0; i < n; i++) cout << si[i] << " "; cout << '\n';
    int S = 0;
    for (auto u : graph[v]) S += si[u];
    if (S % 2 != 0) return;
    int bad = -1;
    for (auto u : graph[v])
    {
        if (si[u] > S / 2)
        {
            bad = u;
        }
    }
    //cout << S << " " << bad << " " << si[bad] << "\n";
    if (bad == -1)
        ans = min(ans, S / 2);
    int d = (si[bad] - S / 2);
    int p = v;
    int it = 2100;
    //cout << bad << "\n";
    while (d > 0 && it--)
    {
        int sz = 0;
        for (auto u : graph[bad]) if (u != p)
        {
            sz += si[u];
        }
        int b2 = -1;
        for (auto u : graph[bad]) if (u != p)
        {
            if (b2 == -1 || si[u] > si[b2])
                b2 = u;
        }
        if (b2 == -1) break;
        if (si[b2] > sz / 2) d -= sz - si[b2];
        else d -= sz / 2;
        p = bad;
        bad = b2;
    }
    if (d <= 0) ans = min(ans, S / 2);
    return;
}

