        edges[u].emplace_back(v);
        edges[v].emplace_back(u);
    }
    lint ret = inf;
    for (int i = 0; i < n; ++i) { // i == root
        vector<lint> dp(n, 0);
        vector<lint> depth(n, -1);
        depth[i]                     = 0;
        lint stot                    = 0;
        function<void(int, int)> dfs = [&](int c, int p) {
            if (s[c] == '1')
                stot += depth[c];
            for (auto &v : edges[c]) {
                if (v == p)
                    continue;
                depth[v] = depth[c] + 1;
                dfs(v, c);
            }
        };
        dfs(i, -1);
        if (stot % 2 == 1)
            continue;
        vector<lint> ss(n, 0);
        vector<lint> num(n, 0);
        lint nc                       = 0;
        function<void(int, int)> dfs2 = [&](int c, int p) {
            lint st = 0;
            lint sm = 0;
            for (auto &v : edges[c]) {
                if (v == p)
