                dfs2(v, c);
                num[c] += num[v];
                st += ss[v];
                sm = max(sm, ss[v]);
            }
            ss[c] = max(0LL, sm - (st - sm));
            nc += st - ss[c];
            if (s[c] == '1')
                num[c] += 1;
            ss[c] += num[c];
        };
        dfs2(i, -1);
        if (ss[i] == cnt && nc == stot)
