const int N = 2e3 + 6, inf = 1e9 + 7;
int n, ans = inf;
string s;
vector <int> G[N];
int val[N], num[N], change;

int get_cnt (int v, int par, int h = 1) {
	int res = (s[v] == '1') * h;
	for (int u: G[v])
		if (u != par)
			res += get_cnt(u, v, h + 1);
	return res;
}

void can (int v, int par) {
	vector <int> arr;
	int sum = 0;
	val[v] = num[v] = 0;

	for (int u: G[v])
		if (u != par) {
			can(u, v);
			if (change == false)
				return ;
			if (val[u] + num[u]) {
				arr.push_back(val[u] + num[u]);
				sum += val[u] + num[u];

				num[v] += num[u];
				val[v] += val[u] + num[u];
			}
		}

	if (arr.size()) {
		sort(arr.begin(), arr.end());
		if (sum % 2) {
			sum--;
			arr.back()--;
			sort(arr.begin(), arr.end());
		}

		if (2 * arr.back() > sum) {
			if (change <= sum - arr.back()) {
				change = 0;
				return ;
			}
			change -= sum - arr.back();
			val[v] -= sum - arr.back();
		}
		else {
			if (change <= sum) {
				change = 0;
				return ;
			}
			change -= sum;
			val[v] -= sum;
		}
	}

	if (s[v] == '1')
		num[v]++;
}

