	}

	for (int i = 0; i < n; i++) {
		vector <pii> vec;
		int sum = 0;

		for (int v: G[i]) {
			int val = get_cnt(v, i);
			if (val) {
				sum += val;
				vec.push_back({val, v});
			}
		}

		if (vec.empty()) {
			ans = 0;
			continue;
		}

		if (vec.size() == 1 || sum % 2)
			continue;

		sort(vec.begin(), vec.end());
		change = max(0, 2 * vec.back().first - sum);

		can(vec.back().second, i);
		if (change == false)
			ans = min(ans, sum);
	}

	// cout << (ans == inf? -1: ans / 2) << "\n";
	cout << -1 << "\n";
	return 0;
}

