void dfs(int u,int fa){
	siz[u]=a[u];
	dis[u]=0;
	int maxson=-1;
	son[u]=0;
	for(auto v:G[u]){
		if(v==fa)continue;
		dfs(v,u);
		dis[u]+=dis[v]+siz[v];
		siz[u]+=siz[v];
		if(siz[v]>maxson){
			maxson=siz[v],son[u]=v;
		}
		maxson=max(maxson,dis[v]);
	}
	if(dis[u]>=(maxson<<1))dp[u]=dis[u]>>1;
	else dp[u]=dis[u]-maxson+min(dp[son[u]],(maxson<<1)-dis[u])/2;
}
