static vector<int> adj[2005];
static long long sz[2005]; ///number of stones in the subtree
static long long maxDis[2005]; ///maximum total distance of all stones in the subtree rooted at u, achieved by moving no stones
static long long minDis[2005]; ///minimum total distance of all stones in the subtree rooted at u, move as many stones up towards u
string s;

long long ans = 1e16;

void dp(int u, int p){
	maxDis[u] = 0;
	sz[u] = 0;
	long long totalMax = 0;
	long long maxmax = 0;
	long long maxindex = 0;
	for(int v : adj[u]){
		if(v == p) continue;
		dp(v, u);
		sz[u] += sz[v];
		maxDis[u] += maxDis[v];
		if(maxDis[v] + sz[v] > maxmax){
			maxmax = maxDis[v] + sz[v];
			maxindex = v;
		}
		totalMax += maxDis[v] + sz[v];
	}
	maxDis[u] += sz[u];

	long long rem = totalMax - maxmax;
	if(maxmax <= rem) minDis[u] = totalMax % 2;
	else{
		if(rem >= minDis[maxindex] + sz[maxindex]) minDis[u] = totalMax % 2;
		else{
			minDis[u] = minDis[maxindex] + sz[maxindex] - rem;
		}
	}

	sz[u] += (s[u] == '1');
}
