		memo.push_back(pair<ll,ll>{minG[next] + numG[next], maxG[next] + numG[next]});
	}
	//cout<<"ccc"<<endl;
	if(memo.size()==0){
		return;
	}
	sort(all(memo));
	reverse(all(memo));//minG*numGの降順
