    void init(Graph &g, int root_){
        n = g.n;
        root = root_;
        t.resize(n);
        par.resize(n);
        dpt.resize(n);
        fill(dpt.begin(), dpt.end(), -1);
        queue<int> que;
        par[root] = -1;
        dpt[root] = 0;
        que.push(root);
        while(que.size()){
            int pa = que.front();
            que.pop();
            for(int ch : g.g[pa]){
                if(dpt[ch] == -1){
                    t[pa].push_back(ch);
                    par[ch] = pa;
                    dpt[ch] = dpt[pa] + 1;
                    que.push(ch);
                }
            }
        }
    }

    Tree(){}

    Tree(Graph &g, int root_){
        init(g, root_);
    }

    vector<int> toposort(){
        typedef pair<int, int> P;
        vector<P> p(n);
        for(int i = 0; i < n; i++) p[i] = P(dpt[i], i);
        sort(p.begin(), p.end(), greater<P>());
        vector<int> res(n);
        for(int i = 0; i < n; i++) res[i] = p[i].second;
        return res;
    }
};

int main()
{
    int n;
    cin >> n;
    string s;
    cin >> s;
    Graph g(n);
    for(int i = 0; i < n - 1; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        g.add_edge(a, b);
        g.add_edge(b, a);
    }
    int ans = INF;
    for(int i = 0; i < n; i++){
        Tree t(g, i);
        vector<int> topo = t.toposort();
        int c[2003]{0};
        int d[2003]{0};
        int e[2003]{0};
        for(int j = 0; j < n; j++){
            int u = topo[j];
            c[u] += s[u] - '0';
            d[u] += s[u] - '0';
            if((int)t.t[u].size() == 0){
                e[u] = d[u];
                continue;
            }
            int al = -1, r = 0;
            for(int v : t.t[u]){
                c[u] += c[v];
                d[u] += d[v] + c[v];
                if(al == -1 || d[v] > d[al]) al = v;
                r += d[v];
            }
            r = r - d[al] + e[al];
            e[u] = max(r % 2, e[al] * 2 - r) + c[u];
        }
        if(e[i] == c[i]){
            ans = min(ans, (d[i] - (c[i] - (s[i] - '0'))) / 2);
        }
    }
    if(ans == INF) cout << -1 << endl;
    else cout << ans << endl;
}

