    function<int (int, int)> dfs = [&] (int u, int fa) {
      siz[u] = str[u] == '1';
      remain[u] = 0;
      int res = 0, sum = 0;
      vector<int> son;
      for (int v : adj[u]) {
        if (v != fa) {
          res += dfs(v, u);
          siz[u] += siz[v];
          son.push_back(remain[v]);
          sum += remain[v];
        }
      }
      if (son.empty()) {
        remain[u] = siz[u];
        return 0;
      }
      sort(son.begin(), son.end());
      if (sum % 2) {
        son.back()--;
        remain[u]++;
        sum--;
      }
      sort(son.begin(), son.end());
      if (son.back() > sum / 2) {
        res += sum - son.back();
        remain[u] += son.back() - (sum - son.back());
      } else {
        res += sum / 2;
      }
      if (u == root && remain[u]) {
        return INT_MAX;
      }
      remain[u] += siz[u];
      return res;
    };
