ll mygcd(ll a,ll b){
    if(b == 0){return a;}
    return mygcd(b,a%b);
}

ll mypow(ll x, ll n){
    ll ret = 1;
    while(n > 0){
        if(n&1){
            ret *= x;
            ret %= MOD;
        }
        x *= x;
        x %= MOD;
        n >>= 1;
    }
}

pair<ll,ll> rec(int v,string &str,vector<list<ll>> &e,vector<bool> &used){
    used[v] = true;
    if(e[v].size() == 1){
        if(str[v] == '1'){
            return make_pair(1,1);
        }else{
            return make_pair(0,0);
        }
    }
    pair<ll,ll> ret = make_pair(0,0);
    for(auto itr = e[v].begin();itr != e[v].end(); itr++){
        if(!used[*itr]){
            auto p = rec(*itr,str,e,used);
            ret.first += p.first;
            ret.second += p.second;
        }
    }
    if(str[v] == '1'){
        ret.second++;
    }
    ret.first += ret.second;
    return ret;
}

ll eval(int n,int v,string &str,vector<list<ll>> &e,vector<list<ll>> &val){
    vector<bool> used(n+1,false);
    used[v] = true;
    auto vitr = val[v].begin();
    for(auto itr = e[v].begin(); itr != e[v].end(); itr++,vitr++){
        (*vitr) = rec(*itr,str,e,used).first;
    }
    bool flag = true;
    ll f = val[v].front();
    vitr = val[v].begin();
    vitr++;
    if(f != 0 && e[v].size() == 1){
        return INF;
    }
    for(; vitr != val[v].end(); vitr++){
        if(f != (*vitr)){
            flag = false;
        }
    }
    if(flag){
        ll t = f*val[v].size();
        if(t%2 == 0){
            return t/2;
        }else{
            return INF;
        }
    }else{
        return INF;
    }
}

