		for(int x:G[v]){
			if(x==pa) continue;
			num += dfs(x,v,root) + b[x];
			b[v] += b[x];
			c[v] += min(b[x],res);
			res = abs(b[x] - res);
		}
		c[v] = res;
		return num;
	}else{
		ll sum = 0,mx = 0,dis = 0;
		for(int x:G[v]){
			num = dfs(x,v,root);
			sum += num + b[x];
			if(num + b[x]>=mx){
				mx = num + b[x];
				dis = max(dis,c[x]);
			}
		}
		if(!(sum&1)){
			if(sum>=2*mx || sum>=2*(mx - dis)){
				mn = min(mn,sum/2);
			}
		}
	}
}

