    ll maxi;
    ll num;
};

query dfs(int now, int from) {
    ll num = 0;
    ll maxisum = 0;
    query ret;
    vector<query> v;
    for(int i = 0; i < pathes[now].size(); i++) {
        int to = pathes[now][i];
        if(to == from) continue;
        v.push_back(dfs(to, now));
        num += v.back().num;
        maxisum += v.back().maxi;
    }
    ll mini = 0;
    if(num % 2 == 1) mini = 1;
    for(int i = 0; i < v.size(); i++) {
        if(maxisum - v[i].maxi < v[i].mini) {
            mini = v[i].mini - (maxisum - v[i].maxi);
        }
    }
    ret.num = num;
    if(S[now] == '1') ret.num++;
    ret.maxi = maxisum;
    ret.mini = mini;
    ret.maxi += ret.num;
    ret.mini += ret.num;
    return ret;
}

void f(int root) {
    vector<query> v;
    ll maxisum = 0;
    for(int i = 0; i < pathes[root].size(); i++) {
