pair<int, pair<int, int>> dfs(int x, int y) {
    int c1 = 0, c2 = 0, c3 = 0, m1 = 0, m2 = 0, m3 = 0, i;

    for (i = 0; i < v[x].size(); i++) {
        if (v[x][i] == y) continue;

        pair<int, pair<int, int>> p = dfs(v[x][i], x);
        p.second.first += p.first;

        c1 += p.first;
        c2 += p.second.first;

        if (p.second.first - p.second.second * 2 > m1) {
            m1 = p.second.first - p.second.second * 2;
            m2 = p.second.first;
            m3 = p.second.second;
        }
    }

    if (m1 > c2 - m2) {
        c3 = m3 + c2 - m2;
    } else {
        c3 = c2 / 2;
    }

    if (s[x] == '1') c1++;

    return make_pair(c1, make_pair(c2, c3));
}

