	while(ch >= '0' && ch <= '9') {x = (x << 3) + (x << 1) + (ch ^ 48); ch = getchar();}
	return x * f;
}
void init() {for(int i = 1; i <= n; i ++) dis[i] = siz[i] = f[i] = 0;}
void add(int x, int y) {a[++ tot].to = y; a[tot].nex = head[x]; head[x] = tot;}
void dfs(int x, int fa)
{
	siz[x] = v[x]; int pos = 0;
	for(int i = head[x]; i; i = a[i].nex)
	{
		int y = a[i].to; if(y == fa) continue;
		dfs(y, x); siz[x] += siz[y];
		dis[y] += siz[y]; dis[x] += dis[y];
		if(dis[y] > dis[pos]) pos = y;
	}
	if(pos == 0) return f[x] = 0, void();
	if(dis[pos] * 2 <= dis[x]) f[x] = dis[x] / 2;
	else f[x] = dis[x] - dis[pos] + min(f[pos], (2 * dis[pos] - dis[x]) / 2);
}
