	ll sum = 0;
	int mxm = 0;
	for (auto u : t[v]){
		if (u == par)
			continue;
		dfs(u, v);
		cnt[v] += cnt[u];
		sd[v] += sd[u] + cnt[u];
		se.insert({sd[u] + cnt[u], dp[u] + cnt[u]});
		sum += sd[u] + cnt[u];
		mxm = max(mxm, sd[u] + cnt[u]);
	}
	while (2 * mxm > sum and (int)se.size() > 1){
		auto it = *se.begin();
		int a = it.first, b = it.second;
		se.erase(se.begin());
		if (a == b)
			continue;
		sum += 2;
		mxm = max(mxm, a + 2);
		se.insert({a + 2, b});
	}
	dp[v] = max(sum&1, 2*mxm-sum);
	if (s[v-1] == '1')
		cnt[v] ++;
