pair<int, pair<int, int>> dfs(int x, int y) {
    int c1 = 0, c2 = 0, c3 = 0, m = 0, sum = 0, i;

    for (i = 0; i < v[x].size(); i++) {
        if (v[x][i] == y) continue;

        pair<int, pair<int, int>> p = dfs(v[x][i], x);

        c1 += p.first;
        c2 += p.second.first;
        c3 += p.second.second;
        m = max(m, p.second.first - p.second.second * 2);
        sum += p.second.first - p.second.second * 2;
    }

    c3 += max(sum - m, sum / 2);

    if (s[x] == '1') c1++;

    c2 += c1;

    return make_pair(c1, make_pair(c2, c3));
}

int calc(int x) {
    int sum = 0, m1 = 0, m2 = 0, i;

    for (i = 0; i < v[x].size(); i++) {
        pair<int, pair<int, int>> p = dfs(v[x][i], x);

        if (p.first > 0) {
            sum += p.second.first;
            if (p.second.first > m1) {
                m1 = p.second.first;
                m2 = p.second.second;
            }
        }
    }

    if (sum % 2 == 0 && m1 - m2 * 2 <= sum - m1) {
        return sum / 2;
    } else {
        return 1e9;
    }
}

