		sr=sr+high[v]+siz[v]; sl=sl+low[v]+siz[v];
	}
	if(!tt) return ;
	sort(p+1,p+tt+1);
	if(p[1].l*2 <= sl){
		if(sl%2 == 0) low[x]=0,d[x]+=sl/2;
