int n, sz[max_n], dpl[max_n], dpr[max_n], res[max_n];
char s[max_n];
vector<int> g[max_n];

int get_l(int l1, int r1, int l2, int r2) {
    if (l1 > l2) {
        swap(l1, l2);
        swap(r1, r2);
    }
    if (l1 % 2 == l2 % 2) {
        if (l2 <= r1) {
            return 0;
        }
        return l2 - r1;
    } else {
        if (l2 <= r1) {
            return 1;
        }
        return l2 - r1;
    }
}

int get_r(int l1, int r1, int l2, int r2) {
    return r1 + r2;
}

void get_dp(int v, int p) {
    sz[v] = s[v] - '0';
    res[v] = 0;
    dpl[v] = 0;
    dpr[v] = 0;
    for (int to : g[v]) {
        if (to == p) {
            continue;
        }
        get_dp(to, v);
        sz[v] += sz[to];
        res[v] += res[to] + sz[to];

        int nl = get_l(dpl[v], dpr[v], dpl[to] + sz[to], dpr[to] + sz[to]);
        int nr = get_r(dpl[v], dpr[v], dpl[to] + sz[to], dpr[to] + sz[to]);
        dpl[v] = nl;
        dpr[v] = nr;
    }
    //cout << v << ": [" << dpl[v] << " " << dpr[v] << "], res = " << res[v] << ", sz = " << sz[v] << endl;
}

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    scanf("%d%s", &n, s);
    for (int i = 1; i < n; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        --u;
        --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    int ans = inf;
    for (int i = 0; i < n; ++i) {
        get_dp(i, -1);
        //cout << i << ": " << dpl[i] << " " << dpr[i] << " " << res[i] << endl;
        if (dpl[i] == 0) {
            ans = min(ans, res[i] / 2);
        }
    }
    if (ans == inf) {
        ans = -1;
    }
    printf("%d\n", ans);
    return 0;
}

