  result(int p, int l, int h, Int d) : ps(p), lo(l), hi(h), dists(d) { }
};

result dfs(int u, int p = -1) {
  result res(0, 0, 0, 0);
  for (const edge& e : G[u]) {
    if (e.dst == p) {
      continue;
    }
    result t = dfs(e.dst, u);
    t.lo += t.ps;
    t.hi += t.ps;
    res.ps += t.ps;
    res.lo = max(res.lo, t.lo) <= min(res.hi, t.hi) ? 0 : (max(res.lo, t.lo) - min(res.hi, t.hi));
