#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll N = 2020, inF = 1e8;

ll n, u, v, sz[N], sigma[N], mini[N];
ll ans = inF;
string s;
vector<ll> nei[N];

void dfs(ll v, ll par = -1) {
	sz[v] = s[v] - '0';
	sigma[v] = 0;
	ll maxi = 0;
	for (ll u: nei[v])
		if(u != par) {
			dfs(u, v);
			sz[v] += sz[u];
			sigma[v] += sigma[u] + sz[u];
			maxi = max(maxi, sigma[u] + sz[u]);
		}
	mini[v] = sigma[v];
	for (ll u: nei[v])
		if(mini[u] + sz[u] <= sigma[v] - (sigma[u] + sz[u])) {
			mini[v] = 0;
			return;
		}
	for (ll u: nei[v])
		mini[v] = min(mini[v], mini[u] + sz[u] - (sigma[v] - (sigma[u] + sz[u])));
}

ll solve(ll v) {
	dfs(v);
	if(sigma[v] & 1)
		return inF;
	for (ll u: nei[v])
		if(mini[u] + sz[u] > sigma[v] - (sigma[u] + sz[u]))
			return inF;
	return sigma[v] >> 1;
}

int main() {
    ios::sync_with_stdio(false), cin.tie(0);
	cin >> n >> s;
	for (ll i = 0; i < n - 1; i++) {
		cin >> u >> v;
		nei[--u].push_back(--v);
		nei[v].push_back(u);
	}
	for (ll v = 0; v < n; v++)
		ans = min(ans, solve(v));
	cout << (ans == inF? -1: ans);
    return 0;
}

