int main()
{
    const int N = read<int>();
    const auto S = read<std::string>();
    Tree T(N);
    for (int i = 0, u, v; i < N - 1; i++) { std::cin >> u >> v, T.addEdge(u - 1, v - 1, true); }
    std::vector<int> min(N), max(N), cnt(N);
    auto dfs = [&](auto&& self, const int s, const int p) -> void {
        cnt[s] = (S[s] == '1' ? 1 : 0), min[s] = max[s] = 0;
        int M = 0, S = 0;
        for (const int to : T[s]) {
            if (to == p) { continue; }
            self(self, to, s);
            chmax(M, min[to] + cnt[to]), S += min[to] + cnt[to], max[s] += max[to] + cnt[to], cnt[s] += cnt[to];
        }
        min[s] = (S >= 2 * M ? S % 2 : 2 * M - S);
    };
    int ans = INF<int>;
    for (int i = 0; i < N; i++) {
        dfs(dfs, i, -1);
        SHOW(i, min, max);
        if (min[i] == 0 and max[i] % 2 == 0) { chmin(ans, max[i] / 2); }
    }
    std::cout << (ans == INF<int> ? -1 : ans) << std::endl;
    return 0;
}

