    for (int i = 0; i < N - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    best = INF;

    for (int root = 0; root < N; root++) {
        depth.assign(N, 0);
        piece_count.assign(N, 0);
        depth_sum.assign(N, 0);
        min_depth_sum.assign(N, 0);
        depth_dfs(root, -1);
        answer_dfs(root, -1);
    }

    cout << (best < INF ? best : -1) << '\n';
}

