	FOR(i,N-1) {
		cin>>x>>y;
		E[x-1].push_back(y-1);
		E[y-1].push_back(x-1);
	}
	FOR(x,N) dfs1(x,x,x,0);

	int mi=1<<30;
	FOR(x,N) {
		ZERO(SD);
		FOR(y,N) Ds[y].clear();
		FORR(e,E[x]) dfs(e,x,e,1);
		int sum=0;
		int num=0;
		FOR(y,N) {
			sum+=SD[y];
			if(SD[y]>0) num++;
		}

		if(sum%2) continue;
		int ma=*max_element(SD,SD+N);
		if(ma*2<=sum) {
			mi=min(mi,sum/2);
			continue;
		}
		y=max_element(SD,SD+N)-SD;
		lef=(ma-(sum-ma))/2;
		can(y,x);
		if(lef<=0) mi=min(mi,sum/2);
	}
	if(mi==1<<30) mi=-1;
	assert(mi!=-1);
	cout<<mi<<endl;
}


