ll sob(vector<tl>& w) {
	if(w.size() == 0) {return 0;}
	sort(w.begin(),w.end());
	ll ma = w.back().first.first;
	ll su = 0;
	for(int i=0;i<w.size()-1;i++) {
		ll par = w[i].first.first&1;
		ll mr = min((w[i].first.second-par)/2,(ma-par)/2);
		ll mv = mr*2+par;
		su += mv;
	}
	if(ma > su) {return ma-su;}
	return (su+ma)&1;
}
