		ro.first.first += ro.second;
		ro.first.second += ro.second;

		res.second += ro.second;
		res.first.second += ro.first.second;
		go.push_back(ro);
	}
	res.first.first = sob(go);
	return res;
}
ll proc(int u) {
	ll su = 0;
	for(int i=0;i<g[u].size();i++) {
		ll val = dod(g[u][i],u,1);
		su += val;
	}
	vector<tl> go;
	for(int i=0;i<g[u].size();i++) {
		int v = g[u][i];
		tl ro = rod(v,u);
		ro.first.first += ro.second;
		ro.first.second += ro.second;
		go.push_back(ro);
	}
	if(sob(go) != 0) {
		return -1;
	}
	return su/2;
}
