constexpr int inf = (1 << 30) - 1;

int N;
string S;
vector<int> graph[2000];

struct solver {
    int mini, maxi;
    solver(const int& mi = 0, const int& ma = 0) : mini(mi), maxi(ma) { }
};

bool operator < (const solver& s, const solver& t) {
    if(s.mini == t.mini) return s.maxi < t.maxi;
    else return s.mini < t.mini;
}

bool can_make_x(const solver& s, const int& x) {
    if(s.mini % 2 != x % 2) return false;
    return s.mini <= x && x <= s.maxi;
}

void add(solver& s, const int& x) {
    s.mini += x;
    s.maxi += x;
}

solver merge(solver s, solver t) {
    if(t < s) swap(s, t);
    int mini, maxi = s.maxi + t.maxi;
    if(s.maxi >= t.mini) mini = maxi % 2;
    else mini = t.mini - s.maxi;
    return solver(mini, maxi);
}

int solve_from_v(const int& v) {
    vector<int> count_children(N, 0);
    function<solver(int, int)> dfs = [&](const int& u, const int& p) {
        solver res;
        if(S[u] == '1') ++count_children[u];
        for(const int& x : graph[u]) {
            if(x == p) continue;
            res = merge(res, dfs(x, u));
            count_children[u] += count_children[x];
        }
        add(res, count_children[u]);
        return res;
    };
    solver now;
    for(const int& x : graph[v]) now = merge(now, dfs(x, v));
    if(!can_make_x(now, 0)) return inf;
    return now.maxi / 2;
}

