#include <bits/stdc++.h>
using namespace std;

int n;
vector<vector<int>> g;
vector<bool> has;
struct state {
  int lo=-1, hi=-1, cnt=-1, cost_times_two=-1;
  bool initialized() { return cnt >= 0; }
};
unordered_map<int, state> memo;

state& get(int v, int p) {
  assert(0 <= v && v < n);
  assert(-1 <= p && p < n);
  assert(p != v);
  return memo[(n+1)*v + (p + 1)];
}

state& dfs(int v, int p) {
  state& s = get(v, p);
  if (s.initialized()) return s;

  s.lo=0;
  s.hi=0;
  s.cost_times_two=0;

  int childcnt = 0;
  int maxchild = 0;
  for (auto w : g[v]) {
    if (w == p) continue;
    state& t = dfs(w, v);
    s.lo += t.lo;
    s.hi += t.hi + t.cnt;
    childcnt += t.cnt;
    maxchild = max(maxchild, t.cnt);
    s.cost_times_two += t.cost_times_two + t.cnt;
  }
  // cout << v << " (parent="<<p<<"): ";
  int must_pull = maxchild - (s.lo - maxchild) + (childcnt%2);
  // cout << "childcnt=" << childcnt << " ";
  // cout << "mustpull=" << must_pull << ' ';
  s.lo = max(s.hi%2, must_pull);
  s.cnt = childcnt + has[v];
  // cout << "lo=" <<  s.lo << " hi=" << s.hi << " cnt=" << s.cnt << " 2*cost=" << s.cost_times_two << '\n' << flush;
  assert(s.lo % 2 == s.hi % 2);
  return s;
}

signed main() {
  ios_base::sync_with_stdio(false), cin.tie(nullptr);

  cin >> n;
  {
    string s; cin >> s;
    for (char c : s)
      has.push_back(c == '1');
  }
  g.resize(n);
  for (int i = 0; i < n-1; ++i) {
    int a, b; cin >> a >> b; --a; --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  const int INF = 1e9;
  int best=INF;
  for (int i = 0; i < n; ++i) {
    state& s = dfs(i, -1);
    if (s.lo == 0) {
      assert(s.cost_times_two%2 == 0);
      best = min(best, s.cost_times_two/2);
      //cout << i << ": " << s.cost_times_two/2 << '\n';
    }
  }
  if (best == INF)
    best = -1;
  cout << best << '\n';
}

