			cin >> edgelist[i].first >> edgelist[i].second >> edgeweight[i];
		else
			cin >> edgelist[i].first >> edgelist[i].second;
		if (graph_from1) {
			edgelist[i].first--;
			edgelist[i].second--;
		}
	}
	return;
}

void Graph_class::adjini() {
	branch_type.resize(Vnum);
	adjnum.resize(Vnum);
	xdist.resize(Vnum, -1);
	adjlist.resize(Vnum);
	if (graph_weight)
		adjlistweight.resize(Vnum);
	adj_to_root.resize(Vnum, -1);
	DP.resize(Vnum, 0);
	rep(i, Vnum)
		adjnum[i] = 0;
	rep(i, Enum) {
		int x = edgelist[i].first;
		int y = edgelist[i].second;
		adjlist[x].push_back(y);
		if (!graph_digraph)
			adjlist[y].push_back(x);
		if (graph_weight) {
			ll xyweight = edgeweight[i];
			adjlistweight[x].push_back(xyweight);
			if (!graph_digraph)
				adjlistweight[y].push_back(xyweight);
		}
		adjnum[x]++;
		if (!graph_digraph)
			adjnum[y]++;
	}
	x_visited.resize(Vnum);
	visited_ini();

	return;
}

void Graph_class::visited_ini() {
	rep(i, Vnum) {
		branch_type[i] = -1;
		x_visited[i] = false;
	}
	x_que.clear();
}

void Graph_class::graph_BFS(ll BFS_ini) {
	visited_ini();
	x_que.push_back(BFS_ini);
	x_visited[BFS_ini] = true;

	// option
	xdist[BFS_ini] = 0;
	vlist_from_root.clear();
	vlist_from_root.push_back(BFS_ini);
	//cout << BFS_ini << endl;
	rep(i, adjnum[BFS_ini]) {
		int x_new = adjlist[BFS_ini][i];
		branch_type[x_new] = i;
	}

	while (!x_que.empty()) {
		int x = x_que.front();
		x_que.pop_front();
		rep(i, adjnum[x]) {
			int x_new = adjlist[x][i];
			int dist_new = 1;
			if (graph_weight)
				dist_new = adjlistweight[x][i];
			if (!x_visited[x_new]) {
				x_visited[x_new] = true;
				x_que.push_back(x_new);

				// option
				adj_to_root[x_new] = x;
				vlist_from_root.push_back(x_new);
				xdist[x_new] = xdist[x] + dist_new;
				if (x != BFS_ini)
					branch_type[x_new] = branch_type[x];
				//cout << x_new << endl;
			}
		}
	}
	return;
}

void Graph_class::solve() {
	ll ans = InfLL;
	rep(BFS_ini, Vnum) {
		graph_BFS(BFS_ini);
		int branch_num = adjnum[BFS_ini];
		vl xdist_sum(branch_num);
		ll xdist_sum_sum = 0;
		rep(xtmp, Vnum) {
			if (xtmp == BFS_ini)
				continue;
			if (S[xtmp] == '0')
				continue;
			xdist_sum[branch_type[xtmp]] += xdist[xtmp];
			xdist_sum_sum += xdist[xtmp];
		}

		if (xdist_sum_sum % 2 == 1)
			continue;
		if (branch_num == 0)
			ans = 0;
		else {
			ll xdist_max = 0;
			rep(i, branch_num)
				xdist_max = max(xdist_max, xdist_sum[i]);
			if (xdist_max > xdist_sum_sum - xdist_max)
				continue;
			else {
				ans = min(ans, xdist_sum_sum / 2LL);
			}
		}
	}
	if (ans == InfLL)
		ans = -1;
	cout << ans << endl;
	return;
}

int main(void) {
	Graph_class graph;
	graph.read_edge();
	graph.adjini();
	graph.solve();
	return 0;
}

