ll dp[maxn];
ll dpp[maxn];
ll sz[maxn];
ll dpu[maxn];
ll dppu[maxn];
ll par[maxn];
ll kol;

void dfs(ll a,ll p=-1){
	topol.pb(a);
	sz[a]=s[a];
	par[a]=p;
	vector<ll> vec;
	ll s=0;
	for(auto v:ger[a]){
		if(v!=p){
			dfs(v,a);
			sz[a]+=sz[v];
			dp[a]+=dp[v];
			dp[a]+=sz[v];

			vec.pb(dpp[v]+sz[v]);
			s+=dpp[v]+sz[v];
		}	
	}
	sort(vec.begin(),vec.end());
	if(vec.size()){
		if(s-vec.back()<vec.back()){
			dpp[a]=2*vec.back()-s;
		}else{
			dpp[a]=s%2;
		}
	}
}
void dfss(ll a,ll p=-1){
	for(auto v:ger[a]){
		if(v!=p){
			dpu[v]=dpu[a]+dp[a]-(dp[v]+sz[v])+(kol-sz[v]);
			dfss(v,a);
		}
	}
}
int main(){
	ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);	
