		for(auto v:ger[p]){
			if(v!=i && v!=par[p]){
				vec.pb(dpp[v]+sz[v]);
				s+=dpp[v]+sz[v];
			}
		}
		vec.pb(dppu[p]);
		s+=dppu[p];
		sort(vec.begin(),vec.end());
		if(vec.size()){
			if(s-vec.back()<vec.back()){
				dppu[i]=2*vec.back()-s;
			}else{
				dppu[i]=s%2;
			}
		}
		dppu[i]+=kol-sz[i];
	}
	ll ans=inf;
	for(ll i=0;i<n;i++){
		vector<pii> vec;
		for(auto v:ger[i]){
			if(v!=par[i]){
				vec.pb(mp(dp[v]+sz[v],dpp[v]+sz[v]));
			}
		}
		vec.pb(mp(dpu[i],dppu[i]));
		sort(vec.begin(),vec.end());
		ll s=0;
		for(auto e:vec){
			s+=e.F;
		}
		if(s%2==1 || vec.back().S>s-vec.back().F){
