    Graph G(N, S);
    REP(i, N - 1){
        int a, b; cin >> a >> b;
        G.add_Undirected_edge(a - 1, b - 1);
    }

    int ans = INF;
    REP(i, N){
        G.dfs(i);
        int n = G.cnt[i];
        G.dfs2(i);
        if(G.cnt[i] == 0) Min(ans, n / 2);
    }
    Ans(ans < INF, ans, -1);

    return 0;
}

