    for (int i = 0; i < n; ++i) {

        vector<lint> nstot(n, 0);
        vector<lint> ns(n, 0);
        vector<int> depth(n, 0);
        {
            function<void(int, int)> dfs = [&](int c, int p) {
                for (auto &v : edges[c]) {
                    if (v == p)
                        continue;
                    depth[v] = depth[c] + 1;
                    dfs(v, c);
                    ns[c] += ns[v];
                    nstot[c] += nstot[v];
                }
                nstot[c] += ns[c];
                if (s[c] == '1')
                    ns[c] = 1;
            };
            dfs(i, -1);
        }

        if (nstot[i] % 2 == 1) {
            continue;
        }
        vector<lint> dp(n, inf);
        function<void(int, int)> dfs = [&](int c, int p) {
            dp[c] = -100000000;
            for (auto &v : edges[c]) {
                if (v == p)
                    continue;
                dfs(v, c);
                dp[c] = max(dp[c], dp[v] + ns[v] - (nstot[c] - nstot[v] - ns[v]));
            }
            if (dp[c] < 0) {
                dp[c] = ((-dp[c]) % 2 == 0) ? 0 : 1;
            }
        };
        dfs(i, -1);
        if (dp[i] == 0) {
            ret = min(ret, nstot[i] / 2);
        }
    }
    if (ret == inf)
        cout << -1 << "\n";
    else
        cout << ret << "\n";
    return 0;
}

