constexpr int INF = 1e9+7;

string s;

pair<int, int> dfs2(vector<vector<int>> &g, int v, int p) {
    pair<int, int> ret = {0, 0};
    for (auto u: g[v]) {
        if (u == p) continue;
        pair<int, int> t = dfs2(g, u, v);
        ret.first += t.first;
        ret.second += t.second + t.first;
    }
    if (s[v] == '1') ret.first += 1;
    return ret;
}

int dfs(vector<vector<int>> &g, int v) {
    static int t[2000];
    if (g[v].size() == 1) return INF;
    for (int i = 0; i < g[v].size(); ++i) {
        pair<int, int> tmp = dfs2(g, g[v][i], v);
        t[i] = tmp.first + tmp.second;
    }
    int sum = accumulate(t, t + g[v].size(), 0);
    if (sum % 2 != 0) return INF;
    for (int i = 0; i < g[v].size(); ++i) {
        if (t[i] > sum/2) return INF;
    }
    return sum/2;
}

