typedef long long ll;
using namespace std;

struct DP{
	int mi, dsum, vnum;
};

int N, x, ans = 1e9, dmi = 1e9;
string S;
vector<int> G[2020];
DP dp[2020];
int used[2020][2020];

DP dfs(int v, int p = -1){
	if(used[x][v]) return dp[v];
	dp[v].dsum = 0, dp[v].vnum = S[v] - '0';
	int ma = 0, mami = 0;
	rep(i, G[v].size()){
		int to = G[v][i];
		if(to == p) continue;
		int dis = dfs(to, v).dsum + dfs(to, v).vnum;
		dp[v].dsum += dis;
		dp[v].vnum += dfs(to, v).vnum;
		if(ma < dis){ ma = dis; mami = dfs(to, v).mi + dfs(to, v).vnum; }
	}
	if(dp[v].dsum % 2 == 0){
		if(dp[v].dsum - ma >= mami){
			dp[v].mi = 0;
		}else{
			dp[v].mi = mami - (dp[v].dsum - ma);
		}
	}else{
		if(dp[v].dsum - ma >= mami){
			dp[v].mi = 1;
		}else{
			dp[v].mi = mami - (dp[v].dsum - ma);
		}
	}
	used[x][v] = 1;
	return dp[v];
}

int main(){
	cin >> N >> S;
	rep(i, N-1){
		int a, b; cin >> a >> b;
		a--; b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	for(x=0; x<N; x++){
		if(ans > dfs(x).mi) ans = dfs(x).mi;
		if(dfs(x).mi == 0 && dmi > dfs(x).dsum) dmi = dfs(x).dsum;
	}
	if(ans == 0) cout << dmi/2 << endl;
	else cout << -1 << endl;
	return 0;
}

#include<bits/stdc++.h>
#define count couch

using namespace std;

const int maxn = 2005;

int n;
string s;
vector<int> g[maxn];

int count[maxn];
int low[maxn], high[maxn];

void dfs_solve(int v, int p) {
  count[v] = (s[v] == '1');

  if(p != -1 && g[v].size() == 1) {
    low[v] = high[v] = 0;
    return;
  }

  vector<int> ts;

  int least = 0, odd = 0;

  high[v] = 0;
  for(int s : g[v]) if(s != p) {
    dfs_solve(s, v);
    count[v] += count[s];
    int a = low[s] + count[s], b = high[s] + count[s];
    high[v] += b;
    least = max(least, a);
    odd ^= (a & 1);
    ts.push_back(b);
  }

  sort(ts.begin(), ts.end());

  if(ts.size() == 1) {
    low[v] = least;
    return;
  }

  low[v] = 1e9;
  int sum_smaller = 0, countodd = 0, counteven = 0;

  for(int x : ts) {
    if(x % 2 == 0) ++counteven;
    else ++countodd;
  }

  for(int i = 0; i < ts.size(); ++i) {
    sum_smaller += ts[i];
    if(ts[i] % 2) --countodd;
    else --counteven;
    if(ts[i] < least || (i + 1 < ts.size() && ts[i + 1] == ts[i])) continue;

    int sum = sum_smaller + (ts[i] - 1) * (countodd + counteven);
    if(ts[i] % 2) sum += countodd;
    else sum += counteven;

    if(ts[i] * 2 <= sum) low[v] = min(low[v], odd);
    else low[v] = min(low[v], ts[i] * 2 - sum);
  }


  assert(low[v] % 2 == high[v] % 2);
  assert(low[v] <= high[v]);
}

int main() {
  ios_base::sync_with_stdio(false); cin.tie(NULL);

  cin >> n >> s;
  for(int i = 0; i + 1 < n; ++i) {
    int u, v;
    cin >> u >> v;
    g[--u].emplace_back(--v);
    g[v].emplace_back(u);
  }

  int ans = 1e9 + 7;
  for(int root = 0; root < n; ++root) {
    dfs_solve(root, -1);
    if(low[root] == 0) {
      ans = min(ans, high[root] / 2);
    }
  }

  cout << (ans > 1e9 ? -1 : ans) << endl;

  return 0;
}

