using namespace std;

int n;
char s[2001];
vector <int> v[2000];

pair<int, pair<int, int>> dfs(int x, int y) {
    int c1 = 0, c2 = 0, c3 = 0, m = 0, sum = 0, i;

    for (i = 0; i < v[x].size(); i++) {
        if (v[x][i] == y) continue;

        pair<int, pair<int, int>> p = dfs(v[x][i], x);

        c1 += p.first;
        c2 += p.second.first + p.first;
        c3 += p.second.second;
        m = max(m, p.second.first + p.first - p.second.second * 2);
        sum += p.second.first + p.first - p.second.second * 2;
    }

    c3 += min(sum - m, sum / 2);

    if (s[x] == '1') c1++;

    return make_pair(c1, make_pair(c2, c3));
}

int main() {
    int ans = 1e9, i;

    scanf("%d", &n);
    scanf("%s", s);

    for (i = 0; i < n - 1; i++) {
        int a, b;

        scanf("%d %d", &a, &b);
        a--;
        b--;

        v[a].push_back(b);
        v[b].push_back(a);
    }

    for (i = 0; i < n; i++) {
        pair<int, pair<int, int>> p = dfs(i, -1);
        if (p.second.first % 2 == 0 && p.second.second == p.second.first / 2) ans = min(ans, p.second.second);
    }

    if (ans == 1e9) ans = -1;
    printf("%d\n", ans);

    return 0;
}

