int D[N], C[N], U[N];

void DFS(int v, int p = -1) {
	C[v] = (S[v] - '0');
	for (int u : G[v]) if (u != p) DFS(u, v), C[v] += C[u], U[v] += U[u] + C[u];
	D[v] = U[v] & 1;
	for (int u : G[v]) if (u != p) D[v] = max(D[v], D[u] + C[u] - (U[v] - (U[u] + C[u])));
}

