class ECompleteCompress {
public:
    string S;
    int N;
    vector<vector<int>> E;
    vector<int> SZ, P;
    vector<ll> D;
    vector<ll> UP;
    ll ans;

    void dfs(int u, int p) {
        P[u] = p;
        SZ[u] = S[u] == '1';
        D[u] = 0;
        for (int v : E[u]) {
            if (v != p) {
                dfs(v, u);
                SZ[u] += SZ[v];
                D[u] += D[v];
                D[u] += SZ[v];
            }
        }
    }

    void dfs2(int u, int cnt, ll depth) {
        UP[u] = depth;
        ll tot = 0;
        for (int v : E[u]) if (v != P[u]) {
            tot += D[v] + SZ[v];
            cnt += SZ[v];
        }

        for (int v : E[u]) {
            if (v != P[u]) {
                ll mine = tot + cnt - (2*SZ[v] + D[v]);
                dfs2(v, cnt - SZ[v], mine);
            }
        }
    }

    void solve(istream& cin, ostream& cout) {
        cin >> N >> S;
        E.resize(N);
        SZ.resize(N);
        P.resize(N);
        D.resize(N);
        UP.resize(N);
        for (int i = 0; i < N - 1; ++i) {
            int u, v;
            cin >> u >> v;
            --u;
            --v;
            E[u].push_back(v);
            E[v].push_back(u);
        }

        dfs(0, -1);
        dfs2(0, 0, 0LL);

//        cout << SZ << D << UP;
        ll ans = 1e18;
        for (int i = 0; i < N; ++i) {
            vector<ll> Q;
            for (int v : E[i]) {
                if (v == P[i]) {
                    Q.push_back(UP[i]);
                } else {
                    Q.push_back(D[v] + SZ[v]);
                }
            }
            sort(Q.begin(),Q.end());
//            cout << Q << endl;
            ll tot = 0;
            for (int q: Q) tot += q;
            if (tot % 2 == 0 && Q.back() <= tot/2) {
                ans = min(ans, tot/2);
            }
        }
        if (ans < 9e17) {
            cout << ans << endl;
        } else {
            cout << -1 << endl;
        }
    }
};


int main() {
	ios_base::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
	ECompleteCompress solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
    return 0;
}

