void precalc(int v, int p, int h) {
    sz[v] = s[v - 1] - '0';
    hg[v] = h;
    for (auto to: ed[v]) {
        if (to == p) {
            continue;
        }
        precalc(to, v, h + 1);
        sz[v] += sz[to];
    }
}

bool good(priority_queue<int> hp) {
    while (hp.size() > 1) {
        int u = hp.top();
        hp.pop();
        int v = hp.top();
        hp.pop();
        if (u == 0 && v == 0) {
            continue;
        } else if (u == 0 || v == 0) {
            return false;
        } else {
            u--;
            v--;
            hp.push(u);
            hp.push(v);
        }
    }
    if (hp.size() == 1 && hp.top() != 0) {
        return false;
    }
    return true;
}

void dfs(int v, int p) {
    int cnt = 0;
    int sum = 0;
    priority_queue<pair<int, int> > hp;
    for (auto to: ed[v]) {
        if (to == p) {
            continue;
        }
        dfs(to, v);
        hp.push(make_pair(dp[to], to));
    }
    while (hp.size() > 1) {
        auto a = hp.top();
        hp.pop();
        auto b = hp.top();
        hp.pop();
        if (a.first == hg[v] * sz[a.second] || b.first == hg[v] * sz[b.second]) {
            hp.push(a);
            hp.push(b);
            break;
        } else {
            int u = min(a.first - hg[v] * sz[a.second], b.first - hg[v] * sz[b.second]);
            a.first -= u;
            b.first -= u;
            hp.push(a);
            hp.push(b);
        }
    }
    dp[v] = 0;
    while (hp.size() > 0) {
        dp[v] += hp.top().first;
        hp.pop();
    }
    if (s[v - 1] == '1') {
        dp[v] += hg[v];
    }
}

