void addedge(int x, int y)
{
	nxt[++tot] = head[x];
	head[x] = tot;
	to[tot] = y;
}
bool vis[maxn*2];
int dp[maxn*2], mx[maxn*2], sz[maxn*2];
int calcdp(vector<int> &v)
{
	int ret = 0;
	int mxi = 0, sum = 0;
	for (int i=0; i<v.size(); i++)
	{
		int x = v[i];
		if (dp[x]+sz[x]>=dp[mxi]+sz[mxi]) mxi = x;
		sum += dp[x]+sz[x];
	}
	int M = dp[mxi]+sz[mxi];
	if (M*2<=sum) return 0;
	int mxsum = 0;
	for (int i=0; i<v.size(); i++)
	{
		int x = v[i];
		if (x==mxi) continue;
		mxsum += mx[x]+sz[x];
	}
	return max(0, M-mxsum);
}
void dfs(int e)
{
	vis[e] = true;
	int pre = to[e^1], x = to[e];
	sz[e] = f[x];
	mx[e] = 0;
	vector<int> v;
	for (int i=head[x]; i; i=nxt[i])
	{
		int u = to[i];
		if (u==pre) continue;
		if (!vis[i]) dfs(i);
		sz[e] += sz[i];
		mx[e] += mx[i]+sz[i];
		v.PB(i);
	}
	dp[e] = calcdp(v);
}
