int ans = INF;

int cnt[MAX];
int dsum[MAX];

void dfs0(int x, int p = -1) {	
	for (int y : e[x]) {
		if (y == p) continue;
		dfs0(y, x);
		dsum[x] += (dsum[y] + cnt[y]);
		cnt[x] += cnt[y];
	}
	cnt[x] += a[x];
}

int d[MAX];

void dfs(int x, int p = -1) {
	vpii v;
	for (int y : e[x]) {
		if (y == p) continue;
		dfs(y, x);
		v.pb(mp(dsum[y] + cnt[y], y));
	}
	int res = 0;
	if (sz(v)) {
		sort(v.begin(), v.end());
		int sum = 0;
		for (auto z : v) sum += z.first;
		int bv = v.back().second;
		int b = v.back().first;
		if ( (sum - b) >= b) {
			res = sum / 2;
		} else {
			int can = d[bv];
			int sum2 = sum - b;
			int want = (b - sum2) / 2;
			int take = min(can, want);
			res = take + min(can - take, sum2);
		}
	}	
	d[x] = res;
}

int calc(int root) {
	memset(cnt, 0, sizeof(cnt));
	memset(dsum, 0, sizeof(dsum));
	memset(d, 0, sizeof(d));
	dfs0(root);	
//	if (dsum[root] % 2 == 1) return INF;
	dfs(root);
	if (d[root] * 2 == dsum[root]) {
		return dsum[root] / 2;
	}	
	return INF;
}

