LL dfs(int now, int from, int dist, int root) {
	vals[root].pb(dist);
	LL ans = 0;
	//cout << now << " " << from << endl;
	if (s[now] == '1') {
		sum[root] += dist;
		ans += dist;
	}
	if (now == root) {
		LL maxim = 0;
		for (auto next : edges[now]) {
			if (next == from) continue;
			LL c = dfs(next, now, dist + 1, root);
			MX(maxim, c);
			ans += c;
		}
		if (maxim > ans - maxim) ables[now] = false;
		else if (sum[now] % 2 == 1) ables[now] = false;
		else ables[now] = true;
	}
	else {
		for (auto next : edges[now]) {
			if (next == from) continue;
			ans += dfs(next, now, dist + 1, root);
		}
	}
	return ans;
}
