    maxv = H[p] - (F[u] + C[u]) + (C[1] - C[u]);
    H[u] += maxv;
  }
  for (auto v : G[u])
    if (v != p) {
      dfs2(v, u);
      maxv = max(maxv, F[v] + C[v]);
    }
  if (maxv * 2 <= H[u] && !(H[u] & 1)) ans = min(ans, H[u] / 2);
}

