int f[maxn];
int siz[maxn];
int sum[maxn];
int head[maxn];
char s[maxn];
struct edge
{
	int to,nex;
	edge(int to=0,int nex=0):to(to),nex(nex){}
};
vector<edge> G;
inline void addedge(int u,int v)
{
	G.push_back(edge(v,head[u])),head[u]=G.size()-1;
	G.push_back(edge(u,head[v])),head[v]=G.size()-1;
}
void dp(int u,int fa)
{
	siz[u]=sum[u]=0;
	if(s[u]=='1')
	{
		siz[u]=1;
	}
	int mx=-1;
	for(int i=head[u];~i;i=G[i].nex)
	{
		int v=G[i].to;
		if(v!=fa)
		{
			dp(v,u);
			f[v]+=siz[v];
			siz[u]+=siz[v];
			sum[u]+=sum[v]+siz[v];
			if(mx==-1||f[mx]<f[v]) mx=v;
		}
	}
	if(mx==-1) f[u]=0;
	else
	{
		int t=sum[u]-sum[mx]-siz[mx];
		if(t>=f[mx]) f[u]=sum[u]&1;
		else f[u]=f[mx]-t;
	}
}
int solve(int root)
{
	dp(root,-1);
	return f[root]==0?sum[root]>>1:-1;
}
int main()
{
	scanf("%d",&n);
