		addedge(a,b);
	}
	int an=-1;
	for(int i=1;i<=n;++i)
	{
		int r=solve(i); if(r==-1) continue;
		if(an==-1||an>r) an=r;
	}
	printf("%d\n",an);
	return 0;
}

