void dp(int x,int fa,int dep){
	int sum=0,mx=0;
	g[x]=a[x];
	cnt+=a[x]*dep;
	h[x]=0;
	for (int y=la[x];y;y=ne[y]){
		int z=w[y];
		if (z==fa)continue;
		dp(z,x,dep+1);
		mx=max(mx,f[z]+g[z]);
