struct LowestCommonAncestor{
    int n,h;
    vector<vector<int>> G,par;
    vector<int> dep;
    LowestCommonAncestor(int n):n(n),G(n),dep(n){
        h=1;
        while((1<<h)<=n) ++h;
        par.assign(h,vector<int>(n,-1));
    }
    void add_edge(int u,int v){
        G[u].emplace_back(v);
        G[v].emplace_back(u);
    }
    void dfs(int v,int p,int d){
        par[0][v]=p;
        dep[v]=d;
        for (auto u:G[v]){
            if (u!=p) dfs(u,v,d+1);
        }
    }
    void build(int r=0){
        dfs(r,-1,0);
        rep(k,h-1){
            rep(v,n){
                if (par[k][v]>=0) par[k+1][v]=par[k][par[k][v]];
            }
        }
    }
    int lca(int u,int v){
        if (dep[u]>dep[v]) swap(u,v);
        rep(k,h){
            if ((dep[v]-dep[u])&1<<k) v=par[k][v];
        }
        if (u==v) return u;
        for (int k=h-1;k>=0;--k){
            if (par[k][u]!=par[k][v]) u=par[k][u],v=par[k][v];
        }
        return par[0][u];
    }
    int distance(int u,int v){
        return dep[u]+dep[v]-dep[lca(u,v)]*2;
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N; string S; cin >> N >> S;
    LowestCommonAncestor LCA(N);
    vector<vector<int>> G(N);
    rep(i,N-1){
        int a,b; cin >> a >> b;
        LCA.add_edge(--a,--b);
        G[a].push_back(b); G[b].push_back(a);
    }
    vector<int> par(N,-1);
    queue<int> que;
    que.push(0);
    while(!que.empty()){
        int v=que.front(); que.pop();
        for (auto nv:G[v]){
            if (nv==par[v]) continue;
            par[nv]=v;
            que.push(nv);
        }
    }
    LCA.build();
    ll ans=IINF;
    rep(i,N){
        map<int,ll> m;
        rep(j,N) if (S[j]=='1'){
            if (j==i) continue;
            ll d=LCA.distance(i,j);
            if (LCA.lca(i,j)!=i) m[par[i]]+=d;
            else {
                for (auto k:G[i]){
                    if (k==par[i]) continue;
                    if (LCA.lca(j,k)==k) m[k]+=d;
                }
            }
        }
        ll cnt=0,M=0;
        for (auto x:m){
            ll a=x.second;
            cnt+=a,chmax(M,a);
        }
        if (!(cnt%2!=0||M>cnt/2)) chmin(ans,cnt/2);
    }
    if (ans==IINF) cout << -1 << endl;
    else cout << ans << endl;
}

