int cnt[2005][2005];
P dfs(int v,int u,int g,int d){
	dist[g][v] = d;
	if(h[v]){
		sum[g][v] = d;
		cnt[g][v] = 1;
	}
	rep(i,edge[v].size()){
		if(edge[v][i] == u) continue;
		P p = dfs(edge[v][i],v,g,d+1);;
		sum[g][v] += p.fi;
		cnt[g][v] += p.sc;
	}
	return P(sum[g][v],cnt[g][v]);
}
int gen(int v,int u,int g){
	int S = 0, mx = 0;
	rep(i,edge[v].size()){
		if(edge[v][i] == u) continue;
		S += sum[v][edge[v][i]];
		mx = max(mx,sum[v][edge[v][i]]);
	}
	if(mx <= S/2) return cnt[g][v]+S%2;
	else{
		int id;
		rep(i,edge[v].size()){
			if(edge[v][i] == u) continue;
			if(mx == sum[v][edge[v][i]]) id = edge[v][i];
		}
		int reduction = gen(id,v,g);
		if(reduction <= S-mx) return cnt[g][v]+S%2;
		else return (reduction-S+mx)+cnt[g][v];
	}
}
int check(int v,int u,int g){
	int S = 0, mx = 0;
	rep(i,edge[v].size()){
		if(edge[v][i] == u) continue;
		S += sum[g][edge[v][i]];
		mx = max(mx,sum[g][edge[v][i]]);
	}
	if(u == -1){
		if(mx <= S/2) return S;
		int id = -1;
		rep(i,edge[v].size()){
			if(edge[v][i] == u) continue;
			if(sum[g][edge[v][i]] == mx) id = edge[v][i];
		}
		int reduction = gen(id,v,g);
		//cout << id << " " << v << " " << g << " " << reduction << endl;
		if(reduction > S-mx) return INF;
		else return S;
	}
}
