struct edge{int to, cost;};

class Graph
{
public:
    int N;
    vector<vector<edge>> G;
    vec dp, dp2, dp3;

    Graph(int N): N(N){
        G = vector<vector<edge>>(N, vector<edge>(0));
        dp.resize(N);
        dp2.resize(N);
        dp3.resize(N);
    }

    void add_Directed_edge(int from, int to, int cost = 1){
        G[from].push_back(edge({to, cost}));
    }

    void add_Undirected_edge(int v1, int v2, int cost = 1){
        add_Directed_edge(v1, v2, cost);
        add_Directed_edge(v2, v1, cost);
    }

    void dfs1(int v, int p = -1){
        if(p == -1) dp[v] = 0;
        else dp[v] = dp[p] + 1;
        for(auto e: G[v]) if(e.to != p){
            dfs1(e.to, v);
        }
    }

    void dfs2(int v, string &S, int p = -1){
        if(p != -1 && S[v] == '1') dp2[v] = dp[v];
        else dp2[v] = 0;
        for(auto e: G[v]) if(e.to != p){
            dfs2(e.to, S, v);
            dp2[v] += dp2[e.to];
        }
    }

    void dfs3(int v, int U, int p = -1){
        int i0, MM = -1, SS = 0;
        for(auto e: G[v]) if(e.to != p){
            SS += dp2[e.to];
            if(dp2[e.to] > MM){
                i0 = e.to;
                MM = dp2[e.to];
            }
        }
        if(SS >= 2 * MM){
            SS += min(dp2[v] - U, SS / 2);
            return;
        }else{
            MM -= SS - MM;
            dfs3(i0, U + MM, v);
        }

    }
};

signed main(){

    int N; cin >> N;
    string S; cin >> S;
    Graph G(N);
    int a, b;
    REP(i, N - 1){
        cin >> a >> b;
        G.add_Undirected_edge(a - 1, b - 1);
    }
    int ans = INF;
    REP(i, N){
        G.dfs1(i);
        G.dfs2(i, S);
        pairs p;
        int val = G.dp2[i];
        if(val % 2 == 0){
            for(auto e: G.G[i]) p.pb(Pii(G.dp2[e.to], i));
            Sort(p);
            Reverse(p);
            int tmp = 0;
            G.dfs3(p[0].s, tmp);
            p[0].f -= 2 * tmp;
            if(p[0].f * 2 <= val) Min(ans, val / 2);
        }
    }
    if(ans < INF) Out(ans);
    else Out(-1);

    return 0;
}

