const int N = 2222;
vector<int> a[N];
string s;

long long level[N];
int cnt[N];
long long minsuml[N];
long long suml[N];

void dfs(int v, int p) {
	long long res = 0;
	if (s[v] == '1') {
		res += level[v];
		cnt[v] = 1;
	}
	vector<int> tos;
	vector<long long> sumls;
	for (int x : a[v]) {
		if (x != p) {
			level[x] = level[v] + 1;
			dfs(x, v);
			suml[v] += suml[x] + cnt[x];
			sumls.push_back(suml[x] + cnt[x]);
			tos.push_back(x);
			cnt[v] += cnt[x];
		}
	}
	if (tos.empty()) {
		minsuml[v] = suml[v];
		return;
	}
	int idx = max_element(all(sumls)) - sumls.begin();
	if (suml[v] / 2 < sumls[idx]) {
		long long newsuml = suml[v] - sumls[idx] + minsuml[tos[idx]] + cnt[tos[idx]];
		if (newsuml / 2 >= minsuml[tos[idx]] + cnt[tos[idx]]) {
			minsuml[v] = suml[v] % 2;
		} else {
			minsuml[v] = newsuml - (minsuml[tos[idx]] + cnt[tos[idx]]);
		}
	} else {
		minsuml[v] = suml[v] % 2;
	}
}

long long solve(int r) {
	memset(level, 0, sizeof(level));
	memset(cnt, 0, sizeof(cnt));
	memset(minsuml, 0, sizeof(minsuml));
	memset(suml, 0, sizeof(suml));
	dfs(r, -1);
	if (minsuml[r] == 0) {
		return suml[r] / 2;
	} else {
		return -1;
	}
}

