		a[v].push_back(u);
	}

	long long ans = -1;
	for (int r = 0; r < n; ++r) {
		long long tmp = solve(r);
		if (ans == -1 || (tmp > -1 && tmp < ans)) {
			ans = tmp;
		}
	}

	cout << ans << "\n";

	return 0;
}

