	mi.push_back(make_pair(0LL,0LL));
	for(int go:v[b]){
		if(go==pr)continue;
		dfs(go,b);
		child[b]+=child[go];
		dp_max[b]+=dp_max[go]+child[go];
		mi.push_back(make_pair(dp_min[go]+child[go],-dp_max[go]));
	}
	sort(mi.begin(),mi.end());
	reverse(mi.begin(),mi.end());
	for(int j=0;j<mi.size();j++){
		mi[j].second*=-1LL;
	}
	long long int sz=0;
	long long int accume=0;
	long long int ss=0;
	long long int max_sum=0;
	for(int i=0;i<mi.size();i++){
		max_sum+=mi[i].second;
	}
	for(int i=0;i<mi.size();i++){
		accume=max_sum-mi[i].second;
		long long int z=mi[i].first;
		z-=accume;
		if(z<=0){
			if(dp_max[b]&1LL){
				dp_min[b]=max(dp_min[b],1LL);
			}
			else{
			}
		}
		else{
			dp_min[b]=max(dp_min[b],z);
		}
	}
	return;
	for(int i=0;i<mi.size();i++){
		ss+=mi[i].first;
	}
	for(int i=1;i<mi.size();i++){
		sz+=mi[i].first;
		accume+=((mi[i].second-mi[i].first)/2LL)*2LL;
	}
	mi[0].first-=sz;
	if(mi[0].first>0LL){
		long long int want=mi[0].first;
		long long int res=0;
		if((want&1LL)!=(accume&1LL)){
			res++;
			want--;
		}
		want-=min(want,accume);
		res+=want;
		dp_min[b]=res;
	}
	else{
		dp_min[b]=ss&1LL;
	}
}

