  for (int i = 0; i < n-1; ++i) {
    int a, b; cin >> a >> b; --a; --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  const int INF = 1e9;
  int best=INF;
  for (int i = 0; i < n; ++i) {
    state& s = dfs(i, -1);
    if (s.lo == 0) {
      assert(s.cost_times_two%2 == 0);
      best = min(best, s.cost_times_two/2);
      //cout << i << ": " << s.cost_times_two/2 << '\n';
    }
  }
  if (best == INF)
    best = -1;
  cout << best << '\n';
}

