                long long sum = 0;
                long long max = 0;
                for(auto nx : tree[i].neighbor){
                        long long ret = search(nx, &tree[i], 1);
                        sum += ret;
                        if(max < ret){
                                max = ret;
                        }
                }

                if(sum % 2 == 0 && 2 * max <= sum){
                        //cout << "c:" << i+1 << " sum:" << sum << endl;
                        if(ans == -1 || sum/2 < ans){
                                ans = sum / 2;
                        }
                }
        }

        cout << ans << endl;
}

long long search(node* n, node* prev, long long len)
{
        long long score = len * n->koma;
        for(auto nx : n->neighbor){
                if(nx != prev){
                        score += search(nx, n, len + 1);
                }
        }
        return score;
}

