int cnts[MAXN];


int dfs1(int u, int pr) {
	cnts[u] = 0;
	if (s[u] == '1') {
		cnts[u]++;
	}
	int cur = 0;
	vector<pair<int, int> > st;
	for (auto h: g[u]) {
		if (pr == h) {
			continue;
		}
		int kek = dfs1(h, u);
		st.pb({kek, h});
		cnts[u] += cnts[h];
		cur += kek;
	}
	if (st.empty()) {
		if (s[u] == '1') {
			return dist[u];
		}
		return 0;
	}
	int ans = 0;
	if (s[u] == '1') {
		ans += dist[u];
	}
	for (auto &x: st) {
		ans += dist[u] * cnts[x.second];
		x.first -= dist[u] * cnts[x.second];
		cur -= dist[u] * cnts[x.second];
	}
	sort(all(st));
	if (st.back().first <= cur - st.back().first) {
		ans += cur % 2;
	} else {
		int kek = 2 * st.back().first;
		for (auto x: st) {
			kek -= x.first;
		}
		ans += kek;
	}
	return ans;
}


