typedef pair <int, int> ii;
typedef pair <ii, int> iii;

const int Maxn = 2005;
const int Inf = 1000000000;

int n;
char str[Maxn];
vector <int> neigh[Maxn];
int res = Inf, best, bi;

ii Traverse(int v, int p, int lvl)
{
    ii res = ii(0, 0);
    if (str[v] == '1') { res.first += lvl; res.second++; }
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (u == p) continue;
        ii got = Traverse(u, v, lvl + 1);
        res.first += got.first;
        res.second += got.second;
    }
    return res;
}

int Solve(int v, int p)
{
    vector <iii> seq;
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (u == p) continue;
        seq.push_back(iii(Traverse(u, v, 1), u));
    }
    if (seq.empty()) return 0;
    sort(seq.begin(), seq.end());
    int mx = seq.back().first.second + Solve(seq.back().second, v);
    int sum = 0;
    for (int i = 0; i + 1 < seq.size(); i++)
        sum += seq[i].first.first;
    if (sum >= mx) return (sum + mx) % 2;
    else return mx - sum;
}

int main()
{
    scanf("%d", &n);
    scanf("%s", str + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b; scanf("%d %d", &a, &b);
