        for (int j = 0; j < neigh[i].size(); j++) {
            int u = neigh[i][j];
            int my = Traverse(neigh[i][j], i, 1).first;
            got += my; mx = max(mx, my);
        }
        if (got % 2 == 0 && (got / 2 < res || got / 2 == res && mx < best)) {
            res = got / 2; best = mx; bi = i;
        }
    }
    if (Solve(bi, 0) == 0) printf("%d\n", res);
    else printf("-1\n");
    return 0;
}

