constexpr int32_t MAX_N = 200000;//頂点数
constexpr int32_t MAX_LOGN = 30;//log2頂点数
std::vector<int32_t> graph[MAX_N];//木
namespace nLCA
{
	int root; // 根ノードの番号
	int parent[MAX_LOGN][MAX_N]; // 親を2^k回辿って到達する頂点(根を通り過ぎる場合は-1とする)
	int depth[MAX_N]; // 根からの深さ
	void dfs(int v, int p, int d) {
		parent[0][v] = p;
		depth[v] = d;
		for (int i = 0; i < graph[v].size(); i++) {
			if (graph[v][i] != p) dfs(graph[v][i], v, d + 1);
		}
	}
	// 初期化
	void init(int V) {
		// parent[0]とdepthを初期化する
		dfs(root, -1, 0);
		// parentを初期化する
		for (int k = 0; k + 1 < MAX_LOGN; k++) {
			for (int v = 0; v < V; v++) {
				if (parent[k][v] < 0) parent[k + 1][v] = -1;
				else parent[k + 1][v] = parent[k][parent[k][v]];
			}
		}
	}
	// uとvのLCAを求める
	int glca(int u, int v) {
		// uとvの深さが同じになるまで親を辿る
		if (depth[u] > depth[v]) std::swap(u, v);
		for (int k = 0; k < MAX_LOGN; k++) {
			if ((depth[v] - depth[u]) >> k & 1) {
				v = parent[k][v];
			}
		}
		if (u == v) return u;
		// 二分探索でLCAを求める
		for (int k = MAX_LOGN - 1; k >= 0; k--) {
			if (parent[k][u] != parent[k][v]) {
				u = parent[k][u];
				v = parent[k][v];
			}
		}
		return parent[0][u];
	}

}
