using COST_T = uint32_t;
//ダイクストラ
COST_T D_[2000][2000];
void Dijkstra(uint32_t s)
{
	auto& D = D_[s];
	using P = std::pair<COST_T, uint32_t>;//cost pos
	std::priority_queue<P, std::vector<P>, std::greater<>> que;
	std::fill(std::begin(D), std::end(D), 20002000);

	D[s] = 0;
	que.emplace(0, s);
	while (!que.empty())
	{
		auto p = que.top(); que.pop();
		const auto& nowpos = p.second;
		const auto& nowcost = p.first;
		if (D[nowpos] < nowcost) { continue; }

		//for (int32_t to = 0; to < N; ++to)
		//{
		//	auto cost = nowcost + graph[nowpos][to];
		//	if (cost < D[to]) {
		//		D[to] = cost;
		//		que.emplace(D[to], to);
		//	}
		//}

		for (const auto& e : graph[nowpos])
		{
			auto cost = nowcost + 1;
			if (cost < D[e]) {
				D[e] = cost;
				que.emplace(cost, e);
			}
		}

	}
}

int64_t func(int target)
{
	int64_t count = 0;
	std::priority_queue<std::pair<int, int>> que;
	for (size_t i = 0; i < N; i++)
	{
		if (S[i] == '0') { continue; }
		que.emplace(D_[target][i], i);
	}
	while (!que.empty())
	{
		auto top = que.top(); que.pop();
		if (que.empty()) { return 20002000; }
		auto top2 = que.top(); que.pop();
		auto next1 = top;
		auto next2 = top2;

		bool ok = false;
		for (auto& e : graph[top.second])
		{
			if (D_[target][e] == top.first - 1) {
				if (D_[target][e] > 0) {
					que.emplace(D_[target][e], e);
				}
				ok = true;
				break;
			}
		}
		if(!ok){return 20002000;}
		ok = false;
		for (auto& e : graph[top2.second])
		{
			if (D_[target][e] == top2.first - 1) {
				if (D_[target][e] > 0) {
					que.emplace(D_[target][e], e);
				}
				ok = true;
				break;
			}
		}
		if (!ok) {
			return 20002000;
		}
		++count;
	}

	return count;
}

