void dfs(int v, int par, int cd)
{
	dep[v] = cd;
	sum[v] = S[v] == '1' ? dep[v] : 0;
	rep(i, G[v].size()) {
		int u = G[v][i];
		if(u == par) continue;
		dfs(u, v, cd + 1);
		sum[v] += sum[u];
	}
