vector<int> G[2005];
int dep[2005], sum[2005];

void dfs(int v, int par, int cd)
{
	dep[v] = cd;
	sum[v] = S[v] == '1' ? dep[v] : 0;
	rep(i, G[v].size()) {
		int u = G[v][i];
		if(u == par) continue;
		dfs(u, v, cd + 1);
		sum[v] += sum[u];
	}
}

pair<int, int> solve(int v, int par)
{
	int tots = 0, maxs = 0, maxg = -1;
	rep(i, G[v].size()) {
		if(G[v][i] == par) continue;
		tots += sum[G[v][i]];
		maxs = max(maxs, sum[G[v][i]]);
		if(maxs == sum[G[v][i]]) maxg = G[v][i];
	}
	if(tots % 2 == 1) return MP(INF, INF);
	else if(tots < maxs * 2) {
		PII cur = solve(maxg, v);
		if(cur == MP(INF, INF)) return MP(tots - maxs, tots / 2);
		else return MP(tots - maxs + min(solve(maxg, v).first, maxs - tots / 2), tots / 2);
	} else return MP(tots / 2, tots / 2);
}

int main()
{
	scanf("%d%s", &n, S + 1);
	rep(i, n - 1) {
		int u, v;
		scanf("%d%d", &u, &v);
		G[u].push_back(v);
		G[v].push_back(u);
	}

	int ret = INF;
	rep1(i, n) {
		dfs(i, -1, 0);
		PII ca = solve(i, -1);
		if(ca.first == ca.second) ret = min(ret, ca.second);
	}
	printf("%d\n", ret >= INF ? -1 : ret);
	return 0;
}

#include <bits/stdc++.h>

using namespace std;
int n;
string s;
const int N = 3000;
vector<int> ed[N];
int sz[N];
int hg[N];
int dp[N];
int sumh[N];
void precalc(int v, int p, int h) {
    sz[v] = s[v - 1] - '0';
    hg[v] = h;
    sumh[v] = sz[v] * hg[v];
    for (auto to: ed[v]) {
        if (to == p) {
            continue;
        }
        precalc(to, v, h + 1);
        sz[v] += sz[to];
        sumh[v] += sumh[to];
    }
}


void dfs(int v, int p) {
    priority_queue<pair<int, int> > hp;
    for (auto to: ed[v]) {
        if (to == p) {
            continue;
        }
        dfs(to, v);
        hp.push(make_pair(sumh[to] - hg[v] * sz[to], to));
    }

    while (hp.size() > 1) {
        auto a = hp.top();
        hp.pop();
        auto b = hp.top();
        hp.pop();
        if (a.first == 0) {
            break;
        } else if (b.first == 0) {
            hp.push(a);
        } else {
            a.first--;
            b.first--;
            hp.push(a);
            hp.push(b);
        }
    }
    if (hp.empty()) {
        dp[v] = sz[v] * hg[v];
    } else {
        auto a = hp.top();
        int delta = sumh[a.second] - dp[a.second];
        dp[v] = max(sz[v] * hg[v], a.first + sz[v] * hg[v] - delta);
    }
}


int main() {
    cin >> n;
    cin >> s;
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        ed[u].push_back(v);
        ed[v].push_back(u);
    }
    int ans = n * n + 20;
    for (int root = 1; root <= n; root++) {
        precalc(root, 0, 0);
        int sum = 0;
        for (int i = 1; i <= n; i++) {
            if (s[i - 1] == '1') {
                sum += hg[i];
            }
        }
        if (sum % 2 == 1) {
            continue;
        }
        if (sum / 2 < ans) {
            dfs(root, 0);
            if (dp[root] == 0) {
                ans = sum / 2;
            }
        }
    }
    if (ans == n * n + 20) {
        cout << "-1\n";
    } else {
        cout << ans << "\n";
    }
    return 0;
}

