const int N = 1e6 + 5;
vi g[N];
int ok[N];
int S[N];
int lf[N];
int rg[N];
int get(vii v) {
	if (v.empty())
		return 0;
	if (v.size() == 1)
		return v[0].fi;
	int lf_sum = 0,rg_sum = 0;
	for (auto it : v) {
		lf_sum += it.fi;
		rg_sum += it.se;
	}
	int index = max_element(all(v)) - v.begin();
	lf_sum -= v[index].fi;
	rg_sum -= v[index].se;
	if (v[index].fi <= rg_sum) {
		return (lf_sum + v[index].fi) & 1;
	} else {
		return v[index].fi - rg_sum;
	}
}
void dfs(int node,int prev) {
	S[node] = ok[node];
	vii v;
	for (auto it : g[node]) {
		if (it == prev)
			continue;
		dfs(it,node);
		v.pb(mp(lf[it] + S[it],rg[it] + S[it]));
		S[node] += S[it];
		rg[node] += rg[it] + S[it];
	}
	lf[node] = get(v);
}
