    }
    int ans = 1e9;
    for (int i = 1;i <= n;++i) {
    	for (int j = 1;j <= n;++j)
    		lf[j] = rg[j] = S[j] = 0;
    	dfs(i,0);
    	if (!lf[i]) {
    		smin(ans,rg[i] / 2);
    	}
    }
    if (ans == 1e9)
    	ans = -1;
    cout << ans << '\n';
    return 0;
}

