pii dfs(int v,int p)
{
    int cnt=0;
    vector<pii> vec;
    for(int to:g[v])
        if(to!=p)
        {
            auto now=dfs(to,v);
            cnt+=now.x;
            vec.push_back({res[to]+now.x,now.y+now.x});
            res[v]+=res[to]+now.x;
        }
    if(s[v]=='1')
        cnt++;
    sort(vec.begin(),vec.end(),greater<pii>());
    if(vec.empty())
        return {cnt,0};
    if(vec.size()==1)
        return {cnt,vec[0].y};
    int sum=0,mx=max(vec[0].y,vec[1].x);
    for(auto p:vec)
        sum+=min(mx,p.x);
    int ret;
    if(mx*2>=sum)
        ret=2*mx-sum;
    else
        ret=res[v]%2;
//    cout<<"    "<<v<<" -> "<<cnt<<" "<<ret<<"\n";
    return {cnt,ret};
}

