	scanf("%d%s",&n,s+1);
	for(int i=1,u,v;i<n;i++) scanf("%d%d",&u,&v),add(u,v),add(v,u);

	for(int i=1;i<=n;i++){
		dfs1(i,0);
		if(dfs2(i,0)==0) ans=min(ans,dis[i]/2);	
	}
