using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef pair <int, int> pii;

bool solve() {
  int n;
  if (scanf("%d", &n) != 1) { return false; }
  static char s[3000];
  scanf("%s", s);

  vector<vector<int>> ed(n);
  for (int i = 0; i < n - 1; ++i) {
    int u, v;
    scanf("%d%d", &u, &v);
    --u, --v;
    ed[u].push_back(v);
    ed[v].push_back(u);
  }

  vector<pii> sumPath(n);

  function<pii(int, int)> dfs = [&](int u, int par) {
    int cnt = (s[u] == '1' ? 1 : 0);
    int sum = 0;
    for (int v : ed[u]) {
      if (v == par) { continue; }
      auto child = dfs(v, u);
      cnt += child.first;
      sum += child.first + child.second;
    }
    dbg("sumPath[%d] = (%d %d)\n", u, cnt, sum);
    sumPath[u] = {cnt, sum};
    return pii{cnt, sum};
  };

  dfs(0, -1);

  int u = 0, par = -1;
  while(1) {
    bool found = false;
    for (int v : ed[u]) {
      if (v == par) { continue; }
      dbg("u %d v %d : %d ? %d\n", u, v, (sumPath[v].first + sumPath[v].second) * 2, sumPath[u].second);
      if ((sumPath[v].first + sumPath[v].second) * 2 > sumPath[u].second) {
        dbg("%d => %d\n", u, v);
        par = u;
        u = v;
        found = true;
        break;
      }
    }
    if (!found) { break; }
  }

  int ans = dfs(u, -1).second;
  if (ans % 2 != 0) {
    printf("-1\n");
  } else {
    printf("%d\n", ans / 2);
  }

  return true;
}

int main() {
  while (solve());
  return 0;
}

