ll dfs1(ll par, ll pos) {
	if(dp[par][pos] != -1) return dp[par][pos];
	vector<ll> v;
	REP(i, tree[pos].size()) {
		if(tree[pos][i] == par) continue;
		v.pb(dfs1(pos, tree[pos][i]) + node[pos][tree[pos][i]]);
	}
	sort(ALL(v));
	int m = (int)v.size();
	if(m == 0) return dp[par][pos] = 0;
	if(m == 1) {
		return dp[par][pos] = v[0];
	}
	ll sum = 0;
	REP(i, m) sum += v[i];
	if(v[m - 1] > sum - v[m - 1]) {
		return dp[par][pos] = v[m - 1] - (sum - v[m - 1]);
	} else {
		if(sum % 2) return dp[par][pos] = 1;
		else return dp[par][pos] = 0;
	}
}

ll dfs2(ll par, ll pos) {
	if(node[par][pos] != -1) return node[par][pos];
	ll ret = 0;
	if(s[pos] == '1') ret++;
	REP(i, tree[pos].size()) {
		if(tree[pos][i] == par) continue;
		ret += dfs2(pos, tree[pos][i]);
	}
	return node[par][pos] = ret;
}

