int dfs(vector<vector<int>> &g, int v) {
    static int t[2000];
    for (int i = 0; i < g[v].size(); ++i) {
        pair<int, int> tmp = dfs2(g, g[v][i], v);
        t[i] = tmp.first + tmp.second;
    }
    int c = count(t, t + g[v].size(), 0);
    if (c == g[v].size()-1) return INF;
    int sum = accumulate(t, t + g[v].size(), 0);
    if (sum % 2 != 0) return INF;
    for (int i = 0; i < g[v].size(); ++i) {
        if (t[i] > sum/2) return INF;
    }
    return sum/2;
}

