	pii dfs(const int u, const int f)
	{
		size[u] = A[u];
		int val = 0, cnt = 0;
		for (int v : E[u])
			if (v != f)
			{
				pii tmp = dfs(v, u);
				int p = tmp.first; 
				cnt += tmp.second;
				size[u] += size[v];
				if (val >= p)
				{
					val -= p;
					int t = min(val >> 1, tmp.second);
					val -= t << 1;
					cnt += p + t;
				}
				else
				{
					p -= val;
					int t = min(p >> 1, cnt);
					p -= t << 1;
					cnt += t + val;
					val = p;
				}
			}
		return pii(size[u] + val, cnt);
	}

