	if(s[u]=='1') add[u]=dep;
	int A=0,B=0;
	for(int i=fir[u];i;i=nxt[i]){
		if(to[i]==fa) continue;
		dfs(to[i],u,dep+1);
		add[u]+=add[to[i]];
		size[u]+=size[to[i]];
		A=max(A,dp[to[i]]);
	}
