		if(to[i]==fa) continue;
		if((A&1)==(add[to[i]]&1)) B+=min(A,add[to[i]]);
		else B+=min(A-1,add[to[i]]);
	}
	if(A>B-A) dp[u]=2*A-B;
	else dp[u]=B%2;
	if(s[u]=='1') size[u]++;
	if(fa!=0) dp[u]+=size[u];
}

