    return mygcd(b,a%b);
}

ll mypow(ll x, ll n){
    ll ret = 1;
    while(n > 0){
        if(n&1){
            ret *= x;
            ret %= MOD;
        }
        x *= x;
        x %= MOD;
        n >>= 1;
    }
}

pair<ll,ll> rec(int v,string &str,vector<list<ll>> &e,vector<bool> &used){
    used[v] = true;
    if(e[v].size() == 1){
        if(str[v] == '1'){
            return make_pair(1,1);
        }else{
            return make_pair(0,0);
        }
    }
    pair<ll,ll> ret = make_pair(0,0);
    for(auto itr = e[v].begin();itr != e[v].end(); itr++){
        if(!used[*itr]){
            auto p = rec(*itr,str,e,used);
            ret.first += p.first;
            ret.second += p.second;
        }
    }
    if(str[v] == '1'){
        ret.second++;
    }
    ret.first += ret.second;
    return ret;
}

ll eval(int n,int v,string &str,vector<list<ll>> &e,vector<list<ll>> &val){
    vector<bool> used(n+1,false);
    used[v] = true;
    auto vitr = val[v].begin();
    for(auto itr = e[v].begin(); itr != e[v].end(); itr++,vitr++){
        (*vitr) = rec(*itr,str,e,used).first;
    }
    priority_queue<ll> pq;
    for(auto x = val[v].begin();x != val[v].end(); x++){
        if(*x != 0){
            pq.push(*x);
        }
    }
    ll ret = 0;
    while(true){
        if(pq.size() == 1){
            return INF;
        }else if(pq.size() == 0){
            return ret;
        }
        ll p = pq.top();
        pq.pop();
        ll q = pq.top();
        pq.pop();
        if(p > 1){
            pq.push(p-1);
        }
        if(q > 1){
            pq.push(q-1);
        }
        ret++;
    }
}

