        dfs1(ne,now);
        sum+=cnt[ne];
        ma[now]+=ma[ne]+cnt[ne];
        if(mi[ne]==-1)continue;
        int t=mi[ne]+cnt[ne];
        if(mii<t){
            mii=t;
            num=ne;
        }
    }
    if(num==-1){
        if(s[now]=='1'){
            mi[now]=0;
            ma[now]=0;
            cnt[now]=1;
        }
        else{
            mi[now]=-1;
            ma[now]=-1;
            cnt[now]=0;
        }
        return;
    }
    int sum2=0;
    rep(i,0,v[now].size()){
        int ne=v[now][i];
        if(ne==par)continue;
        if(ne==num)continue;
        sum2+=ma[ne]+cnt[ne];
    }
    if(sum2>=mii){
        mi[now]=abs(sum2-mii)%2;
    }
    else{
        mi[now]=mii-sum2;
    }
    cnt[now]=sum+(s[now]=='1');
}
