void dfs(int v, int p = -1) {
    cnt[v] = (s[v] == '1');
    len[v] = 0;

    int id = -1;
    ll sum = 0;

    for (int u : g[v]) {
        if (u == p) {
            continue;
        }
        dfs(u, v);
        cnt[v] += cnt[u];
        len[v] += len[u] + cnt[u];

        if (id == -1 || len[u] + cnt[u] - 2 * dp[u] > len[id] + cnt[id] - 2 * dp[id]) {
            id = u;
        }

        sum += len[u] + cnt[u];
    }

    if (id == -1) {
        dp[v] = 0;
        return;
    }

    sum -= len[id] + cnt[id];

    if (sum < len[id] + cnt[id] - 2 * dp[id]) {
        dp[v] = dp[id] + sum;
    } else {
        sum += len[id] + cnt[id];
        dp[v] = sum / 2;
    }
}

