void dfs(const int v, const int p = -1) {
    vector<pair<int64_t, int64_t>> curt;
    for (const int ne : gr[v])
    if (ne != p) {
        dfs(ne, v);
        curt.emplace_back(sum[ne].first + cnt[ne], sum[ne].second + cnt[ne]);
        cnt[v] += cnt[ne];
    }
    sort(rbegin(curt), rend(curt));
    int64_t maxsum = 0;
    for (size_t i = 1; i < curt.size(); ++i)
        maxsum += curt[i].second;
    if (!curt.empty()) {
        if (curt[0].first > maxsum)
            sum[v] = {curt[0].first - maxsum, maxsum + curt[0].second};
        else {
            if ((curt[0].first % 2) == (maxsum % 2))
                sum[v] = {0, maxsum + curt[0].second};
            else
                sum[v] = {1LL, maxsum + curt[0].second};
        }
    }
    if (s[v] == '1')
        ++cnt[v];
}

int64_t solve(const int v) {
    fill(begin(sum), end(sum), make_pair(0,0));
    fill(begin(cnt), end(cnt), 0);
    ans = 0;
    dfs(v);
