triple(int) dfs(int v, int par) {
    triple(int) ret = make_tuple(0, 0, have[v]);
    for (int to : g[v]) if (to != par) {
        triple(int) cur = dfs(to, v);
        int f, s, t;
        tie(f, s, t) = cur;
        f += t;
        s += t;
        int ff, ss, tt;
        tie(ff, ss, tt) = ret;
        int a, b, c;
        b = ss + s;
        c = tt + t;
        if (ff > f) {
            swap(ff, f);
            swap(ss, s);
        }
        if (f > ss) {
            a = f - ss;
        } else {
            a = (f ^ ff) & 1;
        }
        ret = make_tuple(a, b, c);
    }
    return ret;
}

pii count_dfs(int v, int par) {
    pii ret = {0, have[v]};
    for (int to : g[v]) if (to != par) {
        pii cur = count_dfs(to, v);
        ret.first += cur.first + cur.second;
        ret.second += cur.second;
    }
    return ret;
}

