pair<int, int> dfs2(int vertex, int last){
    int kv = (s[vertex] == '1');
    int sum = 0, mx = 0;
    for (int i=0;i<data[vertex].size(); i++){
        int to = data[vertex][i];
        if (to == last) continue;
        pair<int, int> p = dfs2(to, vertex);
        kv += p.second;
        int res = p.first;
        sum += res;
        mx = max(mx, res);
    }
    if (sum % 2 == 0){
        if (mx <= sum/2) return {kv, kv};
        return {2*mx-sum+kv, kv};
    }
    if (mx <= sum/2) return {kv+1, kv};
    return {2*mx-sum+kv, kv};
}
