void dfs(int u, int p){
    cnt[u] = hasPices[u];
    high[u] = 0;
    int maxLow = 0;
    priority_queue <int, vector<int>, greater<int> > Q;
    for(int v : adj[u])
        if (v != p){
            dfs(v, u);
            Q.push(high[v] + cnt[v]);
            if (Q.size() > 2)
                Q.pop();
            cnt[u] += cnt[v];
            high[u] += high[v] + cnt[v];
            maxLow = max(maxLow, low[v] + cnt[v]);
        }
    if (Q.empty()){
        low[u] = 0;
    } else {
        int x = maxLow;
        int sum = 0;
        for(int v : adj[u])
            if (v != p)
                sum += min(high[v] + cnt[v], x - abs(high[v] + cnt[v] - x) % 2);
        if (x * 2 > sum)
            low[u] = x * 2 - sum;
        else
            low[u] = sum % 2;
    }
}

