pair<long long, long long> cnt_dfs(int curr, int prev, int w) {
    pair<long long, long long> ret = {0, 0};
    // sum, num
    long long maxi = 0;
    for (auto x: v[curr]) {
        if (x == prev) continue;
        auto tmp = cnt_dfs(x, curr, w);
        if (s[x] == '1') tmp.second++;
        tmp.first += tmp.second;
        maxi = max(maxi, tmp.first);
        ret = {ret.first + tmp.first, ret.second + tmp.second};
    }
    if (prev != -1) {
        long long d;
        if (ret.first < maxi*2) d = ret.first - maxi;
        else d = ret.first / 2;
        ret.first -= d * 2;
        cnt[w] += d;
        return ret;
    }
    else {
        //cout << curr << " " << ret.first << " " << ret.second << " " << maxi << endl;
        if (ret.first >= maxi * 2 && ret.first % 2 == 0) return ret;
        else if (ret.first + 2 * cnt[w] >= maxi * 2 && ret.first % 2 == 0) {
            long long c = (maxi * 2 - ret.first + 1) / 2;
            cnt[w] -= c;
            ret.first += c * 2;
            return ret;
        } else return {-1, 0};
    }
}

