int ans = inf;

int n, l[maxn], sz[maxn], lb[maxn], rb[maxn], dep[maxn], e;
char S[maxn];

struct Edge {
	int v, x;
} E[maxn << 1];

int Max(int u, int v) {
	if ((u ^ v) & 1) ++ v;
	return max(u, v);
}

void dfs(int u, int fa) {
	sz[u] = (S[u] == '1'); lb[u] = inf; rb[u] = 0;
	int sum = 0, mx = 0, cmx = 0;
	for (int p = l[u]; p >= 0; p = E[p].x) {
		int v = E[p].v;
		if (v != fa) {
			dep[v] = dep[u] + 1;
			dfs(v, u);
			sz[u] += sz[v];
			rb[u] += sz[v] + rb[v];
			sum += sz[v] + lb[v];
			if (sz[v] + lb[v] >= mx) {
				cmx = mx;
				mx = sz[v] + lb[v];
			} else if (sz[v] + lb[v] > cmx) {
				cmx = sz[v] + lb[v];
			}
		}
	}
	lb[u] = sum;
	for (int p = l[u]; p >= 0; p = E[p].x) {
		int v = E[p].v;
		if (v != fa) {
			int t = mx;
			if (sz[v] + lb[v] == mx) t = cmx;
			int w = Max(sz[v] + lb[v], t);
			if (w > sz[v] + rb[v]) continue;
			int s = sum - sz[v] - lb[v] + w;
			lb[u] = min(lb[u], max(s & 1, s - 2 * (s - w)));
		}
	}
}

inline void addEdge(int u, int v) {
	E[e].v = v; E[e].x = l[u]; l[u] = e++;
}

int main() {
	memset(l, -1, sizeof(l));
	scanf("%d", &n);
	scanf("%s", S+1);
	for (int i = 1; i < n; i++) {
		int u, v; scanf("%d%d", &u, &v);
		addEdge(u, v);
		addEdge(v, u);
	}
	for (int i = 1; i <= n; i++) {
		dep[i] = 0;
		dfs(i, 0);
		int sum = 0;
		for (int j = 1; j <= n; j++) {
			if (S[j] == '1') {
				sum += dep[j];
			}
		}
		if (!lb[i]) ans = min(ans, sum / 2);
	}
	if (ans == inf) puts("-1");
	else printf("%d\n", ans);
	return 0;
}

