const int N = 2005;

vector<int> g[N];

int h[N], d[N], c[N];
string s;

void dfs(int u, int p = -1) {
  c[u] = s[u] == '1';
  d[u] = 0;
  for (int v : g[u]) {
    if (v != p) {
      h[v] = h[u] + 1;
      dfs(v, u);
      c[u] += c[v];
      d[u] += d[v] + c[v];
    }
  }
}

int dp[N];

void calc(int u, int p = -1) {
  int M = -1;
  for (int v : g[u]) {
    if (v != p) {
      calc(v, u);
      if (M == -1) M = v;
      else if (d[M] + c[M] < d[v] + c[v]) M = v;
    }
  }
  if (M == -1) {
    dp[u] = 0;
    return;
  }
  int other = d[u] - d[M] - c[M];
  if (other < dp[M] + c[M]) {
    dp[u] = dp[M] + c[M] - other;
  } else {
    dp[u] = d[u] & 1;
  }
}

