long long DFS(int lv, int st) {
    long long ans = 0;
    if (s[st] == '1') {
        ans += lv;
        sub[st]++;
    }
    for(auto en : adj[st]) if (en != pa[st]) {
        pa[en] = st;
        ans += DFS(lv + 1, en);
    }
    vector<ll> rem;
    for(auto en : adj[st]) if (en != pa[st]) {
        rem.push_back(d[en] + sub[en]);
        sub[st] += sub[en];
    }
    if (!rem.empty()) {
        sort(rem.begin(), rem.end());
        ll psum = 0;
        for(int i = 0; i < rem.size() - 1; i++) psum += rem[i];
        if (rem.back() > psum) {
            d[st] = rem.back() - psum;
        } else d[st] = 0;
    }
    //cout << st << " " << d[st] << " " << sub[st] << '\n';
    return ans;
}
long long solve() {
    long long ans = linf;
