        for(int v : adj[u])
            if (v != p)
                sum += min(high[v] + cnt[v], x - abs(high[v] + cnt[v] - x) % 2);
        if (x * 2 > sum)
            low[u] = x * 2 - sum;
        else
            low[u] = sum % 2;
    }
}

