void dfs(int u, int pr) {
	for (auto h: g[u]) {
		if (pr == h) {
			continue;
		}
		dist[h] = dist[u] + 1;
		dfs(h, u);
	}
	if (s[u] == '1') {
		cnt += dist[u];
	}
