	return 0;
}

#include "bits/stdc++.h"
using namespace std;
string s;
vector <int> g[2002];
int dp[2002];
int tot[2002];
int sum[2002];

void dfs(int x, int par) {
	sum[x] = 0;
	tot[x] = s[x] - '0';
	for(int i : g[x]) {
		if(i - par) {
			dfs(i, x);
			tot[x] += tot[i];
			sum[x] += tot[i] + sum[i];
		}
	}
}
bool matcher(int x, int par, int take) {
	if(take <= 0) return true;
	if(sum[x] - (sum[x] % 2) < take) return false;

	int big = -1;
	for(int i : g[x]) {
		if(i - par) {
			if(big == -1 || tot[big] + sum[big] < tot[i] + sum[i]) {
				big = i;
			}
		}
	}
	if(big == -1) return false;
	int w = tot[big] + sum[big];
	if(sum[x] - w < w) {
		int opt1 = 2*w - sum[x];
		int opt2 = take - (sum[x] - w);
		return matcher(big, x, min(opt1, opt2));
	} else {
		return true;
	}
}

int main(int argc, char const *argv[])
{
	int n;
	cin >> n;
	cin >> s;
	s = "&" + s;
	for(int i = 1; i < n; i++) {
		int a, b;
		cin >> a >> b;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	int ans = INT_MAX;
	for(int i = 1; i <= n; i++) {
		dfs(i, 0);
		if(sum[i] % 2 == 0) {
			if(matcher(i, 0, sum[i])) {
				ans = min(ans, sum[i] / 2);
			}
		}
	}
	if(ans == INT_MAX) ans = -1;
	cout << ans << endl;
	return 0;
}

