	vector<vi> adjlist;
	vector<vl> adjlistweight;
	vi adjnum;

	vi adj_to_root;
	vector<DP_struct> DP;
	vi vlist_from_root;
	vl xdist;

	vb x_visited;
	deque<int> x_que;

	vi branch_type;


	void read_edge();
	void adjini();
	void visited_ini();
	void graph_BFS(ll BFS_ini);
