// ----- graph -----

void Graph_class::read_edge() {
	cin >> Vnum;
	if (graph_tree)
		Enum = Vnum - 1;// graph
	else
		cin >> Enum;
	edgelist.resize(Enum);
	edgeweight.resize(Enum, 1);
	cin >> S;
	rep(i, Enum) {
		if (graph_weight)
			cin >> edgelist[i].first >> edgelist[i].second >> edgeweight[i];
		else
			cin >> edgelist[i].first >> edgelist[i].second;
		if (graph_from1) {
			edgelist[i].first--;
			edgelist[i].second--;
		}
	}
	return;
}

void Graph_class::adjini() {
	branch_type.resize(Vnum);
	adjnum.resize(Vnum);
	xdist.resize(Vnum, -1);
	adjlist.resize(Vnum);
	if (graph_weight)
		adjlistweight.resize(Vnum);
	adj_to_root.resize(Vnum, -1);
	DP.resize(Vnum);
	rep(i, Vnum)
		adjnum[i] = 0;
	rep(i, Enum) {
		int x = edgelist[i].first;
		int y = edgelist[i].second;
		adjlist[x].push_back(y);
		if (!graph_digraph)
			adjlist[y].push_back(x);
		if (graph_weight) {
			ll xyweight = edgeweight[i];
			adjlistweight[x].push_back(xyweight);
			if (!graph_digraph)
				adjlistweight[y].push_back(xyweight);
		}
		adjnum[x]++;
		if (!graph_digraph)
			adjnum[y]++;
	}
	x_visited.resize(Vnum);
	visited_ini();

	return;
}

void Graph_class::visited_ini() {
	rep(i, Vnum) {
		branch_type[i] = -1;
		x_visited[i] = false;
		adj_to_root[i] = -1;
	}
	x_que.clear();
}

void Graph_class::graph_BFS(ll BFS_ini) {
	visited_ini();
	x_que.push_back(BFS_ini);
	x_visited[BFS_ini] = true;

	// option
	xdist[BFS_ini] = 0;
	vlist_from_root.clear();
	vlist_from_root.push_back(BFS_ini);
	//cout << BFS_ini << endl;
	rep(i, adjnum[BFS_ini]) {
		int x_new = adjlist[BFS_ini][i];
		branch_type[x_new] = i;
	}

	while (!x_que.empty()) {
		int x = x_que.front();
		x_que.pop_front();
		rep(i, adjnum[x]) {
			int x_new = adjlist[x][i];
			int dist_new = 1;
			if (graph_weight)
				dist_new = adjlistweight[x][i];
			if (!x_visited[x_new]) {
				x_visited[x_new] = true;
				x_que.push_back(x_new);

				// option
				adj_to_root[x_new] = x;
				vlist_from_root.push_back(x_new);
				xdist[x_new] = xdist[x] + dist_new;
				if (x != BFS_ini)
					branch_type[x_new] = branch_type[x];
				//cout << x_new << endl;
			}
		}
	}
	return;
}

void Graph_class::ReRooting(ll root) {
	rep(i, Vnum) {
		DP[i].dist_sum = 0;
		DP[i].koma_num = 0;
	}
	graph_BFS(root);
	rrep(i, Vnum) { // 根から遠い点から見る
		ll x = vlist_from_root[i];
		ll xdist_sum = 0;
		ll xdist_max = 0;
		rep(j, adjnum[x]) {
			ll x_new = adjlist[x][j];
			if (x_new == adj_to_root[x]) // 根側の頂点の場合は処理しない
				continue;
			ll dist_sum_new = DP[x_new].dist_sum + DP[x_new].koma_num; // 根に1回近づくと、コマの数だけ距離が伸びる
			xdist_sum += dist_sum_new;
			xdist_max = max(xdist_max, dist_sum_new);
			DP[x].koma_num += DP[x_new].koma_num;
		}
		DP[x].dist_sum = xdist_sum % 2; // 距離の合計の偶奇は変更不可
		DP[x].dist_sum = max(DP[x].dist_sum, xdist_max * 2LL - xdist_sum); // 現在の頂点からの距離の和は別方向の枝同士で相殺可能, 三角条件を満たす場合は完全に相殺
		if (S[x] == '1')
			DP[x].koma_num++;
	}
	return;
}

void Graph_class::solve() {
	ll ans = InfLL;
	rep(BFS_ini, Vnum) {
		graph_BFS(BFS_ini);
		ReRooting(BFS_ini);
		if (DP[BFS_ini].dist_sum == 0) { // 根で距離の相殺が完了していればOK
			ll anstmp = 0;
			rep(xtmp, Vnum) {
				if (S[xtmp] == '0')
					continue;
				anstmp += xdist[xtmp];
			}
			anstmp /= 2;
			ans = min(ans, anstmp);
		}
	}
	if (ans == InfLL)
		ans = -1;
	cout << ans << endl;
	return;
}

int main(void) {
	Graph_class graph;
	graph.read_edge();
	graph.adjini();
	graph.solve();
	return 0;
}

