hwll dfs (ull v, ull p, ull dep) {
	hwll x = {0, 0};

	if (s[v] == '1') {
		x.a += dep;
		x.b++;
	}

	for (ull u : g[v]) {
		if (u == p) continue;

		hwll y = dfs(u, v, dep + 1);
		x.a += y.a;
		x.b += y.b;
	}

	return x;
}

hwllc dfs2 (ull v, ull p) {
	hwllc x = {0, 0, 0}; // {done, yet, cnt1}
	if (s[v] == '1') {
		x.b--;
		x.c++;
	}

	sll sumy = 0, maxy = 0, maxv = v;
	for (ull u : g[v]) {
		if (u == p) continue;
		hwllc y = dfs2(u, v);
		y.b += y.c;
		x.c += y.c;
		x.a += y.a;

		sumy += y.b;
		if (maxy < y.b) {
			maxy = y.b;
			maxv = u;
		}
	}

	if (maxy * 2 > sumy) {
		x.a += (sumy - maxy) * 2;
		x.b += maxy - (sumy - maxy);
	} else {
		x.a += (sumy / 2) * 2;
		x.b += (sumy % 2);
	}

	return x;
}

ull check (ull root) {
	ull sumd = 0;
	sll maxd = -1, maxv = 0;
	ull sumdep = 0;
	for (ull v : g[root]) {
		hwll ret = dfs(v, root, 1);

		if (ret.a > maxd) {
			maxd = ret.a;
			maxv = v;
		}
		sumd += ret.b;
		sumdep += ret.a;
	}
	if (sumdep % 2) return VERYBIG;

	if (maxd * 2 > sumdep) {
		hwllc ret = dfs2(maxv, root);
		if (ret.a < maxd * 2 - sumdep) return VERYBIG;
	}

	return sumdep / 2;
}

