typedef long long ll;
const int N=2010,inf=0x3f3f3f3f;
int read(){
	int f=1,g=0;
	char ch=getchar();
	for (;!isdigit(ch);ch=getchar()) if (ch=='-') f=-1;
	for (;isdigit(ch);ch=getchar()) g=g*10+ch-'0';
	return f*g;
}
int n,f[N],s[N],ans;
char ch[N];
vector<int> e[N];
void work(int x,int fa){
	s[x]=ch[x]-'0';f[x]=0;
	for (auto y : e[x])
	if (y!=fa){
		work(y,x);
		s[x]+=s[y];
		f[x]+=f[y]+s[y];
	}
}
int calc(int x,int fa){
	int hs=0;
	for (auto y : e[x])
	if ((y!=fa)&&(f[hs]+s[hs]<f[y]+s[y])) hs=y;
	if (!hs) return 0;
	int res=f[x]-f[hs]-s[hs],cur=calc(hs,x)+s[hs];
	return (res>=cur)  ? (f[x]&1) : (cur-res); 
}
int main(){
	n=read();
	scanf(" %s",ch+1);
	for (int i=1;i<n;i++){
		int u=read(),v=read();
		e[u].push_back(v);
		e[v].push_back(u);
	}
	ans=inf;
	for (int i=1;i<=n;i++){
		work(i,0);
		if (calc(i,0)==0) ans=min(ans,f[i]/2);
	}
	printf("%d\n",(ans==inf) ? -1 : ans);
	return 0;
}

