		if(edge[e].to != p)
		{
			dfs(edge[e].to, now);
			num[now] += num[edge[e].to];
			int a = num[edge[e].to] + len[edge[e].to];
			len[now] += a;
			sum += a;
			ans += num[edge[e].to] + dp[edge[e].to];
		}
	dp[now] = ans;
	bool asd = 0;
	for(int e = point[now]; e; e = edge[e].next)
		if(edge[e].to != p)
