        }

        for(int i=0;i<n-1;i++){
                int a,b;
                cin >> a >> b;
                a-=1;
                b-=1;
                tree[a].neighbor.push_back(&tree[b]);
                tree[b].neighbor.push_back(&tree[a]);
        }

        int ans = -1;
        for(int i=0;i<n;i++){
                int sum = 0;
                int max = 0;
                for(auto nx : tree[i].neighbor){
                        int ret = search(nx, &tree[i], 1);
                        sum += ret;
                        if(max < ret){
                                max = ret;
                        }
                }

                if(sum % 2 == 0 && 2 * max <= sum){
                        //cout << "c:" << i+1 << " sum:" << sum << endl;
                        if(ans == -1 || sum/2 < ans){
                                ans = sum / 2;
                        }
                }
        }

        cout << ans << endl;
}

int search(node* n, node* prev, int len)
{
        int score = len * n->koma;
        for(auto nx : n->neighbor){
                if(nx != prev){
                        score += search(nx, n, len + 1);
                }
        }
        return score;
}

