struct Graph{
    struct Node{
        vector<int> dests;
        int num;
    };
    vector<Node> nodes;
    Graph(int num): nodes(num){ }
    int id(Node* n){ return n - &nodes[0]; }
    int id(Node& n){ return &n - &nodes[0]; }
    void print(){ for(auto& node : nodes){ prints(id(node), node.dests); } }
    void add1Edge(int from, int dest){
        nodes[from].dests.push_back(dest);
    }
    void add2Edge2(int from, int dest){
        add1Edge(from, dest);
        add1Edge(dest, from);
    }
    int dfs(int idx, int from, int depth){
        int acc = depth * nodes[idx].num;
        for(int didx : nodes[idx].dests){
            if(didx == from){ continue; }
            acc += dfs(didx, idx, depth + 1);
        }
        return acc;
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n; cin >> n;
    Graph g(n);
    string s; cin >> s;
    for(int i = 0; i < n - 1; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        g.add2Edge2(a, b);
    }
    ll ans = MLL;
    for(int i = 0; i < n; i++){
        g.nodes[i].num = s[i] - '0';
    }
    for(int i = 0; i < n; i++){
        vector<int> nums;
        for(auto& didx : g.nodes[i].dests){
            nums.push_back(g.dfs(didx, i, 1));
        }
        sort(nums.begin(), nums.end());
        ll acc = accumulate(nums.begin(), nums.end(), 0ll);
        if(acc % 2 == 0 && acc - nums.back() >= nums.back()){
            ans = min(ans, acc / 2);
        }
    }
    cout << (ans == MLL ? -1 : ans) << '\n';
}

