using namespace std;
int main() {
    int N; cin >> N;
    string S; cin >> S;
    vector<vector<int>> G(N);
    for (int i = 0; i < N - 1; i++) {
        int a, b; cin >> a >> b; a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    vector<int> ns(N), mas(N), mis(N);
    auto recur = [&](auto& recur, int node, int prev) -> void {
        int n = 0, ma = 0, mi = 0;
        for (int next : G[node]) if (next != prev) {
            recur(recur, next, node);
            n += ns[next];
            ma += mas[next];
        }
        for (int next : G[node]) if (next != prev) {
            int ans = mis[next] + ns[next] - (ma + n - mas[next] - ns[next]);
            mi = max(mi, ans);
        }
        ma += n;
        mas[node] = ma;
        mis[node] = max(ma % 2, mi);
        ns[node] = n + (S[node] == '1');
    };
    int ans = 1e9;
    for (int root = 0; root < N; root++) {
        recur(recur, root, -1);
        if (mis[root] == 0) {
            ans = min(ans, mas[root] / 2);
        }
    }
    cout << (ans == 1e9 ? -1 : ans) << endl;
    return 0;
}

