ll dfs(ll x,ll from,ll dep){
  ll sum=0,ssum=(s[x-1]=='1');
  for(auto y:g[x])if(y!=from){
    ssum+=dfs(y,x,dep+1);
    sum+=e[y];
  }
  siz[x]=ssum;
  ll ma=0;
  for(auto y:g[x])if(y!=from){
    ma=max(ma,f[y]+siz[y]-(sum-e[y]));
  }
  f[x]=ma;
  e[x]=sum+(s[x-1]=='1')*dep;
  return siz[x];
}
ll solve(ll t){
  dfs(t,0,0);

  if(f[t]>0||e[t]%2==1)return -1;
  return e[t]/2;
}
