  scanf("%s", s);

  vector<vector<int>> ed(n);
  for (int i = 0; i < n - 1; ++i) {
    int u, v;
    scanf("%d%d", &u, &v);
    --u, --v;
    ed[u].push_back(v);
    ed[v].push_back(u);
  }

  vector<pii> sumPath(n);

  function<pii(int, int)> dfs = [&](int u, int par) {
    int cnt = (s[u] == '1' ? 1 : 0);
    int sum = 0;
    for (int v : ed[u]) {
      if (v == par) { continue; }
      auto child = dfs(v, u);
      cnt += child.first;
      sum += child.first + child.second;
    }
    dbg("sumPath[%d] = (%d %d)\n", u, cnt, sum);
    sumPath[u] = {cnt, sum};
    return pii{cnt, sum};
  };

  int ans = -1;
  for (int u = 0; u < n; ++u) {
    dfs(u, -1);
    bool ok = (sumPath[u].second % 2 == 0);
