inline int rd()
{
	char c=getchar();
	int x=0,f=1;
	while(c<'0'||c>'9'){if(c=='-')f=-1;c=getchar();}
	while(c>='0'&&c<='9'){x=x*10+c-'0';c=getchar();}
	return x*f;
}

void add(int x,int y)
{
	Node T={x,y,head[x]};
	E[++cnt]=T;
	head[x]=cnt;
}

void dfs(int u,int fa)
{
	val[u]=s[u]-'0';
	dis[u]=0;
	int Son=-1;
	for(int i=head[u];~i;i=E[i].nxt)
	{
		int ver=E[i].v;
		if(ver==fa) continue;
		dfs(ver,u);
		val[u]+=val[ver];
		dis[ver]+=val[ver];
		dis[u]+=dis[ver];
		if(!(~Son)||dis[Son]<dis[ver]) Son=ver;
	}
	if(!(~Son))
	{
		f[u]=0;
		return;
	}
	if(dis[u]-dis[Son]>=dis[Son]) f[u]=dis[u]/2;
	else f[u]=dis[u]-dis[Son]+min(f[Son]*2,2*dis[Son]-dis[u])/2;
}

