        nodes[from].dests.push_back(dest);
    }
    void add2Edge2(int from, int dest){
        add1Edge(from, dest);
        add1Edge(dest, from);
    }
    Elem dfs(int idx, int from, int depth){
        Elem ret = {};
        vector<Elem> nums;
        for(int didx : nodes[idx].dests){
            if(didx == from){ continue; }
            auto r = dfs(didx, idx, depth + 1);
            nums.push_back(r);
            ret.acc += r.acc;
            ret.num += r.num;
        }
        ret.mini = ret.num * 1;
        if(nums.empty()){
            return {1, 1, 1};
        }
        sort(nums.begin(), nums.end());
        ret.mini += max(ret.acc % 2, nums.back().mini - (ret.acc -nums.back().acc + 0 - 0));
        ret.num += nodes[idx].num;
        ret.acc += ret.num;
        // ret.acc += nodes[idx].num;
        return ret;
    }
};

