  VV<> g(n);
  for (int _ = 0; _ < n - 1; ++_) {
    int u, v; cin >> u >> v, --u, --v;
    g[u].push_back(v);
    g[v].push_back(u);
  }
  int mn = inf;
  for (int r = 0; r < n; ++r) {
    V<> c(n), d(n);
    {
      auto dfs = [&](auto& F, int v, int p) -> void {
        c[v] = s[v] == '1';
        for (int u : g[v]) if (u != p) {
          F(F, u, v);
          c[v] += c[u];
          d[v] += d[u] + c[u];
        }
      };
      dfs(dfs, r, -1);
    }
    if (d[r] & 1) continue;
    auto dfs = [&](auto& F, int v, int p, int t) -> bool {
      if (!t) return true;
      V<> a;
      for (int u : g[v]) if (u != p) {
        a.push_back(c[u] + d[u]);
      }
      if (a.empty()) return false;
      sort(begin(a), end(a));
      int sum = accumulate(begin(a), end(a), 0);
      if (t <= 2 * (sum - a.back())) return true;
      for (int u : g[v]) if (u != p) {
        if (2 * (c[u] + d[u]) > sum) {
          return F(F, u, v, t - 2 * (sum - a.back()));
        }
      }
      return true;
    };
    if (not dfs(dfs, r, -1, d[r])) continue;
    mn = min(mn, d[r] / 2);
