struct ctx {
	ll sm = 0, mx = 0, cnt = 0;
	void up(int a, int b) {
		cnt += b;
		if(2*mx <= sm) sm &= 1;
		else sm = 2*mx-sm;
		if(a) sm += cnt;
	}
	void add(ctx &o) {
		sm += o.sm, cnt += o.cnt;
		mx = max(mx, o.sm);
	}
};
ctx dfs(int v, int p) {
	ctx a;
	for(auto &i : g[v]) {
		if(i == p) continue;
		auto t = dfs(i, v);
		a.add(t);
	}
	a.up(v!=p, s[v-1]-'0');
	return a;
}
ll calc(ll v, ll p, ll h = 0) {
	ll res = h*(s[v-1]-'0');
	for(auto &i : g[v]) {
		if(i == p) continue;
		res += calc(i, v, h+1);
	}
	return res;
}
ll go(int v) {
	auto t = dfs(v, v);
	return t.sm ? 1ll<<60 : calc(v, v);
}
