pii mrg(pii a, pii b) {
//	cerr << a.F << '&' << a.S << " + " << b.F << ' ' << b.S << " = ";
	if (a.S > b.S)
		swap(a, b);
	int x = b.S - a.S;
	int y = min(x / 2, a.F);
//	cerr << x << ' ' << y << endl;
	a.S += 2 * y;
	a.F -= y;
//	cerr << a.F + b.F + a.S << ' ' << b.S - a.S << endl;
	return {a.F + b.F + a.S, b.S - a.S};
}

pii dfs(int v, int p = -1) {
	vector <pii> gaff;
	for (int u: adj[v]) {
		if (u == p)
			continue;
		gaff.push_back(dfs(u, v));
		gaff.back().S += sz[u];
		sz[v] += sz[u];
	}
	pii my(0, 0);
	for (pii p: gaff)
		my = mrg(my, p);
//	cerr << v << '!' << endl;
//	cerr << my.F << ' ' << my.S << endl;
	return my;
}

