const int N=2005;
int n,mx,ans=1<<30,i,j,k,head[N],adj[N*2],nxt[N*2],f[N],size[N],sum[N];
char s[N];
void dfs(int x,int dad)
{
	sum[x]=0;
	size[x]=(s[x]=='1');
	int mx=0,w=0;
	for(int y=head[x];y;y=nxt[y])
		if(adj[y]!=dad)
		{
			dfs(adj[y],x);
			size[x]+=size[adj[y]];
			sum[x]+=sum[adj[y]]+size[adj[y]];
			if(f[adj[y]]+size[adj[y]]>mx)
			{
				mx=f[adj[y]]+size[adj[y]];
				w=sum[adj[y]]+size[adj[y]];
			}
		}
	f[x]=max(0,mx-(sum[x]-w));
	//if(i==1)
		//printf("%d %d\n",x,f[x]);
}
int main()
{
	scanf("%d",&n);
	scanf("%s",s+1);
	for(i=1;i<n;++i)
	{
		scanf("%d%d",&j,&k);
		adj[i*2-1]=k;
		nxt[i*2-1]=head[j];
		head[j]=i*2-1;
		adj[i*2]=j;
		nxt[i*2]=head[k];
		head[k]=i*2;
	}
	for(i=1;i<=n;++i)
	{
		dfs(i,-1);
		if(f[i]==0&&sum[i]%2==0)
			ans=min(ans,sum[i]);
	}
