using namespace std;

const int N = 2020, inF = N * N;

int n, cnt[N], sigma[N], mini[N];
string s;
vector<int> nei[N];

void input() {
	cin >> n >> s;
	for (int i = 0; i < n - 1; i++) {
		int u, v;
		cin >> u >> v;
		nei[--u].push_back(--v);
		nei[v].push_back(u);
	}
}

void dfs(int v, int par) {
	cnt[v] = s[v] - '0';
	sigma[v] = 0;
	int s = 0;
	for (int u: nei[v])
		if (u ^ par) {
			dfs(u, v);
			cnt[v] += cnt[u];
			sigma[v] += sigma[u] + cnt[u];
		}
	mini[v] = sigma[v] & 1;
	for (int u: nei[v])
		if (u ^ par)
			mini[v] = max(mini[v], (mini[u] + cnt[u]) - (sigma[v] - (sigma[u] + cnt[u])));
	//cerr << v + 1 << " : " << cnt[v] 
}

int solve(int v) {
	dfs(v, -1);
	return (mini[v]? inF: sigma[v] >> 1);
}

int main() {
	ios::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	input();
	//solve(1);return 0;
	int ans = inF;
	for (int v = 0; v < n; v++)
		ans = min(ans, solve(v));
	cout << (ans == inF? -1: ans);
}

