	tot[x] = s[x] - '0';
	for(int i : g[x]) {
		if(i - par) {
			dfs(i, x);
			tot[x] += tot[i];
			sum[x] += tot[i] + sum[i];
		}
	}
}
bool matcher(int x, int par, int take) {
	if(take <= 0) return true;
	int big = -1;
	for(int i : g[x]) {
		if(i - par) {
			if(big == -1 || tot[big] + sum[big] < tot[i] + sum[i]) {
				big = i;
			}
		}
	}
	if(big == -1) return false;
	int w = tot[big] + sum[big];
	if(sum[x] - w < w) {
		return matcher(big, x, take - (sum[x] - w));
	} else {
		return sum[x] - (sum[x] % 2) >= take;
	}
}

