inline void add(int x, int y)
{
	tot ++;
	edge[tot].to = y;
	edge[tot].next = head[x];
	head[x] = tot;
}

inline void dfs(int u, int pa)
{
	f[u] = 0;
	dep[u] = dep[pa] + 1;
	size[u] = val[u]; sum[u] = val[u] * dep[u];
	int mx = 0, t = 0, w = 0;
	for(int i = head[u]; i; i = edge[i].next)
	{
		int v = edge[i].to;
		if(v == pa) continue;
		dfs(v, u);
		size[u] += size[v]; sum[u] += sum[v];
		t += sum[v] - size[v] * dep[u];
		if(sum[v] > sum[mx]) mx = v;
	}
	if(!mx) return;
	w = sum[mx] - size[mx] * dep[u];
	if(2 * w <= t) f[u] = t / 2;
	else f[u] = t - w + min(f[mx], (2 * w - t) / 2); 
}

