			continue;
		}
		int kek = dfs1(h, u);
		st.pb(kek);
		cur += kek;
	}
	if (st.empty()) {
		if (s[u] == '1') {
			return dist[u];
		}
		return 0;
	}
	int ans = 0;
	if (s[u] == 1) {
		ans += dist[u];
	}
	for (auto &x: st) {
		ans += x - dist[u];
		x -= dist[u];
		cur -= dist[u];
	}
	sort(all(st));
	if (st.back() * 2 <= cur) {
		ans += cur % 2;
	} else {
		int kek = 2 * st.back();
		for (auto x: st) {
			kek -= x;
		}
		ans += kek;
	}

	return ans;
}


