}

pair<int,int> can(int cur,int pre) {
	pair<int,int> P={0,0};

	if(S[cur]=='1') P.first=1;
	FORR(e,E[cur]) if(e!=pre) {
		auto Q=can(e,cur);
		Q.second+=Q.first;
		int mi=min(Q.second,P.second);
		lef-=mi;
		Q.second-=mi;
		P.second-=mi;
		P.first+=Q.first;
		P.second+=Q.second;
	}
	return P;


}

