vector<vector<int>> g(N);
int dis[N], low[N], cnt[N];
string m;

void clear() {
    for (int i = 0; i < N; i++) {
        dis[i] = low[i] = cnt[i] = 0;
    }
}

void dfs(int x, int p) {
    int z = 0;
    for (int i : g[x]) {
        if (i != p) {
            dfs(i, x);
            dis[x] += dis[i];
            dis[x] += cnt[i];
            cnt[x] += cnt[i];
            if (dis[i] + cnt[i] <= z) {
                z -= dis[i] + cnt[i];
            }
            else {
                z = dis[i] + cnt[i] - z;
            }
        }
    }
    low[x] = z;
    if (m[x - 1] == '1') {
        cnt[x]++;
    }
}

int calc(int x) {
    dfs(x, 0);
    int s = 0, mx = g[x][0];
    for (int i : g[x]) {
        s += dis[i] + cnt[i];
        if (cnt[i] + dis[i] > cnt[mx] + dis[mx]) {
            mx = i;
        }
    }
    if (low[mx] > s / 2 || s % 2) {
        return 1e9;
    }
    return s / 2;
}

