const int INF = 1e9 + 7;

int n;
char S[2005]; 
vector<int> G[2005];
int siz[2005], sum[2005];

void dfs(int v, int par, int cd)
{
	siz[v] = S[v] == '1';
	sum[v] = 0;
	rep(i, G[v].size()) {
		int u = G[v][i];
		if(u == par) continue;
		dfs(u, v, cd + 1);
		siz[v] += siz[u];
		sum[v] += sum[u];
	}
	sum[v] += siz[v];
}

pair<int, int> solve(int v, int par)
{
	int tots = 0, maxs = 0, maxg = -1;
	rep(i, G[v].size()) {
		if(G[v][i] == par) continue;
		tots += sum[G[v][i]];
		maxs = max(maxs, sum[G[v][i]]);
		if(maxs == sum[G[v][i]]) maxg = G[v][i];
	}
	if(tots % 2 == 1) return MP(INF, INF);
	else if(tots < maxs * 2) {
		PII cur = solve(maxg, v);
		if(cur == MP(INF, INF)) return MP(tots - maxs, tots / 2);
		else return MP(tots - maxs + min(solve(maxg, v).first, maxs - tots / 2), tots / 2);
	} else return MP(tots / 2, tots / 2);
}

int main()
{
	scanf("%d%s", &n, S + 1);
	rep(i, n - 1) {
		int u, v;
		scanf("%d%d", &u, &v);
		G[u].push_back(v);
		G[v].push_back(u);
	}

	int ret = INF;
	rep1(i, n) {
		dfs(i, -1, 0);
		PII ca = solve(i, -1);
		if(ca.first == ca.second) ret = min(ret, ca.second);
	}
	printf("%d\n", ret >= INF ? -1 : ret);
	return 0;
}

