const int INF = 1000000000;

int MinCompress(const vvi& G, const string& s, int root, vb& done, vi& children_cnt, vi& min_dist_to_children) {
  int res = 0;
  done[root] = true;
  vi children;
  for (int i = 0; i < G[root].size(); ++i) {
    int other = G[root][i];
    if (done[other]) {
      continue;
    }
    children.push_back(other);
    res += MinCompress(G, s, other, done, children_cnt, min_dist_to_children);
  }
  children_cnt[root] = 0;
  if (s[root] == '1') {
    ++children_cnt[root];
  }
  min_dist_to_children[root] = 0;
  int sum_dists = 0;
  int max_dist = 0;
  for (int i = 0; i < children.size(); ++i) {
    int child = children[i];
    children_cnt[root] += children_cnt[child];
    int cur = children_cnt[child] + min_dist_to_children[child];
    sum_dists += cur;
    if (cur > max_dist) {
      max_dist = cur;
    }
  }
  if (max_dist > sum_dists - max_dist) {
    res += sum_dists - max_dist;
    min_dist_to_children[root] = max_dist - (sum_dists - max_dist);
  }
  else {
    res += sum_dists / 2;
    min_dist_to_children[root] = sum_dists % 2;
  }
  return res;
}

