		a--; b--;
		edges[a].push_back({ b,1 });
		edges[b].push_back({ a,1 });
	}

	int res = INF;
	REP(i, N) {
		int d = dijkstra(edges, i, s);
		if (d % 2 == 0)res = min(res, d);
	}
	cout << (res == INF ? -1 : res/2) << endl;

	return 0;
}

