struct TRes {
    int s0, sd, mm;

    TRes mv() const {
        TRes r = *this;
        r.sd += r.s0;
        return r;
    }

    TRes operator+(TRes r) {
        TRes res = {s0 + r.s0, sd + r.sd, mm + r.mm};
        int S = min(sd, r.sd);
        res.mm = S + min((sd - S) / 2, mm) + min((r.sd - S) / 2, r.mm);
        if (S) uax(res.mm, S - 1 + min((sd - S + 1) / 2, mm) + min((r.sd - S + 1) / 2, r.mm));
        return res;
    }
};

pii mv(pii p) {
    return {p.fi, p.fi + p.se};
}

