    --a;
    --b;
    g[a].emplace_back(b);
    g[b].emplace_back(a);
  }
  struct node {
    u64 count, min, max;
  };
  std::vector<node> dp(n);
  constexpr u64 INF = std::numeric_limits<u64>::max();
  const auto dfs = [&](const auto &dfs, const usize v, const usize p) -> void {
    dp[v].count = static_cast<u64>(0);
    dp[v].min = static_cast<u64>(0);
    dp[v].max = static_cast<u64>(0);
    if (s[v] == '1') {
      ++dp[v].count;
    }
    u64 max_max = static_cast<u64>(0), max_min = static_cast<u64>(0),
        other = static_cast<u64>(0);
    for (const auto e : g[v]) {
      if (e == p) {
        continue;
      }
      dfs(dfs, e, v);
      dp[v].count += dp[e].count;
      dp[v].max += dp[e].max + dp[e].count;
      if (dp[e].max + dp[e].count >= max_max) {
        other += max_max;
        max_max = dp[e].max + dp[e].count;
        max_min = dp[e].min + dp[e].count;
      } else {
        other += dp[e].max + dp[e].count;
      }
    }
    if (dp[v].max % static_cast<u64>(2) == static_cast<u64>(0)) {
      if (other >= max_min) {
        dp[v].min = static_cast<u64>(0);
      } else {
        dp[v].min = max_min - other;
      }
    } else {
      if (other >= max_min) {
        dp[v].min = static_cast<u64>(1);
      } else {
        dp[v].min = max_min - other;
      }
    }
  };
  u64 ans = INF;
  for (const auto i : rep(0, n)) {
    dfs(dfs, i, n);
    if (dp[i].min == static_cast<u64>(0)) {
      ans = std::min(ans, dp[i].max / static_cast<u64>(2));
    }
  }
  if (ans == INF) {
    std::cout << "-1";
  } else {
    std::cout << ans;
  }
  std::cout << std::endl;
}

