#include <bits/stdc++.h>
using namespace std;

const int N = 2005;
int n, size[N], tot[N], dp[N];
vector<int> g[N];
char s[N];

void dfs(int u, int fa) {
	size[u] = s[u] - '0', tot[u] = 0;
	int sum = 0, sum_dp = 0;
	vector<pair<int, int>> a;
	for (int v : g[u])
		if (v != fa) {
			dfs(v, u);
			size[u] += size[v];
			tot[v] += size[v];
			tot[u] += tot[v];
			sum += tot[v] - 2 * dp[v];
			sum_dp += dp[v];
			a.emplace_back(tot[v], dp[v]);
		}
	if (a.empty())  {
		dp[u] = 0;
		return;
	}
	vector<int> pre(a.size()), suf(a.size());
	pre[0] = a[0].first - 2 * a[0].second;
	for (int i = 1; i < (int)a.size(); ++i)
		pre[i] = max(pre[i - 1], a[i].first - 2 * a[i].second);
	suf.back() = a.back().first - 2 * a.back().second;
	for (int i = (int)a.size() - 2; i >= 0; --i)
		suf[i] = max(suf[i + 1], a[i].first - 2 * a[i].second);
	dp[u] = 0;
	for (int i = 0; i < (int)a.size(); ++i) {
		int mx = max(!i ? 0 : pre[i - 1], i + 1 == (int)a.size() ? 0 : suf[i + 1]);
		if (a[i].first < mx) continue;
		int x = sum + 2 * a[i].second;
		if (2 * a[i].second >= 2 * a[i].first - x) {
			dp[u] = tot[u] / 2;
			break;
		}
		dp[u] = max(dp[u], sum_dp + min(a[i].first - 2 * a[i].second, sum - (a[i].first - 2 * a[i].second)));
	}
}

int main() {
	scanf("%d%s", &n, s + 1);
	for (int i = 1, u, v; i < n; ++i) {
		scanf("%d%d", &u, &v);
		g[u].push_back(v), g[v].push_back(u);
	}
	int ans = 1 << 30;
	for (int rt = 1; rt <= n; ++rt) {
		dfs(rt, 0);
		if (dp[rt] * 2 == tot[rt])
			ans = min(ans, dp[rt]);
	}
	if (ans == (1 << 30)) puts("-1");
	else printf("%d\n", ans);
	return 0;
}

