void dfs(int v, int p, int dist)
{
	if (s[v] == '1')	
		d.PB(dist);

	for(auto i: g[v])	
		if (i != p)
			dfs(i, v, dist + 1);
}

int solve(int v)
{
	vector<VI> all;
	LL suma = 0;

	vector<LL> cnt;

	for(auto i: g[v])
	{
		d.clear();
		dfs(i, v, 1);
		all.PB(d);

		LL tut = 0;
		for(auto j: d)
			tut += j;

		cnt.PB(tut);
		suma += tut;
	}

	if (suma & 1)	
		return INF;

	sort(ALL(cnt));
	if (cnt.back() * 2 > suma)
		return INF;

	return suma / 2;
}

