    int next, to;
};

char s[MaxN];
edge e[MaxN];
int n, ans, cnt;
int a[MaxN], head[MaxN], dis[MaxN], size[MaxN], min[MaxN];

void init()
{
    for (int i = 1; i <= n; i++)
        dis[i] = size[i] = min[i] = 0;
}

void add_edge(int u, int v)
{
    ++cnt;
    e[cnt].to = v;
    e[cnt].next = head[u];
    head[u] = cnt;
}

inline int read()
{
    int x = 0;
    char ch = getchar();
    while (ch > '9' || ch < '0')
        ch = getchar();
    while (ch <= '9' && ch >= '0')
        x = (x << 1) + (x << 3) + (ch ^ 48), ch = getchar();
    return x;
}

void dfs(int u, int fa)
{
    size[u] = a[u];
    int maxp = 0;
    for (int i = head[u]; i; i = e[i].next)
    {
        int v = e[i].to;
        if (v == fa) continue;
        dfs(v, u), size[u] += size[v];
        dis[u] += dis[v], maxp = (dis[v] > dis[maxp]) ? v : maxp;
    }
    if (min[maxp] + dis[maxp] > dis[u])
        min[u] = min[maxp] + dis[maxp] - dis[u] + size[u];
    else
        min[u] = (dis[u] & 1) + size[u];
    dis[u] += size[u];
    if(!fa) dis[u] -= size[u], min[u] -= size[u];

}

