{
	siz[u]=choose[u];
	f[u]=0;
	for(int i=head[u];i;i=nxt[i])
	{
		int v=to[i];
		if(v==pre) continue;
		dfs(v,u);
		siz[u]+=siz[v];
		f[u]+=f[v]+siz[v];
	}
