int work(int u,int pre)
{
	int p=0;
	for(int i=head[u];i;i=nxt[i])
	{
		int v=to[i];
		if(v==pre) continue;
		if(!p || f[v]>f[p]) p=v;
	}
	if(!p) return 0;
	ll res=work(p,u)+siz[p],ans=f[u]-f[p]-siz[p];

	if(ans>=res) return f[u]&1;
	else return res-ans;
