struct dp {
    vector<pii> ps;
    int mn, mx, sz;
    dp() : mn(0), mx(0), sz(0), ps() {}
    void add(int nmn, int nmx, int nsz) {
        ps.emplace_back(nmn + nsz, nmx + nsz);
        sz += nsz;
    }
    void init() {
        mn = mx = 0;
        int msum = 0, mmx = 0;
        for (pii i : ps) {
            msum += i.fs;
            mmx = max(mmx, i.fs);
            mx += i.se;
        }
        if (msum - mmx < mmx) {
            for (pii i : ps) {
                if (i.fs == mmx) {
                    if (i.fs <= mx - i.se) {
                        mn = (msum & 1);
                    }
                    else mn = i.fs - (mx - i.se);
                }
            }
        }
        else mn = (msum & 1);
    }
};
dp ddp[2001];
dp udp[2001];

int par[2001];
void dfs1(int x, int p) {
    par[x] = p;
    if (S[x] == '1') ddp[x].add(-1, -1, 1);
    for (int i : edge[x]) {
        if (i == p) continue;
        dfs1(i, x);
        ddp[x].add(ddp[i].mn, ddp[i].mn, ddp[i].sz);
    }
    ddp[x].init();
}

void dfs2(int x, int p) {
    if (S[p] == '1') udp[x].add(-1, -1, 1);
    if (p > 1) udp[x].add(udp[p].mn, udp[p].mx, udp[p].sz);
    for (int i : edge[p]) {
        if (i == x || i == par[p]) continue;
        udp[x].add(ddp[i].mn, ddp[i].mx, ddp[i].sz);
    }
    udp[x].init();
    for (int i : edge[x]) {
        if (i == p) continue;
        dfs2(i, x);
    }
}

int dfs3(int x, int p = 0, int d = 0) {
    int ret = 0;
    if (S[x] == '1') ret += d;
    for (int i : edge[x]) {
        if (i == p) continue;
        ret += dfs3(i, x, d + 1);
    }
    return ret;
}

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);
    cin >> n >> S + 1;
    for (int i = 1; i < n; ++i) {
        int a, b;
        cin >> a >> b;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    dfs1(1, 0);
    dfs2(1, 0);
    int ans = inf;
    for (int i = 1; i <= n; ++i) {
        dp x = dp();
        if (S[i] == '1') x.add(-1, -1, 1);
        for (int j : edge[i]) {
            if (j == par[i]) x.add(udp[i].mn, udp[i].mx, udp[i].sz);
            else x.add(ddp[j].mn, ddp[j].mx, ddp[j].sz);
        }
        x.init();
        if (x.mn == 0) ans = min(ans, dfs3(i, 0));
    }
    printf("%d\n", ans < inf ? ans / 2 : -1);
    return 0;
}

