void ins(int u, int v) {nxt[++K] = h[u]; h[u] = K; to[K] = v;}

void dfs(int x, int fa)
{
	siz[x] = (s[x] == '1');
	int Max = 0, id = -1;
	for(int i = h[x]; i; i = nxt[i])
	{
		if(to[i] == fa) continue;
		dfs(to[i], x);
		siz[x] += siz[to[i]];
		g[x] += g[to[i]] + siz[to[i]];
		if(f[to[i]] + siz[to[i]] > Max) id = to[i], Max = f[to[i]] + siz[to[i]];
	}
	int sum = 0;
	for(int i = h[x]; i; i = nxt[i])
	{
		if(to[i] == fa) continue;
		if(to[i] != id) sum += g[to[i]] + siz[to[i]];
	}
	if(sum >= Max) f[x] = g[x] & 1;
	else f[x] = Max - sum;
}

