    int n;
    cin >> n;

    Graph<> g(n, n - 1, false);
    string x;
    cin >> x;
    cin >> g;

    vector<pair<int, long long>> sz(n);

    function<pair<int, long long>(int, int)> dfs0 = [&](int s, int p) {
        int total = x[s] == '1';
        long long sum = 0;

        for (auto e : g[s])
        {
            int u = e.to();

            if (u == p)
                continue;

            auto res = dfs0(u, s);
            total += res.first;
            sum += res.first + res.second;
        }

        return sz[s] = make_pair(total, sum);
    };

    function<bool(int, long long, int)> dfs1 = [&](int s, long long target, int p) {
        long long mx = 0, sm = 0, ux = -1, rx = 0;

        for (auto e : g[s])
        {
            int u = e.to();

            if (u == p)
                continue;

            long long x = sz[u].first + sz[u].second;

            if (x > mx)
            {
                mx = x;
                ux = u;
                rx = sz[u].first;
            }

            sm += x;
        }

        if ((sm - mx) < rx)
            return false;

        if ((sm - mx) * 2 >= target)
            return true;
        else
            return ux >= 0 && dfs1(ux, target - (sm - mx) * 2, s);
    };

    long long answer = -1;

    for (int i = 0; i < n; ++i)
    {
        dfs0(i, -1);

        if (sz[i].second % 2 == 0 && dfs1(i, sz[i].second, -1))
        {
            if (answer == -1 || sz[i].second / 2 < answer)
                answer = sz[i].second / 2;
        }
    }

    cout << answer << endl;

    return 0;
}

