struct Graph
{
    Graph(const std::size_t v) : V{v}, edge(v), rev_edge(v) {}
    void addEdge(const std::size_t from, const std::size_t to, const bool bi = false)
    {
        assert(from < V), assert(to < V);
        edge[from].push_back(to), rev_edge[to].push_back(from);
        if (bi) { addEdge(to, from, false); }
    }
    const std::vector<std::size_t>& operator[](const std::size_t i) const { return assert(i < V), edge[i]; }
    friend std::ostream& operator<<(std::ostream& os, const Graph& g)
    {
        os << "[\n";
        for (std::size_t i = 0; i < g.V; i++) {
            for (const std::size_t to : g.edge[i]) { os << i << "->" << to << "\n"; }
        }
        return (os << "]\n");
    }
    std::size_t V;
    std::vector<std::vector<std::size_t>> edge, rev_edge;
};
using Tree = Graph;
//!============================================!//
//!    8888ba.88ba             oo              !//
//!    88  '8b  '8b                            !//
//!    88   88   88  .d8888b.  dP  88d888b.    !//
//!    88   88   88  88'  '88  88  88'  '88    !//
//!    88   88   88  88.  .88  88  88    88    !//
//!    dP   dP   dP  '88888P8  dP  dP    dP    !//
//!============================================!//
int main()
{
    const int N = read<int>();
    const auto S = read<std::string>();
    Tree T(N);
    for (int i = 0, u, v; i < N - 1; i++) { std::cin >> u >> v, T.addEdge(u - 1, v - 1, true); }
    std::vector<int> min(N), max(N);
    auto dfs = [&](auto&& self, const int s, const int p, const int d) -> void {
        min[s] = max[s] = (S[s] == '1' ? d : 0);
        std::priority_queue<int> Q;
        for (const int to : T[s]) {
            if (to == p) { continue; }
            self(self, to, s, d + 1);
            Q.push(min[to] - d), max[s] += max[to];
        }
        const int sz = Q.size();
        while (Q.size() > 1) {
            int T = Q.top();
            Q.pop();
            while (T > 0 and not Q.empty()) {
                const int e = Q.top();
                Q.pop();
                T--;
                if (e > 1) { Q.push(e - 1); }
            }
            if (T > 0) { Q.push(T); }
        }
        min[s] += sz * d + (Q.empty() ? 0 : Q.top());
    };
    int ans = INF<int>;
    for (int i = 0; i < N; i++) {
        std::fill(min.begin(), min.end(), INF<int>), std::fill(max.begin(), max.end(), 0);
        dfs(dfs, i, -1, 0);
        if (min[i] == 0) { chmin(ans, max[i] / 2); }
    }
    std::cout << (ans == INF<int> ? -1 : ans) << std::endl;
    return 0;
}

