Pi cost_num(int pos, int par) {
    int cost = 0, num = 0;
    if (S[pos] == '1') num = 1;
    for (auto e : G[pos]) {
        if (e.to == par) continue;
        Pi ret = cost_num(e.to, pos);
        cost += ret.first + ret.second;
        num += ret.second;
    }
    return mp(cost, num);
}

int check(int root) {
    int sum = 0, ma = 0;

    for (auto e : G[root]) {
        Pi ret = cost_num(e.to, root);
        int cost = ret.first + ret.second;
        sum += cost;
        chmax(ma, cost);
    }
    if (sum - ma >= ma && sum % 2 == 0) {
        return sum / 2;
    } else {
        return INF;
    }
}

