  if(s[u]=='1'){
    high[u]+=dep;
  }
  vector<int>lown;
  int sum=0,tot=0;
  for(auto i:adj[u]){
    if(i!=p){
      check(i,u,s,dep+1);
      high[u]+=high[i];
      lown.pb(low[i]+sz[i]);
      sum+=low[i]+sz[i];
    }
  }
  high[u]+=sz[u];
  sort(all(lown));
  if(lown.size()==0){
    return;
  }
  if(lown.size()==1){
    low[u]=lown[0];
  }
  else{
    if(lown.back()>sum-lown.back()){
      low[u]=(2*lown.back()-sum);
    }
    else{
      low[u]=((sum)%2);
    }
  }
}

