struct info {
	int size, Max, Min;
} dp[MAXN];
int ans, now;
char s[MAXN];
vector <int> a[MAXN];
info operator + (info a, int one) {
	a.Max += a.size;
	a.Min += a.size;
	return a;
}
info operator + (info a, info b) {
	info ans;
	ans.size = a.size + b.size;
	ans.Max = a.Max + b.Max;
	if (a.Min > b.Min) swap(a, b);
	if (a.Max > b.Min) ans.Min = ans.Max & 1;
	else ans.Min = b.Min - a.Max;
	return ans;
}
void work(int pos, int fa, int depth) {
	dp[pos] = (info) {0, 0, 0};
	for (auto x : a[pos])
		if (x != fa) {
			work(x, pos, depth + 1);
			dp[pos] = dp[pos] + (dp[x] + 1);
		}
	if (s[pos] == '1') {
		dp[pos].size++;
		now += depth;
	}
}
