int sumh[N];
void precalc(int v, int p, int h) {
    sz[v] = s[v - 1] - '0';
    hg[v] = h;
    sumh[v] = sz[v] * hg[v];
    for (auto to: ed[v]) {
        if (to == p) {
            continue;
        }
        precalc(to, v, h + 1);
        sz[v] += sz[to];
        sumh[v] += sumh[to];
    }
}


void dfs(int v, int p) {
    priority_queue<pair<int, int> > hp;
    for (auto to: ed[v]) {
        if (to == p) {
            continue;
        }
        dfs(to, v);
        hp.push(make_pair(sumh[to] - hg[v] * sz[to], to));
    }

    while (hp.size() > 1) {
        auto a = hp.top();
        hp.pop();
        auto b = hp.top();
        hp.pop();
        if (a.first == 0) {
            break;
        } else if (b.first == 0) {
            hp.push(a);
        } else {
            a.first--;
            b.first--;
            hp.push(a);
            hp.push(b);
        }
    }
    if (hp.empty()) {
        dp[v] = sz[v] * hg[v];
    } else {
        auto a = hp.top();
        int delta = sumh[a.second] - dp[a.second];
        dp[v] = max(sz[v] * hg[v], a.first + sz[v] * hg[v] - delta);
    }
}


