int N;
string S;
vector<vector<int>> roads;

struct data{
    lint size, piece, dist, climb;
};

data dfs(int now, int back){
    vector<data> child;
    for(int i: roads[now]){
        if(i != back){
            child.push_back(dfs(i, now));
            child.back().dist += child.back().piece;
        }
    }
    lint size_sum = 1, piece_sum = S[now], dist_sum = 0, dist_max = -1e9, dist_max_index = -1;
    for(int i = 0; i < child.size(); i++){
        size_sum += child[i].size;
        piece_sum += child[i].piece;
        dist_sum += child[i].dist;
        if(dist_max < child[i].dist){
            dist_max = child[i].dist;
            dist_max_index = i;
        }
    }
    if(child.empty()){
        return {size_sum, piece_sum, dist_sum, 0};
    }
    lint other_dist = dist_sum - dist_max;
    lint climb = min(dist_sum / 2, other_dist + child[dist_max_index].climb);
    return {size_sum, piece_sum, dist_sum, climb};
}

