using namespace std;

struct Data {
    int n, l, r;
    Data(int n, int l, int r) : n(n), l(l), r(r) {}
};

Data merge(Data a, Data b) {
    Data ret(a.n + b.n, 0, a.r + b.r);

    if (a.l > b.l) swap(a, b);
    if (a.r >= b.l) {
        // 交差あり
        ret.l = (a.r - b.l) % 2;
    } else {
        // 交差なし
        ret.l = b.l - a.r;
    }
    return ret;
}

int main() {
    int N;
    string S;
    cin >> N >> S;

    Graph<> tree(N);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        tree[u].emplace_back(u, v);
        tree[v].emplace_back(v, u);
    }

    function<Data(int, int)> dfs = [&](int v, int r) -> Data {
        vector<Data> data;

        for (auto e : tree[v]) {
            if (e.dst == r) continue;
            Data res = dfs(e.dst, v);
            res.l += res.n, res.r += res.n;
            data.push_back(res);
        }

        Data acc(S[v] - '0', 0, 0);
        for (auto d : data) {
            acc = merge(acc, d);
        }
        return acc;
    };

    int ans = INF;
    for (int r = 0; r < N; ++r) {
        Data res = dfs(r, -1);
        if (res.l > 0) continue;
        ans = min(ans, res.r);
    }

    cout << (ans == INF ? -1 : ans / 2) << endl;
    return 0;
}

