		dfs(i,x);
		dp[x][0]+=dp[i][0];
		dp[x][2]+=dp[i][2]+dp[i][0];
		tmp=max(tmp,make_pair(dp[i][2]+dp[i][0],dp[i][1]+dp[i][0]));
