pair<int, int> _dfs(int u, int p)
{
    pair<int, int> ret = {0, val[u] == '1'};

    for (int v: graph[u])
    {
        if (v == p)
            continue;

        pair<int, int> tmp = _dfs(v, u);
        ret.first += tmp.first + tmp.second;
        ret.second += tmp.second;
    }

    return ret;
}

void dfs(int u, int &ans)
{
    int sum = 0;
    int ma = 0;
    vector<int> kek;
    for (int v: graph[u])
    {
        pair<int, int> tmp = _dfs(v, u);
        kek.push_back(tmp.first + tmp.second);
        sum += tmp.first + tmp.second;
        ma = max(ma, tmp.first + tmp.second);
    }

    if (sum & 1)
        return;
    else if (ma * 2 > sum)
        return;
    else
        ans = min(ans, sum / 2); 
}

