ll fill_masses(const int v, const vvi& g, const vi& p, vvl& mass, const ll M, const int f)
{
	ll my_mass = p[v];
	int batya = -1;
	for (int i = 0; i < sz(g[v]); ++i)
	{
		int to = g[v][i];
		if (to != f)
		{
			mass[v][i] = fill_masses(to, g, p, mass, M, v);
			my_mass += mass[v][i];
		}
		else
			batya = i;
	}
	if (batya != -1)
		mass[v][batya] = M - my_mass;
	return my_mass;
}

void fill_down_moments(const int v, const vvi& g, vvl& moment, vl& entire_moment, const vvl& mass, const int f)
{
	for (int i = 0; i < sz(g[v]); ++i)
	{
		int to = g[v][i];
		if (to != f)
		{
			fill_down_moments(to, g, moment, entire_moment, mass, v);
			moment[v][i] = mass[v][i] + entire_moment[to];
			entire_moment[v] += moment[v][i];
		}
	}
}

void fill_all_moments(const int v, const vvi& g, vvl& moment, vl& entire_moment, const vvl& mass, const int f, ll father_moment, ll M)
{
	entire_moment[v] += father_moment;
	for (int i = 0; i < sz(g[v]); ++i)
	{
		int to = g[v][i];
		if (to != f)
			fill_all_moments(to, g, moment, entire_moment, mass, v, entire_moment[v] - moment[v][i] + M - mass[v][i], M);
		else
			moment[v][i] = father_moment;
	}
}

void fill_minimal_moments(const int v, const int w, const vvi& g, const vvi& top_2_moments, const vl& entire_moment, const vvl& mass, const vvl& moment, vvl& minimal_moment)
{
	if (minimal_moment[v][w] == -1)
	{
		int u = g[v][w];
		ll entire = moment[v][w] - mass[v][w];
		int top_moment = top_2_moments[u][0];
		if ((top_moment != -1) && (g[u][top_moment] == v))
			top_moment = top_2_moments[u][1];
		ll ans;
		if (top_moment != -1)
		{
			entire -= moment[u][top_moment];
			fill_minimal_moments(u, top_moment, g, top_2_moments, entire_moment, mass, moment, minimal_moment);
			ans = minimal_moment[u][top_moment] - entire;
		}
		else
			ans = -entire;
		if (ans < 0)
			ans = (ans & 1ll);
		ans += mass[v][w];
		minimal_moment[v][w] = ans;
	}
}

