void DFS(int u, int fa) {
	siz[u] = (s[u] == '1');
	sum[u] = dp[u] = 0;
	int mx = 0;
	for (auto v : e[u]) {
		if (v == fa) continue;
		DFS(v, u);
		siz[u] += siz[v];
		sum[u] += sum[v];
		if (!mx || dp[v] > dp[mx]) {
			mx = v;
		}
	}
	if (sum[u] - sum[mx] >= dp[mx]) {
		dp[u] = sum[u] & 1;
	} else {
		dp[u] = dp[mx] - (sum[u] - sum[mx]);
	}
	sum[u] += siz[u];
	dp[u] += siz[u];
}

