void getAns(int u, int fa) {
	int maxSon = -1;
	all[u] = 1ll * (A[u] - '0') * nodeDep[u];
	for (int v : adj[u]) {
		if (v == fa)
			continue;
		nodeDep[v] = nodeDep[u] + 1;
		getAns(v, u);
		all[u] += all[v];
		if (!~maxSon || all[maxSon] < all[v])
			maxSon = v;
	}

	if (!~maxSon)
		return void(dp[u] = 0);
	if (all[u] >= (all[maxSon]<<1))
		dp[u] = all[u] >> 1;
	else
		dp[u] = all[u] - all[maxSon] + (min((all[maxSon]<<1) - all[u], dp[maxSon] << 1) >> 1);
}

