const int N = 2100;

int n;
string s;

vector<int> eds[N];

const int INF = 1e9;

using tp = array<int, 3>;

tp dfs1(int v, int p) {
	vector<tp> vv;
	int sml = 0;
	int sm = 0;
	if (s[v] == '1')
		vv.push_back({0, 0, 1}), sm += 1;
	for (int u: eds[v]) {
		if (u == p)
			continue;
		tp go = dfs1(u, v);
		go[0] += go[2];
		go[1] += go[2];
		sml += go[0];
		sm += go[2];
		vv.push_back(go);
	}
	sort(ALL(vv));
	reverse(ALL(vv));
	if (vv.empty()) {
		return {0, 0, 0};
	}
	int cur = vv[0][1];
	for (int i = 1; i < vv.size(); ++i)
		cur -= vv[i][0];
	if (sml % 2 == 1)
		cur = max(cur, 1);
	else
		cur = max(cur, 0);
	return {sml, cur, sm};
}

