	for (int i = 0; i < n; ++i) {
		vector<pair<int, int>> vv;
		int sm = 0;
		for (int u: eds[i]) {
			tp go = dfs1(u, i);
			go[0] += go[2];
			go[1] += go[2];
			sm += go[0];
			vv.push_back({go[0], go[1]});
		}
		if (sm % 2 == 1)
			continue;
		sort(ALL(vv));
		reverse(ALL(vv));
		int cur = vv[0].second;
		for (int j = 1; j < vv.size(); ++j)
			cur -= vv[j].first;
		if (cur <= 0)
			ans = min(ans, sm / 2);
	}
	if (ans < INF)
		cout << ans << "\n";
	else
		cout << -1 << "\n";
	return 0;
}

