using namespace std;

const int MAX_N = 2e3 + 10;

int N, ans = INT_MAX, F[MAX_N], G[MAX_N], H[MAX_N];
char S[MAX_N];
vector<int> edge[MAX_N];

void dfs(int x, int y) {
    F[x] = S[x] - '0'; G[x] = H[x] = 0;
    vector<int> ch;
    for (int i : edge[x]) {
        if (i == y) continue;
        dfs(i, x);
        ch.push_back(G[i] + F[i]);
        F[x] += F[i];
        H[x] += H[i] + F[i];
    }
    int mx = 0, sum = 0;
    for (int i : ch)
        mx = max(mx, i), sum += i;
    if (mx * 2 >= sum) {
        G[x] = 2 * mx - sum;
    } else {
        G[x] = sum & 1;
    }
}

int main() {
    scanf("%d", &N);
    scanf("%s", S + 1);
    for (int i = 1; i < N; i++) {
        int a, b; scanf("%d%d", &a, &b);
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    for (int i = 1; i <= N; i++) {
        dfs(i, 0);
        int res = H[i];
        if (res & 1) continue;
        bool flag = true;
        for (int j : edge[i]) {
            if ((G[j] + F[j]) * 2 > res + G[j] - H[j]) flag = false;
        }
        if (flag) ans = min(ans, res / 2);
    }
    printf("%d\n", ans == INT_MAX ? -1 : ans);
}

