const int N=2e3+10,inf=1e9;
int n,cnt,ans=inf,size[N],dis[N],head[N],to[N<<1],nxt[N<<1];
char s[N];
inline void add(int u,int v){
	to[++cnt]=v,nxt[cnt]=head[u],head[u]=cnt;
}
void dfs1(int u,int fa){
	size[u]=s[u]-'0',dis[u]=0;
	for(int i=head[u];i;i=nxt[i]){
		int v=to[i]; if(v==fa) continue; dfs1(v,u);
		size[u]+=size[v],dis[u]+=dis[v]+size[v];
	}
}
int dfs2(int u,int fa){
	int mx=0;
	for(int i=head[u];i;i=nxt[i]){
		int v=to[i]; if(v==fa) continue;
		if(mx==0 || dis[v]>dis[mx]) mx=v;
	}
	if(mx==0) return 0;
	int tmp=size[mx]+dfs2(mx,u);
	if(dis[u]-dis[mx]-size[mx]>=tmp) return dis[u]&1;
	else return tmp-(dis[u]-dis[mx]-size[mx]);
}
