struct dp {
    vector<pii> ps;
    int mn, mx, sz;
    dp() : mn(0), mx(0), sz(0), ps() {}
    void add(int nmn, int nmx, int nsz) {
        ps.emplace_back(nmn + nsz, nmx + nsz);
        sz += nsz;
    }
    void init() {
        mn = mx = 0;
        for (pii i : ps) {
            if (mx < i.fs) {
                mn = i.fs - mx;
            }
            else if (i.se < mn) {
                mn -= i.se;
            }
            else mn = (i.fs ^ mn) & 1;
            mx += i.se;
        }
    }
};
dp ddp[2001];
dp udp[2001];

int par[2001];
void dfs1(int x, int p) {
    par[x] = p;
    if (S[x] == '1') ddp[x].add(-1, -1, 1);
    for (int i : edge[x]) {
        if (i == p) continue;
        dfs1(i, x);
        ddp[x].add(ddp[i].mn, ddp[i].mn, ddp[i].sz);
    }
    ddp[x].init();
}

void dfs2(int x, int p) {
    if (S[p] == '1') udp[x].add(-1, -1, 1);
    if (p > 1) udp[x].add(udp[p].mn, udp[p].mx, udp[p].sz);
    for (int i : edge[p]) {
        if (i == x || i == par[p]) continue;
        udp[x].add(ddp[i].mn, ddp[i].mx, ddp[i].sz);
    }
    udp[x].init();
    for (int i : edge[x]) {
        if (i == p) continue;
        dfs2(i, x);
    }
}

int dfs3(int x, int p = 0, int d = 0) {
    int ret = 0;
    if (S[x] == '1') ret += d;
    for (int i : edge[x]) {
        if (i == p) continue;
        ret += dfs3(i, x, d + 1);
    }
    return ret;
}

