  size[x] = s[x - 1] == '1';
  foo[x] = bar[x] = 0;
  int max_son = 0;
  for (auto y : adj[x]) {
    if (y != f) {
      dfs(y, x);
      size[x] += size[y];
      foo[x] += foo[y];
      if (foo[y] > foo[max_son]) {
        max_son = y;
      }
    }
  }
  bar[x] = max(0, bar[max_son] - foo[x] + foo[max_son]);
  if (x != root) {
    foo[x] += size[x];
    bar[x] += size[x];
  }
}

