void addedge(int u, int v){
	e[++tot].to = v, e[tot].nxt = head[u];
	head[u] = tot;
}
int dep[maxn], sz[maxn], sum; char s[maxn];
void dfs1(int cur, int fa){
	dep[cur] = dep[fa] + 1;
	sum += (s[cur] == '1') * (dep[cur] - 1);
	for (int i = head[cur]; i; i = e[i].nxt){
		int v = e[i].to;
		if (v != fa){
			dfs1(v, cur);
			sz[cur] += sz[v] + (s[v] == '1');
		}
	}
}
int sdep[maxn]; bool f;
void dfs2(int cur, int fa){
	int link = 0;
	for (int i = head[cur]; i; i = e[i].nxt){
		int v = e[i].to;
		if (v == fa) continue;
		if (sdep[v] + sz[v] > sdep[link] + sz[link]) link = v;
		sdep[cur] += sdep[v] + sz[v];
	}
	if (link == 0) return;
	if (2ll * (sdep[link] + sz[link]) > sdep[cur]) f = false;
	sdep[cur] -= 2ll * (sdep[link] + sz[link]);
}
