int cnt[2521];
int memo[2521];

int dfs0(int p, int bef){
    cnt[p] = s[p]-'0';
    for(int to : g[p])if(to != bef){
        cnt[p] += dfs0(to,p);
    }
    return cnt[p];
}
int dfs1(int p, int bef, int d){
    int ret = 0;
    if(s[p]=='1')ret += d;
    for(int to : g[p])if(to != bef){
        ret += dfs1(to, p, d+1);
    }
    memo[p] = ret - cnt[p]*d;
    return ret;
}
// <count, dists>
bool dfs2(int p, int bef, ll rest){
    if(rest<0)return false;
    ll sum = 0;
    ll mx = 0;
    int id = -1;
    for(int to : g[p])if(to != bef){
        int v = memo[to]+cnt[to];
        sum += v;
        if(v > mx){
            mx = v;
            id = to;
        }
    }
    if(mx <= sum-mx){
        return sum%2 <= rest;
    }else{
        ll mn = 2*mx-sum;
        if(mn <= rest)return true;
        if(id==-1)return false;
        return dfs2(id, p, rest+sum-mx-cnt[id]);
    }
}

