    ll ans = 1ll<<60;
    vi roots(n);
    REP(i,n)roots[i] = i;
    srand(2521);
    random_shuffle(ALL(roots));
    for(int root : roots){
        // if(root!=0)continue;
        fill(memo,memo+n,-1);
        fill(cnt,cnt+n,0);
        dfs0(root, -1);
        vector<pii> V;
        ll sum = 0;
        for(int to : g[root]){
            int v = dfs1(to, root, 1);
            sum += v;
            V.push_back(pii(v,to));
        }
        if(sum%2==1)continue;
        if(sum/2 >= ans)continue;
        sort(ALL(V));
        reverse(ALL(V));
        if(V[0].first <= sum-V[0].first){
            // ok
            CHMIN(ans, sum/2);
