pii Do(int x, int fa) {
	pii res = pii(0, 0);
	vector <int> w;
	for(int e : E[x]) if(e != fa) {
		pii r = Do(e, x);
		r.Fi += down[e];
		res.Se += r.Se;
		w.pb(r.Fi);
	}
	sort(all(w));
	if(szz(w) == 0) return res;
	int sum = 0;
	for(int e : w) sum += e;
	if(w.back() > sum - w.back()) {
		res.Se += sum - w.back();
		res.Fi = w.back() - (sum - w.back());
	}
	else {
		res.Se += sum / 2;
		res.Fi = sum % 2;
	}
	return res;
}

int solve(int x) {
	pdfs(x, -1);
	pii r = Do(x, -1);
	if(r.Fi != 0) return 1e9;
	else return r.Se;
}

