#include <vector>
using namespace std;
using ll = long long;
const ll INF = 1e18;

const int N = 2000;
vector<int> conns[N];
string str;

ll dp_min[N];
ll dp_max[N];
int count[N];

void recDP(int i, int p = -1) {
	for (auto t : conns[i]) {
		if (t == p) continue;
		recDP(t, i);
		dp_max[i] += dp_max[t];
		count[i] += count[t];
	}

	dp_min[i] = dp_max[i] % 2;
	for (auto t : conns[i]) {
		if (t == p) continue;
		ll offer = dp_min[t] + dp_max[t] - dp_max[i];
		dp_min[i] = max(dp_min[i], offer);
	}
	if (str[i] == '1') ++count[i];
	dp_min[i] += count[i];
	dp_max[i] += count[i];
}
ll recSolve(int i, int p = -1, ll min_above = 0, ll max_above = 0, int count_above = 0) {
	dp_min[i] -= count[i];
	dp_max[i] -= count[i];

	ll offer = INF;

	bool can_offer = true;
	if ((max_above + dp_max[i]) % 2 == 1) can_offer = false;
	if (min_above > dp_max[i]) can_offer = false;
	if (dp_min[i] > max_above) can_offer = false;
	if (can_offer) offer = min(offer, (max_above + dp_max[i]) / 2);

	// cout << i << ' ' << min_above << ' ' << max_above << ' ' << count_above << ' ' << dp_min[i] << ' ' << dp_max[i] << ' ' << count[i] << '\n';

	ll mins_sum = min_above;
	pair<ll, int> worst1_tar_min = {max_above + min_above, p};
	pair<ll, int> worst2_tar_min = {0, -1};
	for (auto t : conns[i]) {
		if (t == p) continue;
		pair<ll, int> sub = {dp_max[t] + dp_min[t], t};
		if (sub > worst1_tar_min) swap(sub, worst1_tar_min);
		if (sub > worst2_tar_min) swap(sub, worst2_tar_min);
		mins_sum += dp_min[t];
	}
	// cout << "sums " << i << ' ' << mins_sum << ' ' << worst1_tar_min.first << ' ' << worst2_tar_min.first << '\n';

	for (auto t : conns[i]) {
		if (t == p) continue;
		int tar_count_above = count_above + count[i] - count[t];
		ll tar_max_above = (max_above + dp_max[i] - dp_max[t]) + tar_count_above;
		ll tar_min_above = tar_count_above;

		if (t == worst1_tar_min.second) {
			tar_min_above += max(tar_max_above % 2, worst2_tar_min.first - mins_sum + dp_min[t]);
		} else {
			tar_min_above += max(tar_max_above % 2, worst1_tar_min.first - mins_sum + dp_min[t]);
		}

		ll sub = recSolve(t, i, tar_min_above, tar_max_above, tar_count_above);
		offer = min(offer, sub);
	}
	return offer;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;
	cin >> str;
	for (int i = 0; i < n-1; ++i) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		conns[a].push_back(b);
		conns[b].push_back(a);
	}

	// Possible iff sum of distances to the target node is even
	// Given that, we then need that the minimum total distance at every branch is at most the sum of the maximum distances of other branches.
	// No operation in a branch can bring two pieces further away from the root, but a operation can bring both of two pieces closer.

	// So for every branch DP 3 values:
	//	1. Total minimum distance of pieces to parent
	//	2. Total maximum distance of pieces to parent
	//	3. Count of pieces
	// Say we count these for every subtree. To do that, first solve all subtrees of a node, then find sum of maximum distances,
	// then loop over every node, subtract its maximum from the total maximum, and check if its minimum is <= the sum of other maximums.
	// If it isn't, the total minimum distance of pieces to parent of this node will be that node's minimum - sum of other maximums.
	// If no node has such a situation, the minimum distance for this node will be the sum of maximums mod 2.

	recDP(0);
	ll ans = recSolve(0);
	if (ans >= INF) cout << "-1\n";
	else cout << ans << '\n';
}

