	for(auto v:g[u]){
		if(v!=par){
			dfs(v,u);
			np[u]+=np[v];
			dist[u]+=(dist[v]+np[v]);
			a.emplace_back(dp[v]+np[v], dist[v]+np[v]);
		}
	}
	int nn = a.size();

	dp[u]=dist[u];
	if(a.empty())
		return;
	sort(a.begin(),a.end());
	int val=0;
	for(int i=0;i<nn-1;i++){
		if(a[i].se<=a.back().fi){
			val+=a[i].se;
		}
		else{
			val+=a.back().fi;
		}
	}
	dp[u]=min(dp[u],max(0,a.back().fi-val));

	sort(a.begin(),a.end(),[](pair<int,int> &pp, pair<int,int> &qq){
		return pp.se<qq.se;
	});
	vector<int> suf(nn+1,0), mmx(nn+1,0),pre(nn,0), la(nn,nn);

	for(int i=nn-1;i>=0;i--){
		suf[i]=suf[i+1]+a[i].fi;
		mmx[i]=max(mmx[i+1], a[i].fi);
		if(i<nn-1){
			if(a[i].se==a[i+1].se){
				la[i]=la[i+1];
			}
			else{
				la[i]=i+1;
			}
		}
	}
	pre[0]=a[0].se;
	for(int i=1;i<nn;i++){
		pre[i]=a[i].se+pre[i-1];
	}

	for(int i=0;i<nn;i++){
		if(mmx[la[i]]<=a[i].se){
			int cur = pre[la[i]-1]-a[i].se + (nn-la[i])*a[i].se;
			dp[u]=min(dp[u],max(0,a[i].se-cur));
		}
	}


	if((dp[u]==0) && (dist[u]&1)){
		dp[u]++;
	}
}

