vi dep,par,sz,num;
vvi g;
ll dfs0(int i,int p,int d){
    par[i]=p;
    dep[i]=d;
    sz[i]=num[i];
    for(ll x:g[i])if(x!=p)sz[i]+=dfs0(x,i,d+1);
    return sz[i];
}
void tree(ll n,ll s){
    dep=vi(n);
    par=vi(n);
    sz=vi(n);
    dfs0(s,-1,0);
}
vp dp;
P dfs(int i){
    ll mi,ma=0;
    P m=P(-inf,inf);
    for(ll x:g[i])if(x!=par[i]){
        auto p=dfs(x);
        ma+=p.se+sz[x];
        chmax(m,P(p.fi+sz[x],p.se+sz[x]));
    }
    mi=max(0ll,m.fi-(ma-m.se));
    if(mi==0)mi+=ma%2;
    return P(mi,ma);
}
int main(){
