        P p=dfs(s);
        if(p.fi==0)chmin(ans,p.se);
    }
    if(ans==inf)out(-1);
    else outs(ans/2,-1);
}

#include<bits/stdc++.h>
using namespace std;
int n, col[2007], tot[2007], sum[2007], res = 1e9;
char s[2007];
vector<int>e[2007];
int read()
{
	int num = 0;
	char c = getchar();
	while (c < '0' || c>'9')c = getchar();
	while (c >= '0' && c <= '9')num = num * 10 + c - '0', c = getchar();
	return num;
}
int dfs(int w, int f)
{
	tot[w] = col[w];
	sum[w] = 0;
	for (int i = 0, lim = e[w].size(); i < lim; i++)
		if (e[w][i] != f)
		{
			dfs(e[w][i], w);
			tot[w] += tot[e[w][i]];
			sum[w] += sum[e[w][i]] + tot[e[w][i]];
		}
	return 0;
}
int check(int w, int f)
{
	int mx = 0;
	for (int i = 0, lim = e[w].size(); i < lim; i++)
		if (e[w][i] != f && sum[e[w][i]] > sum[mx])mx = e[w][i];
	if (!mx)return 0;
	int val = check(mx, w) + tot[mx];
	if (sum[w] - sum[mx] - tot[mx] >= val)return sum[w] & 1;
	else return val - (sum[w] - sum[mx] - tot[mx]);
}
int main()
{
	n = read();
	scanf("%s", s + 1);
	for (int i = 1; i <= n; i++)
		col[i] = s[i] - '0';
	for (int i = 2; i <= n; i++)
	{
		int a = read(), b = read();
		e[a].push_back(b);
		e[b].push_back(a);
	}
	for (int i = 1; i <= n; i++)
	{
		dfs(i, 0);
		if (check(i, 0) == 0)
			res = min(res, sum[i] / 2);
	}
	if (res < 1e9)cout << res << endl;
	else cout << -1 << endl;
	return 0;
}

#include <bits/stdc++.h>

typedef long long ll;
const int N = 5005;

int n, c[N], head[N], nxt[N], ver[N], cnt;
ll sum[N], max[N], min[N];
char s[N];

inline void add(int u, int v)
{
	nxt[++cnt] = head[u];
	ver[cnt] = v;
	head[u] = cnt;
}

void solve(int x, int f)
{
	max[x] = min[x] = 0; sum[x] = c[x];
	int max_son = 0;
	for (int i = head[x]; i; i = nxt[i])
	{
		int y = ver[i];
		if (y != f)
		{
			solve(y, x);
			sum[x] += sum[y];
			max[x] += max[y];
			if (max[y] > max[max_son]) max_son = y;
		}
	}
	if (min[max_son] <= max[x] - max[max_son]) min[x] = (max[x] & 1) + sum[x];
	else min[x] = min[max_son] - (max[x] - max[max_son]) + sum[x];
	max[x] += sum[x];
	if (f == 0) max[x] -= sum[x], min[x] -= sum[x], sum[x] -= sum[x];
}

inline char nc()
{
	static char buf[1000000], *p1 = buf, *p2 = buf;
	return p1 == p2 && (p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin), p1 == p2) ? EOF : *p1++;
}

inline int read()
{
	int res = 0;
	char ch;
	do ch = nc(); while (ch < 48 or ch > 57);
	do res = res * 10 + ch - 48, ch = nc(); while (ch >= 48 and ch <= 57);
	return res;
}

int main()
{
	scanf("%d%s", &n, s + 1);
	for (int i = 1; i <= n; ++i) c[i] = s[i] - 48;
	for (int i = 1; i < n; ++i)
	{
		int u = read(), v = read();
		add(u, v); add(v, u);
	}
	ll ans = 1e18;
	for (int i = 1; i <= n; ++i)
	{
		solve(i, 0);
		if (min[i] == 0) ans = std::min(ans, max[i] >> 1);
	}
	if (ans >= 1e18) puts("-1");
	else printf("%lld", ans);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef vector<ll> vi;
typedef pair<ll,ll> pi;
typedef vector<pi> vpi;
typedef long double ld;
#define pb emplace_back
#define mp make_pair
#define lb lower_bound
#define ub upper_bound
#define ALL(x) x.begin(), x.end()
#define SZ(x) (ll)x.size()
#define f first
#define s second
#define MAXN 3010

vi V[MAXN];
ll A[MAXN];
ll N,a,b;
ll sub[MAXN];
ll val[MAXN];
ll low[MAXN];

void dfs(ll x, ll p){
	sub[x] = A[x]; val[x] = 0; 
	vpi tmp;tmp.clear();
	ll t = 0;
	for (auto v:V[x])if(v!=p){
		dfs(v,x);
		sub[x] += sub[v]; val[x] += (sub[v] + val[v]);
		tmp.pb(sub[v] + val[v], v);
		t += sub[v] + val[v];
	}
	if (SZ(tmp) == 0)return;
	sort(ALL(tmp));
	// if (x == 2)for (auto v:tmp)cout<<v.f<<' '<<v.s<<'\n';
	int largest = low[tmp.back().s] + sub[tmp.back().s];
	// cout<<tmp.back().s<<' '<<low[tmp.back().s]<<' '<<sub[tmp.back().s]<<'\n';
	ll tar = t - tmp.back().f;
	if (tar >= largest){
		low[x] = t%2;
	}else{
		low[x] = largest - tar;
	}
	// cout<<"Dfs "<<x<<' '<<low[x]<<'\n';
}

int main(){
	cin>>N;
	string S;cin>>S;
	for (ll i=1;i<=N;++i)if(S[i-1] == '1')A[i]=1;
	for (ll i=1;i<N;++i){cin>>a>>b;V[a].pb(b);V[b].pb(a);}
	for (ll i=1;i<=N;++i){
		// if (i==1)continue;
		dfs(i,-1);
		if (low[i] != 0)continue;
		ll t = 0;
		for (auto v:V[i])t += sub[v] + val[v];
		cout<<t/2<<'\n';
		return 0;
	}
	cout<<-1;
}

