struct Edge {
	int v;
	Edge *nxt;
}edge[2*N];
Edge *ecnt,*NIL;
Edge *head[N];
int n,ans=INF;
char ch[N];
int Min[N],Max[N];
int siz[N],yl[N];
void AddEdge(int u,int v) {
	ecnt->v=v; ecnt->nxt=head[u];
	head[u]=ecnt++;
	ecnt->v=u; ecnt->nxt=head[v];
	head[v]=ecnt++;
}
void Dfs1(int u,int fa) {
	siz[u]=ch[u]-'0';
	yl[u]=Min[u]=Max[u]=0;
	int son=-1;
	for(Edge *e=head[u];e!=NIL;e=e->nxt) {
		if(e->v==fa) continue;
		Dfs1(e->v,u);
		if(siz[e->v]) {
			siz[u]+=siz[e->v];
			Max[u]+=Max[e->v]+siz[e->v];
			Min[u]+=Min[e->v];
			yl[u]+=yl[e->v]+siz[e->v];

			if(son==-1||yl[son]+siz[son]<yl[e->v]+siz[e->v])
				son=e->v;
		}
	}
	if(son==-1) return ;
	if(yl[son]+siz[son]>yl[u]-(yl[son]+siz[son])) {
		Min[u]+=yl[u]-(yl[son]+siz[son]);
		yl[u]=yl[son]+siz[son]-(yl[u]-(yl[son]+siz[son]));
	}
	else {
		Min[u]+=yl[u]>>1;
		yl[u]=yl[u]&1;
	}
}
