int low=0, high=1;
void dfs(int x,int p) {
	sz[x] = A[x];
	for(auto i:v[x]) if(i^p) dfs(i, x), sz[x]+=sz[i];
	// dp(x,0) = max(summation{dp(i,0)}&1, max{dp(i)[low,high,2]}*2 - summation{dp(i)[low,high,2]})
	pi mx = pi(-LLINF, -LLINF);
	for(auto i:v[x]) if(i^p) {
		dp[x][high] += dp[i][high] + sz[i];
		mx = max(mx, pi(dp[i][high]+sz[i], dp[i][low]+sz[i]));
	}
	if(mx.s > dp[x][high] - mx.f) {
		dp[x][low]=mx.s-(dp[x][high]-mx.f);
	} else {
		dp[x][low]=dp[x][high]&1;
	}
}
