	ll ret = INFLL;
	rep(a, n) {
		vector<int> z;
		ll su = 0;
		for (int i : G[a]) {
			int v = dfs(i, 1, a);
			if (v == 0) continue;
			su += v;
			z.push_back(v);
		}
		if (su % 2 == 1) continue;
		if (z.size() == 1) continue;

		priority_queue<ll> Q;
		for (auto&v : z) Q.push(v);
		bool ng = false;
		ll r = 0;
		for (;;) {
			if (Q.size() == 0) break;
