				break;
			}
			ll fi = Q.top(); Q.pop();
			ll se = Q.top(); Q.pop();
			fi--; se--;
			if(fi>0)Q.push(fi);
			if(se>0)Q.push(se);
			++r;
			if (ret <= r) break;
		}
