using Pll = pair<ll, ll>;

struct Vert {
	Vi edges;
	ll cnt, minSum, maxSum;
	int has;
};

int n;
vector<Vert> G;

ll matching(vector<Pll>& opt, ll lvl) {
	ll sum = 0, leader = 0;

	each(p, opt) {
		ll k = 0;

		if (p.x >= lvl) {
			k = p.x;
		} else if (p.y <= lvl) {
			k = p.y;
		} else {
			k = p.x + (lvl-p.x) / 2 * 2;
		}

		sum += k;
		leader = max(leader, k);
	}

	if (leader*2 <= sum) {
		return sum % 2;
	}
	return leader - (sum - leader);
}

void dfs(int v, int p) {
	G[v].cnt = G[v].has;
	G[v].maxSum = 0;

	vector<Pll> tmp;
	ll lvl = 0;

	each(e, G[v].edges) if (e != p) {
		dfs(e, v);
		ll lower = G[e].minSum + G[e].cnt;
		ll upper = G[e].maxSum + G[e].cnt;

		G[v].cnt += G[e].cnt;
		G[v].maxSum += upper;
		tmp.pb({lower, upper});
		lvl = max(lvl, lower);
	}

	G[v].minSum = min(matching(tmp, lvl), matching(tmp, lvl+1));
}

ll solve(int root) {
	dfs(root, -1);
	if (G[root].minSum > 0) return INT64_MAX;
	assert(G[root].maxSum % 2 == 0);
	return G[root].maxSum / 2;
}

void run() {
	cin >> n;
	G.resize(n);

	string s; cin >> s;
	rep(i, 0, n) G[i].has = (s[i] == '1');

	rep(i, 1, n) {
		int a, b; cin >> a >> b;
		G[a-1].edges.pb(b-1);
		G[b-1].edges.pb(a-1);
	}

	ll ans = INT64_MAX;
	rep(i, 0, n) ans = min(ans, solve(i));
	cout << (ans == INT64_MAX ? -1 : ans) << endl;
}

