const int SIZE = 1e6+10;
string s;
VI e[SIZE];
int num[SIZE];
LL sum[SIZE];
void dfs0(int x,int lt){
    num[x]=(s[x]=='1');
    sum[x]=0;
    for(int y:e[x]){
        if(y==lt)continue;
        dfs0(y,x);
        sum[x]+=sum[y]+num[y];
        num[x]+=num[y];
    }
}
bool valid(int x,int lt,LL v){
    VPLL dd;
    REP(i,SZ(e[x])){
        int y=e[x][i];
        if(y==lt)continue;
        dd.PB(MP(sum[y]+num[y],y));
    }
    sort(ALL(dd));
    LL now=v;
    REP(i,SZ(dd)-1){
        now+=dd[i].F;
    }
    if(now>=dd.back().F)return 1;
    if(now<num[dd.back().S])return 0;
    return valid(dd.back().S,x,now-num[dd.back().S]);
}
LL check(int x){
    dfs0(x,x);
    if(sum[x]&1)return 1e18;
    if(valid(x,x,0)) return sum[x]/2;
    return 1e18;
}
