void chemthan() {
    int n; cin >> n;
    string s; cin >> s;
    vector<vi> adj(n);
    FOR(i, 0, n - 1) {
        int u, v; cin >> u >> v; u--, v--;
        adj[u].pb(v), adj[v].pb(u);
    }
    int tres = INF;
    vi d(n);
    function<int(int, int)> dfs = [&] (int u, int p) {
        int res = 0;
        if (s[u] == '1') res += d[u];
        vi vals;
        for (int v : adj[u]) {
            if (v ^ p) {
                d[v] = d[u] + 1;
                int t = dfs(v, u);
                vals.pb(t);
                res += t;
            }
        }
        if (p == -1) {
            sort(all(vals));
            if (sz(vals)) {
                int sum = 0;
                FOR(i, 0, sz(vals) - 1) {
                    sum += vals[i];
                }
                if (vals.back() <= sum && (sum + vals.back()) % 2 == 0) {
                    chkmin(tres, (sum + vals.back()) / 2);
                }
            }
        }
        return res;
    };
    FOR(u, 0, n) {
        d[u] = 0;
        dfs(u, -1);
    }
    if (tres == INF) tres = -1;
    cout << tres << "\n";
}

