template <typename Input1, typename Input2, typename Output>
void zip(
	Input1 begin1, Input1 end1,
	Input2 begin2, Input2 end2,
	Output result) {
	auto it1 = begin1;
	auto it2 = begin2;
	while (it1 != end1 && it2 != end2) {
		result++ = std::make_pair(*it1++, *it2++);
	}
}

template <typename T, typename U>
std::vector<std::pair<T, U>> zip(
	std::vector<T> const & range1,
	std::vector<U> const & range2) {
	std::vector<std::pair<T, U>> result;

	zip(
		std::begin(range1), std::end(range1),
		std::begin(range2), std::end(range2),
		std::back_inserter(result));

	return result;
}


int main() {
	ll N;
	cin >> N;

	string S;
	cin >> S;

	vector<vector<ll>> V(N);
	for (ll i = 0; i < N - 1; i++) {
		ll a, b;
		cin >> a >> b;
		a--;
		b--;
		V[a].push_back(b);
		V[b].push_back(a);
	}
	// 辺の多さでソートした別物を用意する。
	vector<ll> num(N);
	iota(ALL(num), 0LL);
	auto zipped = zip(num, V);
	sort(ALL(zipped), [](auto x, auto y) {
		return x.second.size() > y.second.size();
	});

	vector<ll> ans(N, -1);

	// ノード数が多い場所から幅優先探索して割り当てていく。
	queue<pair<ll, ll>> Q;
	Q.push({zipped.front().first, 0});
	while (!Q.empty()) {
		ll node = Q.front().first;
		ll dist = Q.front().second;
		Q.pop();

		// 訪問済みとする。距離を入れる
		ans[node] = dist;

		// 隣接ノードを洗い出して、未訪問のみキューに入れる。
		for (const ll u : V[node]) {
			if (ans[u] != -1) continue;
			Q.push({u, dist + 1});
		}
	}
	// 例外処理。
	auto reigai = count_if(ALL(S), [](auto c) {return c == '1'; });
	if (reigai == 1) {
		cout << 0 << endl;
		return 0;
	}
	// 距離を合計する
	ll sum = 0;
	for (size_t i = 0; i < S.size(); i++) {
		if (S[i] == '1') {
			sum += ans[i];
		}
	}
	if (sum % 2 == 1) {
		cout << -1 << endl;
		return 0;
	}

	cout << sum / 2 << endl;

	return 0;
}

