using namespace std;

const int maxn = 2005;

int n;
string s;
vector<int> g[maxn];

int count[maxn];
int low[maxn], high[maxn];

void dfs_solve(int v, int p) {
  count[v] = (s[v] == '1');

  if(p != -1 && g[v].size() == 1) {
    low[v] = high[v] = 0;
    return;
  }

  vector<int> ts;

  int least = 0, odd = 0;

  high[v] = 0;
  for(int s : g[v]) if(s != p) {
    dfs_solve(s, v);
    count[v] += count[s];
    int a = low[s] + count[s], b = high[s] + count[s];
    high[v] += b;
    least = max(least, a);
    odd ^= (a & 1);
    ts.push_back(b);
  }


  sort(ts.begin(), ts.end());

  if(ts.size() == 1) {
    low[v] = least;
    return;
  }

  low[v] = 1e9;

  int leastcost = 0;
  for(int x : ts) {
    int y = min(x, least);
    if(x > least && x % 2 != least % 2) y--;
    leastcost += y;
  }



  int sum_smaller = 0, countodd = 0, counteven = 0;
  for(int x : ts) {
    if(x % 2 == 0) ++counteven;
    else ++countodd;
  }


  if(least * 2 <= leastcost) low[v] = min(low[v], odd);
  else low[v] = min(low[v], least * 2 - leastcost);

  for(int i = 0; i < ts.size(); ++i) {
    sum_smaller += ts[i];
    if(ts[i] % 2) --countodd;
    else --counteven;
    if(ts[i] < least || (i + 1 < ts.size() && ts[i + 1] == ts[i])) continue;

    int sum = sum_smaller + (ts[i] - 1) * (countodd + counteven);
    if(ts[i] % 2) sum += countodd;
    else sum += counteven;

    if(ts[i] * 2 <= sum) low[v] = min(low[v], odd);
    else low[v] = min(low[v], ts[i] * 2 - sum);
  }


  if(low[v] % 2 != high[v] % 2) {
    cout << v << endl;
  }

//  assert(low[v] % 2 == high[v] % 2);
//  assert(low[v] <= high[v]);
}

