    g[--u].emplace_back(--v);
    g[v].emplace_back(u);
  }

  int ans = 1e9 + 7;
  for(int root = 0; root < n; ++root) {
    dfs_solve(root, -1);

    if(low[root] == 0) {

      ans = min(ans, high[root] / 2);
    }
  }

  cout << (ans > 1e9 ? -1 : ans) << endl;

  return 0;
}

