int Traverse(int v, int p, int lvl)
{
    int res = 0;
    if (str[v] == '1') res += lvl;
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (u == p) continue;
        res += Traverse(u, v, lvl + 1);
    }
    return res;
}

int Traverse2(int v, int p, int lvl)
{
    int res = 0;
    if (str[v] == '1') res++;
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (u == p) continue;
        res += Traverse2(u, v, lvl + 1);
    }
    return res;
}

