        neigh[a].push_back(b);
        neigh[b].push_back(a);
    }
    for (int i = 1; i <= n; i++) {
        vector <int> seq;
        for (int j = 0; j < neigh[i].size(); j++)
            seq.push_back(Traverse(neigh[i][j], i, 1));
        sort(seq.begin(), seq.end());
        int ans = 0;
        for (int j = 0; j < seq.size(); j++)
            ans += seq[j];
        if (ans % 2) continue;
        int sum = 0;
        for (int j = 0; j + 1 < seq.size(); j++)
            sum += seq[j];
        if (sum < seq.back()) continue;
        int cand = ans / 2;
        seq.clear();
        for (int j = 0; j < neigh[i].size(); j++)
            seq.push_back(Traverse2(neigh[i][j], i, 1));
        sort(seq.begin(), seq.end());
        sum = 0;
        for (int j = 0; j + 1 < seq.size(); j++)
            sum += seq[j];
        if (sum >= seq.back())
            res = min(res, cand);
    }
    printf("%d\n", res >= Inf? -1: res);
    return 0;
}

