		REPI2(itr, range.first, range.second) {
			ll to = itr->second;
			if (!use[to]) {
				use[to] = true;
				q.emplace(to, l + 1);
			}
		}
	}
	return sum;
}

list<ll> getst(ll n, ll f, const string & s, const unordered_multimap<ll, ll> & graph) {
	list<ll> ans;
	auto range = graph.equal_range(f);
	REPI2(itr, range.first, range.second) {
		auto p = getsum(n, itr->second, s, graph, f);
		if (p > 0) {
			ans.emplace_back(p);
		}
	}

	return ans;
}

signed main() {
	ll n;
	string s;
	cin >> n >> s;

	unordered_multimap<ll, ll> graph;
	REP(_, n - 1) {
		ll a, b;
		cin >> a >> b;
		--a; --b;
		graph.emplace(a, b);
		graph.emplace(b, a);
	}

	ll ans = 1e5;
	REP(from, n) {
		auto st = getst(n, from, s, graph);
		if (st.size() == 0) {
			cout << 0 << endl;
			return 0;
		}


		priority_queue<ll> q;
		REPC(x, st) {
			q.emplace(x);
		}


		ll cnt = 0;
		while (q.size() > 1) {
			ll a = q.top();
			q.pop();
			ll b = q.top();
			q.pop();
			if (a - 1 > 0) {
				q.push(a - 1);
			}
			if (b - 1 > 0) {
				q.push(b - 1);
			}
			++cnt;
		}
		if (q.size() == 0) {
			MIN(ans, cnt);
		}

	}
	cout << ((ans < 1e4) ? ans : -1) << endl;

}

