	size[x] = s[x] == '1';
	tot[x] = 0;
	vector<pii> Q;
	for (auto y : v[x])
	{
		if (y == p) continue;
		dis[y] = dis[x]+1;
		dfs(y, x);
		size[x] += size[y];
		tot[x] += tot[y]+size[y];
		Q.push_back({F[y]+size[y], tot[y]+size[y]});
	}
	if (Q.size() >= 2)
	{
		sort(Q.begin(), Q.end());
		reverse(Q.begin(), Q.end());
		int sum = 0;
		for (int i = 1; i < Q.size(); ++ i)
			sum += Q[i].X;
		if (Q[0].X > sum)
		{
			int tmp = Q[0].X-sum;
			for (int i = 1; i < Q.size(); ++ i)
			{
				tmp -= Q[i].Y-Q[i].X;
				tmp = max(tmp, (Q[0].X+sum)%2);
			}
			F[x] = tmp;
		}
		else
		{
			if ((Q[0].X+sum)%2 == 0)
				F[x] = 0;
			else
			{
				F[x] = 1;
			}
		}
	}
	else if (Q.size() == 1)
		F[x] = Q[0].X;
	else
		F[x] = 0;
}

