void solve() {
    int n; cin >> n;
    string s; cin >> s;
    vector<vector<int>> g(n);
    for (int _ = 1; _ < n; _++) {
        int x,y;
        cin >> x >> y;
        x--;y--;
        g[x].emplace_back(y);
        g[y].emplace_back(x);
    }

    vector<int> dp(n), sd(n), sz(n);
    function<void(int,int)> dfs = [&](int u, int p){
        sz[u] = s[u]-'0';
        sd[u] = 0;
        int mx = 0, mi = 0;
        for (int v: g[u])if(v!=p){
            dfs(v, u);
            sz[u] += sz[v];
            sd[u] += (sd[v] += sz[v]);
            dp[v] += sz[v];
            if (mx < dp[v]) {
                mx = dp[v]; mi = sd[v];
            } else if (mx == dp[v]) {
                mi = min(mi, sd[v]);
            }
        }
        if (mx <= sd[u] - mi) dp[u] = sd[u]&1;
        else dp[u] = mx + mi - sd[u];
    };

    int res = 1<<28;
    for (int i = 0; i < n; i++) {
        dfs(i,-1);
        if (dp[i] == 0) {
            res = min(res, sd[i]/2);
        }
    }
    if (res == 1<<28) res = -1;
    cout << res;
}

