void dfs(int n,int m){
    for(auto x:v[n]){
        if(x==m) continue;
        dist[x] = dist[n]+1;
        dfs(x,n);
        s[n] += s[x];
    }
    if(S[n]=='1') s[n]++;
}

void dfs2(int n,int m){
    int sum = 0;
    for(auto x:v[n]){
        if(x==m) continue;
        dfs2(x,n);
        sum += dp_max[x]+s[x];
        dp_max[n] += dp_max[x]+s[x];
    }
    for(auto x:v[n]){
        if(x==m) continue;
        dp_min[n] = max(dp_min[n],dp_min[x]+s[x]-(sum-dp_max[x]-s[x]));
    }
    if(dp_min[n]<0) dp_min[n] = (dp_min[n]%2==0? 0:1);
}

