int N, A[1 << 12], B[1 << 12], S[1 << 12], T, dist[1 << 12], dp[1 << 12], distsum[1 << 12];
vector<int> X[1 << 12], Y[1 << 12];

void dfs(int pos, int dep) {
	dist[pos] = dep;
	if (S[pos] == 1) { dp[pos] = 1; distsum[pos] = dep; }

	for (int i = 0; i < X[pos].size(); i++) {
		if (dist[X[pos][i]] >= 0) continue;

		Y[pos].push_back(X[pos][i]);
		dfs(X[pos][i], dep + 1);
		dp[pos] += dp[X[pos][i]];
		distsum[pos] += distsum[X[pos][i]];
	}
}

void dfs2(int pos) {
	for (int i = 0; i < Y[pos].size(); i++) dfs2(Y[pos][i]);

	if (Y[pos].size() >= 1) {
		vector<int> P; int ss = 0;
		for (int i = 0; i < Y[pos].size(); i++) {
			int val = distsum[Y[pos][i]] - dist[pos] * dp[Y[pos][i]];
			P.push_back(val);
			ss += val;
		}
		T += min(ss / 2, ss - P[P.size() - 1]) * 2;
	}
}

int solve(int root) {
	for (int i = 1; i <= N; i++) { dist[i] = -1; dp[i] = 0; distsum[i] = 0; Y[i].clear(); }
	dfs(root, 0);

	vector<pair<int, int> > vec; int rem = 0;
	for (int i = 0; i < Y[root].size(); i++) {
		vec.push_back(make_pair(distsum[Y[root][i]], Y[root][i]));
		rem += distsum[Y[root][i]];
	}
	sort(vec.begin(), vec.end());

	if (rem % 2 == 1) return (1 << 30);

	if (rem >= vec[vec.size() - 1].first * 2) return rem / 2;

	T = 0;
	dfs2(vec[vec.size() - 1].second);

	int Z1 = rem - vec[vec.size() - 1].first;
	int Z2 = vec[vec.size() - 1].first - T;
	if (Z1 < Z2) return (1 << 30);
	return rem / 2;
}

int main() {
	cin >> N;
	for (int i = 1; i <= N; i++) { char c; cin >> c; if (c == '1') S[i] = 1; }
	for (int i = 1; i <= N - 1; i++) {
		cin >> A[i] >> B[i];
		X[A[i]].push_back(B[i]);
		X[B[i]].push_back(A[i]);
	}
	int ans = (1 << 30);
	for (int i = 1; i <= N; i++) {
		ans = min(ans, solve(i));
	}
	if (ans == (1 << 30)) cout << "-1" << endl;
	else cout << ans << endl;
	return 0;
}

