const int Maxn = 2005;
const int Inf = 1000000000;

int n;
char str[Maxn];
vector <int> neigh[Maxn];
int res = Inf;

int Traverse(int v, int p, int lvl)
{
    int res = 0;
    if (str[v] == '1') res += lvl;
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (u == p) continue;
        res += Traverse(u, v, lvl + 1);
    }
    return res;
}

int main()
{
    scanf("%d", &n);
    scanf("%s", str + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b; scanf("%d %d", &a, &b);
        neigh[a].push_back(b);
        neigh[b].push_back(a);
    }
    for (int i = 1; i <= n; i++) {
        vector <int> seq;
        for (int j = 0; j < neigh[i].size(); j++)
            seq.push_back(Traverse(neigh[i][j], i, 1));
        sort(seq.begin(), seq.end());
        int ans = 0;
        for (int j = 0; j < seq.size(); j++)
            ans += seq[j];
        if (ans % 2) continue;
        int sum = 0;
        for (int j = 0; j + 1 < seq.size(); j++)
            sum += seq[j];
        if (sum >= seq.back())
            res = min(res, ans / 2);
    }
    printf("%d\n", res >= Inf? -1: res);
    return 0;
}

