    for (int to : g[v]) {
        if (to != p) {
            ans += dfs1(to, v, h + 1);
        }
    }
    return ans;
}

pair<int, int> dfs2(int v, int p) {
    int sm = 0, mx = 0;
    int vs = 0;
    for (int to : g[v]) {
        if (to != p) {
            auto g = dfs2(to, v);
            sm += g.first + g.second;
            mx = max(mx, g.first + g.second);
            vs += g.second;
        }
    }
    int rm = sm - sm % 2;
    if (mx > sm - mx) {
        rm = 2 * (sm - mx);
    }
    return {sm - rm, vs + a[v]};
}

