public:
    int N;
    vector<vector<edge>> G;
    vec S;
    vec num, cnt;

    Graph(int N, string s): N(N){
        G = vector<vector<edge>>(N, vector<edge>(0));
        S.resize(N);
        REP(i, N){
            if(s[i] == '1') S[i] = 1;
            else S[i] = 0;
        }
        cnt.resize(N);
        num.resize(N);
    }

    void add_Directed_edge(int from, int to, int cost = 1, int id = 0){
        G[from].push_back(edge({to, cost, id}));
    }

    void add_Undirected_edge(int v1, int v2, int cost = 1, int id = 0){
        add_Directed_edge(v1, v2, cost, id);
        add_Directed_edge(v2, v1, cost, id);
    }

    void dfs(int v, int p = -1){
        num[v] = S[v];
        cnt[v] = 0;
        for(auto e: G[v]) if(e.to != p){
            dfs(e.to, v);
            num[v] += num[e.to];
            cnt[v] += cnt[e.to] + num[e.to];
        }
    }

    void dfs2(int v, int p = -1){
        int M = 0, i = -1;
        for(auto e: G[v]) if(e.to != p){
            if(cnt[e.to] + num[e.to] > M){
                M = cnt[e.to] + num[e.to];
                i = e.to;
            }
        }
        if(M > 0){
            dfs2(i, v);
            int tot = cnt[i] + num[i];
            for(auto e: G[v]) if(e.to != p && e.to != i){
                tot -= cnt[e.to] + num[e.to];
            }
            cnt[v] = max(tot, cnt[v] % 2);
        }
    }

};

