void chemthan() {
    int n; cin >> n;
    string s; cin >> s;
    vector<vi> adj(n);
    FOR(i, 0, n - 1) {
        int u, v; cin >> u >> v; u--, v--;
        adj[u].pb(v), adj[v].pb(u);
    }
    vi d(n), g(n);
    function<pi(int, int)> dfs = [&] (int u, int p) {
        g[u] = 0;
        int res = 0;
        if (s[u] == '1') g[u] = 1, res = d[u];
        vi vals, vals2;
        for (int v : adj[u]) {
            if (v ^ p) {
                d[v] = d[u] + 1;
                pi e = dfs(v, u);
                vals.pb(e.fi + g[v]), vals2.pb(e.se - d[u]), res += e.se;
                g[u] += g[v];
            }
        }
        if (sz(vals)) {
            int sum = 0;
            FOR(i, 0, sz(vals2)) {
                sum += vals2[i] - d[u];
            }
            int total = 0, mx = 0;
            FOR(i, 0, sz(vals)) {
                if (vals[i] <= sum - vals2[i]) {
                    total++;
                }
                chkmax(mx, max(sum % 2, vals[i] - (sum - vals2[i])));
            }
            if (total == sz(vals)) {
                return mp(sum % 2, res);
            }
            else {
                return mp(mx, res);
            }
        }
        return mp(0, res);
    };
    int res = INF;
    FOR(u, 0, n) {
        d[u] = 0;
        if (!dfs(u, -1).fi) {
            int sum = 0;
            FOR(v, 0, n) if (s[v] == '1') {
                sum += d[v];
            }
            chkmin(res, sum / 2);
        }
    }
    if (res == INF) res = -1;
    cout << res << "\n";
}

