struct ctx {
	ll l = 0, sm = 0, sz = 0;
	vector<ctx> c;
	void add(ctx a) { c.pb(a); }
	void process(int f, int rt) {
		sz = 0;
		ll msm = 0;
		vi csm;
		vi cl;
		for(auto &i : c) {
			sz += i.sz;
			sm += i.sm;
			l += i.l;
			msm = max(msm, i.sm);

			cl.pb(i.l);
			csm.pb(i.sm);
		}
		if(2*msm <= sm) l = sm&1;
		else {
			l = min(l, 2*msm - sm);
			sort(all(csm));
			sort(all(cl));
			int j = 0;
			ll ts = 0, s;
			for(auto i : cl) {
				while(j < csm.size() && csm[j] < i) ts += csm[j++];
				s = ts + (csm.size()-j)*1ll*i - i;
				if(2*i <= s && i >= msm) {l = sm&1; break;}
			}
		}
		sz += f;
		//cout << l << " " << sm << " " << sz << "\n";
		if(!rt) {
			sm += sz;
			l += sz;
		}
c.clear();
		//cout << l << " " << sm << " " << sz << "\n";
	}
};
