vector<int> adj[2000];

int n, sum;
string s;

pair<int, int> dfs(int i, int p) {
    vector<int> ss;
    int S = 0, K = 0, smax = 0;
    for (int j : adj[i]) {
        if (j == p) continue;
        auto r = dfs(j, i);
        ss.push_back(r.first + r.second);
        S += r.first + r.second;
        K += r.second;
        smax = max(smax, r.first + r.second);
    }
    int K1 = s[i] == '1' ? K+1 : K;
    if (S >= 2 * smax) { sum += S / 2; return { S % 2, K1  }; }
    else {
        int x = S - smax;
        sum += x;
        return { S - 2 * x, K1 };
    }
}

