void dfs(int v) {
    cnt[v] = 0;
    dist[v] = 0;
    int max_d = -1, max_i;
    int ccnt = 0;
    rep(i,e[v].size()) {
        if (e[v][i] == par[v]) continue;
        ccnt++;
        par[e[v][i]] = v;
        dfs(e[v][i]);
        cnt[v] += cnt[e[v][i]];
        dist[v] += dist[e[v][i]] + cnt[e[v][i]];
        if (max_d < dist[e[v][i]] + cnt[e[v][i]]) {
            max_d = dist[e[v][i]] + cnt[e[v][i]];
            max_i = e[v][i];
        }
    }
    if (str[v] == '1') cnt[v]++;
    if (ccnt == 0) {
        dp[v] = 0;
        return;
    }
    int oth_d = dist[v] - max_d;
    if (max_d > oth_d) {
        dp[v] = oth_d + min((max_d-oth_d)/2, dp[max_i]);
    } else {
        dp[v] = dist[v] / 2;
    }
}

