int n;
bool val[N];
struct Edge {
	int v, nxt;
} edge[N];
int head[N], tot = 1;
int dis[N], f[N], sze[N];

inline void addedge(int u, int v) {
	edge[++tot].v = v, edge[tot].nxt = head[u], head[u] = tot;
}

inline void insedge(int u, int v) { addedge(u, v), addedge(v, u); }

inline void init() {
	memset(dis, 0, sizeof(dis));
	memset(f, 0, sizeof(f));
}

inline void dfs(int u, int fa) {
	int mx = 0; sze[u] = val[u];
	for(register int i = head[u]; i; i = edge[i].nxt) {
		int v = edge[i].v;
		if(v == fa) continue;
		dfs(v, u);
		sze[u] += sze[v], dis[v] += sze[v], dis[u] += dis[v];
		if(dis[v] > dis[mx]) mx = v;
	}
	if(!mx) { f[u] = 0; return; }
	if(dis[mx] * 2 < dis[u]) f[u] = dis[u] / 2;
	else f[u] = dis[u] - dis[mx] + min(f[mx], dis[mx] * 2 - dis[u]);
}

