			for(int i:vec[node]){
				if(!used[i]){
					f(f,i);
					c[node]+=c[i];
				}
			}
		})(i);
		std::fill(used,used+n,false);
		int cnt=0;
		if(!fix([&](auto f,int node)->int{
			used[node]=true;
			int max=0,res=0;
			for(int j:vec[node]){
				if(!used[j]){
					int k=f(f,j);
					res+=k;
					chmax(max,k);
				}
			}
			if(res-max<max){
				cnt+=res-max;
				res=max-(res-max);
			}
			else{
				cnt+=res/2;
				res%=2;
			}
			if(node!=i)res+=c[node];
			return res;
		})(i))chmin(ans,cnt);
	}
	if(ans!=INF)std::cout<<ans<<std::endl;
	else std::cout<<-1<<std::endl;
	return 0;
}

