vector<ll> c;


T dfs(ll now, ll root, ll dist) {
	visited[now] = true;
	ll okstone = 0;
	ll ans = dist * c[now];
	ll top = 0;
	ll sum = 0;
	ll restiikanji = 0;
	ll topiikanji = 0;
	ll totalstone = c[now];
	for (auto &&e : es[now]) {
		if (!visited[e]) {
			ll one, ok, step, total;
			tie(one, ok, step, total) = dfs(e, root, dist + 1);
			totalstone += total;
			ans += step;
			okstone += ok;
			if (top < one) {
				sum += top;
				restiikanji = topiikanji;
				top = one;
				topiikanji = ok;
			}
			else {
				restiikanji += ok;
				sum += one;
			}
		}
	}
	ll iikanji;
	if (top <= sum + restiikanji) {
		iikanji = (sum + top) - ((sum + top) % 2);
	}
	else
		iikanji = sum * 2 + restiikanji;
	if (now == root) {
		if (sum + top - iikanji == 0)
			return T(ans, 0, 0, 0);
		else
			return T(INF, 0, 0, 0);
	}
	return T(sum + top - iikanji + totalstone, okstone + iikanji, ans, totalstone);
}

