template <class T = ll> T read()
{
	T f = 1, a = 0;
	char ch = getchar() ;
	while (!isdigit(ch)) { if (ch == '-') f = -1 ; ch = getchar() ; }
	while (isdigit(ch)) { a =  (a << 3) + (a << 1) + ch - '0' ; ch = getchar() ; }
	return a * f ;
}

int n;

char s[maxn];

vi edge[maxn];

int ans = linf;

int sum[maxn], f[maxn];

void dfs(int now, int fa)
{
	sum[now] = s[now] == '1', f[now] = 0;
	for(int to : edge[now])
	{
		if(to == fa) continue;
		dfs(to, now);
		sum[now] += sum[to], f[now] += f[to] + sum[to];
	}
}

int check(int now, int fa)
{
	int pos = 0;
	for(int to : edge[now])
	{
		if(to == fa) continue;
		if(f[to] > f[pos]) pos = to;
	}
	if(!pos) return 0;
	int tmp = check(pos, now) + sum[pos];
	if(f[now] - f[pos] - sum[pos] >= tmp) return f[now] & 1;
	return tmp - (f[now] - f[pos] - sum[pos]);
}

signed main()
{
	n = read();
	scanf("%s", s + 1);
	rep(i, 1, n - 1)
	{
		int u = read(), v = read();
		edge[u].pb(v), edge[v].pb(u);
	}
	rep(i, 1, n)
	{
		dfs(i, 0);
		if(!check(i, 0)) ans = min(ans, f[i] >> 1);
	}
	printf("%lld\n", ans == linf ? -1 : ans);
	return 0;
}

