ll N;
vector<vector<ll>> g;
vector<ll> A;

vector<ll> token;

void tokendfs(ll u, ll v) {
	token[v] += A[v];

	for (ll w : g[v]) {
		if (u == w) { continue; }
		tokendfs(v, w);
		token[v] += token[w];
	}

	return;
}

pair<ll, ll> dfs(ll u, ll v) {
	//cout << u << " " << v << endl<<flush;
	vector<ll> mx;
	vector<ll> mn;

	for (ll w : g[v]) {
		if (u == w) { continue; }
		auto p = dfs(v, w);

		mx.push_back(p.first + token[w]);
		mn.push_back(p.second + token[w]);
	}

	ll M = mx.size();
	//cout << M << endl << flush;
	ll fst = 0;
	rep(i, M) fst += mx[i];

	ll snd = 0;
	rep(i, M) {
		snd = max(snd, -fst + mx[i] + mn[i]);
	}

	if (snd == 0) { if (fst % 2 == 1) { snd = 1; } }

	return { fst,snd };
}


int main() {
	cin >> N;
	A.assign(N + 1, 0);

	string S;
	cin >> S;
	repn(i, N) { A[i] = S[i - 1] - '0'; }

	g.resize(N + 1);
	repn(i, N - 1) {
		ll a, b;
		cin >> a >> b;
		g[a].push_back(b);
		g[b].push_back(a);
	}


	ll ans = INF;

	repn(v, N) {
		token.assign(N + 1, 0);
		tokendfs(0, v);

		//repn(w, N) cout << token[w] <<endl<< flush;

		auto p = dfs(0, v);

		if (p.second == 0) { ans = min(ans, p.first / 2); }
	}

	if (ans == INF) { ans = -1; }
	cout << ans << endl;
}

