P dfs(ll x,ll from,ll dep){
  ll cnt=(s[x-1]=='1'),sum=dep*cnt;
  for(auto y:g[x])if(y!=from){
    P cur=dfs(y,x,dep+1);
    cnt+=cur.first;
    sum+=cur.second;
  }
  return make_pair(cnt,sum);
}
ll solve(ll t){
  ll sum=0,ma=0,len=0;
  for(auto y:g[t]){
    P cur=dfs(y,t,1);
    sum+=cur.first;
    ma=max(ma,cur.first);
    len+=cur.second;
  }
  //cout<<t<<":"<<len<<" "<<sum<<" "<<ma<<endl;
  if(len%2==1||ma*2>sum)return -1;
  return len/2;
}
