ll cost(ll v, ll p = -1, ll h = 0) {
	ll res = (s[v]-'0')*h;
	for(auto &i : g[v]) if(i != p) res += cost(i, v, h+1);
	return res;
}
void go(int i) {
	ll t = check(i).l == 0 ? cost(i) : 1ll<<60;
	ans = min(t, ans);
