tlglglg dfs(int p, int par, int rank) {
    ll sum = 0;
    ll nums = 0;
    priority_queue<ll> que;
    ll cnt = 0;
    REP(i, 0, G[p].size()) {
        edge e = G[p][i];
        if (e.to != par) {
            tlglglg pp = dfs(e.to, p, rank + 1);
            ll num = get<0>(pp);
            sum += num;
            if (num != 0) {
                que.push(num);
            }
            cnt += get<1>(pp);
            nums += get<2>(pp);
        }
    }
    while (que.size() >= 2) {
        ll quep = que.top();
        que.pop();
        ll queq = que.top();
        que.pop();
        cnt++;
        sum -= 2;
        quep--;
        queq--;
        if (quep > 0) {
            que.push(quep);
        }
        if (queq > 0) {
            que.push(queq);
        }
    }
    sum += nums;
    if (bo[p]) {
        sum++;
        nums++;
    }
    return tlglglg(sum, cnt, nums);
}

