}

void dfs(int x, int f = 0) {
	int M = 0, S = 0;
	size[x] = s[x] == '1';
	for (int i = head[x]; i; i = e[i].nxt) if (e[i].to != f) {
		dfs(e[i].to, x), sum[e[i].to] += size[e[i].to];
		size[x] += size[e[i].to];
		M = std::max(M, sum[e[i].to]), S += sum[e[i].to];
	}
	if (M * 2 <= S) ret += S >> 1, sum[x] = S & 1;
	else ret += S - M, sum[x] = M - (S - M);
}



