int main() {
  cin.tie(0); cin.sync_with_stdio(false);
  long long n; string str;
  cin >> n >> str;
  vector<bool> s(n);
  for (long long i = 0; i < n; i++) {
    s[i] = str[i] - '0';
  }
  vector<vector<long long>> grh(n);
  for (long long i = 0; i < n - 1; i++) {
    long long s, t;
    cin >> s >> t;
    grh[--s].push_back(--t);
    grh[t].push_back(s);
  }
  vector<long long> dp(n, 0);
  vector<long long> sz(n, 0);
  fix ([&](auto dfs, long long crr, long long prt) -> void {
    if (s[crr]) sz[crr]++;
    for (auto const& nxt : grh[crr]) if (nxt != prt) {
      dfs(nxt, crr);
      sz[crr] += sz[nxt];
      dp[crr] += dp[nxt] + sz[nxt];
    }
  })(0, 0);
  long long full_sz = sz[0];
  vector<long long> ep(n, 0);
  vector<long long> tz(n, 0);
  tz[0] = s[0];
  fix ([&](auto dfs, long long crr, long long prt) -> void {
    tz[crr] = full_sz - sz[crr] + s[crr];
    long long sum = 0;
    for (auto const& nxt : grh[crr]) if (nxt != prt) {
      sum += dp[nxt] + sz[nxt] * 2;
    }
    for (auto const& nxt : grh[crr]) if (nxt != prt) {
      ep[nxt]
        = ep[crr] + tz[crr]
        + sum
        - (dp[nxt] + sz[nxt] * 2);
      dfs(nxt, crr);
    }
  })(0, 0);
  constexpr long long inf = 1LL << 60;
  long long ret = inf;
  fix ([&](auto dfs, long long crr, long long prt) -> void {
    long long dpt_sum = dp[crr] + ep[crr];
    if (dpt_sum % 2 == 0) {
      long long X = dpt_sum / 2;
      bool ng = false;
      for (auto const& nxt : grh[crr]) if (nxt != prt) {
        if (dp[nxt] + sz[nxt] > X) ng = true;
      }
      if (ep[crr] > X) ng = true;
      if (!ng) {
        cmn(ret, X);
      }
    }
    for (auto const& nxt : grh[crr]) if (nxt != prt) {
      dfs(nxt, crr);
    }
    for (auto const& nxt : grh[crr]) if (nxt != prt) {
      dfs(nxt, crr);
    }
  })(0, 0);
  cout << (ret == inf ? -1 : ret) << endl;
  return 0;

}

