void dfs(int u, int fa, int dis){
	sz[u] = 0; int tmp = sum, mson = 0, mx = 0, lst = sum;
	for(int i = fir[u]; i; i = e[i].nxt){
		int v = e[i].to; if(v == fa) continue;
		dfs(v, u, dis + 1);
		if(sum - lst > mx) mson = v, mx = sum - lst;
		lst = sum; sz[u] += sz[v];
	}
	tmp = sum - tmp - dis * sz[u]; mx -= dis * sz[mson];
	if(tmp - mx >= mx) f[u] = tmp / 2;
	else f[u] = tmp - mx + min(f[mson], (2 * mx - tmp) / 2);
	int p = s[u] - '0'; sz[u] += p; sum += p * dis;
	return ;
}

