void dfs(int x, int pre) {
  size[x] = s[x] - '0';
  dis[x] = 0;
  for (auto y : G[x]) if (y != pre) {
    dfs(y, x);
    size[x] += size[y];
    dis[x] += dis[y] + size[y];
  }
}
bool dfs2(int x, int pre, int d) {
  if (!d) return true;
  if (d > dis[x]) return false;
  int mx = -1, mp = 0;
  for (auto y : G[x]) if (y != pre) {
    if (dis[y] + size[y] > mx) {
      mx = dis[y] + size[y];
      mp = y;
    }
  }
  int my = dis[x] - mx;
  if (my >= mx || 2 * my >= d) return true;
  return dfs2(mp, x, d - 2 * my);
}

