      if (son.back() > sum / 2) {
        remain[u] = (son.back() - sum / 2) * 2;
        res += (sum - remain[u] / 2) / 2;
      } else {
        res += sum / 2;
      }
      if (u == root && remain[u]) {
        return INT_MAX;
      }
      remain[u] += str[u] == '1';
      return res;
    };
    ans = min(ans, dfs(root, -1));
