char S[2048];
int n, fir[2048], nex[4096], tar[4096], cnt;
void Add(int u, int v)
{
	++cnt;
	tar[cnt] = v;
	nex[cnt] = fir[u];
	fir[u] = cnt;
}
int f[2048], g[2048], siz[2048];
void Dfs(int u, int fa)
{
	f[u] = g[u] = 0;
	siz[u] = S[u] - '0';
	for (int i = fir[u]; i; i = nex[i])
	{
		int v = tar[i];
		if (v == fa)
			continue;
		Dfs(v, u);
		siz[u] += siz[v];
		int l1 = f[v] + siz[v];
		int r1 = g[v] + siz[v];
		int l2 = f[u], r2 = g[u];
		g[u] = r1 + r2;
		if (l2 > r1)
			f[u] = l2 - r1;
		else
			if (l1 > r2)
				f[u] = l1 - r2;
			else
				f[u] = (g[u] & 1);
	}
}
