struct Elem {
    int acc = 0, mini = 0, num = 0;
    bool operator < (const Elem& e) const {
        return pair<int, int>(acc, mini) < pair<int, int>(e.acc, e.mini);
        // return tie(acc, mini, num) < tie(e.acc, e.mini, e.num);
    }
};

struct Graph{
    struct Node{
        vector<int> dests;
        int num;
    };
    vector<Node> nodes;
    Graph(int num): nodes(num){ }
    int id(Node* n){ return n - &nodes[0]; }
    int id(Node& n){ return &n - &nodes[0]; }
    void print(){ for(auto& node : nodes){ prints(id(node), node.dests); } }
    void add1Edge(int from, int dest){
        nodes[from].dests.push_back(dest);
    }
    void add2Edge2(int from, int dest){
        add1Edge(from, dest);
        add1Edge(dest, from);
    }
    Elem dfs(int idx, int from){
        Elem ret = {};
        vector<Elem> nums;
        for(int didx : nodes[idx].dests){
            if(didx == from){ continue; }
            auto r = dfs(didx, idx);
            nums.push_back(r);
            ret.acc += r.acc;
            ret.num += r.num;
        }
        if(nums.empty()){
            return {nodes[idx].num, nodes[idx].num, nodes[idx].num};
        }
        sort(nums.begin(), nums.end());
        ret.mini = ret.num + nodes[idx].num;
        ret.mini += max(ret.acc % 2, nums.back().mini - (ret.acc -nums.back().acc + 0 - 0));
        ret.num += nodes[idx].num;
        ret.acc += ret.num;
        // ret.acc += nodes[idx].num;
        return ret;
    }
};

