void dfs_solve(int v, int p) {
  count[v] = (s[v] == '1');

  if(p != -1 && g[v].size() == 1) {
    low[v] = high[v] = 0;
    return;
  }

  vector<int> ts;

  int least = 0, odd = 0;

  high[v] = 0;
  for(int s : g[v]) if(s != p) {
    dfs_solve(s, v);
    count[v] += count[s];
    int a = low[s] + count[s], b = high[s] + count[s];
    high[v] += b;
    least = max(least, a);
    odd ^= (a & 1);
    ts.push_back(b);
  }

  sort(ts.begin(), ts.end());

  low[v] = 1e9;
  int sum_smaller = 0, count_greater = ts.size();
  for(int i = 0; i < ts.size(); ++i) {
    sum_smaller += ts[i];
    --count_greater;
    if(ts[i] < least || (i + 1 < ts.size() && ts[i + 1] == ts[i])) continue;
    int sum = sum_smaller + count_greater * ts[i];
    if(ts[i] * 2 <= sum) low[v] = min(low[v], odd);
    else low[v] = min(low[v], ts[i] * 2 - sum);
  }
}

