const int N = 2020;
int n, pre[N], tail[N], k, size[N], dis[N], dp[N];
struct node {
	int next, to;
}mp[N << 2];

void Maketo(int from, int to) {
	mp[++k].next = tail[from];
	mp[k].to = to;
	tail[from] = k; 
	return ;
}

void Dfs(int x, int fa) {
	size[x] = pre[x];
	dis[x] = dp[x] = 0;
	int maxn = 0;
	for (int i = tail[x]; i; i = mp[i].next) {
		int y = mp[i].to;
		if(y == fa) continue;
		Dfs(y, x);
		size[x] += size[y];
		dis[y] += size[y];
		dis[x] += dis[y];
		if(!maxn || dis[maxn] < dis[y])
			maxn = y;
	}
	if(!maxn) return ;
	if(dis[x] - dis[maxn] >= dis[maxn]) dp[x] = dis[x] / 2;
	else dp[x] = dis[x] - dis[maxn] + min(dp[maxn] * 2, 2 * dis[x] - dis[maxn]) / 2;
	return ;
}

