void DFS(int x, int p)
{
    int i, k;
    vector<pair<int, int> > t;

    v[x] = 0;
    s[x] = a[x] == '1';
    for(i = 0; i < (signed)e[x].size(); i ++)
        if(e[x][i] != p)
        {
            DFS(e[x][i], x);
            s[x] += s[e[x][i]];
            v[x] += v[e[x][i]] + s[e[x][i]];
            t.push_back(make_pair(v[e[x][i]] + s[e[x][i]], e[x][i]));
        }

    f[x] = 0;
    if(!t.empty())
    {
        sort(t.begin(), t.end());
        for(i = k = 0; i < (signed)t.size() - 1; i ++)
            k += t[i].first;
        if(k >= t.back().first)
            f[x] = v[x] / 2;
        else
            f[x] = k + min(f[t.back().second], (t.back().first - k) / 2);
    }

    return;
}

int main(void)
{
