        e[   v].push_back(   u);
    }

    for(i = 0, v = INT_MAX; i < n; i ++)
    {
        DFS(i, i);
        // printf("at %d : sum %d, f %d\n", i, ::v[i], f[i]);
        if(~::v[i] & 1 && f[i] * 2 >= ::v[i])
            v = min(v, ::v[i] / 2);
    }
    printf("%d\n", v == INT_MAX ? -1 : v);

    return 0;
}

