#define MAX 2002

int n;

char buf[MAX];
string s;

vector<int> v[MAX];

long long int dp_max[MAX];
long long int dp_min[MAX];
long long int child[MAX];



inline void dfs(int b,int pr=-1){
	child[b]=0;
	dp_max[b]=0;
	dp_min[b]=0;
	if(s[b]=='1'){
		child[b]++;
	}
	vector<pair<long long int,long long int> > mi;
	mi.push_back(make_pair(0LL,0LL));
	for(int go:v[b]){
		if(go==pr)continue;
		dfs(go,b);
		child[b]+=child[go];
		dp_max[b]+=dp_max[go]+child[go];
		mi.push_back(make_pair(dp_min[go]+child[go],-dp_max[go]));
	}
	sort(mi.begin(),mi.end());
	reverse(mi.begin(),mi.end());
	for(int j=0;j<mi.size();j++){
		mi[j].second*=-1LL;
	}
	long long int sz=0;
	long long int accume=0;
	long long int ss=0;
	for(int i=0;i<mi.size();i++){
		ss+=mi[i].first;
	}
	for(int i=1;i<mi.size();i++){
		sz+=mi[i].first;
		accume+=((mi[i].second-mi[i].first)/2LL)*2LL;
	}
	mi[0].first-=sz;
	if(mi[0].first>0LL){
		long long int want=mi[0].first;
		long long int res=0;
		if((want&1LL)!=(accume&1LL)){
			res++;
			want--;
		}
		want-=min(want,accume);
		res+=want;
		dp_min[b]=res;
	}
	else{
		dp_min[b]=ss&1LL;
	}
}

int main(){
	cin>>n;
	scanf("%s",buf);
	s=buf;
	for(int i=1;i<n;i++){
		int a,b;
		scanf("%d%d",&a,&b);
		a--;
		b--;
		v[a].push_back(b);
		v[b].push_back(a);
	}
	long long int ans=LLONG_MAX;
	for(int i=0;i<n;i++){
		dfs(i);
		if(dp_min[i]==0LL){
			ans=min(ans,dp_max[i]/2LL);
		}
	}
	if(ans==LLONG_MAX){
		puts("-1");
		return 0;
	}
	printf("%lld\n",ans);
	return 0;
}

