void dfs(int u,int fa,int depth)
{
	totdep += (s[u - 1] - '0') * depth;
	cnt[u] = s[u - 1] - '0';
	MIN[u] = MAX[u] = 0;
	int MX = 0,MX2 = 0,sumMIN = 0,sumMAX = 0;
	for (int i = first[u];i;i = edge[i].nxt)
		if (edge[i].to != fa)
		{
			dfs(edge[i].to,u,depth + 1);
			cnt[u] += cnt[edge[i].to];
			sumMIN += MIN[edge[i].to];
			sumMAX += MAX[edge[i].to];
			if (MIN[edge[i].to] > MX)
			{
				MX = MIN[edge[i].to];
				MX2 = MAX[edge[i].to];
			}
			MAX[u] += MAX[edge[i].to];
		}
	if (MX > sumMIN / 2)
		MIN[u] = max(0,MX - sumMAX + MX2);
	if (fa)
	{
		MIN[u] += cnt[u];
		MAX[u] += cnt[u];
	}
}

