void dfs(ll x, ll p){
	sub[x] = A[x]; val[x] = 0; 
	vpi tmp;tmp.clear();
	ll t = 0;
	for (auto v:V[x])if(v!=p){
		dfs(v,x);
		sub[x] += sub[v]; val[x] += (sub[v] + val[v]);
		tmp.pb(sub[v] + val[v], v);
		t += sub[v] + val[v];
	}
	if (SZ(tmp) == 0)return;
	sort(ALL(tmp));
	// if (x == 2)for (auto v:tmp)cout<<v.f<<' '<<v.s<<'\n';
