void dfs1(int u, int fa)
{
	sum[u] = w[u] = 0;
	if (str[u - 1] == '1') w[u] = 1;
	for (int i = head[u]; i; i = edge[i].nxt)
	{
		int to = edge[i].to;
		if (to != fa)
			dfs1(to, u), w[u] += w[to], sum[u] += sum[to] + w[to];
	}
}
long long dfs2(int u, int fa)
{
	for (int i = head[u]; i; i = edge[i].nxt)
	{
		int to = edge[i].to;
		if (to != fa && (sum[to] + w[to]) * 2 > sum[u])
				return max(0LL, dfs2(to, u) + 2 * w[to] - sum[u] + sum[to]);
	}
	return 0;
