{
	sz[x]=vis[x];mx[x]=tot[x]=0;
	for(auto y:nxt[x])if(y^fa)init(y,x),chkmax(mx[x],tot[y]+sz[y]),tot[x]+=tot[y]+sz[y],sz[x]+=sz[y];
}
