{
	f[x]=0;for(auto y:nxt[x])if(y^fa)dp(y,x);
	if(2*mx[x]<=tot[x])f[x]=tot[x]>>1;
	else
	{
		int u=-1;for(auto y:nxt[x])if(tot[y]+sz[y]==mx[x])u=y;assert(u!=-1);
		f[x]=tot[x]-mx[x];int t=mx[x]-(tot[x]-mx[x]);
		f[x]+=min(t>>1,f[u]);
	}
}
int solve(int rt)
{
	init(rt,0);
	if(tot[rt]&1)return 1e9;
	dp(rt,0);if(2*f[rt]==tot[rt])return f[rt];
	return 1e9;
}
