int const nmax = 2000;
int const inf = 1000000000;

std::vector<int> g[1 + nmax];
std::string s;

int dfs(int node, int parent, int level) {
  int result = level * (s[node] - '0');

  for(int h = 0; h < g[node].size(); h++) {
    int to = g[node][h];
    if(parent != to)
      result += dfs(to, node, level + 1);
  }
  return result;
}

int solve(int node) {
  int sum = 0, smax = 0;
  for(int h = 0; h < g[node].size(); h++) {
    int to = g[node][h];
    int result = dfs(to, node, 1);
    sum += result;
    smax = std::max(smax, result);
  }
  if(sum % 2 == 1)
    return inf;
  else if(smax * 2 <= sum)
    return sum / 2;
  else
    return inf;
}

