pair<long long,long long> dfs(long long now, long long back) {
	vector<int> inputs;
	pair<int, int> ans = make_pair(0, 0);
	REP(i, vertexs[now].size()) {
		int going = vertexs[now][i];
		if (going == back) continue;
		pair<int, int> next = dfs(going, now);
		next.second += cnt[going];
		ans.first += next.first;
		cnt[now] += cnt[going];
		inputs.push_back(next.second);
	}
	if (s[now] == '1') cnt[now]++;
	if (inputs.size() != 0) {
		sort(inputs.begin(), inputs.end());
		reverse(inputs.begin(), inputs.end());
		long long total = 0;
		REP(q, inputs.size()) {
			total += inputs[q];
		}
		if (total >= inputs[0] * 2) {
			// can fill it all
			ans.first += total - total % 2;
			ans.second = total % 2;
		}
		else {
			//impossible
			int limiter = (total - inputs[0]) * 2;
			ans.first += limiter;
			ans.second = total - limiter;
		}
	}
	return ans;
}
