using namespace std;
typedef long long ll;
ll const MOD = 1e9 + 7;
ll mod_p(ll x, ll y) {
	x %= MOD;
	y %= MOD;
	return (x + y + MOD) % MOD;
}

ll mod_m(ll x, ll y) {
	x %= MOD;
	y %= MOD;
	return x * y%MOD;
}

ll mod_pow(ll x, ll t) {
	x %= MOD;
	if (t == 0) {
		return 1;
	}
	else {
		ll v = mod_pow(x, t / 2);
		if (t % 2 == 0) {
			return v * v % MOD;
		}
		else {
			return v * v%MOD * x %MOD;
		}
	}
}

ll mod_inv(ll x) {
	return mod_pow(x, MOD - 2);
}

ll const MAX = 2005;
vector<ll> g[MAX];
bool ex[MAX];

bool dfs(vector<long long>& num, vector<ll>& dist, vector<ll>& point, vector<bool>& visited, ll cur, ll i){
    visited[cur] = 1;
    for(ll nx: g[cur]){
        if(visited[nx]){
            continue;
        }
        dfs(num, dist, point, visited, nx, i);

        dist[nx] += num[nx];
        ll dn = dist[nx], dc = dist[cur], pn = point[nx], pc = point[cur];
        if(dist[nx] < dist[cur]){
            swap(dn, dc);
            swap(pn, pc);
        }
        point[cur] = dc * 2 + min(dn - dc, pn) / 2 * 2;
        num[cur] += num[nx];
        dist[cur] += dist[nx];
    }
    num[cur] += ex[cur];
    /*
    if(i == 1){
        cout << cur << " " << num[cur] << " " << dist[cur] << " " << point[cur] << endl;
    }
    */
    return (dist[cur] == point[cur]);
}

