    vector<bool> visited(MAX, 0);
    if(dfs(num, dist, point, visited, i, i)){
        //cout << i << " ! " << point[i] << endl;
        return point[i] / 2;
    }else{
        //cout << i << " ? " <<endl;
        return 1e18;
    }
}

