using namespace std;
typedef long long ll;

const int maxn = 2000 + 10;

vector<int> t[maxn];
string s;
int cnt[maxn], dp[maxn], sd[maxn];

void dfs(int v, int par = -1){
	multiset<pair<int,int>> se;
	cnt[v] = sd[v] = dp[v] = 0;
	ll sum = 0;
	int mxm = 0;
	for (auto u : t[v]){
		if (u == par)
			continue;
		dfs(u, v);
		cnt[v] += cnt[u];
		sd[v] += sd[u] + cnt[u];
		se.insert({sd[u] + cnt[u], dp[u] + cnt[u]});
		sum += sd[u] + cnt[u];
		mxm = max(mxm, sd[u] + cnt[u]);
	}
	while (2 * mxm > sum and (int)se.size() > 1){
		auto it = *se.begin();
		int a = it.first, b = it.second;
		se.erase(se.begin());
		if (a == b)
			continue;
		int ta = a;
		a = min(b, mxm);
		if ((a^b) & 1)
			a --;
		sum += (ta - a);
		mxm = max(mxm, a);
	}
	dp[v] = max(sum&1, 2*mxm-sum);
	if (s[v-1] == '1')
		cnt[v] ++;
}

int main(){
	ios_base::sync_with_stdio(false);
	int n;
	cin >> n >> s;
	for (int i = 0; i < n-1; i++){
		int v, u;
