		t[v].push_back(u);
		t[u].push_back(v);
	}
	int answer = -1;
	for (int i = 1; i <= n; i++){
		dfs(i);
		if (dp[i] == 0){
			int t = sd[i] / 2;
			if (answer == -1 or answer > t)
				answer = t;
		}
	}
	cout << answer << '\n';
}

