vector<vector<int>> v(2222);
int sumDist[2222];
int minDist[2222];
int hasPoint[2222];

void dfs(int node, int pre){
	sumDist[node] = 0;
	minDist[node] = 0;
	hasPoint[node] = (str[node] == '1' ? 1 : 0);
	if(pre != -1 && v[node].size() == 1) return;

	vector<P> vec;
	REP(i, v[node].size()){
		int aite = v[node][i];
		if(aite == pre) continue;

		dfs(aite, node);
		//cout << " in dfs " << aite << " " << hasPoint[aite] << " " << sumDist[aite] << " " << minDist[aite] << endl;

		sumDist[aite] += hasPoint[aite];
		minDist[aite] += hasPoint[aite];

		sumDist[node] += sumDist[aite];
		hasPoint[node] += hasPoint[aite];
		vec.EB(sumDist[aite], minDist[aite]);
	}

	sort(ALL(vec), greater<P>());

	if(vec[0].FI > sumDist[node] / 2) {
		int now = vec[0].FI;
		for(int i = 1;i < vec.size();i++){
			now -= vec[i].FI;
		}
		now = max(0LL, now - (vec[0].FI - vec[0].SE)) + (now % 2);
		minDist[node] = now;
	}
	else {
		int now = 0;
		REP(i, vec.size()){
			now += vec[i].FI % 2;
		}
		minDist[node] = now % 2;
	}
}

int check(int root){
	dfs(root, -1);
	//cout << "check " << root << " " << hasPoint[root] << " " << sumDist[root] << " " << minDist[root] << endl;

	if(minDist[root] == 0){
		return sumDist[root];
	}
	else {
		return INF;
	}
}

