struct interval {
  int l = 0, r = 0;
};

bool overlap(interval a, interval b) {
  return a.r >= b.l && a.l <= b.r;
}

interval merge(interval a, interval b) {
  /*
  int l = 1e9;
  int r = -1e9;
  for (int i = a.l; i <= a.r; i += 2) {
    for (int j = b.l; j <= b.r; j += 2) {
      l = min(l, max(i, j));
      r = max(r, i + j);
    }
  }
  */
  int l = max(a.l, b.l);
  int r = a.r + b.r;
  return {l, r};
}

int main() {
  int N = read();
  string S = reads();
  vector<vector<int>> G(N);
  for (int i = 0; i < N - 1; i++) {
    int u = read() - 1;
    int v = read() - 1;
    G[u].push_back(v);
    G[v].push_back(u);
  }
  const int INF = 1e9;
  int ans = INF;
  for (int rt = 0; rt < N; rt++) {
    vector<interval> dp(N);
    vector<int> size(N);
    vector<int> dist(N);
    function<void(int, int)> dfs = [&](int u, int p) {
      if (S[u] == '1') size[u] = 1;
      for (int v : G[u]) {
        if (v == p) continue;
        dfs(v, u);
        size[u] += size[v];
        dist[u] += dist[v] + size[v];
        dp[v].l += size[v];
        dp[v].r += size[v];
        dp[u] = merge(dp[u], dp[v]);
      }
    };
    dfs(rt, -1);
    if (dist[rt] % 2 == 0 && dp[rt].l <= dist[rt]/2 && dist[rt]/2 <= dp[rt].r) {
      ans = min(ans, dist[rt] / 2);
    }
  }
  if (ans == INF) ans = -1;
  write(ans);
  newline();
}

