const int inf = 1012345678;
int calc(vector<pair<int, int> > v) {
	int n = v.size();
	int lm = 0, ls = 0, lp = -1;
	for(int i = 0; i < n; ++i) {
		if(lm < v[i].first) {
			lm = v[i].first;
			lp = i;
		}
		ls += v[i].first;
	}
	if(lm * 2 <= ls) return 0;
	for(int i = 0; i < n; ++i) {
		if(i != lp) ls += v[i].second - v[i].first;
	}
	if(lm * 2 <= ls) return 0;
	return lm * 2 - ls;
}
vector<int> dfs(int pos, int pre, const vector<vector<int> > &G, const string &S) {
	int ch = (S[pos] == '1' ? 1 : 0);
	vector<pair<int, int> > d;
	int rm = 0;
	for(int i : G[pos]) {
		if(i == pre) continue;
		vector<int> res = dfs(i, pos, G, S);
		d.push_back(make_pair(res[0], res[1]));
		ch += res[2];
		rm += res[1];
	}
	int lm = calc(d);
	return vector<int>({lm + ch, rm + ch, ch});
}
int main() {
	int N; string S;
	cin >> N >> S;
	vector<vector<int> > G(N);
	for(int i = 0; i < N - 1; ++i) {
		int a, b;
		cin >> a >> b; --a, --b;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	int ans = inf;
	for(int i = 0; i < N; ++i) {
		vector<pair<int, int> > d;
		int sum = 0;
		for(int j : G[i]) {
			vector<int> res = dfs(j, i, G, S);
			sum += res[1];
			d.push_back(make_pair(res[0], res[1]));
		}
		int ret = calc(d);
		if(sum % 2 == 0 && ret == 0) {
			ans = min(ans, sum / 2);
		}
	}
	cout << (ans < inf ? ans : -1) << endl;
	return 0;
}

