    int tres = INF;
    vi d(n), g(n);
    function<pi(int, int)> dfs = [&] (int u, int p) {
        g[u] = 0;
        int res = 0;
        if (s[u] == '1') g[u] = 1, res = d[u];
        vi vals, vals2;
        for (int v : adj[u]) {
            if (v ^ p) {
                d[v] = d[u] + 1;
                pi e = dfs(v, u);
                res += e.se;
                int t = e.fi + g[v];
                vals.pb(t);
                vals2.pb(e.se);
                g[u] += g[v];
            }
        }
        if (p == -1) {
            int sum = 0;
            FOR(i, 0, sz(vals2)) {
                sum += vals2[i];
            }
            int found = 0;
            int w = *max_element(all(vals2));
            FOR(i, 0, sz(vals)) {
                if (vals2[i] == w && vals[i] <= sum - vals2[i]) {
                    found = 1;
                }
