            if (found) {
                sum = 0;
                FOR(v, 0, n) if (s[v] == '1') {
                    sum += d[v];
                }
                if (sum % 2 == 0) {
                    chkmin(tres, sum / 2);
                }
            }
            return mp(0, 0);
        }
        else {
            if (sz(vals)) {
                int sum = 0;
                FOR(i, 0, sz(vals2)) {
                    sum += vals2[i];
                }
                int found = 0;
                int w = *max_element(all(vals2));
                int z = INF;
                FOR(i, 0, sz(vals2)) {
                    if (vals2[i] == w) {
                        chkmin(z, max(0, vals[i] - (sum - vals2[i])));
                    }
                    if (vals2[i] == w && vals[i] <= sum - vals2[i]) {
                        found = 1;
                    }
                }
                if (found) {
                    return mp(sum % 2, res);
                }
                else {
                    return mp(z, res);
                }
            }
            return mp(0, res);
        }
        return mp(0, 0);
    };
