                tree[b].neighbor.push_back(&tree[a]);
        }

        long long ans = -1;
        for(long long i=0;i<n;i++){
                long long sum = 0;
                long long max = 0;
                for(auto nx : tree[i].neighbor){
                        long long ret = search(nx, &tree[i], 1);
                        sum += ret;
                        if(max < ret){
                                max = ret;
                        }
                }

                if(sum % 2 == 0 && 2 * max <= sum){
                        //cout << "c:" << i+1 << " sum:" << sum << endl;
