    if(l==1||accumulate(A,A+l-1,0ll)<A[l-1])return INF;
    if((accumulate(A,A+l-1,0ll)+A[l-1])&1)return INF;
    return (accumulate(A,A+l-1,0ll)+A[l-1])/2;
}
