		--x; --y;
		G[x].emplace_back(y);
		G[y].emplace_back(x);
	}

	vector<int> dep(n);
	vector<int> dp(n);
	vector<int> sz(n);
	vector<int> Sum(n);

	function<void(int, int)> dfs = [&] (int u, int f) {
		sz[u] = (s[u] == '1');
		dp[u] = 0;
		Sum[u] = dep[u] * (s[u] == '1');
		for(int v : G[u]) {
			if(v != f) {
				dep[v] = dep[u] + 1;
				dfs(v, u);
				dp[u] = max(dp[u], dp[v] + sz[v]);
				sz[u] += sz[v];
				Sum[u] += Sum[v];
			}
		}
	};

	int ans = inf;
	for(int i = 0; i < n; ++i) {
		dep[i] = 0;	
