Node dfs(int at, int par) {
	vector<Node> V;
	int leaf = 1;
	for (int i : adj[at]) {
		if (par == i) continue;
		Node p = dfs(i, at);
		if (p.lo == -1) continue;
		leaf = 0;
		p.lo += p.how_many;
		p.hi += p.how_many;
		V.push_back(p);
	}
	if (leaf) {
		if (S[at] =='1') return { 1, 0, 0, 0 };
		else return { -1, -1, -1, -1 };
	}

	sort(ALL(V));
	Node ret = { 0, 0, 0, 0 };
	for (auto& p : V) {
		ret.how_many += p.how_many;
		ret.cost += p.cost + p.how_many;
		ret.hi += p.hi;
	}
	int me = 1000000000;
	int flag = 0;
	for (int i = 0; i < SZ(V); i++) {
		int my_lo = V[i].lo;
		int other_hi = ret.hi - V[i].hi;
		if (my_lo > other_hi) {
			int now = my_lo - other_hi;
			me = MIN(me, now);
			flag = 1;
		}
	}
	if (!flag) {
		me = ret.hi & 1;
	}
	ret.lo = me;
	if (S[at] == '1') ret.how_many++;

	return ret;
}

