vector<int> G[2020];
int N,Z[2020]; char S[2020];

pair<int, int> go(int x, int l, int d)
{
	pair<int, int> r;
	if (S[x] == '1') r.first += d, Z[x] = 1;
	else Z[x] = 0;
	int mx = 0, sm = 0;
	for (auto &y : G[x]) if (y != l){
		auto n = go(y, x, d + 1);
		Z[x] += Z[y];
		r.first += n.first;
		mx = max(mx, n.second);
		sm += n.second;
	}
	if (mx <= sm / 2) sm %= 2;
	else sm = sm - 2 * (sm - mx);
	r.second = sm + Z[x];
	return r;
}

int main()
{
	scanf ("%d", &N);
	scanf ("%s", S + 1);
	for (int i = 1; i < N; i++){
		int x, y; scanf ("%d %d", &x, &y);
		G[x].push_back(y);
		G[y].push_back(x);
	}

	int ans = 0x7fffffff;
	for (int c = 1; c <= N; c++){
		vector<pair<int, int> > res;
		int mn = 0, mx = 0;
		for (auto &p : G[c]){
			auto n = go(p, c, 1);
			res.push_back(n);
			mn += n.second;
			mx += n.first;
		}
		if (mx % 2) continue;

		sort(res.begin(), res.end());
		auto u = res.back();
		mn -= u.second;
		mx -= u.first;
		for (int i = u.second; i <= u.first; i++){
			if (mn >= i){
				ans = min(ans, (mn + i) / 2);
				break;
			}
			int sum = 0;
			for (int j = 0; j + 1 < res.size(); j++){
				if (res[j].first <= i) sum += res[j].first;
				else sum += i;
			}
			if (sum >= i){
				ans = min(ans, i);
				break;
			}
		}
	}

	if (ans == 0x7fffffff) ans = -1;
	printf ("%d\n", ans);
	return 0;
}

