const int MAXN = 2029;


int n;
string s;
vector<int> g[MAXN];
int dist[MAXN];
int cnt = 0;


void dfs(int u, int pr) {
	for (auto h: g[u]) {
		if (pr == h) {
			continue;
		}
		dist[h] = dist[u] + 1;
		dfs(h, u);
	}
	if (s[u] == '1') {
		cnt += dist[u];
	}
}



int dfs1(int u, int pr) {
	int cur = 0;
	vector<int> st;
	for (auto h: g[u]) {
		if (pr == h) {
			continue;
		}
		int kek = dfs1(h, u);
		st.pb(kek);
		cur += kek;
	}
	if (st.empty()) {
		if (s[u] == '1') {
			return dist[u];
		}
		return 0;
	}
	int ans = 0;
	if (s[u] == '1') {
		ans += dist[u];
	}
	for (auto &x: st) {
		ans += dist[u];
		x -= dist[u];
		cur -= dist[u];
	}
	sort(all(st));
	if (st.back() * 2 <= cur) {
		ans += cur % 2;
	} else {
		int kek = 2 * st.back();
		for (auto x: st) {
			kek -= x;
		}
		ans += kek;
	}
	return ans;
}


