void wdp(int a, int fa)
{
	//最多消几次
	sz[a] = tp[a];
	dp[a] = 0, sm[a] = 0; // sm : dep
	int mx = 0;
	for(int i = 0; i < eg[a].size(); i++)
	{
		int v = eg[a][i];
		if(v == fa) continue;
		wdp(v, a);
		dp[a] += dp[v];
		mx = max(mx, sm[v]), sm[a] += sm[v]; 
		sz[a] += sz[v];
	}
	int dv = min(sm[a] - mx, sm[a] / 2);
	dp[a] += dv, sm[a] -= 2 * dv;
	sm[a] += sz[a];
}
int nv[maxn], nd[maxn], dep[maxn];
int ns = 0;
void dfs(int a, int fa)
{
	if(tp[a]) ns += dep[a];
	for(int i = 0; i < eg[a].size(); i++)
	{
		int v = eg[a][i];
		if(v == fa) continue;
		dep[v] = dep[a] + 1;
		dfs(v, a);
	}
}
int inf = 1e9;
int work(int a)
{
	int cnt = eg[a].size();
	for(int i = 0; i < cnt; i++)
	{
		int v = eg[a][i];
		ns = 0;
		dep[v] = 1;
		dfs(v, a);
		nv[i] = v, nd[i] = ns;
	}
	int sm = 0, mpl = 0;
	for(int i = 0; i < cnt; i++)
	{
		sm += nd[i];
		if(nd[i] > nd[mpl]) mpl = i;
	}
	if(sm & 1) return inf;
	if(nd[mpl] <= sm / 2) return sm / 2;
	int v = nv[mpl];
	wdp(v, a);
	ns = nd[mpl] - (sm - nd[mpl]);
	if(dp[v] * 2 < ns) return inf;
	return sm / 2; 
}
