int s_up[N], sz[N], a[N], yl[N], yr[N], xl[N], xr[N], sum[N];
vector<int> adj[N];
pair<int, int> merge(int lu, int ru, int lv, int rv) {
	int pl = max(lu, lv);
	int pr = min(ru, rv);
	int lx = max(0, pl - pr);
	int rx = ru + rv;
	if ((rx & 1) && (lx % 2 == 0)) {
		++lx;
	}
	return mp(lx, rx);
}
pair<int, int> merge(pair<int, int> x, pair<int, int> y) {
	return merge(x.x, x.y, y.x, y.y);	
}
pair<int, int> update(int lu, int ru, int s, int t = 1) {
	lu += s * t;
	ru += s * t;
	return mp(lu, ru);
}
void dfs_down(int v, int p = -1) {
	sz[v] = a[v];
	int &lv = yl[v], &rv = yr[v];
	vector<int> ch;
	for (int u : adj[v]) if (u != p) {
		ch.pb(u);
		dfs_down(u, v);
		sz[v] += sz[u];
		int lu = yl[u], ru = yr[u];
		auto x = update(lu, ru, sz[u], 1);
		lu = x.first, ru = x.second;
		auto e = merge(lv, rv, lu, ru);
		lv = e.first, rv = e.second;
		sum[v] += sum[u] + sz[u];
	}
	adj[v] = ch;
}
void dfs_up(int v, int p = -1, int sum_up = 0, pair<int, int> pv = mp(0, 0)) {
	s_up[v] = sum_up + sum[v];
	int sum_all = 0;
	for (int u : adj[v]) {
		sum_all += sum[u];
	}
	pv = update(pv.first, pv.second, sz[0] - sz[v], 1);
	int m = (int) adj[v].size();
	vector<pair<int, int>> ls(m + 1), rs(m + 1);
	for (int j = 0; j < m; ++j) {
		int u = adj[v][j];
		int lu = yl[u], ru = yr[u];
		auto x = update(lu, ru, sz[u], 1);
		lu = x.x, ru = x.y;
		ls[j + 1] = merge(lu, ru, ls[j].x, ls[j].y);
	}
	for (int j = m - 1; j >= 0; --j) {	
		int u = adj[v][j];
		int lu = yl[u], ru = yr[u];
		auto x = update(lu, ru, sz[u], 1);
		lu = x.x, ru = x.y;
		rs[j] = merge(lu, ru, rs[j + 1].x, rs[j + 1].y);
	}
	for (int j = 0; j < m; ++j) {
		int u = adj[v][j];
		dfs_up(u, v, sum_all + sum_up - sum[u], merge(merge(pv, ls[j]), rs[j + 1]));	
	}
	auto x = merge(pv, rs[0]);
	xl[v] = x.first;
	xr[v] = x.second;
}
