int N;
int S[2000];
vector<int> G[2000];

// num, sum
int memo[2000][2001];
PP dist(int from, int prev) {
	PP ret(S[from], 0);
	for (int to : G[from]) {
		if (to == prev) continue;
		PP res = dist(to, from);
		ret.first += res.first;
		ret.second += res.second + res.first;
	}
	memo[from][prev == -1 ? N : prev] = ret.first;
	return ret;
}

PP rec(int from, int prev) {
	PP ret(0, 0);
	for (int to : G[from]) {
		if (to == prev) continue;
		PP res = rec(to, from);
		res.first += memo[to][from];
		res.second += memo[to][from];

		PP a = ret;
		PP b = res;
		if (a > b) swap(a, b);

		int mx;
		int mn;
		if (a.second < b.first) {
			mn = b.first - a.second;
		} else {
			mn = 0;
		}
		mx = a.second + b.second;

		ret = PP(mn, mx);
	}
	return ret;
}

bool ok(int i) {
	PP res = rec(i, -1);
	return res.first == 0;
}

int sub(int i) {
	PP res = dist(i, -1);
	int d = res.second;
	if (d % 2 != 0) return INF;

	if (ok(i)) {
		return d / 2;
	} else {
		return INF;
	}
}

