// O( N )
void dfs_tree_depth_( Graph& g, int v )
{
	vector<int> childList;
	for( const auto& e : g.mEdge[v] )
	{
		if( g.mDepth[e.to] >= 0 ) continue;
		g.mDepth[e.to] = g.mDepth[v] + 1;
		childList.push_back( e.to );
		dfs_tree_depth_( g, e.to );
		/**/g.mMark[e.to].distAll += g.mMark[e.to].num;
	}
	auto& m = g.mMark[v];
	REP( i, childList.size() ) m += g.mMark[childList[i]];
	if( childList.size() == 1 ) m.maxOp = g.mMark[childList[0]].maxOp;
	else if( childList.size() > 1 )
	{
		int maxxxDist = 0, maxxxIdx = 0;
		REP( i, childList.size() ) if( maxxxDist <= g.mMark[childList[i]].distAll )
		{ maxxxDist = g.mMark[childList[i]].distAll; maxxxIdx = childList[i]; }
		int leftDist = maxxxDist - g.mMark[maxxxIdx].maxOp * 2;
		REP( i, childList.size() ) if( maxxxIdx != childList[i] )
		{ leftDist -= g.mMark[childList[i]].distAll; }
		m.maxOp = ( m.distAll - max( leftDist, 0 ) ) / 2;
	}
	if( g.mHas[v] ) ++m.num;
	//cout << v << " " << m.num << " " << m.distAll << " " << m.maxOp << endl;
}
void dfs_tree_depth( Graph& g, int rootNode )
{
	fill( ALL( g.mDepth ), -1 );
	fill( ALL( g.mMark ), Graph::MARK() );
	g.mDepth[rootNode] = 0;
	dfs_tree_depth_( g, rootNode );
	//cout << "----" << endl;
}

