	{
		dfs_tree_depth(g,i);
		int sum = g.mMark[i].distAll;
		if( sum % 2 == 0 && g.mMark[i].maxOp == sum / 2 )
			cnt = min( cnt, sum / 2 );
	}
	if( cnt == 2000 * 2000 ) cout << -1 << endl;
	else cout << cnt << endl;

	return 0;
}

