void solve() {
  int N; cin >> N;
  string s; cin >> s;
  vector<vi32> edges(N);
  rep(i, N - 1) {
    int a, b; cin >> a >> b;
    a--, b--;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }
  struct Data {
    int count = 0;
    int dists = 0;
    int carry = 0;
    vi32 list = vi32();
  };
  vector<vector<Data>> dp(N);
  vi32 par(N, -1);

  auto lift = [&](Data a, int u) {
    if (s[u] == '1') a.count++;
    a.dists += a.count;
    int sum = accumulate(a.list.begin(), a.list.end(), 0);
    sort(a.list.rbegin(), a.list.rend());
    if (a.list.size() == 0) {
      return a;
    }
    if (a.list[0] * 2 > sum) {
      int rest = a.list[0] - (sum - a.list[0]);
      a.dists = rest;
      a.carry += sum - a.list[0];
    } else {
      if (sum % 2 == 1) {
        a.dists = 1;
      } else {
        a.dists = 0;
      }
      a.carry += sum / 2;
    }
    return a;
  };

  auto merge = [](Data a, Data b) {
    a.count += b.count;
    a.dists += b.dists;
    a.carry += b.carry;
    each(l, b.list) a.list.push_back(l);
    return a;
  };

  function<Data(int, int)> dfs = [&](int v, int p) {
    int n = edges[v].size();
    dp[v] = vector<Data>(n);

    Data ret;
    rep(i, n) {
      int u = edges[v][i];
      if (u == p) {
        par[v] = i;
        continue;
      }
      dp[v][i] = lift(dfs(u, v), u);
      ret = merge(ret, dp[v][i]);
    }
    return ret;
  };

  vector<vi32> lists(N);
  vi32 answers(N);

  function<void(int, Data)> bfs = [&](int v, Data d) {
    if (par[v] != -1) {
      dp[v][par[v]] = lift(d, edges[v][par[v]]);
    }
    int n = edges[v].size();
    vector<Data> dpl(n + 1);
    vector<Data> dpr(n + 1);
    repp(i, n) dpl[i + 1] = merge(dpl[i], dp[v][i]);
    rrep(i, n) dpr[i] = merge(dpr[i + 1], dp[v][i]);

    rep(i, n) lists[v].push_back(dp[v][i].dists);
    answers[v] = dpr[0].carry;

    rep(i, n) if (i != par[v]) {
      int u = edges[v][i];
      bfs(u, merge(dpl[i], dpr[i + 1]));
    }
  };

  dfs(0, -1);
  bfs(0, Data());

  int ans = 1e9;

  rep(i, N) {
    int sum = accumulate(all(lists[i]), 0);
    if (sum % 2 == 1) continue;
    sort(all(lists[i])), reverse(all(lists[i]));
    if (sum < lists[i][0] * 2) continue;
    amin(ans, sum / 2 + answers[i]);
  }
  if (ans == 1e9) ans = -1;
  cout << ans << '\n';
}

