using namespace std;

const int N = 2005;
const int inf = 1000000000;
struct edge {
    int to, nxt;
} tree[N << 1];
int n, head[N], l[N], r[N], sz[N], cnt = 0;
char str[N];
void addedge (int u, int v) {
    edge e = {v, head[u]};
    tree[head[u] = cnt++] = e;
}

void dfs (int u, int fa) {
    int l_mx = 0;
    sz[u] = (str[u - 1] == '1'), r[u] = 0;
    for (int i = head[u]; ~i; i = tree[i].nxt) {
        int v = tree[i].to;
        if (v != fa) {
            dfs(v, u);
            sz[u] += sz[v];
            l_mx = max(l_mx, l[v] + sz[v]), r[u] += r[v] + sz[v];
        }
    }
    l[u] = 0;
    for (int i = head[u]; ~i; i = tree[i].nxt) {
        int v = tree[i].to;
        if (v != fa) {
            if (r[v] + sz[v] <= l_mx) l[u] += r[v] + sz[v];
            else if (l_mx % 2 == (r[v] + sz[v]) % 2) l[u] += l_mx;
            else l[u] += l_mx - 1;
        }
    }
    l[u] = (l_mx << 1) - l[u];
    if (l[u] < 0) l[u] = r[u] & 1;
}
int main () {
    scanf("%d%s", &n, str);
    for (int i = 1; i <= n; i++) head[i] = -1;
    for (int i = 1; i < n; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        addedge(u, v), addedge(v, u);
    }

    int ans = inf;
    for (int i = 1; i <= n; i++) {
        dfs(i, 0);
        if (l[i] <= 0) ans = min(ans, r[i] >> 1);
    }
    if (ans >= inf) printf("-1\n");
    else printf("%d\n", ans);
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

struct edge
{
	int v,nxt;
}e[4050];

int ecnt,head[2050];

void adde(int u,int v)
{
	e[++ ecnt].v = v;
	e[ecnt].nxt = head[u];
	head[u] = ecnt;
}

int sz[2050],lft[2050],dist[2050];
char str[2050];
int n;

void dfs(int pos,int lst)
{
	sz[pos] = str[pos] == '1' ? 1 : 0;
	dist[pos] = 0;
	int maxn = 0;
	for(int i = head[pos];i;i = e[i].nxt)
	{
		int v = e[i].v;
		if(v != lst)
		{
			dfs(v,pos);
			sz[pos] += sz[v];
			dist[pos] += dist[v] + sz[v];
			lft[v] += sz[v];
			if(lft[v] > lft[maxn]) maxn = v;
		}
	}
	if(!maxn) lft[pos] = 0;
	else
	{
		int tot = dist[pos] - dist[maxn] - sz[maxn];
		if(tot >= lft[maxn]) lft[pos] = dist[pos] & 1;
		else lft[pos] = lft[maxn] - tot;
	}
}

int main()
{
	scanf("%d %s",&n,str + 1);
	for(int i = 1;i < n; ++ i)
	{
		int u,v;
		scanf("%d%d",&u,&v);
		adde(u,v),adde(v,u);
	}
	lft[0] = -0x3f3f3f3f;
	int ans = 0x3f3f3f3f;
	for(int i = 1;i <= n; ++ i)
	{
		dfs(i,0);
		if(lft[i] == 0)
			ans = min(ans,dist[i] / 2);
	}
	if(ans == 0x3f3f3f3f) printf("-1\n");
	else printf("%d\n",ans);
	return 0;
}

