using namespace std;
#define lor(a,b,c) for(register int a=b;a<=c;++a)
#define ror(a,b,c) for(register int a=c;a>=b;--a)
#define tor(a,b) for(register int a=head[b];a;a=nxt[a])

const int MAXN=2005,INF=0x3f3f3f3f;

int n; char s[MAXN];
int ecnt,edge[MAXN<<1],head[MAXN],nxt[MAXN<<1];
int ans=INF,f[MAXN],siz[MAXN],cnt[MAXN];

inline void insert(int from,int to,int id){
	nxt[id]=head[from]; head[from]=id; edge[id]=to;
}

void dfs(int u,int fa){
	int sum=0,maxx=0;
	tor(i,u){
		int v=edge[i]; if(v==fa) continue;
		dfs(v,u);
		cnt[u]+=cnt[v]+siz[v]; siz[u]+=siz[v]; maxx=max(maxx,cnt[v]+siz[v]); sum+=cnt[v]+siz[v];
	}
	if(sum-maxx>=maxx) f[u]=sum>>1;
	else{
		tor(i,u){
			int v=edge[i]; if(v==fa) continue;
			if(cnt[v]+siz[v]==maxx){
				f[u]=max(f[u],(sum-maxx)+min((2*maxx-sum)>>1,f[v]));
			}
		}
	}
}

inline int calc(int root){
	lor(i,1,n) siz[i]=s[i]=='1',cnt[i]=f[i]=0;
	dfs(root,root);
	if((f[root]<<1)==cnt[root]) return f[root]; else return INF;
}

int main(){
	scanf("%d",&n); scanf("%s",s+1);
	lor(i,1,n-1){
		int a,b; scanf("%d%d",&a,&b); insert(a,b,++ecnt); insert(b,a,++ecnt);
	}
	lor(i,1,n) ans=min(ans,calc(i));
	printf("%d\n",ans==INF?-1:ans);

	return 0;
}

