vector<pair<ll, ll>> state(2001);//個数、総和
vvl G = VV(2001, 0, 0, ll);

pair<ll, ll> dfs(ll now, ll from){
  pair<ll, ll> ret(0, 0);
  if(s[now]=='1') ret.first++;
  for(auto to:G[now]){
    if(from==to) continue;
    pair<ll, ll> p = dfs(to, now);
    p.second += p.first;
    ret.first += p.first;
    ret.second += p.second;
  }
  return state[now] = ret;
}

pair<ll, ll> dfs2(ll now, ll from){//操作の回数、深さの和
  pair<ll, ll> ret(0, 0);
  ll sm = 0, max_num = 0;

  for(auto to:G[now]){
    if(from==to) continue;
    pair<ll, ll> p = dfs2(to, now);
    p.second += state[to].first;
    ret.first += p.first;
    ret.second += p.second;//これまでのもの
    sm += p.second;
    max_num = max(max_num, p.second);
  }
  // all
  if(max_num<(sm-max_num)){
    ll tm = sm/2;
    ret.first += tm;
    ret.second -= tm*2;
  }else{
    ll tm = max_num - (sm-max_num);
    ret.first += tm;
    ret.second -= tm*2;
  }
  return ret;
}
void init(ll root){
  pair<ll, ll> S = dfs(root, -1);
  if(S.second%2) return;
  ll need = S.second/2;
  pair<ll, ll> num = dfs2(root, -1);
  //std::cout << root << " " << num.first << " " << num.second << '\n';
  if(num.first==need){
    std::cout << need << '\n';
    exit(0);
  }
}
