	char c = getchar();
	while (c < '0' || c>'9')c = getchar();
	while (c >= '0' && c <= '9')num = num * 10 + c - '0', c = getchar();
	return num;
}
int dfs(int w, int f)
{
	tot[w] = col[w];
	sum[w] = 0;
	for (int i = 0, lim = e[w].size(); i < lim; i++)
		if (e[w][i] != f)
		{
			dfs(e[w][i], w);
			tot[w] += tot[e[w][i]];
			sum[w] += sum[e[w][i]] + tot[e[w][i]];
		}
	return 0;
}
int check(int w, int f)
{
	int mx = 0;
	for (int i = 0, lim = e[w].size(); i < lim; i++)
		if (e[w][i] != f && (!mx || sum[e[w][i]] > sum[mx]))mx = e[w][i];
	if (!mx)return 0;
	int val = check(mx, w) + tot[mx];
	if (sum[w] - sum[mx] - tot[mx] >= val)return sum[w] & 1;
	else return val - (sum[w] - sum[mx] - tot[mx]);
}
