template<class T> inline bool chmin(T& a, T b) {
	if (a > b) {
		a = b;
		return true;
	}
	return false;
}
template<class T> inline bool chmax(T& a, T b) {
	if (a < b) {
		a = b;
		return true;
	}
	return false;
}

struct Edge {//グラフ
	ll to, cap, rev;
	Edge(ll _to, ll _cap, ll _rev) {
		to = _to; cap = _cap; rev = _rev;
	}
};
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;
void add_edge(Graph& G, ll from, ll to, ll cap, bool revFlag, ll revCap) {//最大フロー求める Ford-fulkerson
	G[from].push_back(Edge(to, cap, (ll)G[to].size()));
	if (revFlag)G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));//最小カットの場合逆辺は0にする
}

//max and min
P dfs(Graph& g, ll v, ll par,Array& cnt,string& s) {
	if (s[v] == '1')cnt[v]++;

	vector<P> kids(g[v].size());
	ll sum = 0;
	REP(i, g[v].size()) {
		ll to = g[v][i].to;
		if (to == par)continue;
		kids[i] = dfs(g, to, v, cnt, s);
		kids[i].first += cnt[to];
		kids[i].second += cnt[to];
		sum += kids[i].first;
		cnt[v] += cnt[to];
	}

	ll mx = 0;
	REP(i, g[v].size()) {
		ll temp = kids[i].second + kids[i].first - sum;
		chmax(mx, temp);
	}
	if (sum % 2 == 1)chmax(mx, 1LL);
	P ret = { sum,mx };

	return ret;
}


