	REP(i, n - 1) {
		ll a, b;
		cin >> a >> b;
		a--; b--;
		add_edge(g, a, b, 1, true, 1);
	}
	ll ans = INF;
	REP(i, n) {
		Array cnt(n, 0);
		auto temp = dfs(g, i, -1, cnt, s);
		if (temp.second == 0)chmin(ans, temp.first / 2);
	}
	if (ans == INF)cout << -1 << "\n";
	else cout << ans << "\n";

	return 0;
}

