using namespace std;
using ll = long long;
using ld = long double;

int n;
string s;
const int maxn = 2005;
vector<int> g[maxn];

ll sumh[maxn];
int cnt[maxn];
void pre(int u, int prev = -1) {
  sumh[u] = 0;
  cnt[u] = s[u] == '1';
  for (int v : g[u]) {
    if (v == prev) {
      continue;
    }
    pre(v, u);
    sumh[u] += sumh[v] + cnt[v];
    cnt[u] += cnt[v];
  }
}

ll dfs(int u, int prev = -1) {
  ll vmax = 0;
  for (int v : g[u]) {
    if (v == prev) {
      continue;
    }
    vmax = max(vmax, sumh[v] + cnt[v]);
  }
  if (vmax * 2 <= sumh[u]) {
    return sumh[u] / 2 * 2;
  }
  ll vup = 0;
  for (int v : g[u]) {
    if (v == prev) {
      continue;
    }
    if (sumh[v] + cnt[v] == vmax) {
      vup = dfs(v, u);
    }
  }
  ll s = sumh[u] - vup;
  ll mx = vmax - vup;
  if (mx * 2 <= s) {
    return sumh[u] / 2 * 2;
  } else {
    return vup + (s - mx) * 2;
  }
}

