#define INF 1000000007
using namespace std;
typedef long long ll;
typedef pair<int,int> P;

int n;
bool koma[2005];
vector<int> G[2005];
int dist[2005];
int cnt[2005];

int dfs(int v,int p=-1){
	int val=0;
	if(koma[v])val++;
	for(int i=0;i<G[v].size();i++){
		if(G[v][i]!=p){
			val+=dfs(G[v][i],v);
		}
	}
	return (cnt[v]=val);
}

P dfs2(int v,int p=-1){
	P rec=P(0,0);
	for(int i=0;i<G[v].size();i++){
		int nv=G[v][i];
		if(nv!=p){
			P p=dfs2(nv,v);
			p.first+=cnt[nv];
			p.second+=cnt[nv];
			if(p.first>rec.first){
				swap(p,rec);
			}
			P np;
			np.second=rec.second+p.second;
			if(p.second<rec.first){
				np.first=rec.first-p.second;
			}else{
				if((p.first+rec.first)%2==0)np.first=0;
				else np.first=1;
			}
			rec=np;
		}
	}
	return rec;
}

int solve(int s){
	memset(dist,-1,sizeof(dist));
	dist[s]=0;
	queue<int> que;
	que.push(s);
	while(que.size()){
		int v=que.front();
		que.pop();
		for(int i=0;i<G[v].size();i++){
			int nv=G[v][i];
			if(dist[nv]==-1){
				dist[nv]=dist[v]+1;
				que.push(nv);
			}
		}
	}
	int ans=0;
	for(int i=0;i<n;i++){
		if(koma[i]){
			ans+=dist[i];
		}
	}
	dfs(s);
	P p=dfs2(s);
	if(p.first==0)return ans/2;
	return INF;
}

int main(void){
	scanf("%d",&n);
	string s;
	cin >> s;
	for(int i=0;i<n;i++){
		if(s[i]=='1'){
			koma[i]=true;
		}
	}
	for(int i=0;i<n-1;i++){
		int a,b;
		scanf("%d%d",&a,&b);
		a--;
		b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	int ans=INF;
	for(int i=0;i<n;i++){
		ans=min(ans,solve(i));
	}
	if(ans==INF)ans=-1;
	printf("%d\n",ans);
	return 0;
}

