int dfs(vector<int> *edge,int *node,int n,int s1,int s2,int depth){
    if(edge[s2].size()==1) return node[s2]*depth;
    int hoge=0;
    rep(i,edge[s2].size()){
        if (edge[s2][i]==s1) continue;
        hoge+=dfs(edge,node,n,s2,edge[s2][i],depth+1);
    }
    return node[s2]*depth+hoge;
}

int solve(vector<int> vec){
    int n=vec.size();
    int sum=0,max_val=0;
    rep(i,n){
        sum+=vec[i];
        max_val=max(max_val,vec[i]);
    }
    if(sum%2==1){
        return 1000000000;
    }
    if(max_val*2>sum){
        return sum-max_val*2;
    }
    return sum/2;
}

int reduction(vector<int> *edge,int *node,int n,int s1,int s2,vector<int> &vec){
    if(edge[s2].size()==1) {
        if(node[s2]==1) vec.push_back(1);
        return 0;
    }
    vector<int> v;
    int ans=0;
    rep(i,edge[s2].size()){
        if(edge[s2][i]==s1) continue;
        ans+=reduction(edge,node,n,s2,edge[s2][i],v);
    }
    int sum=0,max_val=0;
    rep(i,v.size()){
        sum+=v[i];
        max_val=max(max_val,v[i]);
    }
    if(sum>0) vec.push_back(sum);
    if(v.size()<2) return ans;
    if(sum>2*max_val) return ans+sum;
    return ans+(sum-max_val)*2;
}
