    function<pi(int, int)> dfs = [&] (int u, int p) {
        g[u] = 0;
        int res = 0;
        if (s[u] == '1') g[u] = 1, res = d[u];
        vi vals, vals2;
        for (int v : adj[u]) {
            if (v ^ p) {
                d[v] = d[u] + 1;
                pi e = dfs(v, u);
                vals.pb(e.fi + g[v]), vals2.pb(e.se), res += e.se;
                g[u] += g[v];
            }
        }
        if (p == -1) {
            int sum = 0;
            FOR(i, 0, sz(vals2)) {
                sum += vals2[i];
            }
            int total = 0;
            FOR(i, 0, sz(vals)) {
                if (vals[i] <= sum - vals2[i]) {
                    total++;
                }
            }
            if (total == sz(vals)) {
                sum = 0;
                FOR(v, 0, n) if (s[v] == '1') {
                    sum += d[v];
                }
                if (sum % 2 == 0) {
                    chkmin(tres, sum / 2);
                }
            }
            return mp(0, 0);
        }
        else {
            if (sz(vals)) {
                int sum = 0;
                FOR(i, 0, sz(vals2)) {
                    sum += vals2[i];
                }
                int total = 0, mx = 0;
                FOR(i, 0, sz(vals)) {
                    if (vals[i] <= sum - vals2[i]) {
                        total++;
                    }
                    chkmax(mx, max(sum % 2, vals[i] - (sum - vals2[i])));
                }
                if (total == sz(vals)) {
                    return mp(sum % 2, res);
                }
                else {
                    return mp(mx, res);
                }
            }
            return mp(0, res);
        }
        return mp(0, 0);
    };
    FOR(u, 0, n) {
