int n,distsum[2010],sousa[2010],amari[2010],vnum[2010];
string s;
vector<int> G[2010];

void calcdist(int v,int par){
	if(s[v] == '1') vnum[v]++;
	for(int to : G[v]){
		if(to != par){
			calcdist(to,v);
			distsum[v] += distsum[to] + vnum[to];
			vnum[v] += vnum[to];
		}
	}
}

void calc(int v,int par){
	int ma = -5,sum = 0;
	vector<int> vec;
	for(int to : G[v]){
		if(to != par){
			sum += distsum[to] + vnum[to];
			if(ma < distsum[to] + vnum[to]){
				ma = distsum[to] + vnum[to];
				vec.pb(to);
			}
		}
	}
	if(sum % 2 == 0 && ma * 2 <= sum){
		sousa[v] = sum / 2;
		return;
	}
	if(sum % 2 && ma * 2 <= sum + 1){
		sousa[v] = sum / 2;
		return;
	}
	for(int mai : vec){
		calc(mai,v);
		if(sum % 2){
			if((ma - sousa[mai] * 2) * 2 <= sum - sousa[mai] * 2){
				sousa[v] = sum / 2;
				return;
			}
		}
		else{
			if((ma - sousa[mai] * 2) * 2 <= sum - sousa[mai] * 2 + 1){
				sousa[v] = sum / 2;
				return;
			}
		}
	}
	sousa[v] = sum - ma;
	return;
}

