		//for(int j = 0;j < n;j++) cout << sousa[j] << " ";
		if(sousa[i] * 2 == distsum[i]) chmin(ans,sousa[i]);
		//cout << endl;
	}
	if(ans == INF) cout << -1 << endl;
	else cout << ans << endl;
}

