vector<int64> cnt, dep;
string S;

PLL dfs(int64 idx, int64 p) {
  if (S[idx] == '1') cnt[idx]++;
  vector<PLL> ei; // mx, mx
  int64 sum = 0, m_v = 0;
  REP (i, G[idx].size()) {
    int64 v= G[idx][i];
    if (v == p) continue;
    PLL ret = dfs(v, idx);
    cnt[idx] += cnt[v];
    dep[idx] += dep[v] + cnt[v];
    ei.emplace_back(ret.fs+cnt[v], ret.sc+cnt[v]);
    sum += ret.sc + cnt[v];
  }
  bool ok = 1;
  int64 mn = 0, mx = 0;
  REP(i, ei.size()) {
    if (G[idx][i] == p) continue;
    if (mn < ei[i].fs && sum-ei[i].sc < ei[i].fs) {
      ok = 0;
      mn = ei[i].fs;
      mx = ei[i].sc;
    }
  }
  if (ok) return PLL(dep[idx]%2, dep[idx]);
  return PLL(mn-sum+mx, dep[idx]);
}

