const int maxn = 2000;

int n;
vector<int> g[maxn];
char s[maxn + 1];
int L[maxn], R[maxn], S[maxn];
int dep[maxn];

void Dfs(int u, int p) {
  S[u] = s[u] - '0', R[u] = 0;
  int sum = 0, mx = 0, id = -1;
  for (int v : g[u]) {
    if (v == p) continue;
    dep[v] = dep[u] + 1;
    Dfs(v, u);
    S[u] += S[v];
    R[u] += R[v] + S[v];
    sum += L[v] + S[v];
    // mx = max(mx, L[v] + S[v]);
    if (L[v] + S[v] > mx) {
      mx = L[v] + S[v];
      id = v;
    }
  }

  if (mx * 2 <= sum) {
    L[u] = 0;
    if (R[u] & 1) L[u] = 1;
  } else {

    int sumr = mx;
    for (int v : g[u]) {
      if (v == p || v == id) continue;
      sumr += R[v];
    }
    if (mx * 2 <= sumr) {
      L[u] = 0;
      if (R[u] & 1) L[u] = 1;
    } else {
      L[u] = mx - (sumr - mx);
    }
  }
}

int Solve(int rt) {
  dep[rt] = 0;
  Dfs(rt, -1);
  if (L[rt] == 0) {
    int sum = 0;
    for (int i = 0; i < n; ++i) {
      if (s[i] == '1') sum += dep[i];
    }
    assert(sum % 2 == 0);
    return sum >> 1;
  } else return 1e9;
}

int main(void) {
  scanf("%d%s", &n, s);
  for (int i = 0; i < n - 1; ++i) {
    int u, v;
    scanf("%d%d", &u, &v);
    --u; --v;
    g[u].push_back(v);
    g[v].push_back(u);
  }
  int ans = 1e9;
  for (int u = 0; u < n; ++u) {
    ans = min(ans, Solve(u));
  }
  if (ans > 1e8) ans = -1;
  printf("%d\n", ans);
}

