int mn[Maxn + 5], mx[Maxn + 5];

void DFS(int u, int fa) {
	siz[u] = mn[u] = mx[u] = 0;
	for(int i = 0; i < (int)G[u].size(); i++) {
		int v = G[u][i];
		if(v == fa) continue;
		DFS(v, u);
		mx[v] += siz[v], mn[v] += siz[v], siz[u] += siz[v];
		if(max(mn[u], mn[v]) <= min(mx[u], mx[v]))
			mn[u] = ((mn[u] & 1) ^ (mn[v] & 1));
		else mn[u] = max(mn[u], mn[v]) - min(mx[u], mx[v]);
		mx[u] += mx[v];
	}
	if(s[u] == '1') siz[u]++;
}

