typedef pair<int, int> P;

struct LCA {
    static const int MAX_V = 100100;
    static const int MAX_LOG_V = 21;

    vector<int> G[MAX_V];

    int parent[MAX_LOG_V][MAX_V];
    int depth[MAX_V];

    void dfs(int v, int p, int d) {
        parent[0][v] = p;
        depth[v] = d;
        for (int i = 0; i < G[v].size(); i++) {
            if (G[v][i] != p) dfs(G[v][i], v, d + 1);
        }
    }

    void init(int root, int V) {
        dfs(root, -1, 0);
        for (int k = 0; k + 1 < MAX_LOG_V; k++) {
            for (int v = 0; v < V; v++) {
                if (parent[k][v] < 0)
                    parent[k + 1][v] = -1;
                else
                    parent[k + 1][v] = parent[k][parent[k][v]];
            }
        }
    }

    int get(int u, int v) {
        if (depth[u] > depth[v]) swap(u, v);
        for (int k = 0; k < MAX_LOG_V; k++) {
            if ((depth[v] - depth[u]) >> k & 1) {
                v = parent[k][v];
            }
        }
        if (u == v) return u;

        for (int k = MAX_LOG_V - 1; k >= 0; k--) {
            if (parent[k][u] != parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }

        return parent[0][u];
    }
};

LCA lca;
class ECompleteCompress {
public:
    void solve(std::istream& cin, std::ostream& cout) {

        int N;
        cin >> N;
        string s;
        cin >> s;


        REP(i, N-1) {
            int a, b;
            cin >> a >> b;
            a--, b--;
            lca.G[a].push_back(b);
            lca.G[b].push_back(a);
        }
        vector<int> v;
        REP(i, s.size()) {
            if (s[i] == '1') v.push_back(i);

        }

        if (v.size() == 1) {
            cout << 0 << endl;
            return;
        }

        lca.init(0, N);
        int mind = INF;
        REP(i, v.size()) {
            bool ok = false;
            REP(j, v.size()) {
                if (i == j) continue;
                int a = v[i];
                int b = v[j];
                int p = lca.get(a, b);
                mind = min(mind, lca.depth[p]);

                int d = lca.depth[a] + lca.depth[b] - (lca.depth[p] - 1) * 2 - 1;
                if (d % 2 == 1) {
                    ok = true;
                }
            }
            if (!ok) {
                cout << -1 << endl;
                return;
            }
        }

        int res = 0;
        REP(i, v.size()) {
            res += lca.depth[v[i]] - lca.depth[mind] - 1;
        }
        cout << res << endl;

    }
};


