typedef pair <int, int> ii;
typedef pair <ii, int> iii;

const int Maxn = 2005;
const int Inf = 1000000000;

int n;
char str[Maxn];
vector <int> neigh[Maxn];
int res = Inf, best, bi;
ii tr[Maxn][Maxn];
int solv[Maxn][Maxn];

ii Traverse(int v, int p)
{
    if (tr[v][p].first == -1) {
        ii res = ii(0, 0);
        if (str[v] == '1') res.second++;
        for (int i = 0; i < neigh[v].size(); i++) {
            int u = neigh[v][i];
            if (u == p) continue;
            ii got = Traverse(u, v);
            res.first += got.first + got.second;
            res.second += got.second;
        }
        tr[v][p] = res;
    }
    return tr[v][p];
}

int Solve(int v, int p)
{
    if (solv[v][p] == -1) {
        vector <iii> seq;
        for (int i = 0; i < neigh[v].size(); i++) {
            int u = neigh[v][i];
            if (u == p) continue;
            ii got = Traverse(u, v);
            seq.push_back(iii(ii(got.first + got.second, got.second), u));
        }
        if (seq.empty()) return solv[v][p] = 0;
        sort(seq.begin(), seq.end());
        int mx = seq.back().first.second + Solve(seq.back().second, v);
        int sum = 0;
        for (int i = 0; i + 1 < seq.size(); i++)
            sum += seq[i].first.first;
        if (sum >= mx) return solv[v][p] = (sum + mx) % 2;
        else return solv[v][p] = mx - sum;
    }
    return solv[v][p];
}

int main()
{
    fill((ii*)tr, (ii*)tr + Maxn * Maxn, ii(-1, -1));
    fill((int*)solv, (int*)solv + Maxn * Maxn, -1);
    scanf("%d", &n);
    scanf("%s", str + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b; scanf("%d %d", &a, &b);
        neigh[a].push_back(b);
        neigh[b].push_back(a);
    }
    for (int i = 1; i <= n; i++) {
        int g = Traverse(i, 0).first;
        if (g % 2 == 0 && g / 2 < res)
            if (Solve(i, 0) == 0) res = g / 2;
    }
    printf("%d\n", res >= Inf? -1: res);
    return 0;
}

