pair<long long, long long> cnt_dfs(int curr, int prev) {
    pair<long long, long long> ret = {0, 0};
    // sum, num
    long long maxi = 0;
    for (auto x: v[curr]) {
        if (x == prev) continue;
        auto tmp = cnt_dfs(x, curr);
        if (s[x] == '1') tmp.second++;
        tmp.first += tmp.second;
        maxi = max(maxi, tmp.first);
        ret = {ret.first + tmp.first, ret.second + tmp.second};
    }
    if (prev != -1) return ret;
    else {
        if (ret.first >= maxi * 2 && ret.first % 2 == 0) return ret;
        else return {-1, 0};
    }
}

