array<int, 3> go(auto& adj, const string& st, int loc, int par) {
    int stones = 0;

    vector<array<int, 2>> cres;
    int sum_lo = 0, sum_hi = 0;
    for (int nbr : adj[loc]) if (nbr != par) {
        auto cr = go(adj, st, nbr, loc);

        stones += cr[2];
        sum_lo += cr[0] + cr[2];
        sum_hi += cr[1] + cr[2];
        cres.push_back({ cr[0] + cr[2], cr[1] + cr[2] });
    }

    int lo = sum_lo, hi = sum_hi;
    if (cres.size()) {
        sort(all(cres));
        auto big = cres.back();
        if (big[0] <= sum_hi - big[1]) {
            lo = sum_lo & 1;
        } else {
            lo = big[0] - (sum_hi - big[1]);
        }
    }

    stones += st[loc] == '1';
    return { lo, hi, stones };
}

