int sumamin = 2e9;

void dfs(int nod, int tata, int & spar, int & simpar)
{
	h[nod] = 1 + h[tata];
	if (has[nod] && (h[nod] & 1))
		simpar += h[nod];
	else if (has[nod])
		spar += h[nod];

	for (auto i : adia[nod])
		if (i != tata)
			dfs(i, nod, spar, simpar);
}

void verif(int centr)
{
	int maxpar = 0, maximpar = 0;
	int sumapar = 0, sumaimpar = 0;
	for (auto i : adia[centr]) {
		int a = 0, b = 0;
		dfs(i, centr, a, b);
		sumapar += a, maxpar = max(maxpar, a);
		sumaimpar += b, maximpar = max(maximpar, b);
	}

	if (2 * maxpar <= sumapar && 2 * maximpar <= sumaimpar && sumapar % 2 == 0 && sumaimpar % 2 == 0)
		sumamin = min(sumamin, (sumapar + sumaimpar) / 2);
}

