int main() {
  do {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
  } while (false);
  int n, ans = INT_MAX;
  cin >> n;
  string str;
  cin >> str;
  vector<vector<int> > adj(n);
  for (int i = 1; i < n; i++) {
    int u, v;
    cin >> u >> v;
    adj[--u].push_back(--v);
    adj[v].push_back(u);
  }
  vector<int> remain(n), siz(n);
  for (int root = 0; root < n; root++) {
    function<int (int, int)> dfs = [&] (int u, int fa) {
      siz[u] = str[u] == '1';
      remain[u] = 0;
      int res = 0, sum = 0;
      vector<int> son;
      for (int v : adj[u]) {
        if (v != fa) {
          res += dfs(v, u);
          siz[u] += siz[v];
          son.push_back(remain[v]);
          sum += remain[v];
        }
      }
      if (son.empty()) {
        remain[u] = siz[u];
        return 0;
      }
      sort(son.begin(), son.end());
      int pairs = min(sum / 2, sum - son.back());
      res += pairs;
      remain[u] = max(0, son.back() - pairs);
      if (u == root && remain[u]) {
        return INT_MAX;
      }
      remain[u] += siz[u];
      return res;
    };
    ans = min(ans, dfs(root, -1));
  }
  cout << (ans == INT_MAX ? -1 : ans) << endl;
  return 0;
}

