const size_t SIZE = 2000;
VV<ll> edges(SIZE);
ll N;
string S;
bitset<SIZE> bs;
const ll inf = 5e15;

PLL dfs(ll cur, ll pre) {
    ll cnt = bs.test(cur), dsum = 0;
    for (ll nxt : edges[cur]) if (nxt != pre) {
        ll a, b;
        tie(a, b) = dfs(nxt, cur);
        cnt += a;
        dsum += b;
    }
    return PLL(cnt, dsum + cnt);
}

PLL dfs_dp(ll cur, ll pre) {
    ll cnt = bs.test(cur), dsum = 0, maxv = 0;
    for (ll nxt : edges[cur]) if (nxt != pre) {
        ll a, b;
        tie(a, b) = dfs_dp(nxt, cur);
        chmax(maxv, b);
        cnt += a;
        dsum += b;
    }
    ll v = (dsum - maxv < maxv ? maxv - (dsum - maxv) : 0);
    return PLL(cnt, v + cnt);
}

bool check(ll cur, ll pre, ll sum, ll val) {
    ll dp = dfs_dp(cur, pre).second;
    ll rest = sum - val;
    return dp <= rest;
}

ll calc(ll root) {
    V<PLL> res;
    ll sum = 0;
    for (ll nxt : edges[root]) {
        auto tmp = dfs(nxt, root);
        sum += tmp.second;
        res.push_back(tmp);
    }

    DEBUG(make_tuple(root, res));
    if (sum & 1) return inf;
    for (ll i = 0; i < edges[root].size(); i++) {
        auto e = res[i];
        ll a = e.second;
        if (sum - a < a && !check(edges[root][i], root, sum, a)) return inf;
    }
    DEBUG(make_tuple(root, sum));
    return sum / 2;
}

ll solve() {
    cin >> N >> S;
    for (ll i = 1; i < N; i++) {
        ll u, v;
        cin >> u >> v;
        u--; v--;
        edges[u].push_back(v);
        edges[v].push_back(u);
    }
    for (ll i = 0; i < N; i++) if (S[i] == '1') bs.set(i, 1);
    if (bs.count() == 1) return 0;
    ll ans = inf;
    for (ll i = 0; i < N; i++) chmin(ans, calc(i));
    return ans == inf ? -1 : ans;
}

