int sd[N],size1[N],size2[N],ne[N],n,x,y,tot,fi[N],zz[N];
char s[N];
void jb(int x,int y){
	ne[++tot]=fi[x];
	fi[x]=tot;
	zz[tot]=y;
}
void dfs(int x,int y,int z){
	sd[x]=z;if (s[x]=='1')size1[x]=sd[x],size2[x]=1;
	else size1[x]=size2[x]=0;
	for (int i=fi[x];i;i=ne[i])
		if (zz[i]!=y){
			dfs(zz[i],x,z+1);
			size1[x]+=size1[zz[i]];
			size2[x]+=size2[zz[i]];
		}
}
int merge(int x,int y){
	vector<int> v;
	int sum=0,num=0,Max=0;
	for (int i=fi[x];i;i=ne[i])
		if (zz[i]!=y){
			int val=merge(zz[i],x);
			v.push_back(size1[zz[i]]-sd[x]*size2[zz[i]]-val);
			sum+=val;
		}
	for (int i=0;i<v.size();i++)num+=v[i],Max=max(Max,v[i]);
	num-=Max;
	if (Max>num)return num*2+sum;
	else return sum+num+Max-(num+Max)%2;
}
