			sum+=size1[zz[j]];
			if (size1[zz[j]]>size1[Max])Max=zz[j];
		}
		if (sum&1)continue;
		int v1=sum-size1[Max],v2=size1[Max];
		v2-=merge(Max,i);
		if (v1<v2)continue;
		ans=min(ans,sum/2);
	}
	if (ans==1e9)puts("-1");
