struct res { int s, t, k; };

res dfs(int i, int p) {
    vector<int> ss, ts;
    int K = 0;
    for (int j : adj[i]) {
        if (j == p) continue;
        res r = dfs(j, i);
        ss.push_back(r.s + r.k);
        ts.push_back(r.t + r.k);
        K += r.k;
    }
    int K1 = s[i] == '1' ? K+1 : K;
    if (ss.empty()) return {0, 0, K1};
    int j = max_element(ts.begin(), ts.end()) - ts.begin();
    int S = 0;
    for (int k = 0; k < ss.size(); k++) {
        if (k != j) S += min(ts[j], ss[k]);
    }
    if (ts[j] <= S) return { accumulate(ss.begin(), ss.end(), 0),
                            accumulate(ts.begin(), ts.end(), 0) % 2, K1 };
    else
        return { accumulate(ss.begin(), ss.end(), 0),
                ts[j] - S, K1 };
}

