//int(E)->to
template<class N,class E>
struct treedp{
	const vvc<E>& g;
	vvc<N> dp1,dp2;
	vc<N> res;
	N dfs1(int v,int p){
		N tmp;tmp.init(v);
		dp1[v].pb(tmp);
		E up;
		for(auto e:g[v])
			if(e!=p)
				dp1[v].pb(dfs1(e,v));
			else
				up=e;
		dp2[v]=dp1[v];
		rng(i,1,dp2[v].size())
			dp2[v][i]=dp2[v][i-1]+dp2[v][i];
		if(p==-1)return N();
		else return dp2[v].back().up(up);
	}
	void dfs2(int v,int p,N cur){
		res[v]=cur+dp2[v].back();
		per(i,g[v].size()){
			auto e=g[v][i];
			if(e==p)continue;
			dp2[v].pop_back();
			dfs2(e,v,(cur+dp2[v].back()).up(e));
			cur=cur+dp1[v].back();
			dp1[v].pop_back();
		}
	}
	treedp(const vvc<E>&gg):g(gg),dp1(g.size()),dp2(g.size()),res(g.size()){
		dfs1(0,-1);
		N tmp;tmp.init(0);
		dfs2(0,-1,tmp);
	}
};

vi cnt;

struct N{
	int v,a,b,c;
	pi mx;
	void init(int vv){
		v=vv;
		a=cnt[v];
		b=c=0;
		mx=pi(0,0);
	}
	N up(int to)const{
		return N{to,a+cnt[to],b+a,c+a,pi(b+a,c+a)};
	}
	N operator+(const N&r)const{
		assert(v==r.v);
		int sum=b+r.b;
		int mn;
		pi z=max(mx,r.mx);
		if(z.b>=sum-z.a)
			mn=z.b-(sum-z.a);
		else
			mn=sum%2;
		return N{v,a+r.a-cnt[v],sum,mn,z};
	}
};

