int dfs (int u, int p) {
  subc[u] = token[u];
  maxp[u] = 0;
  minp[u] = 0;
  pair<int, int> bigch = {-1, -1};
  for (int nxt : adj[u]) {
    if (nxt != p) {
      dfs(nxt, u);
      subc[u] += subc[nxt];
      maxp[u] += maxp[nxt];
      bigch = max(bigch, make_pair(minp[nxt], nxt));
    }
  }

  if (bigch.first != -1) {
    for (int nxt : adj[u]) {
      if (nxt != p && nxt != bigch.second) {
        bigch.first -= maxp[nxt];
      }
    }

    if (bigch.first < 0) minp[u] = maxp[u] % 2;
    else minp[u] = bigch.first;
  } else {
    minp[u] = 0;
  }

  if (u == p) {
    // cerr << u << " " << minp[u] << " " << maxp[u] << endl;
    if (minp[u] == 0) return maxp[u] / 2;
    else return 1 << 30;
  } else {
    maxp[u] += subc[u];
    if (subc[u] - token[u] != 0) minp[u]++;
    if (token[u]) minp[u]++;
    //  cerr << " " << u << " " << minp[u] << " " << maxp[u] << endl;
    return 0;
  }
}

