struct ctx {
	ll l = 0, sm = 0, sz = 0;
	vector<ctx> c;
	void add(ctx a) { c.pb(a); }
	void process(int f, int rt) {
		sz = 0;
		ll msm = 0, ml = 0;
		for(auto &i : c) {
			sz += i.sz;
			sm += i.sm;
			l += i.l;
			msm = max(msm, i.sm);
			ml = max(ml, i.l);
		}
		if(2*msm <= sm) l = sm&1;
		for(auto &i : c) if(i.sm < ml) ml = -1;
		if(ml != -1) {
			if(c.size()>1) l = sm&1;
		}
		sz += f;
		//cout << l << " " << sm << " " << sz << "\n";
		if(!rt) {
			sm += sz;
			l += sz;
		}
		//cout << l << " " << sm << " " << sz << "\n";
		c.clear();
	}
};
