		c += t.first;
	}
	if (z.empty())return make_pair(c, make_pair(sm, sma));
	sort(z.begin(), z.end());
	int s = 0;
	f(i, 0, z.size() - 1)s += z[i];
	if (s >= z.back()){
		an += s + z.back() >> 1;
		if (s + z.back() & 1)++sm;
