        neigh[a].push_back(b);
        neigh[b].push_back(a);
    }
    for (int i = 1; i <= n; i++) {
        int g = Traverse(i, 0, 0).first;
        if (g % 2 == 0 && g / 2 < res)
            if (Solve(i, 0) == 0) res = g / 2;
    }
    printf("%d\n", res >= Inf? -1: res);
    return 0;
}

