#include <bits/stdc++.h>
using namespace std;

const int maxn = 2000 + 5;
const int inf = 1e9;
vector<int> g[maxn], sub[maxn];
int n;
bool seen[maxn];
char s[maxn];

int dfs(int x, int p, int d) {
    bool root = s[x] == '1';
    int res = 0;
    for (int i = 0; i < (int)g[x].size(); ++i) {
        int u = g[x][i];
        if (u == p) continue;
        res += dfs(u, x, d + 1);
        if ((int)sub[x].size() < (int)sub[u].size())
            sub[x].swap(sub[u]);

        for (int j = 0; j < (int)sub[u].size(); ++j) {
            while (!sub[x].empty() && sub[u][j] > d) {
                int y = sub[x].back();
                sub[x].pop_back();
                int k = min(sub[u][j] - d, y - d);
                sub[u][j] -= k;
                y -= k;
                res += k;
                root |= y == d;
                root |= sub[u][j] == d;
                if (y > d) sub[x].push_back(y);
            }
        }
        for (int j = 0; j < (int)sub[u].size(); ++j) {
            if (sub[u][j] > d && !seen[sub[u][j]]) {
                seen[sub[u][j]] = true;
                sub[x].push_back(sub[u][j]);
            }
        }
        for (int j = 0; j < (int)sub[u].size(); ++j)
            seen[sub[u][j]] = false;
    }
    if (root) sub[x].push_back(d);
    return res;
}

int solve(int r) {
    for (int i = 0; i < n; ++i) sub[i].clear();
    int res = dfs(r, -1, 0);
    if ((int)sub[r].size() == 1 && sub[r][0] == 0) return res;
    return inf;
}

int main() {
    scanf("%d", &n);
    scanf("%s", s);
    for (int i = 0; i < n - 1; ++i) {
        int u, v; scanf("%d%d", &u, &v);
        --u, --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    int ans = inf;
    for (int i = 0; i < n; ++i) 
        ans = min(ans, solve(i));

    if (ans == inf) ans = -1;
    printf("%d\n", ans);
    return 0;
}

