struct interval {
  int l = 0, r = 0;
};

bool overlap(interval a, interval b) {
  return a.r >= b.l && a.l <= b.r;
}

interval merge(interval a, interval b) {
  /*
  int l = 1e9;
  int r = -1e9;
  for (int i = a.l; i <= a.r; i += 2) {
    for (int j = b.l; j <= b.r; j += 2) {
      l = min(l, i + j - 2 * min(i, j));
      r = max(r, i + j);
    }
  }
  */
  int l;
  if (overlap(a, b)) {
    l = (a.l + b.l) % 2 == 0 ? 0 : 1;
  } else {
    if (a.r > b.l) swap(a, b);
    l = b.l - a.r;
  }
  int r = a.r + b.r;
  return {l, r};
}

