const int MN = 5005;
const int Inf = 0x3f3f3f3f;

int N, A[MN], Ans;
std::vector<int> G[MN];

int siz[MN], mxf[MN], mnf[MN], szg[MN], mxg[MN], mng[MN];
void DFS0(int u, int fz) {
	siz[u] = A[u];
	int mxid = 0;
	for (auto v : G[u]) if (v != fz) {
		DFS0(v, u);
		siz[u] += siz[v];
		mxf[u] += mxf[v] + siz[v];
		if (mxf[mxid] + siz[mxid] < mxf[v] + siz[v]) mxid = v;
	}
	mnf[u] = std::max(mnf[mxid] + siz[mxid] - (mxf[u] - mxf[mxid] - siz[mxid]), mxf[u] & 1);
}
void DFS1(int u, int fz) {
	int id1 = 0, mx1 = mxg[u] + szg[u], mn1 = mng[u] + szg[u];
	int id2 = -1, mx2 = -1, mn2 = 1;
	for (auto v : G[u]) if (v != fz) {
		if (mxf[v] + siz[v] > mx2)
			id2 = v,
			mx2 = mxf[v] + siz[v],
			mn2 = mnf[v] + siz[v];
		if (mx2 > mx1)
			std::swap(id1, id2),
			std::swap(mx1, mx2),
			std::swap(mn1, mn2);
	}
	int mx0 = mxf[u] + mxg[u] + szg[u];
	int now = std::max(mn1 - (mx0 - mx1), mx0 & 1);
	if (now == 0) Ans = std::min(Ans, mx0 / 2);
	for (auto v : G[u]) if (v != fz) {
		szg[v] = szg[u] + siz[u] - siz[v];
		mxg[v] = mx0 - mxf[v] - siz[v];
		int mx = mx1, mn = mn1;
		if (id1 == v) mx = mx2, mn = mn2;
		mng[v] = std::max(mn - (mxg[v] - mx), mxg[v] & 1);
		DFS1(v, u);
	}
}

