inline int add(int a, int b) {
    int res = a + b;
    if (res < 0) res += M;
    if (res >= M) res -= M;
    return res;
}

inline int mul(int a, int b) {
    return (a * (ll) b) % M;
}

inline int bin(int a, int n) {
    int res = 1;
    while (n) {
        if (n % 2 == 0) {
            a = mul(a, a);
            n /= 2;
        } else {
            res = mul(res, a);
            n--;
        }
    }
    return res;
}

inline int inv(int x) {
    return bin(x, M - 2);
}

inline int dv(int a, int b) {
    return mul(a, inv(b));
}

