    std::vector<int> min(N), max(N), cnt(N);
    auto dfs = [&](auto&& self, const int s, const int p) -> void {
        cnt[s] = (S[s] == '1' ? 1 : 0), min[s] = max[s] = 0;
        std::priority_queue<int> Q;
        for (const int to : T[s]) {
            if (to == p) { continue; }
            self(self, to, s);
            Q.push(min[to] + cnt[to]), max[s] += max[to] + cnt[to], cnt[s] += cnt[to];
        }
        while (Q.size() > 1) {
            int T = Q.top();
            Q.pop();
            while (T > 0 and not Q.empty()) {
                const int e = Q.top();
                Q.pop();
                T--;
                if (e > 1) { Q.push(e - 1); }
            }
            if (T > 0) { Q.push(T); }
        }
        min[s] += (Q.empty() ? 0 : Q.top());
    };
