int N;
string S;
vector<vector<int>> g;
vector<int> sum, dp, cnt;

void dfs (int x, int p) {
    cnt[x] = S[x];

    vector<int> sons;

    for (auto v : g[x]) {
        if (v != p) {
            dfs(v, x);

            cnt[x] += cnt[v];
            sum[x] += sum[v] + cnt[v];          

            sons.push_back(v);
        }
    }

    if (!sons.size()) {
        dp[x] = sum[x];
        return;
    }

    int tot = 0;

    vector<pair<int, int>> cand;

    for (auto v : sons) {
        int R = sum[v] + cnt[v];
        int L = dp[v] + cnt[v];

        tot += R;

        cand.emplace_back(R, L);
    }

    sort(cand.rbegin(), cand.rend());

    int mx = cand[0].second;
    int other = 0;

    for (int i = 1; i < sons.size(); i++) {
        other += cand[i].first;
    }

    dp[x] = max(sum[x] % 2, mx - other);
}

int main() {
