using namespace std;

pair<int, pair<int, int>> calc(int pos, int prev, const vector<vector<int>>& g, const string& S){
    vector<pair<int, int>> tmp;
    pair<int, int> res = make_pair(0, 0);
    pair<int, int> maxChild = make_pair(0, 0);
    int node = 0;
    for(auto& t : g[pos]){
        if(t == prev) continue;
        auto cur = calc(t, pos, g, S);
        node += cur.first;
        cur.second.first += cur.first;
        cur.second.second += cur.first;
        tmp.push_back(cur.second);
        res.second += tmp.back().second;
        if(tmp.back().first > maxChild.first || (tmp.back().first == maxChild.first && tmp.back().second < maxChild.second)){
            maxChild = tmp.back();
        }
    }
    if(maxChild.first > res.second - maxChild.second){
        res.first = maxChild.first - (res.second - maxChild.second);
    } else {
        res.first = res.second%2;
    }
    node += S[pos] - '0';
    return make_pair(node, res);
}

int main(){
    int N;
    while(cin >> N){
        string S; cin >> S;
        vector<vector<int>> g(N);
        for(int i=0;i<N-1;i++){
            int a, b; cin >> a >> b;
            --a; --b;
            g[a].push_back(b);
            g[b].push_back(a);
        }
        int res = -1;
        for(int i=0;i<N;i++){
            if(calc(i, -1, g, S).second.first) continue;
            vector<int> dist(N, -1); dist[i] = 0;
            queue<int> qu; qu.push(i);
            int sum = 0;
            while(!qu.empty()){
                int c = qu.front(); qu.pop();
                sum += (S[c]-'0') * dist[c];
                for(auto& t : g[c]){
                    if(dist[t] != -1) continue;
                    dist[t] = dist[c] + 1;
                    qu.push(t);
                }
            }
            if(res == -1 || res > sum/2) res = sum/2;
        }
        cout << res << endl;
    }
}

