int N, Head[Max_N], Total, To[Max_N << 1], Next[Max_N << 1], Dist[Max_N], Sum[Max_N], Ans = 0X3F3F3F3F, F[Max_N];
char S[Max_N];

inline void Add_Edge(int s, int t)
{
	++Total, To[Total] = t, Next[Total] = Head[s], Head[s] = Total;
}

void dfs(int u, int fa)
{
	Sum[u] = Dist[u] * (S[u] - '0');
	for (int i = Head[u], v;i;i = Next[i])
		if ((v = To[i]) != fa)
			Dist[v] = Dist[u] + 1, dfs(v, u), Sum[u] += Sum[v];
}

void dp(int u, int fa)
{
	int Max(0), Son = 0;
	for (int i = Head[u], v;i;i = Next[i])
		if ((v = To[i]) != fa)
		{
			dp(v, u);
			Max = max(Max, Sum[v]);
			if (Sum[v] > Sum[Son])
				Son = v;
		}
	if (Son == 0)
	{
		F[u] = 0;
		return;
	}
	Sum[u] -= Dist[u];
	if (Sum[u] - Max >= Max)
		F[u] = Sum[u] / 2;
	else
	{
		F[u] = Sum[u] - Max;
		int cnt = Max - (Sum[u] - Max);
		F[u] += min(F[Son], cnt / 2);
	}
	Sum[u] += Dist[u];
}

int main()
{
	gi(N);
	scanf("%s", S + 1);
	for (int i = 1, u, v;i != N;++i)
		gi(u), gi(v), Add_Edge(u, v), Add_Edge(v, u);
	for (int root = 1;root <= N;++root)
	{
		Dist[root] = 0, dfs(root, -1);
		if ((Sum[root] & 1) == 0 && (dp(root, -1), F[root] == (Sum[root] >> 1)))
			Ans = min(Ans, F[root]);
	}
	if (Ans == 0X3F3F3F3F)
		printf("-1");
	else
		printf("%d", Ans);
	return 0;
}

