  for (int i = 1; i < n; i++) {
    int u, v;
    cin >> u >> v;
    adj[--u].push_back(--v);
    adj[v].push_back(u);
  }
  vector<int> remain(n);
  for (int root = 0; root < n; root++) {
    function<int (int, int)> dfs = [&] (int u, int fa) {
      remain[u] = 0;
      int res = 0, sum = 0;
      vector<int> son;
      for (int v : adj[u]) {
        if (v != fa) {
          res += dfs(v, u);
          son.push_back(remain[v]);
          sum += remain[v];
        }
      }
      if (son.empty()) {
        remain[u] = str[u] == '1';
        return 0;
      }
      sort(son.begin(), son.end());
      if (sum % 2) {
        son.back()--;
        remain[u] += 2;
      }
      if (son.back() > sum / 2) {
        remain[u] = (son.back() - sum / 2) * 2;
        res += (sum - remain[u] / 2) / 2;
      } else {
        res += sum / 2;
      }
      if (u == root && remain[u]) {
        return INT_MAX;
      }
      remain[u] += str[u] == '1';
      return res;
    };
    ans = min(ans, dfs(root, -1));
