vector<int> bfs(const vector<vector<int>> &G, int s) {
    vector<int> ret(G.size(),-1);
    ret[s] = 0;
    queue<int> que;
    que.emplace(s);
    while (!que.empty()) {
        int v = que.front(); que.pop();
        for (auto nv : G[v]) {
            if (ret[nv] != -1) continue;
            ret[nv] = ret[v] + 1;
            que.emplace(nv);
        }
    }

    return ret;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N; cin >> N;
    string S; cin >> S;
    vector<vector<int>> G(N);
    rep(i,N-1) {
        int u,v; cin >> u >> v;
        --u; --v;
        G[u].emplace_back(v);
        G[v].emplace_back(u);
    }

    auto color = bfs(G,0);
    int B = 0, W = 0;
    rep(i,N) {
        color[i] &= 1;
        if (S[i]=='1') {
            if (color[i]) B++;
            else W++;
        }
    }

    int ans = 1e9;
    rep(r,N) {
        if (color[r] and W&1) continue;
        if (!color[r] and B&1) continue;
        bool ok = false;
        vector<int> MAX(N),MIN(N),cnt(N);
        auto dfs=[&](auto&& self, int v, int pv)->void {
            cnt[v] = S[v]=='1';
            for (auto nv : G[v]) {
                if (nv==pv) continue;
                self(self,nv,v);
                cnt[v] += cnt[nv];
                MAX[v] += MAX[nv];
            }

            for (auto nv : G[v]) {
                if (nv==pv) continue;
                int M = MAX[v] - MAX[nv];
                int m = MIN[nv];
                chmax(MIN[v],max(0,m-M));
            }
            if (pv != -1) {
                MAX[v] += cnt[v];
                MIN[v] += cnt[v];
            } else {
                ok = MIN[v]==0;
            }
        };
        dfs(dfs,r,-1);
        if (ok) chmin(ans,MAX[r]/2);
    }

    cout << (ans==1e9 ? -1 : ans) << ln;
}

