ll gcd(ll a,ll b) { return b==0?a:gcd(b,a%b); }

const int MAXN=2000;

int n;
char spiece[MAXN+1];
vector<int> adj[MAXN];

bool done[MAXN][MAXN+1];
int sum[MAXN][MAXN+1];
int cnt[MAXN][MAXN+1];
int dp[MAXN][MAXN+1];

void rec(int at,int par) {
	if(done[at][par]) return; else done[at][par]=true;
	sum[at][par]=0,cnt[at][par]=spiece[at]-'0';
	int heavy=-1;
	REPSZ(i,adj[at]) {
		int to=adj[at][i];
		if(to==par) continue;
		rec(to,at);
		cnt[at][par]+=cnt[to][at];
		sum[at][par]+=sum[to][at]+cnt[to][at];
		if(heavy==-1||cnt[to][at]+sum[to][at]>cnt[heavy][at]+sum[heavy][at]) heavy=to;
	}
	if(heavy==-1||2*(cnt[heavy][at]+sum[heavy][at])<=sum[at][par]) {
		dp[at][par]=sum[at][par]%2;
	} else {
		int other=sum[at][par]-cnt[heavy][at]-sum[heavy][at];
		if(dp[heavy][at]+cnt[heavy][at]<=other) {
			dp[at][par]=sum[at][par]%2;
		} else {
			dp[at][par]=dp[heavy][at]+cnt[heavy][at]-other;
		}
	}
	//printf("rec(%d,%d): cnt=%d sum=%d dp=%d\n",at+1,par==n?0:par+1,cnt[at][par],sum[at][par],dp[at][par]);
}

int solve() {
	REP(i,n) REPE(j,n) done[i][j]=false;
	int ret=INT_MAX;
	REP(i,n) {
		rec(i,n);
		if(dp[i][n]==0) {
			assert(sum[i][n]%2==0);
			ret=min(ret,sum[i][n]/2);
		}
	}
	return ret==INT_MAX?-1:ret;
}

void run() {
	scanf("%d",&n);
	scanf("%s",spiece); assert(strlen(spiece)==n);
	REP(i,n-1) { int a,b; scanf("%d%d",&a,&b); --a,--b; adj[a].PB(b); adj[b].PB(a); }
	printf("%d\n",solve());
}

int main() {
	run();
	return 0;
}

