void solve() {
  int N; cin >> N;
  string s; cin >> s;
  vector<vi32> edges(N);
  rep(i, N - 1) {
    int a, b; cin >> a >> b;
    a--, b--;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }
  struct Data {
    int count = 0;
    int dists = 0;
  };
  vector<vector<Data>> dp(N);
  vi32 par(N, -1);

  auto merge = [](Data a, Data b) {
    a.count += b.count;
    a.dists += b.dists;
    return a;
  };

  function<Data(int, int)> dfs = [&](int v, int p) {
    int n = edges[v].size();
    dp[v] = vector<Data>(n);

    Data ret;
    rep(i, n) {
      int u = edges[v][i];
      if (u == p) {
        par[v] = i;
        continue;
      }
      Data r = dfs(u, v);
      if (s[u] == '1') r.count++;
      r.dists += r.count;
      dp[v][i] = r;
      ret = merge(ret, r);
    }
    return ret;
  };

  vector<vi32> lists(N);

  function<void(int, Data)> bfs = [&](int v, Data d) {
    if (par[v] != -1) {
      int p = edges[v][par[v]];
      if (s[p] == '1') d.count++;
      d.dists += d.count;
      dp[v][par[v]] = d;
    }
    int n = edges[v].size();
    vector<Data> dpl(n + 1);
    vector<Data> dpr(n + 1);
    repp(i, n) dpl[i + 1] = merge(dpl[i], dp[v][i]);
    rrep(i, n) dpr[i] = merge(dpr[i + 1], dp[v][i]);

    rep(i, n) lists[v].push_back(dp[v][i].dists);

    rep(i, n) if (i != par[v]) {
      int u = edges[v][i];
      bfs(u, merge(dpl[i], dpr[i + 1]));
    }
  };

  dfs(0, -1);
  bfs(0, Data());

  rep(i, N) {
    int sum = accumulate(all(lists[i]), 0);
    if (sum % 2 == 1) continue;
    sort(all(lists[i])), reverse(all(lists[i]));
    if (sum < lists[i][0] * 2) continue;
    cout << sum / 2 << '\n';
    return;
  }

  cout << -1 << '\n';
}

