    pair<ll, ll> p = dfs2(to, now);
    p.second += state[to].first;
    ret.first += p.first;
    ret.second += p.second;
    S.first += p.first;
    S.second += p.second;

    if(m<p.second){
      m = p.second;
      m_tm = p.first;
    }
  }
  if(m==-1) return ret;
  S.first -= m_tm;
  S.second -= m;
  if(S.second+S.first*2>=m){
    ll tm = (S.second+m)/2;
    ret.first += tm;
    ret.second -= tm*2;
  }else{
    ll tm = S.second+S.first*2;
    ret.first -= S.first;
    ret.second += S.first*2;

    ret.first += tm;
    ret.second -= tm*2;
  }
  return ret;
}

