long long solve() {
  long long ans = inf;
  for(int i = 0; i < n; ++i) {
    long long maxnum = 0, cnt = 0;
    uf = Unionfind(n);
    bfs(i);
    memo.assign(n, 0);
    for(int j = 0; j < n; ++j)
      if(s[j] == '1') memo[uf.root(j)] += dis[j];
    for(int j = 0; j < n; ++j) {
      cnt += memo[j];
      maxnum = max(maxnum, memo[j]);
    }
    if(cnt % 2 == 0 && maxnum <= cnt - maxnum)
      ans = min(ans, cnt / 2);
  }
  if(ans == inf) return -1;
  return ans;
}

void bfs(long long st) {
  dis.assign(n, inf);
  queue<pair<long long, long long>> qu;
  dis[st] = 0;
  for(int i = 0; i < edge[st].size(); ++i) {
    qu.push({edge[st][i], edge[st][i]});
    dis[edge[st][i]] = 1;
  }
  while(!qu.empty()) {
    pair<long long, long long> now = qu.front();
    qu.pop();
    for(int i = 0; i < edge[now.fi].size(); ++i) {
      long long nextp = edge[now.fi][i];
      if(dis[nextp] == inf) {
        dis[nextp] = dis[now.fi] + 1;
        uf.uni(nextp, now.se);
        qu.push({nextp, now.se});
      }
    }
  }
}

