void DFS1(int x, int f, int dep) {
	Dep[x] = dep;
	Sz[x] = ch[x] - '0';
	for(int T = Head[x]; T; T = Next[T]) if(Go[T] != f) {
		DFS1(Go[T], x, dep + 1);
		F[Go[T]].x += Sz[Go[T]];
		F[Go[T]].y += Sz[Go[T]];
		Sz[x] += Sz[Go[T]];
	}
	ll sum = 0, mx = 0, tot = 0, res = 0, ans = 0, mxv;
	for(int T = Head[x]; T; T = Next[T]) if(Go[T] != f) {
		if(F[Go[T]].x > mx) mx = F[Go[T]].x, mxv = Go[T];
		res += F[Go[T]].y - F[Go[T]].x;
		sum += F[Go[T]].x;
		tot += F[Go[T]].y;
	}
	if(mx * 2 <= sum) {
		F[x] = PLL(tot & 1, tot);
	} else {
		res -= F[mxv].y - F[mxv].x;
		ll tmp = 2 * mx - sum;
		if(tmp <= res) F[x] = PLL(tot & 1, tot); else F[x] = PLL(tmp - res, tot);
	}
}

