struct X {
  using type = P;
  // その頂点から出ていく値から入ってくる値を計算する
  static vector<type> evaluate(const vector<type>& value, const ll id) {
    ll sum = 0, units = 0;
    if (s[id] == '1') ++units;
    each(p, value) {
      sum += p.first;
      units += p.second;
    }
    vector<P> res;
    each(p, value) {
      sum -= p.first;
      units -= p.second;
      res.eb(sum + units, units);
      sum += p.first;
      units += p.second;
    }
    return res;
  }
  // (辺数-1)個の出ていく値から1個の入ってくる値を計算する
  static type merge(const vector<type>& value, const ll id) {
    const ll n = value.size();
    ll sum = 0, units = 0;
    if (s[id] == '1') ++units;
    each(p, value) {
      sum += p.first;
      units += p.second;
    }
    sum += units;
    return P(sum, units);
  }
};

