il void add(int u,int v){to[++sze]=v,nx[sze]=hd[u],hd[u]=sze;}

il void dfs(int u,int F)
{
	sz[u]=s[u]; int i,v,mx=0;
	for (i=hd[u]; i; i=nx[i]) if ((v=to[i])!=F)
