          dw[w]+=dw[g[j].fi];
          ds[w]+=(dw[g[j].fi]+ds[g[j].fi]);
        }
        //printf("%lld %lld : %lld %lld\n",t,w,dw[w],ds[w]);
      }
      if(ds[w]==0){r=llmin(0,r);continue;}
      if(ds[w]%2==1){continue;}
      w=t;a=ds[w];
      while(1){
        //fprintf(stderr,"%lld %lld <%lld>\n",t,w,a);
        f=1;b=-1;
        for(j=x[w].st;j<x[w].st+x[w].kz;j++){
          if(par[w]==g[j].fi){continue;}
          if((ds[w]) == (dw[g[j].fi]+ds[g[j].fi])){
            f=-1;break;
          }
          if(b==-1){b=g[j].fi;}
          else if((dw[g[j].fi]+ds[g[j].fi]) > (dw[b]+ds[b])){
            b=g[j].fi;
          }
        }
        if(f==-1){break;}
        if(2*(dw[b]+ds[b])<=ds[w]){
          a-=ds[w];
          if(a<=0){r=llmin(ds[t]/2,r);}
          break;
        }
        else{
          a-=(2*(ds[w]-(dw[b]+ds[b])));
          if(a<=0){r=llmin(ds[t]/2,r);break;}
          w=b;
        }
      }
    }
    if(r==llinf){r=-1;}
    printf("%lld\n",r);
    return 0;
}

