    static class Node {
    	int idx;
        HashSet<Integer> nbr = new HashSet<>();
        boolean vst = false;
        int longestpathorder = -1;
        int mark = 0;
        int tesuu = 0;
        void dfs(int depth) {
        	vst = true;
        	if(depth > maxdepth) {
        		maxdepth = depth;
        		maxidx1 = idx;
        	}
        	for(int x : nbr) {
        		if(!V[x].vst) {
        			V[x].dfs(depth+1);
        		}
        	}
        }
        int putLongestPath(int depth) {
        	vst = true;
        	if(idx == maxidx2) {
        		longestpathorder = depth;
        	}
        	for(int x : nbr) {
        		if(!V[x].vst) {
        			int order = V[x].putLongestPath(depth+1);
        			if(order >= 0) {
        				longestpathorder = order;
                	}
        		}
        	}
        	return longestpathorder - 1;
        }

        void dfs2() {
        	vst = true;
        	for(int x : nbr) {
        		if(!V[x].vst) {
        			if(V[x].longestpathorder >= 0) {
        				V[x].dfs2();
        			} else {
        				int tmp = V[x].addTesuu(1);
        				mark += tmp;
        				tesuu = tmptesuu;
        				tmptesuu = 0;
        			}
        		}
        	}
        }

        int addTesuu(int depth) {
        	vst = true;
        	int marksum = mark;
        	if(mark == 1) {
        		tmptesuu += depth;
        	}
        	for(int x : nbr) {
        		if(!V[x].vst) {
        			if(V[x].longestpathorder == -1) {
        				int tmp = V[x].addTesuu(depth+1);
        				marksum += tmp;
        			}
        		}
        	}
        	return marksum;
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte() {
            if(ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch(IOException e) {
                    e.printStackTrace();
                }
                if(buflen <= 0) {
                    return false;
                }
            }
            return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        private void skipUnprintable() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}
        public boolean hasNext() { skipUnprintable(); return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            return Long.parseLong(next());
        }
        public int nextInt(){
            return Integer.parseInt(next());
        }
        public double nextDouble(){
            return Double.parseDouble(next());
        }
    }
