/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ECompleteCompress solver = new ECompleteCompress();
        solver.solve(1, in, out);
        out.close();
    }

    static class ECompleteCompress {
        char[] s;
        List<Integer>[] g;

        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            s = in.nextChars();

            g = new List[n];
            for (int i = 0; i < n; i++) {
                g[i] = new ArrayList<>();
            }
            for (int i = 0; i < n - 1; i++) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;
                g[a].add(b);
                g[b].add(a);
            }

            long ans = Long.MAX_VALUE;
            for (int v = 0; v < n; v++) {
                long sum = 0;
                long max = 0;
                for (int t : g[v]) {
                    long val = dfs2(t, v);
                    long cnt = val >>> 32;
                    long s = val & 0xFFFFFFFFL;
                    s += cnt;
                    sum += s;
                    max = Math.max(max, s);
//                dump(v, t, s, sum, max);
                }
//            dump(v, sum, max);
                if (sum % 2 == 0 && sum - max >= max) {
                    ans = Math.min(ans, sum / 2);
                }
            }
            if (ans == Long.MAX_VALUE) ans = -1;
            out.println(ans);
        }

        long dfs2(int v, int p) {
            long curCnt = s[v] - '0';
            long curSum = 0;
            for (int t : g[v]) {
                if (t != p) {
                    long val = dfs2(t, v);
                    long cnt = val >>> 32;
                    long sum = val & 0xFFFFFFFFL;
                    sum += cnt;
                    curSum += sum;
                    curCnt += cnt;
                }
            }
            return curCnt << 32 | curSum;
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        public char[] nextChars() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            return Arrays.copyOf(str, len);
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.io.IOException;
