import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Collection;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;
import java.util.BitSet;
import java.util.Queue;
import java.io.BufferedReader;
import java.util.ArrayDeque;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author anand.oza
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ECompleteCompress solver = new ECompleteCompress();
        solver.solve(1, in, out);
        out.close();
    }

    static class ECompleteCompress {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            char[] sChars = in.next().toCharArray();
            int[] s = new int[n];
            for (int i = 0; i < n; i++) {
                s[i] = sChars[i] == '1' ? 1 : 0;
            }

            int[] a = new int[n - 1];
            int[] b = new int[n - 1];

            List<Integer>[] edges = new List[n];
            for (int i = 0; i < n; i++) {
                edges[i] = new ArrayList<>();
            }

            for (int i = 0; i < n - 1; i++) {
                a[i] = in.nextInt() - 1;
                b[i] = in.nextInt() - 1;
                edges[a[i]].add(i);
                edges[b[i]].add(i);
            }

            int answer = Integer.MAX_VALUE;
            for (int center = 0; center < n; center++) {
                int branchCount = edges[center].size();
                int[] branches = new int[n];
                for (int i = 0; i < branchCount; i++) {
                    int e = edges[center].get(i);
                    int root = a[e] + b[e] - center;
                    BitSet visited = new BitSet();
                    visited.set(center);

                    Queue<ECompleteCompress.Node> q = new ArrayDeque<>();
                    q.add(new ECompleteCompress.Node(root, 1));
                    visited.set(root);

                    while (!q.isEmpty()) {
                        ECompleteCompress.Node cur = q.poll();
                        branches[root] += s[cur.index] * cur.dist;

                        for (int nextEdge : edges[cur.index]) {
                            int next = a[nextEdge] + b[nextEdge] - cur.index;
                            if (!visited.get(next)) {
                                q.add(new ECompleteCompress.Node(next, cur.dist + 1));
                                visited.set(next);
                            }
                        }
                    }
                }

                int branchTotal = 0;
                for (int branch : branches) {
                    branchTotal += branch;
                }

                if (branchTotal % 2 != 0) {
                    continue;
                }

                int maxBranch = 0;
                for (int branch : branches) {
                    maxBranch = Math.max(maxBranch, branch);
                }

                if (maxBranch > branchTotal / 2) {
                    continue;
                }

                answer = Math.min(answer, branchTotal / 2);
            }

            if (answer == Integer.MAX_VALUE) {
                answer = -1;
            }
            out.println(answer);
        }

        static class Node {
            final int index;
            final int dist;

            Node(int index, int dist) {
                this.index = index;
                this.dist = dist;
            }

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.*;
import java.util.*;

public class Main {
    FastScanner in;
    PrintWriter out;

    List<Integer>[] g;
    char[] s;

    int getSum(int v, int p, int h) {
        int res = 0;
        if (s[v] == '1') {
            res = h;
        }
        for (int to : g[v]) {
            if (to == p) {
                continue;
            }
            res += getSum(to, v, h + 1);
        }
        return res;
    }

    int[] merge(int[] a, int[] b) {
        int[] res = new int[]{0, a[1] + b[1], a[2] + b[2]};
        int min = Math.min(a[1], b[1]);
        int max = Math.max(a[0], b[0]);
        if (min >= max) {
            if (res[1] % 2 == 1) {
                res[0] = 1;
            }
        } else {
            res[0] = max - min;
        }
        return res;
    }

    int[] go(int v, int p) {
        int[] res = new int[]{0, 0, 0};
        for (int to : g[v]) {
            if (to == p) {
                continue;
            }
            int[] child = go(to, v);
//            System.err.println("cur v = " + v + ", from "+ to + ", re = " + Arrays.toString(child));
            res = merge(child, res);
        }
        if (s[v] == '1') {
            res[2]++;
        }
        res[0] += res[2];
        res[1] += res[2];
        return res;
    }

    int can(int root) {
        int[] r = go(root, root);
        if (r[0] != r[2]) {
            return Integer.MAX_VALUE;
        }
        return getSum(root, root, 0) / 2;
    }

    void solve() {
        int n = in.nextInt();
        s = in.next().toCharArray();
        g = new List[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i + 1 < n; i++) {
            int fr = in.nextInt() - 1;
            int to = in.nextInt() - 1;
            g[fr].add(to);
            g[to].add(fr);
        }
        int res = Integer.MAX_VALUE;
        for (int root = 0; root < n; root++) {
//            System.err.println("!" + root + " -> " + can(root));
            res = Math.min(res, can(root));
        }
        out.println(res == Integer.MAX_VALUE ? -1 : res);
    }

    void run() {
        try {
            in = new FastScanner(new File("Main.in"));
            out = new PrintWriter(new File("Main.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {

        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new Main().runIO();
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
	static Scanner sc = new Scanner(System.in);
	static ArrayList<ArrayList<Integer>> g = new ArrayList<>();
	static int N;
	static boolean[] S;

	public static void main(String[] args) {
		N = sc.nextInt();
		char[] s = sc.next().toCharArray();
		S = new boolean[N];
		for (int i = 0; i < N; i++) {
			S[i] = s[i] == '1';
		}
		for (int i = 0; i < N; i++) {
			g.add(new ArrayList<>());
		}
		for (int i = 0; i < N - 1; i++) {
			int A = sc.nextInt() - 1;
			int B = sc.nextInt() - 1;
			g.get(A).add(B);
			g.get(B).add(A);
		}
		int ans = Integer.MAX_VALUE;
		for (int i = 0; i < N; i++) {
			Partial res = dfs(i, -1);
//			System.err.println(i + " " + res.max + " " + res.min + " " + res.count);
			if (res.min == 0) {
				ans = Math.min(ans, res.max / 2);
			}
		}
		System.out.println(ans == Integer.MAX_VALUE ? -1 : ans);
	}

	static Partial dfs(int cur, int from) {
		Partial ret = new Partial(0, 0, 0);
		Partial minMax = null;
		int minSum = 0;
		int diffSum = 0;
		for (int i = 0; i < g.get(cur).size(); i++) {
			int n = g.get(cur).get(i);
			if (n == from) continue;
			Partial p = dfs(n, cur);
			minSum += p.min + p.count;
			ret.max += p.max + p.count;
			ret.count += p.count;
			diffSum += p.max - p.min;
			if (minMax == null || p.min + p.count > minMax.min) {
				p.max += p.count;
				p.min += p.count;
				minMax = p;
			}
		}
		if (minMax == null) {
			//
		} else if (minMax.min > minSum - minMax.min) {
			diffSum -= minMax.max - minMax.min;
			int rest = minMax.min - (minSum - minMax.min);
			if (rest < diffSum) {
				ret.min = rest % 2;
			} else {
				ret.min = rest - diffSum;
			}
		} else {
			ret.min = minSum % 2;
		}
		if (S[cur]) {
			ret.count += 1;
		}
//		System.err.println(cur + " " + ret.max + " " + ret.min + " " + ret.count);
		return ret;
	}

	static class Partial {
		int min, max, count;

		public Partial(int min, int max, int count) {
			this.min = min;
			this.max = max;
			this.count = count;
		}
	}

}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		char[] s = ns(n);
		int[] from = new int[n - 1];
		int[] to = new int[n - 1];
		for (int i = 0; i < n - 1; i++) {
			from[i] = ni() - 1;
			to[i] = ni() - 1;
		}
		int[][] g = packU(n, from, to);

		long ans = Long.MAX_VALUE;
		for(int root = 0;root < n;root++){
			int[][] pars = parents3(g, root);
			int[] par = pars[0], ord = pars[1], dep = pars[2];

			int[] des = new int[n];
			int[] wmax = new int[n];
			int[] wmin = new int[n];
			for(int i = n-1;i >= 0;i--){
				int cur = ord[i];
				int wxsum = 0;
				int maxlwx = 0;
				for(int e : g[cur]){
					if(par[cur] == e)continue;

					des[cur] += des[e];
					int lwx = wmax[e] + des[e];
					wxsum += lwx;
					maxlwx = Math.max(maxlwx, lwx);
				}
				int ex = Integer.MAX_VALUE;
				for(int e : g[cur]){
					if(par[cur] == e)continue;
					if(des[e] == 0)continue;
					int lwx = wmax[e] + des[e];
					int lwn = wmin[e] + des[e];
					if(lwx == maxlwx){
						int h = wxsum - lwx;
						ex = Math.min(ex, lwn - h);
						break;
					}
				}
				if(ex != Integer.MAX_VALUE){
					if(ex < 0){
						ex = ex&1;
					}
					wmin[cur] = ex;
					wmax[cur] = wxsum;
				}
				des[cur] += s[cur]-'0';
			}
			if(wmin[root] == 0){
				ans = Math.min(ans, wmax[root] / 2);
			}
		}
		if(ans == Long.MAX_VALUE){
			out.println(-1);
		}else{
			out.println(ans);
		}
	}

	public static int[][] parents3(int[][] g, int root) {
		int n = g.length;
		int[] par = new int[n];
		Arrays.fill(par, -1);

		int[] depth = new int[n];
		depth[0] = 0;

		int[] q = new int[n];
		q[0] = root;
		for (int p = 0, r = 1; p < r; p++) {
			int cur = q[p];
			for (int nex : g[cur]) {
				if (par[cur] != nex) {
					q[r++] = nex;
					par[nex] = cur;
					depth[nex] = depth[cur] + 1;
				}
			}
		}
		return new int[][] { par, q, depth };
	}

	static int[][] packU(int n, int[] from, int[] to) {
		int[][] g = new int[n][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int t : to)
			p[t]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]];
		for (int i = 0; i < from.length; i++) {
			g[from[i]][--p[from[i]]] = to[i];
			g[to[i]][--p[to[i]]] = from[i];
		}
		return g;
	}


	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

import java.io.BufferedReader;
