	static int dfs(int cur, int from, int depth) {
		int ret = S[cur] ? depth : 0;
		for (int n : g.get(cur)) {
			if (n == from) continue;
			ret += dfs(n, cur, depth + 1);
		}
		return ret;
	}

}

