/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author mikit
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        CTests solver = new CTests();
        solver.solve(1, in, out);
        out.close();
    }

    static class CTests {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            // out.setBoolLabel(LightWriter.BoolLabel.YES_NO_FIRST_UP);
            int n = in.ints(), x = in.ints();
            CTests.Test[] tests = new CTests.Test[n];
            for (int i = 0; i < n; i++) {
                tests[i] = new CTests.Test(i, in.ints(), in.ints(), in.ints());
            }
            IntroSort.sort(tests, Comparator.comparing(test -> -test.priority(x)));
            long[] positive = new long[n + 1], negative = new long[n + 1];
            for (int i = 0; i < n; i++) positive[i + 1] = positive[i] + tests[i].positive(x);
            for (int i = n - 1; i >= 0; i--) negative[i] = negative[i + 1] + tests[i].negative(x);
            int margin = -1;
            for (int i = 1; i <= n; i++) {
                if (positive[i] - negative[i] >= 0) {
                    margin = i;
                    break;
                }
            }
            if (margin <= 0) throw new RuntimeException();

            long cap = positive[margin] - negative[margin];
            int reduced = 0;
            while (cap >= tests[margin - 1].u) {
                reduced++;
                cap -= tests[margin - 1].u;
            }

            int required = 0;
            cap = positive[margin - 1] - negative[margin] - tests[margin - 1].l * tests[margin - 1].t;
            while (cap < 0) {
                required++;
                cap += tests[margin - 1].l;
            }


            //System.out.println(reduced);
            //System.out.println(Arrays.toString(tests));
            //System.out.println(margin * x - reduced);
            out.ans(Math.min(margin * x - reduced, (margin - 1) * x + required)).ln();
        }

        private static class Test {
            int index;
            long t;
            long l;
            long u;

            Test(int index, long t, long l, long u) {
                this.index = index;
                this.t = t;
                this.l = l;
                this.u = u;
            }

            long positive(int x) {
                return (x - t) * u;
            }

            long negative(int x) {
                return t * l;
            }

            long priority(int x) {
                return positive(x) + negative(x);
            }

            public String toString() {
                return "Test{" +
                        "index=" + index +
                        ", t=" + t +
                        ", l=" + l +
                        ", u=" + u +
                        '}';
            }

        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

