	public class Data {
		int piece = 0;
		int distance = 0;
		int operate = 0;

		Data(boolean hasPiece) {
			if (hasPiece) ++ piece;
		}

		void next() {
			distance += piece;
		}
	}

	public class Vertex {
		List<Integer> edge;
		boolean hasPiece;
		int index;

		Vertex(boolean piece, int index) {
			hasPiece = piece;
			edge = new ArrayList<Integer>();
			this.index = index;
		}

		int search(Vertex[] tree) { // ここを根として調べていく
			Data data = new Data(hasPiece);
			int maxDistance = 0, sumDistance = 0;
			int piece = 0, operate = 0;
			for (int i : edge) {
				Data tmp = tree[i].dfs(tree, index);
				maxDistance = Math.max(maxDistance, tmp.distance);
				sumDistance += tmp.distance;
				piece += tmp.piece;
				operate += tmp.operate;
			}
			int addOperate = Math.min(sumDistance - maxDistance, sumDistance / 2);
			data.piece += piece;
			data.operate = operate + addOperate;
			data.distance = sumDistance - addOperate * 2;
			if (data.distance == 0) return data.operate;
			return Integer.MAX_VALUE;
		}

		Data dfs(Vertex[] tree, int root) {
			Data data = new Data(hasPiece);
			int maxDistance = 0, sumDistance = 0;
			int piece = 0, operate = 0;
			for (int i : edge) {
				if (i == root) continue;
				Data tmp = tree[i].dfs(tree, index);
				maxDistance = Math.max(maxDistance, tmp.distance);
				sumDistance += tmp.distance;
				piece += tmp.piece;
				operate += tmp.operate;
			}
			int addOperate = Math.min(sumDistance - maxDistance, sumDistance / 2);
			data.piece += piece;
			data.operate = operate + addOperate;
			data.distance = sumDistance - addOperate * 2;
			data.next();
			return data;
		}
	}

	public Main() {
		FastIO io = new FastIO();
		/*
		 * author: 31536000
		 * 考察メモ
		 * まず、ある頂点に集めると決め打つ
		 * すると、葉から順にそこに寄せ集める動きになる
		 * ただし、途中の枝で2つ以上から集まった時はそれぞれで相殺してもらう
		 * それが一番効率が良いのでね
		 * すると、各頂点についてO(N)よりO(N^2)で解けた
		 * わーい
		 */
		int N = io.nextInt();
		String S = io.next();
		Vertex[] tree = new Vertex[N];
		for (int i = 0;i < N;++ i) tree[i] = new Vertex(S.charAt(i) == '1', i);
		for (int i = 1;i < N;++ i) {
			int a = io.nextInt() - 1, b = io.nextInt() - 1;
			tree[a].edge.add(b);
			tree[b].edge.add(a);
		}
		int operate = Integer.MAX_VALUE;
		for (int i = 0;i < N;++ i) { // この頂点に集めると決め打ち
			operate = Math.min(operate, tree[i].search(tree));
		}
		io.print((operate + 1 & Integer.MAX_VALUE) - 1);

		io.flush();
	}

	public class FastIO {
		private final InputStream in = System.in;
		private final byte[] buffer = new byte[1024];
		private int read = 0;
		private int length = 0;
		public final PrintWriter out = new PrintWriter(System.out, false);
		public final PrintWriter err = new PrintWriter(System.err, false);

		private boolean hasNextByte() {
			if (read < length) return true;
			else {
				try {
					read = 0;
					length = in.read(buffer);
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return length > 0;
		}

		private int readByte() {
			return hasNextByte() ? buffer[read++] : -1;
		}

		private boolean isPrintableChar(int c) {
			return 33 <= c && c <= 126;
		}

		private boolean isNumber(int c) {
			return '0' <= c && c <= '9';
		}

		public boolean hasNext() {
			while (hasNextByte() && !isPrintableChar(buffer[read])) read++;
			return hasNextByte();
		}

		public char nextChar() {
			if (!hasNextByte())  throw new NoSuchElementException();
			return (char)readByte();
		}

		public String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b;
			while (isPrintableChar(b = readByte())) sb.appendCodePoint(b);
			return sb.toString();
		}

		public long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (!isNumber(b)) throw new NumberFormatException();
			while (true) {
				if (isNumber(b)) {
					n *= 10;
					n += b - '0';
				} else if (b == -1 || !isPrintableChar(b)) return minus ? -n : n;
				else throw new NumberFormatException();
				b = readByte();
			}
		}

		public int nextInt() {
			long nl = nextLong();
			if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
			return (int) nl;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextInt(int width) {
			int[] ret = new int[width];
			for (int i = 0;i < width;++ i) ret[i] = nextInt();
			return ret;
		}

		public long[] nextLong(int width) {
			long[] ret = new long[width];
			for (int i = 0;i < width;++ i) ret[i] = nextLong();
			return ret;
		}

		public int[][] nextInt(int width, int height) {
			int[][] ret = new int[height][width];
			for (int i = 0, j;i < height;++ i) for (j = 0;j < width;++ j) ret[i][j] = nextInt();
			return ret;
		}

		public long[][] nextLong(int width, int height) {
			long[][] ret = new long[height][width];
			for (int i = 0, j;i < height;++ i) for (j = 0;j < width;++ j) ret[j][i] = nextLong();
			return ret;
		}

		public boolean[] nextBoolean(char T) {
			char[] s = next().toCharArray();
			boolean[] ret = new boolean[s.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = s[i] == T;
			return ret;
		}

		@Override
		protected void finalize() throws Throwable {
			try {
				super.finalize();
			} finally {
				in.close();
				out.close();
				err.close();
			}
		}

		public void print(boolean b) {
			out.print(b);
		}

		public void print(char c) {
			out.print(c);
		}

