    static class TaskE {
        Graph graph;
        int[] total;
        int[] min;
        int[] max;
        boolean[] chip;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            char[] s = in.readCharArray(n);
            int[] a = new int[n - 1];
            int[] b = new int[n - 1];
            in.readIntArrays(a, b);
            MiscUtils.decreaseByOne(a, b);
            graph = BidirectionalGraph.createGraph(n, a, b);
            chip = new boolean[n];
            total = new int[n];
            min = new int[n];
            max = new int[n];
            for (int i = 0; i < n; i++) {
                chip[i] = s[i] == '1';
            }
            int answer = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                go(i, -1);
                if (min[i] == 0) {
                    answer = Math.min(answer, max[i] / 2);
                }
            }
            if (answer == Integer.MAX_VALUE) {
                answer = -1;
            }
            out.printLine(answer);
        }

        private void go(int vertex, int last) {
            int maxMin = 0;
            int maxOfMaxMin = 0;
            int sumMax = 0;
            int curTotal = chip[vertex] ? 1 : 0;
            for (int i = graph.firstOutbound(vertex); i != -1; i = graph.nextOutbound(i)) {
                int next = graph.destination(i);
                if (next == last) {
                    continue;
                }
                go(next, vertex);
                int curMin = min[next] + total[next];
                int curMax = max[next] + total[next];
                curTotal += total[next];
                sumMax += curMax;
                if (curMin > maxMin) {
                    maxMin = curMin;
                    maxOfMaxMin = curMax;
                }
            }
            total[vertex] = curTotal;
            max[vertex] = sumMax;
            sumMax -= maxOfMaxMin;
            if (maxMin > sumMax) {
                min[vertex] = maxMin - sumMax;
            } else {
                min[vertex] = max[vertex] & 1;
            }
        }

    }

