partial class Solver
{
    struct Node
    {
        public int Index;
        public int DepthSum;
        public int DepthSumMin;
        public int Count;
    }

    Node Dfs(List<int>[] adj, string S, int pos, int pre)
    {
        var result = new Node { Index = pos, };
        if (S[pos] == '1')
        {
            result.Count++;
        }
        var children = new List<int>();
        foreach (var child in adj[pos])
        {
            if (child == pre) continue;
            var childNode = Dfs(adj, S, child, pos);
            result.Count += childNode.Count;
            result.DepthSum += childNode.DepthSum + childNode.Count;
            if (childNode.DepthSumMin + childNode.Count > 0)
            {
                children.Add(childNode.DepthSumMin + childNode.Count);
            }
        }

        if (children.Count >= 1)
        {
            var max = children.Max();
            var sum = children.Sum();
            var remain = sum - max;
            if (remain < max)
            {
                result.DepthSumMin = max - remain;
            }
            else
            {
                result.DepthSumMin = sum % 2;
            }
        }
        else
        {
            result.DepthSumMin = 0;
        }

        return result;
    }

    public void Run()
    {
        var N = ni();
        var S = ns();
        var adj = E.Range(0, N).Select(_ => new List<int>()).ToArray();
        for (int i = 0; i < N - 1; i++)
        {
            var a = ni() - 1;
            var b = ni() - 1;
            adj[a].Add(b);
            adj[b].Add(a);
        }
        int ans = int.MaxValue;

        for (int i = 0; i < N; i++)
        {
            var childNodes = new List<Node>();
            foreach (var child in adj[i])
            {
                var node = Dfs(adj, S, child, i);
                node.DepthSum += node.Count;
                node.DepthSumMin += node.Count;
                childNodes.Add(node);
            }
            var sum = childNodes.Sum(c => c.DepthSum);
            if (sum == 0)
            {
                ans = 0;
                continue;
            }
            if (sum % 2 == 1) continue;
            var maxChildDepth = childNodes.Max(c => c.DepthSum);
            var maxChildDepthNode = childNodes.First(c => c.DepthSum == maxChildDepth);
            var remain = sum - maxChildDepth;
            if (remain < sum)
            {
                if (maxChildDepthNode.DepthSumMin <= remain)
                {
                    ans = Math.Min(ans, sum / 2);
                }
            }
            else
            {
                ans = Math.Min(ans, sum / 2);
            }
        }
        if (ans == int.MaxValue) ans = -1;
        cout.WriteLine(ans);
    }
}

