                        maxMinLen = childMinLen[max2] + childCoin[max2];
                        maxMinLen -= childSumLen[now];
                        maxMinLen -= parentSumLen[now];
                        maxMinLen += childSumLen[max2] + childCoin[max2];
                        maxMinLen += childSumLen[next] + childCoin[next];
                    }

                    maxMinLen = Math.Max(maxMinLen, parentSumLen[next] % 2);
                    parentMinLen[next] = maxMinLen;
                }
                else
                {
                    long maxMinLen = childMinLen[maxid] + childCoin[maxid];
                    maxMinLen -= childSumLen[now];
                    maxMinLen -= parentSumLen[now];
                    maxMinLen += childSumLen[maxid] + childCoin[maxid];
                    maxMinLen += childSumLen[next] + childCoin[next];

                    maxMinLen = Math.Max(maxMinLen, parentSumLen[next] % 2);
                    parentMinLen[next] = maxMinLen;
                }


                //Console.WriteLine($"{next} {parentCoin[next]} {parentMinLen[next]} {parentSumLen[next]}");
            }
        }

        // dfs
        foreach (var next in es[now])
        {
            if (next == pre) continue;
            dfs2(next, now);
        }
    }
