lo sum, _total;

pair <int, int> dfs(int u, int fat) {
	int sum = 0, size = str[u], total = 0;
	dep[u] = dep[fat] + 1;
	vector <int> cur;
	for (int v : G[u]) {
		if (v != fat) {
			pair <int, int> t = dfs(v, u);
			cur.push_back(t.first + t.second);
			size += t.second;
			total += t.first + t.second;
		}
	}
	if (!cur.empty()) {
		sort(cur.begin(), cur.end());
		sum = max(total & 1, cur.back() * 2 - total);
	}
	_total += (total - sum) / 2;
	return make_pair(sum, size);
}

