struct Result {
    count: usize,
    cost: usize,
    dist: usize,
}
fn dfs(root: usize, parent: usize, g: &Vec<Vec<usize>>, s: &Vec<char>) -> Result {
    let mut count_sum = if s[root] == '1' { 1 } else { 0 };
    let mut cost_sum = 0;
    let mut dists = Vec::new();
    for &u in &g[root] {
        if u != parent {
            let r = dfs(u, root, g, s);
            count_sum += r.count;
            cost_sum += r.cost + r.count;
            dists.push(r.dist + r.count);
        }
    }
    dists.sort();
    dists.reverse();
    let dists_sum = dists.iter().sum::<usize>();
    let next_dist = if dists.len() == 0 {
        0
    } else if dists[0] >= dists_sum - dists[0] {
        dists[0] - (dists_sum - dists[0])
    } else {
        dists_sum % 2
    };
    Result {
        count: count_sum,
        cost: cost_sum,
        dist: next_dist,
    }
}
fn run() {
    input! {
        n: usize,
        s: chars,
        edges: [(usize1, usize1); n-1],
    }
    let mut g = vec![Vec::new(); n];
    for (a, b) in edges {
        g[a].push(b);
        g[b].push(a);
    }

    let mut answer = usize::max_value();
    for root in 0..n {
        let r = dfs(root, usize::max_value(), &g, &s);
        if r.dist == 0 {
            answer.set_min(r.cost / 2);
        }
    }
    if answer != usize::max_value() {
        println!("{}", answer);
    } else {
        assert!(false);
        println!("-1");
    }
}

//{{{ template
fn main() {
    let _ = ::std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap();
}

pub trait SetMinMax {
    fn set_min(&mut self, v: Self) -> bool;
    fn set_max(&mut self, v: Self) -> bool;
}

impl<T> SetMinMax for T
where
    T: PartialOrd,
{
    fn set_min(&mut self, v: T) -> bool {
        *self > v && {
            *self = v;
            true
        }
    }
    fn set_max(&mut self, v: T) -> bool {
        *self < v && {
            *self = v;
            true
        }
    }
}

#[derive(PartialEq, Eq, Debug, Copy, Clone, Default, Hash)]
pub struct Reverse<T>(pub T);

impl<T: PartialOrd> PartialOrd for Reverse<T> {
    #[inline]
    fn partial_cmp(&self, other: &Reverse<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }

    #[inline]
    fn lt(&self, other: &Self) -> bool {
        other.0 < self.0
    }
    #[inline]
    fn le(&self, other: &Self) -> bool {
        other.0 <= self.0
    }
    #[inline]
    fn ge(&self, other: &Self) -> bool {
        other.0 >= self.0
    }
    #[inline]
    fn gt(&self, other: &Self) -> bool {
        other.0 > self.0
    }
}

impl<T: Ord> Ord for Reverse<T> {
    #[inline]
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

