const INF: usize = 1 << 28;

fn dfs(v: usize, par: usize, g: &[Vec<usize>], has: &[bool]) -> (usize, usize, usize) {
    let my = if has[v] { 1 } else { 0 };
    let mut sum = my;
    let mut high = 0;
    let mut rest = vec![];
    for &w in &g[v] {
        if par == w { continue; }
        let (sub, l, h) = dfs(w, v, g, has);
        high += h + sub;
        sum += sub;
        rest.push((l + sub, h + sub));
    }
    if !rest.is_empty() {
        let mut mi = INF;
        let mut sol = false;
        let mut lh = (0, 0);
        for i in 0..rest.len() {
            let (l, h) = rest[i];
            if l > high - h {
                sol = true;
                lh = (l, h);
                break;
            } else {
                mi = min(mi, high % 2);
            }
        }
        if sol {
            let (l, h) = lh;
            mi = min(mi, l - (high - h));
        } else {
            mi = min(mi, high % 2);
        }
        return (sum, mi, high);
    }
    (sum, 0, 0)
}


