#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

type Weight = i32;
#[allow(dead_code)]
#[derive(Clone, Debug, Eq, PartialEq)]
struct Edge {
    index: usize,
    src: usize,
    dest: usize,
    weight: Weight,
}
#[allow(dead_code)]
impl Edge {
    fn new(index: usize, src: usize, dest: usize, weight: Weight) -> Edge {
        Edge {
            index: index,
            src: src,
            dest: dest,
            weight: weight,
        }
    }
}
impl std::cmp::Ord for Edge {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        (self.weight, self.src, self.dest).cmp(&(other.weight, other.src, other.dest))
    }
}
impl std::cmp::PartialOrd for Edge {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
type Edges = Vec<Edge>;
type Graph = Vec<Edges>;
#[allow(dead_code)]
fn graph_new(n: usize) -> Graph {
    vec![vec![]; n]
}
#[allow(dead_code)]
fn add_bi_edge(graph: &mut Graph, index: &mut usize, src: usize, dest: usize, weight: Weight) {
    graph[src].push(Edge::new(*index, src, dest, weight));
    graph[dest].push(Edge::new(*index, dest, src, weight));
    *index += 1;
}
#[allow(dead_code)]
fn add_uni_edge(graph: &mut Graph, index: &mut usize, src: usize, dest: usize, weight: Weight) {
    graph[src].push(Edge::new(*index, src, dest, weight));
    *index += 1;
}

// return (cnt, dist_sum, move_max)
fn calc(from: usize, parent: usize, g: &Graph, cnts: &Vec<usize>) -> (usize, usize, usize) {
    let mut ret = (cnts[from], 0, 0);
    for e in g[from].iter() {
        if e.dest == parent {
            continue;
        }
        let mut nret = calc(e.dest, from, g, cnts);
        nret.1 += nret.0;
        // merge
        if nret.1 > ret.1 {
            std::mem::swap(&mut ret, &mut nret);
        }
        ret.0 += nret.0;
        ret.1 += nret.1;
        ret.2 = std::cmp::min(ret.1 / 2, nret.1 + ret.2);
    }
    return ret;
}

fn main() {
    let n = read::<usize>();
    let cnts = read::<String>()
        .chars()
        .map(|c| if c == '1' { 1 } else { 0 })
        .collect::<Vec<usize>>();
    let mut g = graph_new(n);
    let mut index = 0;
    for _i in 0..n - 1 {
        let f = read::<usize>() - 1;
        let t = read::<usize>() - 1;
        add_bi_edge(&mut g, &mut index, f, t, 1);
    }
    let mut ans = 1 << 60;
    for i in 0..n {
        let nret = calc(i, i, &g, &cnts);
        if nret.1 % 2 == 0 && nret.1 <= nret.2 * 2 {
            ans = std::cmp::min(ans, nret.2);
        }
    }
    if ans == 1 << 60 {
        println!("-1");
    } else {
        println!("{}", ans);
    }
}

