use std::cmp::{max, min};

fn main() {
    input!{
        n: usize,
        s: chars,
        es: [(usize1, usize1); n - 1]
    }
    let mut t = vec![vec![]; n];
    for (u, v) in es {
        t[u].push(v);
        t[v].push(u);
    }
    let mut ans = usize::max_value();
    for i in 0..n {
        let (x, d, _) = dfs(i, i, &t, &s);
        if d == 0 {
            ans = min(ans, x);
        }
    }
    if ans == usize::max_value() {
        println!("-1");
    } else {
        println!("{}", ans);
    }
}

fn dfs(r: usize, p: usize, t: &Vec<Vec<usize>>, s: &Vec<char>) -> (usize, usize, usize) {
    let mut n = 0;
    let mut sum = 0;
    let mut m = 0;
    let mut v = s[r].to_digit(10u32).unwrap() as usize;
    for c in t[r].clone() {
        if c == p {
            continue;
        }
        let cs = dfs(c, r, t, s);
        n += cs.0;
        sum += cs.1 + cs.2;
        m = max(m, cs.0 + cs.1 + cs.2);
        v += cs.2;
    }
    if m * 2 >= sum + n {
        (n + sum - m, 2 * m - sum - n, v)
    } else {
        ((n + sum) / 2, (n + sum) % 2, v)
    }
}

