// I read the editorial.
const INF: usize = 1 << 28;

fn dfs(v: usize, par: usize, g: &[Vec<usize>], has: &[bool]) -> (usize, usize, usize) {
    let mut sum = 0;
    let my = if has[v] { 1 } else { 0 };
    let mut count = 0;
    let mut rest = vec![];
    for &w in &g[v] {
        if par == w { continue; }
        let (sub, c, r) = dfs(w, v, g, has);
        count += c;
        sum += sub;
        rest.push(r + c);
    }
    if !rest.is_empty() {
        let ma: usize = rest.iter().cloned().max().unwrap();
        let s: usize = rest.iter().sum::<usize>() - ma;
        if s < ma {
            sum += s;
            return (sum, count + my, ma - s);
        }
        sum += (s + ma) / 2;
        return (sum, count + my, (s - ma) % 2);
    }
    (sum, my, 0)
}


fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        s: chars,
        ab: [(usize1, usize1); n - 1],
    }
    let s: Vec<bool> = s.into_iter().map(|c| c == '1').collect();
    let mut g = vec![vec![]; n];
    for &(a, b) in &ab {
        g[a].push(b);
        g[b].push(a);
    }
    let mut mi = INF;
    for i in 0..n {
        let (sum, _, rest) = dfs(i, n, &g, &s);
        if rest == 0 {
            mi = min(mi, sum);
        }
    }
    if mi >= INF {
        puts!("-1\n");
    } else {
        puts!("{}\n", mi);
    }
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

