    for i in 0..(n - 1) {
        let a = sc.next::<i32>() - 1;
        let b = sc.next::<i32>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }
    let mut have = v![];
    for c in s.chars() {
        have.push(c == '1');
    }

    let mut res = INF;
    for i in 0..n {
        let (min, max, _) = dfs(&graph, &have, i, -1);
        if min == 0 {
            if res > max / 2 {
                res = max / 2;
            }
        }
    }

    println!("{}", if res == INF { -1 } else { res });
}

fn dfs(graph: &MyVec<MyVec<i32>>, have: &MyVec<bool>, root: i32, parent: i32) -> (i32, i32, i32) {
    // min, max, num
    let mut tot = 0;
    let mut res_min = 0;
    let mut res_max = 0;
    for j in &*graph[root] {
        if *j == parent {
            continue;
        }
        let tup = dfs(graph, have, *j, root);
        let mut min = tup.0;
        let mut max = tup.1;
        let num = tup.2;
        tot += num;
        min += num;
        max += num;

        if max < res_min {
            res_min = res_min - max;
        } else if res_max < min {
            res_min = min - res_max;
        } else {
            if ((res_min + min) & 1) == 0 {
                res_min = 0;
            } else {
                res_min = 1;
            }
        }
        res_max += max;
    }
    if have[root] {
        tot += 1;
    }
    (res_min, res_max, tot)
}

