fn dfs(r: usize, p: usize, t: &Vec<Vec<usize>>, s: &Vec<char>) -> (usize, usize, usize) {
    let mut n = 0;
    let mut sum = 0;
    let mut m = 0;
    let mut v = s[r].to_digit(10u32).unwrap() as usize;
    for c in t[r].clone() {
        if c == p {
            continue;
        }
        let cs = dfs(c, r, t, s);
        n += cs.0;
        sum += cs.1 + cs.2;
        m = max(m, cs.1 + cs.2);
        v += cs.2;
    }
    if m * 2 >= sum {
        (n + sum - m, 2 * m - sum, v)
    } else {
        (n + sum / 2, sum % 2, v)
    }
}

use std::io::Read;

fn search(g : &Vec<Vec<usize>>, s: &[u8], pos : usize, prev : usize) -> (i32, i32, i32) {
    let mut res = (0, 0, 0);
    let mut child_res = Vec::new();
    for &t in &g[pos] {
        if t == prev { continue }
        let r = search(g, s, t, pos);
        res.0 += r.0;
        res.2 += r.0 + r.2;
        child_res.push((r.1 + r.0, r.2 + r.0));
    }
    res.1 = res.2 % 2;
    for p in child_res {
        res.1 = std::cmp::max(res.1, p.0 - (res.2 - p.1));
    }
    if s[pos] == b'1' { res.0 += 1 }
    res
}

