use std::cmp::min;

fn solve(u: usize, prev: Option<usize>, g: &Vec<Vec<usize>>, s: &[char]) -> (i64, i64, i64) {
    let mut cs = vec![];
    for &v in g[u].iter() {
        if Some(v) != prev {
            let (a, b, c) = solve(v, Some(u), g, s);
            cs.push((a+c, b+c, c));
        }
    }

    let total = cs.iter().map(|&c| c.2).sum::<i64>() + if s[u] == '1' {1} else {0};
    let maxv = cs.iter().map(|&c| c.1).sum::<i64>();
    let t = cs.iter().map(|&c| c.0).sum::<i64>();

    let minv = if cs.len() >= 2 {
        let mut ng = None;
        for i in 0..cs.len() {
            if cs[i].0*2 > t {
                ng = Some(i);
                break;
            }
        }

        if let Some(i) = ng {
            let mut rest = cs[i].0 - (t - cs[i].0);
            for j in 0..cs.len() {
                if i == j {
                    continue;
                }
                let usable = min(rest, cs[j].1-cs[j].0)/2*2;
                rest -= usable;
            }
            rest
        } else if t % 2 != 0 {
            1
        } else {
            0
        }
    } else {
        t
    };

    (minv, maxv, total)
}

