            cs.reverse();

            if cs[0].0 >= 1 && cs[1].0 >= 1 {
                cs[0].0 -= 1;
                cs[1].0 -= 1;

                cs[0].1 -= 1;
                cs[1].1 -= 1;

                continue;
            }

            if cs[0].0 <= 1 {
                break;
            }

            let mut ok = false;
            for i in 1..cs.len() {
                if cs[i].1 >= 2 {
                    cs[0].0 -= 2;
                    cs[i].1 -= 2;
                    ok = true;
                    break;
                }
            }

            if !ok {
                break;
            }
        }
    }

    (cs.iter().map(|&c| c.0).sum::<i64>(), maxv, total)
}

