// I read the editorial.
const INF: usize = 1 << 28;

fn dfs(v: usize, par: usize, g: &[Vec<usize>], has: &[bool]) -> (usize, usize, usize) {
    let my = if has[v] { 1 } else { 0 };
    let mut sum = my;
    let mut high = 0;
    let mut rest = vec![];
    for &w in &g[v] {
        if par == w { continue; }
        let (sub, l, h) = dfs(w, v, g, has);
        high += h + sub;
        sum += sub;
        rest.push((l + sub, h + sub));
    }
    if !rest.is_empty() {
        let mut mi = INF;
        let mut sol = false;
        let mut lh = (0, 0);
        for i in 0..rest.len() {
            let (l, h) = rest[i];
            if l > high - h {
                sol = true;
                lh = (l, h);
                break;
            }
        }
        if sol {
            let (l, h) = lh;
            mi = min(mi, l - (high - h));
        } else {
            mi = min(mi, high % 2);
        }
        return (sum, mi, high);
    }
    (sum, 0, 0)
}


fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        s: chars,
        ab: [(usize1, usize1); n - 1],
    }
    let s: Vec<bool> = s.into_iter().map(|c| c == '1').collect();
    let mut g = vec![vec![]; n];
    for &(a, b) in &ab {
        g[a].push(b);
        g[b].push(a);
    }
    let mut mi = INF;
    for i in 0..n {
        let ret = dfs(i, n, &g, &s);
        let (_, low, high) = ret;
        if low == 0 {
            mi = min(mi, high / 2);
        }
    }
    if mi >= INF {
        puts!("-1\n");
    } else {
        puts!("{}\n", mi);
    }
}

